  .card.fx-hellfire { animation: none !important; }
}

/* --- Wave 3: SABER / PROJECTILE / FLAME / RING / CELESTIAL (cost-8+ titans) --- */

/* Lightsaber slash — a bright diagonal blade sweep across a card (Luke/Anakin) */
.sig-saber {
  position: fixed;
  height: 5px;
  border-radius: 999px;
  pointer-events: none;
  transform-origin: center;
  transform: translate(-50%, -50%) rotate(var(--sig-ang, -38deg)) scaleX(0);
  background: linear-gradient(90deg, transparent 0%, var(--sig-blade, #3aa0ff) 18%, var(--sig-core, #e8f5ff) 50%, var(--sig-blade, #3aa0ff) 82%, transparent 100%);
  box-shadow: 0 0 14px 2px var(--sig-blade, #3aa0ff);
  animation: sigSaber 440ms cubic-bezier(0.16, 1, 0.30, 1) forwards;
}
@keyframes sigSaber {
  0%   { opacity: 0; transform: translate(-50%, -50%) rotate(var(--sig-ang, -38deg)) scaleX(0); }
  22%  { opacity: 1; transform: translate(-50%, -50%) rotate(var(--sig-ang, -38deg)) scaleX(1); }
  70%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) rotate(var(--sig-ang, -38deg)) scaleX(1); }
}

/* Batarang — a small dark spinning blade that flies to its mark (Batman) */
.sig-projectile {
  position: fixed;
  width: 16px; height: 16px;
  margin: -8px 0 0 -8px;
  pointer-events: none;
  background: var(--sig-c, #cfd6df);
  clip-path: polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
  filter: drop-shadow(0 0 4px var(--sig-c, #cfd6df));
  animation: sigProjFly 300ms linear forwards;
}
@keyframes sigProjFly {
  0%   { opacity: 0; transform: translate(0, 0) rotate(0deg) scale(0.6); }
  12%  { opacity: 1; }
  100% { opacity: 1; transform: translate(var(--sig-dx, 0), var(--sig-dy, 0)) rotate(900deg) scale(1); }
}
.sig-proj-spark {
  position: fixed;
  width: 10px; height: 10px;
  margin: -6px 0 0 -6px;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(circle, #fff 0%, var(--sig-c, #cfd6df) 50%, transparent 72%);
  animation: sigProjSpark 300ms ease-out 260ms forwards;
}
@keyframes sigProjSpark {
  0%   { opacity: 0; transform: scale(0.4); }
  40%  { opacity: 1; transform: scale(2.4); }
  100% { opacity: 0; transform: scale(3.4); }
}

/* Hellfire column — rises from the card's base, flickering red/black (Trigon) */
.sig-flame {
  position: fixed;
  transform: translateX(-50%) scaleY(0);
  transform-origin: bottom center;
  pointer-events: none;
  border-radius: 50% 50% 46% 46% / 62% 62% 38% 38%;
  background: linear-gradient(to top, #ff8a1a 0%, #ff2d1a 30%, #c1121f 60%, rgba(10, 10, 10, 0.5) 100%);
  filter: blur(2px);
  box-shadow: 0 0 26px 6px rgba(255, 60, 20, 0.6);
  animation: sigFlame 720ms ease-out forwards;
}
@keyframes sigFlame {
  0%   { opacity: 0; transform: translateX(-50%) scaleY(0.1) scaleX(1); }
  25%  { opacity: 1; transform: translateX(-50%) scaleY(1.05) scaleX(0.92); }
  55%  { transform: translateX(-50%) scaleY(0.92) scaleX(1.04); }
  100% { opacity: 0; transform: translateX(-50%) scaleY(1.1) scaleX(0.9); }
}

/* Constriction / burst ring over a card (Vader choke = contract) */
.sig-ring {
  position: fixed;
  width: 40px; height: 40px;
  margin: -20px 0 0 -20px;
  border-radius: 50%;
  border: 3px solid var(--sig-c, #c1121f);
  box-shadow: 0 0 20px var(--sig-c, #c1121f), inset 0 0 16px var(--sig-c, #c1121f);
  pointer-events: none;
  opacity: 0;
  animation: sigRingExpand 520ms ease-out forwards;
}
@keyframes sigRingExpand {
  0%   { opacity: 0; transform: scale(0.3); }
  25%  { opacity: 1; }
  100% { opacity: 0; transform: scale(3.4); }
}
.sig-ring.sig-ring-contract {
  width: 150px; height: 150px;
  margin: -76px 0 0 -76px;
  animation: sigRingContract 520ms cubic-bezier(0.5, 0, 0.75, 0) forwards;
}
@keyframes sigRingContract {
  0%   { opacity: 0; transform: scale(1.6) rotate(0deg); }
  25%  { opacity: 1; }
  100% { opacity: 0; transform: scale(0.2) rotate(90deg); }
}

/* Apocalypse celestial-tech transmutation surge over the hand */
.sig-celestial {
  position: fixed;
  border-radius: 12px;
  pointer-events: none;
  opacity: 0;
  background: linear-gradient(120deg, transparent 0%, rgba(46, 198, 198, 0.18) 40%, rgba(74, 144, 194, 0.30) 50%, rgba(207, 216, 227, 0.22) 60%, transparent 100%);
  background-size: 260% 100%;
  box-shadow: inset 0 0 30px rgba(74, 144, 194, 0.5);
  animation: sigCelestial 760ms ease-out forwards;
}
@keyframes sigCelestial {
  0%   { opacity: 0; background-position: 130% 0; }
  30%  { opacity: 1; }
  100% { opacity: 0; background-position: -30% 0; }
}

/* Darth Vader — thrown lightsaber: a crimson blade that spins out to its mark
   and boomerangs back. --sig-dx/--sig-dy = the outbound vector to the target. */
.sig-saber-throw {
  position: fixed;
  width: 58px; height: 6px;
  margin: -3px 0 0 -29px;
  pointer-events: none;
  border-radius: 2px;
  background: linear-gradient(90deg, rgba(255, 45, 45, 0) 0%, #ff2d2d 16%, #fff 50%, #ff2d2d 84%, rgba(255, 45, 45, 0) 100%);
  box-shadow: 0 0 10px 2px #ff2d2d, 0 0 24px 7px rgba(255, 45, 45, 0.5);
  animation: sigSaberThrow 760ms cubic-bezier(0.4, 0, 0.2, 1) forwards;
}
@keyframes sigSaberThrow {
  0%   { opacity: 0; transform: translate(0, 0) rotate(0deg); }
  10%  { opacity: var(--sig-trail-op, 1); }
  /* Outbound arrival at the target — held for a beat as it strikes. */
  47%  { opacity: var(--sig-trail-op, 1); transform: translate(var(--sig-dx, 0), var(--sig-dy, 0)) rotate(540deg); }
  53%  { opacity: var(--sig-trail-op, 1); transform: translate(var(--sig-dx, 0), var(--sig-dy, 0)) rotate(570deg); }
  /* Boomerangs back to Vader's hand, still spinning. */
  100% { opacity: 0; transform: translate(0, 0) rotate(1080deg); }
}
/* Lagging afterimage copies — softer + slightly blurred so they read as a
   crimson motion-trail behind the lead blade rather than three hard blades. */
.sig-saber-throw.sig-saber-ghost {
  filter: blur(1.5px);
  box-shadow: 0 0 8px 1px #ff2d2d, 0 0 18px 5px rgba(255, 45, 45, 0.4);
}

@media (prefers-reduced-motion: reduce) {
  .sig-saber, .sig-projectile, .sig-proj-spark, .sig-flame, .sig-ring, .sig-celestial, .sig-saber-throw {
    animation: none !important;
    opacity: 0 !important;
  }
}

/* --- Wave 4: WHEEL (Mahoraga) / STREAK (Omni-Man) --- */
.sig-wheel {
  position: fixed;
  width: 190px; height: 190px;
  margin: -96px 0 0 -96px;
  pointer-events: none;
  opacity: 0;
  filter: drop-shadow(0 0 10px #d9a441);
  animation: sigWheel 760ms cubic-bezier(0.16, 1, 0.30, 1) forwards;
}
.sig-wheel svg { width: 100%; height: 100%; }
@keyframes sigWheel {
  0%   { opacity: 0; transform: scale(0.2) rotate(-160deg); }
  30%  { opacity: 1; transform: scale(1.05) rotate(-20deg); }
  60%  { transform: scale(1) rotate(6deg); }
  100% { opacity: 0; transform: scale(1) rotate(0deg); }
}
.sig-streak {
  position: fixed;
  left: 0;
  width: 100vw;
  height: 14px;
  margin-top: -8px;
  pointer-events: none;
  transform: translateX(-100%);
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.15) 40%, #ffffff 72%, rgba(193,18,31,0.9) 88%, transparent 100%);
  box-shadow: 0 0 22px 5px rgba(255,255,255,0.55);
  animation: sigStreak 440ms cubic-bezier(0.5, 0, 0.2, 1) forwards;
}
@keyframes sigStreak {
  0%   { opacity: 0; transform: translateX(-100%); }
  25%  { opacity: 1; }
  100% { opacity: 0; transform: translateX(100%); }
}
@media (prefers-reduced-motion: reduce) {
  .sig-wheel, .sig-streak { animation: none !important; opacity: 0 !important; }
}

/* ============================================================
   GLOBAL REDUCED-MOTION SAFETY NET (2026-06 enforcement sweep)
   ------------------------------------------------------------
   The codebase has 61 hand-scoped prefers-reduced-motion blocks,
   but each only covers the specific effect it was written for.
   Any animation added afterward (by either dev) was unprotected
   until someone remembered to write a matching block. This
   catch-all flips that default: under the OS "reduce motion"
   setting, EVERYTHING animated decays to ~instant unless a more
   specific rule already handled it.

   Pattern is the a11y-project standard: 0.01ms (not `none`) so
   animations whose END KEYFRAME sets the visible state still
   snap to that end state instead of leaving the element stuck in
   its hidden start frame. iteration-count:1 stops infinite loops
   (idle pulses, breathing glows) after one near-instant pass.
   Gated entirely behind the OS preference, so it costs nothing
   for players who haven't opted in.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

