.setup2v2-lobby-wait {
  text-align: center; color: #4a6070; font-size: 0.8125rem; margin-top: 14px;
  letter-spacing: .04em;
}

/* --- Team Setup Screen --- */
.twov2-panel {
  background: #111820;
  border: 1.5px solid #2a3a50;
  border-radius: 12px;
  padding: 32px 36px 28px;
  max-width: 500px;
  width: 94%;
  margin: auto;
}
.twov2-title {
  color: var(--theme-accent-bright, #4fc3f7);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-align: center;
  margin: 0 0 6px;
}
.twov2-subtitle {
  color: #88a0b8;
  text-align: center;
  margin: 0 0 22px;
  font-size: 0.875rem;
}
.twov2-names-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 24px;
}
.twov2-name-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.twov2-name-label {
  color: #88a0b8;
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.twov2-name-input {
  background: #000;
  border: 1.5px solid #2a3a50;
  border-radius: 4px;
  color: var(--text-dim, #dcebf8);
  padding: 8px 10px;
  font-size: 0.9375rem;
  outline: none;
  transition: border-color 0.15s var(--ease-snap);
}
.twov2-name-input:focus { border-color: var(--theme-accent-bright, #4fc3f7); }
.twov2-team-assign {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
  justify-content: center;
}
.twov2-team-box {
  flex: 1;
  background: #000;
  border: 1.5px solid #2a3a50;
  border-radius: 8px;
  padding: 12px;
  text-align: center;
}
.twov2-team-label {
  font-weight: 700;
  font-size: 1rem;
  margin-bottom: 8px;
  letter-spacing: 0.06em;
}
.twov2-team-members { display: flex; flex-direction: column; gap: 4px; }
.twov2-member { color: var(--text-dim, #cfd6df); font-size: 0.875rem; }
.twov2-team-vs {
  color: #f5a623;
  font-size: 1.25rem;
  font-weight: 700;
  flex-shrink: 0;
}
.twov2-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
}
.twov2-btn {
  padding: 12px 22px;
  border-radius: 8px;
  border: none;
  font-weight: 700;
  font-size: 0.9375rem;
  cursor: pointer;
  transition: opacity 0.15s var(--ease-snap), transform 0.1s var(--ease-snap);
}
.twov2-btn:hover { opacity: 0.88; transform: translateY(-1px); }
.twov2-btn-pri {
  background: var(--theme-accent-bright, #4fc3f7);
  color: #000000;
}
.twov2-btn-sec {
  background: #1e2d3e;
  color: var(--theme-accent-bright, #4fc3f7);
  border: 1.5px solid var(--theme-accent-bright, #4fc3f7);
}
.twov2-back-btn {
  display: block;
  margin: 0 auto;
  background: none;
  border: none;
  color: #88a0b8;
  font-size: 0.875rem;
  cursor: pointer;
}
.twov2-back-btn:hover { color: var(--text-dim, #cfd6df); }

/* --- Pass Screen --- */
.twov2-pass-panel {
  text-align: center;
  max-width: 380px;
  width: 90%;
  padding: 48px 32px;
}
/* 1v1 local (hotseat) pass gate — fixed OPAQUE cover reusing the 2v2
   pass-panel chrome. Fully opaque on purpose: it hides the outgoing
   player's hand until the incoming player confirms. z-index above the
   board, modals, and phase banners; below the kw-tooltip (10000). */
.hotseat-pass-overlay {
  position: fixed; inset: 0; z-index: 3000;
  background: #000;
  display: flex; align-items: center; justify-content: center;
}
.hotseat-pass-overlay .twov2-pass-name {
  color: rgb(var(--theme-rgb, 79, 195, 247));
}
.twov2-pass-icon { font-size: 3rem; margin-bottom: 14px; }
.twov2-pass-heading {
  color: #88a0b8;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 10px;
}
.twov2-pass-name {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 10px;
}
.twov2-pass-sub {
  color: #6a7f96;
  font-size: 0.875rem;
  margin-bottom: 32px;
}
.twov2-ready-btn {
  padding: 14px 36px;
  font-size: 1rem;
}

/* --- In-Game Layout --- */
.twov2-game-wrap {
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px 80px;
  box-sizing: border-box;
}

/* Team health bars */
.twov2-health-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  max-width: 900px;
  margin-bottom: 10px;
  padding: 8px 12px;
  background: #000;
  border-radius: 8px;
  border: 1px solid #1e2d3e;
}
.twov2-hb-team {
  flex: 1;
  border: 1.5px solid;
  border-radius: 4px;
  padding: 6px 10px;
  text-align: center;
}
.twov2-hb-label {
  font-weight: 700;
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  display: block;
}
.twov2-hb-hp {
  font-size: 1rem;
  font-weight: 700;
  display: block;
}
.twov2-hb-round {
  color: #f5a623;
  font-weight: 700;
  font-size: 1rem;
  flex-shrink: 0;
}
.twov2-block-pip-row {
  display: flex;
  align-items: center;
  gap: 3px;
  justify-content: center;
  margin-top: 4px;
}
.twov2-block-pip {
  width: 10px; height: 10px;
  border-radius: 2px;
  background: #1e2d3e;
  border: 1px solid #2a3a50;
}
.twov2-pip-filled { background: var(--theme-accent-bright, #4fc3f7); border-color: var(--theme-accent-bright, #4fc3f7); }
.twov2-block-label { color: #88a0b8; font-size: 0.6875rem; margin-left: 4px; }

/* 8-lane board */
.twov2-board {
  display: flex;
  gap: 6px;
  width: 100%;
  max-width: 900px;
  margin-bottom: 10px;
  padding: 10px 8px;
  background: #000;
  border-radius: 8px;
  border: 1px solid #1e2d3e;
  overflow-x: auto;
}
.twov2-lane {
  flex: 1;
  min-width: 80px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.twov2-lane-num {
  color: #88a0b8;
  font-size: 0.75rem;
  font-weight: 700;
  text-align: center;
}
.twov2-lane-slot {
  width: 100%;
  min-height: 60px;
  border-radius: 4px;
  border: 1.5px solid #1e2d3e;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4px;
  box-sizing: border-box;
}
.twov2-lane-slot-empty { border-style: dashed; }
.twov2-lane-card {
  border-color: #2a3a50;
}
.twov2-card-name {
  color: var(--text-dim, #cfd6df);
  font-size: 0.6875rem;
  font-weight: 600;
  text-align: center;
  line-height: 1.2;
}
.twov2-card-stats {
  color: #f5a623;
  font-size: 0.75rem;
  font-weight: 700;
}
.twov2-lane-divider {
  width: 100%;
  height: 2px;
  background: #1e2d3e;
  border-radius: 2px;
}

/* Active player bar */
.twov2-active-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 900px;
  background: #000;
  border-radius: 8px;
  border: 1px solid #1e2d3e;
  padding: 8px 14px;
  margin-bottom: 10px;
  box-sizing: border-box;
}
.twov2-active-name {
  font-weight: 700;
  font-size: 1.0625rem;
}
.twov2-energy-display {
  color: #f5a623;
  font-weight: 700;
  font-size: 1rem;
}
.twov2-combat-label {
  color: #ff9800;
  font-size: 0.875rem;
  font-weight: 700;
  animation: pulse 1s ease-in-out infinite alternate;
}

/* Hand area */
.twov2-hand-wrap {
  width: 100%;
  max-width: 900px;
  background: #000;
  border-radius: 8px;
  border: 1px solid #1e2d3e;
  padding: 10px 12px;
  margin-bottom: 10px;
  box-sizing: border-box;
}
.twov2-hand-label {
  color: #88a0b8;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin-bottom: 8px;
}
.twov2-hand {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.twov2-hand-empty {
  color: #4a6070;
  font-size: 0.875rem;
  padding: 12px 0;
}
.twov2-hand-card {
  background: #111820;
  border: 1.5px solid #2a3a50;
  border-radius: 8px;
  padding: 8px 10px;
  cursor: pointer;
  min-width: 80px;
  transition: border-color 0.15s var(--ease-snap), background 0.15s var(--ease-snap);
  position: relative;
}
.twov2-card-play { border-color: var(--theme-accent-bright, #4fc3f7); }
.twov2-hand-card:hover.twov2-card-play { background: #0d1e2e; }
.twov2-card-selected {
  border-color: #ffd700 !important;
  background: #1e1a0a !important;
  box-shadow: 0 0 0 2px rgba(255,215,0,0.4);
}
.twov2-hcard-cost {
  position: absolute;
  top: 4px; left: 6px;
  color: #f5a623;
  font-weight: 700;
  font-size: 0.8125rem;
}
.twov2-hcard-name {
  color: var(--text-dim, #cfd6df);
  font-size: 0.8125rem;
  font-weight: 600;
  margin-top: 14px;
  margin-bottom: 4px;
}
.twov2-hcard-stats {
  font-size: 0.75rem;
  color: #88a0b8;
}
.twov2-tricks-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.twov2-trick-card {
  background: #0d1e14;
  border: 1.5px solid #1e5a2e;
  border-radius: 8px;
  padding: 8px 10px;
  cursor: pointer;
  min-width: 80px;
  position: relative;
}
.twov2-trick-card:hover { background: #122a1a; }
.twov2-trick-cost { color: #4caf50 !important; }

/* Lane selection */
.twov2-lane-select {
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 100%;
  max-width: 900px;
  background: #111820;
  border: 1.5px solid #ffd700;
  border-radius: 8px;
  padding: 12px;
  box-sizing: border-box;
  margin-bottom: 10px;
}
.twov2-ls-label {
  color: #ffd700;
  font-weight: 700;
  font-size: 0.875rem;
}
.twov2-ls-row {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: center;
}
.twov2-ls-btn {
  padding: 8px 12px;
  background: #1e2d3e;
  border: 1.5px solid var(--theme-accent-bright, #4fc3f7);
  border-radius: 4px;
  color: var(--theme-accent-bright, #4fc3f7);
  font-weight: 700;
  cursor: pointer;
  min-width: 64px;
}
.twov2-ls-btn:hover:not(:disabled) { background: #0d1e2e; }
.twov2-ls-blocked { opacity: 0.35; cursor: default; }
.twov2-ls-cancel {
  background: none;
  border: 1px solid #556;
  color: #88a0b8;
  border-radius: 4px;
  padding: 6px 14px;
  cursor: pointer;
  font-size: 0.8125rem;
}

/* Done button */
.twov2-done-btn {
  position: fixed;
  bottom: 20px;
  right: 20px;
  background: var(--theme-accent-bright, #4fc3f7);
  color: #000000;
  border: none;
  border-radius: 8px;
  padding: 12px 28px;
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  box-shadow: 0 4px 20px rgba(var(--theme-rgb, 79,195,247),0.4);
  z-index: 10;
}
.twov2-done-btn:hover { background: #7fd0ff; }

/* ===== 2v2 DRAFT SCREEN ===== */
.twov2-draft-heading {
  font-size: 1.1875rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.twov2-draft-sub {
  color: #aaa;
  font-size: 0.875rem;
  margin-bottom: 16px;
}
.twov2-draft-choices {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.twov2-draft-choice {
  background: #1a2433;
  border: 2px solid var(--theme-accent-bright, #4fc3f7);
  border-radius: 12px;
  color: var(--text-body, #e8f5ff);
  padding: 16px 20px;
  cursor: pointer;
  width: 160px;
  text-align: center;
  transition: background 0.15s var(--ease-snap), transform 0.1s var(--ease-snap);
}
.twov2-draft-choice:hover { background: #0d1e2e; transform: scale(1.04); }
.twov2-dc-name { font-weight: 700; font-size: 1rem; margin-bottom: 6px; }
.twov2-dc-stats { color: #ffd700; font-size: 0.8125rem; margin-bottom: 4px; }
.twov2-dc-cost  { color: #f97316; font-size: 0.75rem; margin-bottom: 6px; }
.twov2-dc-desc  { color: #88a0b8; font-size: 0.75rem; line-height: 1.3; }
.twov2-draft-progress {
  font-size: 0.75rem;
  color: #556;
  margin-top: 8px;
}

/* ===== 2v2 ONLINE LOBBY ===== */
.twov2-lobby-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
  margin: 18px 0;
}
.twov2-lobby-divider { color: #556; font-size: 0.8125rem; margin: 6px 0; }
.twov2-lobby-code-wrap {
  background: #000;
  border: 2px solid var(--theme-accent-bright, #4fc3f7);
  border-radius: 8px;
  padding: 14px 28px;
  text-align: center;
  margin: 14px 0;
}
.twov2-lobby-code-label { color: #888; font-size: 0.75rem; letter-spacing: 2px; }
.twov2-lobby-code { font-size: 2.5rem; font-weight: 700; color: var(--theme-accent-bright, #4fc3f7); letter-spacing: 8px; }
.twov2-lobby-code-sub { color: #556; font-size: 0.75rem; margin-top: 4px; }
.twov2-lobby-players {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 14px 0;
  min-width: 220px;
}
.twov2-lobby-player {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #1a1a2e;
  border: 1px solid #2a3a50;
  border-radius: 8px;
  padding: 8px 14px;
  color: #556;
}
.twov2-lobby-joined { border-color: var(--theme-accent-bright, #4fc3f7); color: var(--text-body, #e8f5ff); }
.twov2-lobby-slot  { font-size: 0.6875rem; font-weight: 700; color: #888; min-width: 24px; }
.twov2-lobby-name  { flex: 1; font-weight: 600; }
.twov2-lobby-check { color: #4caf50; font-weight: 700; }
.twov2-lobby-waiting { color: #888; font-size: 0.875rem; margin: 10px 0; }
.twov2-lobby-error { color: #f44336; font-size: 0.8125rem; margin: 8px 0; }

/* ===== ONLINE WAITING BANNER ===== */
.twov2-waiting-banner {
  text-align: center;
  color: #ffd700;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 0;
  animation: pulse 1.5s ease-in-out infinite;
}
@keyframes pulse {
  0%,100% { opacity: 1; }
  50% { opacity: 0.5; }
}

/* ===== 2v2 ONLINE BOARD MODE — lane-select strip ===== */
/* Appears below the tricks row when the local player has selected a card
   in the polished 1v1-style board view. Row of lane-number buttons + cancel. */
.twov2-board-lane-select {
  display: none;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  background: rgba(0,0,0,0.75);
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247),0.3);
  flex-wrap: wrap;
}
.twov2-bls-label {
  font-family: 'Rajdhani', sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #a8dcff;
  margin-right: 4px;
  flex-shrink: 0;
}
.twov2-bls-btn {
  width: 36px; height: 36px;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247),0.6);
  border-radius: 4px;
  background: rgba(var(--theme-rgb, 79,195,247),0.08);
  color: #a8dcff;
  font-family: 'Rajdhani', sans-serif;
  font-size: 0.875rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s var(--ease-snap), border-color 0.15s var(--ease-snap);
}
.twov2-bls-btn:hover:not(:disabled) {
  background: rgba(var(--theme-rgb, 79,195,247),0.25);
  border-color: var(--theme-accent-bright, #4fc3f7);
  color: #fff;
}
.twov2-bls-blocked {
  opacity: 0.35;
  cursor: not-allowed;
}
.twov2-bls-cancel {
  margin-left: 4px;
  padding: 0 10px; height: 36px;
  border: 1px solid rgba(231,76,60,0.5);
  border-radius: 4px;
  background: transparent;
  color: #ff8a7a;
  font-size: 0.8125rem;
  cursor: pointer;
  transition: background 0.15s var(--ease-snap);
}
.twov2-bls-cancel:hover { background: rgba(231,76,60,0.18); }

/* Waiting banner repositioned for board mode (sits inside #game-area) */
/* #twov2-waiting-banner removed — see UI._update2v2WaitingBanner. */

/* ============================================================
   GLOW-TEXT BUTTON LANGUAGE — STYLE CONTINUITY PASS (2026-07-11)
   User: "I love the main menu style of simple glow buttons when
   hovering — I want those everywhere." One shared treatment,
   mirroring .mm-mw3 .mm-option exactly: NO box/border/pill —
   plain spaced-caps Rajdhani text that scales 1.12 and glows
   neon on hover. Authored at the END of the file so it wins the
   cascade over every older boxed/pill button block. Families:
     • .md-back / .mode-back / .stats-back  (back chips, all screens)
     • .draft-quit-btn / .draft-undo-btn / .draft-mulligan-btn /
       .draft-settings-btn                  (draft control row)
     • .game-over-btn                       (Rematch / Main Menu)
   Deliberately NOT converted: settings cog + ? (icon circles),
   in-match DONE (primary action needs a strong tap target), and
   card-shaped tiles (they're cards, not buttons).
   ============================================================ */
.md-back, .mode-back, .stats-back,
.draft-quit-btn, .draft-undo-btn, .draft-mulligan-btn, .draft-settings-btn,
.game-over-btn {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  outline: none !important;
  padding: 10px 14px;
  font-family: 'Rajdhani', sans-serif !important;
  font-size: 13px; font-weight: 700 !important;
  letter-spacing: 2.5px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 78%, white);
  text-shadow: none;
  cursor: pointer;
  transition: color 200ms var(--ease-snap), text-shadow 200ms var(--ease-snap), transform 150ms var(--ease-spring, var(--ease-snap)), opacity 200ms var(--ease-snap);
}
/* Back chips read left-to-right → grow from the left edge like ← MENU;
   centered rows (draft controls, game-over actions) grow from center. */
.md-back, .mode-back, .stats-back { transform-origin: left center; }
.draft-quit-btn, .draft-undo-btn, .draft-mulligan-btn, .draft-settings-btn,
.game-over-btn { transform-origin: center center; }
.md-back:hover, .mode-back:hover, .stats-back:hover,
.draft-undo-btn:hover, .draft-mulligan-btn:hover, .draft-settings-btn:hover,
.game-over-btn:hover {
  background: none !important; border: none !important; box-shadow: none !important;
  color: #fff;
  transform: scale(1.12);
  text-shadow:
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
.md-back:active, .mode-back:active, .stats-back:active,
.draft-quit-btn:active, .draft-undo-btn:active, .draft-mulligan-btn:active,
.draft-settings-btn:active, .game-over-btn:active { transform: scale(1.02); }
/* Quit keeps its danger identity — red text + red glow, same motion. */
.draft-quit-btn {
  color: color-mix(in srgb, rgb(231,76,60) 72%, white);
}
.draft-quit-btn:hover {
  background: none !important; border: none !important; box-shadow: none !important;
  color: #fff;
  transform: scale(1.12);
  text-shadow: 0 0 12px rgba(231,76,60,0.85), 0 0 22px rgba(231,76,60,0.40);
}
/* Primary action on the result screen (Rematch) — brighter at rest so it
   still reads as THE next step without a filled pill. */
.game-over-btn.game-over-rematch {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 40%, white);
  text-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
/* Disabled states stay dim and motionless (mulligan spent, undo empty). */
.draft-mulligan-btn.mulligan-used, .draft-mulligan-btn[disabled],
.draft-undo-btn.undo-disabled, .draft-undo-btn[disabled] {
  opacity: 0.35 !important;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 45%, #8a96a5) !important;
  text-shadow: none !important;
  transform: none !important;
  cursor: default !important;
}
.draft-mulligan-btn.mulligan-used:hover, .draft-mulligan-btn[disabled]:hover,
.draft-undo-btn.undo-disabled:hover, .draft-undo-btn[disabled]:hover {
  transform: none !important; color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 45%, #8a96a5) !important;
  text-shadow: none !important;
}
/* The tron-fx JS chrome adds .tron-fx-breathe (keyframes that ANIMATE
   box-shadow) to these buttons — that's a box glow, so it's off here too.
   Text glow on hover is the only chrome, exactly like the menu. */
.md-back, .mode-back, .stats-back,
.draft-quit-btn, .draft-undo-btn, .draft-mulligan-btn, .draft-settings-btn,
.game-over-btn { animation: none !important; }
/* The themed draft-chrome rules use compound selectors
   (.draft-panel:not(.draft-tricks) .draft-mulligan-btn — specificity 0,3,0)
   which outrank the single-class strip above. Match them here (same
   specificity, later source order) so the box glow dies on the draft screen
   in BOTH card and trick drafts. The theme-tinted TEXT glow they set is kept —
   that IS the menu language. */
.draft-panel:not(.draft-tricks) .draft-mulligan-btn,
.draft-panel:not(.draft-tricks) .draft-settings-btn,
.draft-panel:not(.draft-tricks) .draft-undo-btn:not(.undo-disabled),
.draft-panel.draft-tricks .draft-mulligan-btn,
.draft-panel.draft-tricks .draft-settings-btn,
.draft-panel.draft-tricks .draft-undo-btn:not(.undo-disabled),
.draft-panel .draft-quit-btn,
.draft-panel:not(.draft-tricks) .draft-mulligan-btn:hover,
.draft-panel:not(.draft-tricks) .draft-settings-btn:hover,
.draft-panel:not(.draft-tricks) .draft-undo-btn:not(.undo-disabled):hover,
.draft-panel.draft-tricks .draft-mulligan-btn:hover,
.draft-panel.draft-tricks .draft-settings-btn:hover,
.draft-panel.draft-tricks .draft-undo-btn:not(.undo-disabled):hover,
.draft-panel .draft-quit-btn:hover {
  background: none !important;
  box-shadow: none !important;
  border: none !important;
}
/* NO SWEEP BAND, EVER, on glow-text buttons — the tron-fx system injects a
   .tron-sweep gradient that slides across on hover. Inside the old boxed
   buttons it read as a fill; on boxless glow-text it's a naked blue rectangle
   over the label (user: "I NEVER want to see the blue box"). Same kill the
   mw3 menu options got. */
.md-back > .tron-sweep, .mode-back > .tron-sweep, .stats-back > .tron-sweep,
.draft-quit-btn > .tron-sweep, .draft-undo-btn > .tron-sweep,
.draft-mulligan-btn > .tron-sweep, .draft-settings-btn > .tron-sweep,
.game-over-btn > .tron-sweep { display: none !important; }

/* ============================================================
   GLOBAL RULE — NO BOXES IN THE DRAFT ACTION ROW.
   User: "no boxes, this needs to be a global rule — just the text, and it
   magnifies." Every kill above is a hand-maintained LIST OF CLASS NAMES, which
   is exactly how a new button (.draft-audio-btn) shipped wearing a box: it
   inherited the boxed base rule and nobody had added its name to the four
   separate strip lists. Target the CONTAINER instead, so any button added to
   this row in future is boxless glow-text automatically and cannot regress.
   ============================================================ */
.draft-hud-actions button {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  /* TYPOGRAPHY LIVES HERE TOO. Dropping a button from the boxed base rule to
     un-box it also dropped its type, so it fell back to plain mixed-case sans
     next to MENU / BACK / MULLIGAN — un-Tron. The row's spaced-caps Rajdhani is
     part of the language, not part of the box, so it belongs on the container
     where every button (present and future) inherits it. */
  display: inline-flex; align-items: center; gap: 10px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px;
  /* 700, not the base rule's 800 — that's what MENU / BACK / MULLIGAN actually
     compute to once the later glow-text block lands, and the point is parity. */
  font-weight: 700;
  letter-spacing: 3.5px;
  text-transform: uppercase;
  cursor: pointer;
  padding: 8px 14px;
  transition: transform 0.15s var(--ease-snap), color 0.2s var(--ease-snap), text-shadow 0.2s var(--ease-snap);
}
.draft-hud-actions button > .tron-sweep { display: none !important; }
/* Grow + glow is the whole affordance — "just the text and it magnifies". */
.draft-hud-actions button:not([disabled]):not(.mulligan-used):not(.undo-disabled):hover {
  transform: scale(1.12);
  color: #fff;
  text-shadow:
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
/* Hand-audio button: themed text at rest, desaturated with a struck-through
   note once cues are hidden — same two states as the in-hand glyph. */
.draft-audio-btn {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 62%, white);
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
.draft-audio-btn.is-muted { color: #94a8c0; text-shadow: none; }
.draft-audio-btn.is-muted .mulligan-icon { position: relative; }
.draft-audio-btn.is-muted .mulligan-icon::after {
  content: '';
  position: absolute;
  left: -3px; right: -3px; top: 50%;
  height: 1.5px;
  background: currentColor;
  transform: rotate(-45deg);
}

/* ============================================================
   LIVING INK (2026-07-11) — user: "grey texts shouldn't happen in
   the menu, they should have color with life — everywhere, just
   don't touch the card text." Every steel-grey secondary text in
   menus/panels re-tints with the active theme so even dim copy
   glows faintly instead of reading dead. Card faces (desc / name /
   stats on actual cards) are deliberately untouched.
   ============================================================ */
.gal-note, .gal-slider, .gal-zoom-val, .gal-reset,
.gal-card-count, .gal-fname,
.gallery-audit-panel .aa-summary, .audio-audit-panel .aa-summary,
.gallery-audit-panel .aa-empty, .audio-audit-panel .aa-empty,
.stats-slash, .db-grid-slash, .db-deck-slash, .mh-hp-sep {
  color: color-mix(in srgb, rgb(var(--theme-rgb,79,195,247)) 48%, #dcebf8) !important;
}
.gal-note b { color: #8ef2ad !important; }
/* Crop captions on the art — theme-bright with a soft glow, not washed white. */
.gal-tag {
  color: color-mix(in srgb, rgb(var(--theme-rgb,79,195,247)) 55%, white);
  text-shadow: 0 1px 3px rgba(0,0,0,0.95), 0 0 8px rgba(var(--theme-rgb,79,195,247),0.5);
}
/* Delete × reads clearly RED (it's destructive), not washed pink. */
.gal-del { color: color-mix(in srgb, rgb(231,76,60) 82%, white); text-shadow: 0 0 6px rgba(231,76,60,0.4); }
/* Disabled states stay dim but TINTED — never steel grey. */
.gal-del-off { color: color-mix(in srgb, rgb(var(--theme-rgb,79,195,247)) 45%, #3a4654); }
.gal-move:disabled { opacity: 0.4; color: color-mix(in srgb, rgb(var(--theme-rgb,79,195,247)) 50%, #4a5866); }
.draft-mulligan-btn.mulligan-used, .draft-mulligan-btn[disabled],
.draft-undo-btn.undo-disabled, .draft-undo-btn[disabled] {
  color: color-mix(in srgb, rgb(var(--theme-rgb,79,195,247)) 50%, #9db5c9) !important;
}
/* Empty states — italic notices tint with the theme too. */
.md-empty, .stats-empty {
  color: color-mix(in srgb, rgb(var(--theme-rgb,79,195,247)) 42%, #c7d9e8) !important;
}
/* Search placeholders glow faintly instead of defaulting to browser grey. */
.gallery-audit-panel .aa-search::placeholder,
.audio-audit-panel .aa-search::placeholder {
  color: color-mix(in srgb, rgb(var(--theme-rgb,79,195,247)) 45%, #8fb4cc);
}

/* REAL CARD FACES in pickers + victory screen (2026-07-11) — chooser options
   and MVP/runner-up render through makeCardEl with the HAND face (rarity
   border + glow), so they're pixel-identical to a real card. They carry NO
   .choice-card class — the card's own cascade paints everything; the picker
   only adds a lift on hover. */
.choice-tray .choice-real { cursor: pointer; transition: transform 0.15s var(--ease-snap); }
.choice-tray .choice-real:hover { transform: translateY(-4px) scale(1.03); }
.go-mvp-slot .card.go-mvp-real { margin: 8px auto 4px; cursor: default; }

/* TRICK PORTRAIT SHINE (2026-07-11) — the old trick sheens painted on the
   card BACKGROUND (draft) or a card-level ::after (in-match), both of which
   ended up hidden behind/under the new opaque full-bleed portrait art (user:
   "the tricks don't have the shimmer over the card art when hovering").
   A dedicated .pt-shine layer INSIDE the portrait sweeps a purple-white band
   directly OVER the painting on hover — same feel as the hand-card sheen. */
.card-portrait .pt-shine {
  position: absolute; inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 2;   /* over the art + gem frame, under the name overlay (z 3) */
  background: linear-gradient(
    125deg,
    transparent 30%,
    rgba(255, 255, 255, 0.14) 45%,
    rgba(233, 213, 255, 0.36) 50%,
    rgba(255, 255, 255, 0.14) 55%,
    transparent 70%
  );
  background-size: 200% 200%;
  background-position: 100% 100%;
  transition: opacity 0.35s var(--ease-snap), background-position 0.9s var(--ease-out-soft);
}
.trick-card:hover .card-portrait .pt-shine,
.draft-card.trick-draft:hover .card-portrait .pt-shine {
  opacity: 1;
  background-position: 0% 0%;
}

/* ============================================================
   PURE-TOUCH DEVICES — kill every mouse-ism. On phones/tablets a
   tap synthesizes a :hover that STICKS until the next tap, so the
   hand-card enlarge, board-card enlarge, hover outlines, and shine
   all fired on tap and read as "the mouse is present" (user: "no
   cursor, no toggle, pure touch based" like any mobile TCG).
   Placed at the END of the file so equal-specificity overrides win
   by source order; transform needs !important to beat the hover
   rule's own !important. Tap now does NOTHING visual — the tap
   action itself is handled in JS (inspect), drag plays the card.
   ============================================================ */
@media (hover: none) {
  .hand-card-wrapper:hover .card.hand-card { transform: none !important; }
  /* The lift+scale now lives on the WRAPPER (see the magnify block), so the
     touch kill has to neutralise it there too — otherwise a sticky :hover on a
     phone would leave a hand card enlarged with no way to dismiss it. */
  .hand-card-wrapper:hover { transform: none !important; z-index: auto !important; }
  .card.enemy-card:hover,
  .card.ally-card:hover { transform: none !important; z-index: auto; }
  .lane .card:hover,
  .lane .card.ai-card:hover { outline-color: transparent; }
  .card:hover { outline-color: color-mix(in srgb, var(--card-edge) 12%, transparent); }
  .player-hand-section .hand-cards .card:hover { transform: none !important; box-shadow: none; }
  .trick-card:hover .card-portrait .pt-shine,
  .draft-card.trick-draft:hover .card-portrait .pt-shine { opacity: 0; }
}

/* ============================================================
   MOBILE LOW-POWER MODE — the phone "gets hot and eats battery"
   because of always-running ORNAMENTAL effects: full-screen
   animated turn-tint pseudo-elements, board sheens and motes,
   per-card idle vibe loops + perimeter shimmers, HUD breathing,
   and (worst of all) always-on backdrop-filter blur across the
   whole HUD. None of these convey game state — kill them on
   touch devices. Everything FUNCTIONAL stays: lane-active combat
   pulse, target highlights, playable-slot cue, hp-critical,
   lethal skull, status badges, spinners, thinking dots.
   ============================================================ */
@media (pointer: coarse), (hover: none), (max-width: 640px) {
  /* Full-screen ambient washes — biggest repaint areas on the page. */
  body::before,
  body.turn-ai::before,
  body.turn-player::after,
  body.turn-combat::before,
  body.turn-combat::after,
  /* Board-wide sheens + floating motes. */
  .board::before,
  .board-section::before,
  .board-mote,
  /* Per-card idle loops — every board card was animating forever. */
  .card.vibe-alien:not(.card-enter):not(.card-exit),
  .card.vibe-cosmic:not(.card-enter):not(.card-exit),
  .card.vibe-magnetic:not(.card-enter):not(.card-exit),
  .card.vibe-phase:not(.card-enter):not(.card-exit),
  .card.vibe-slasher:not(.card-enter):not(.card-exit),
  .card.vibe-speed:not(.card-enter):not(.card-exit),
  .card.vibe-symbiote:not(.card-enter):not(.card-exit),
  .card.vibe-titan:not(.card-enter):not(.card-exit),
  .tron-perimeter::after,
  .tron-shimmer,
  /* HUD / chrome breathing. */
  .hud-pill-main,
  .hud-round #round-num,
  .hud-count b,
  .tron-fx-breathe,
  .lane-number,
  .empty-hand::before,
  /* Menu idle loops (particles + slow hero zoom). */
  .mm-particle,
  .mm-mw3 .mm-hero-img,
  .mm-sideart-img {
    animation: none !important;
  }
  .mm-particle, .board-mote { display: none !important; }
  /* Always-on backdrop blur = constant GPU compositing over the whole
     viewport. The surfaces keep their dark rgba backgrounds, so nothing
     goes transparent — they just stop live-blurring what's behind them. */
  .hud-strip, .top-hud, .game-hud, .player-bar, .ai-bar,
  #game-area > div[class*="hud"], #game-area > div[class*="bar"],
  .card-inspect-backdrop, .ci-backdrop, .rl-modal-backdrop,
  .app-modal-overlay, .multiplayer-overlay, .first-run-overlay,
  .share-card-modal, .lane-recap,
  .decision-modal .choice-tray-backdrop {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }
}

/* ============================================================
   VISUAL POLISH BATCH A — trick reveal theater, titan entrance,
   face-damage vignette. All one-shot animations (no infinite
   loops — mobile battery stays safe); reduced-motion falls back
   in JS before any of these classes are applied.
   ============================================================ */

/* ---- Trick reveal theater ----------------------------------
   Opponent trick materializes center-screen at full size for a
   beat, then collapses into its effect. Replaces the corner
   toast as the "enemy trick" cue (toast remains the reduced-
   motion fallback). Pointer-events none — pure theater, never
   blocks input. No grey backdrop per the style language; the
   purple glow + scale does the separating. */
.trick-reveal {
  position: fixed; inset: 0;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  gap: 14px;
  z-index: 8600;
  pointer-events: none;
}
.trick-reveal-card {
  width: min(200px, 52vw);
  aspect-ratio: 5 / 7;
  border-radius: 8px;
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(rgba(10,2,16,0.20), rgba(10,2,16,0.20)),
    var(--portrait-bg, linear-gradient(160deg, #120a1c 0%, #000000 100%));
  background-size: cover;
  background-position: center 20%;
  border: 1px solid rgba(155, 89, 182, 0.95);
  box-shadow:
    0 0 18px rgba(155, 89, 182, 0.55),
    0 0 46px rgba(155, 89, 182, 0.25),
    inset 0 0 14px rgba(155, 89, 182, 0.20);
  transform: scale(0.55) translateY(14px);
  opacity: 0;
  animation: trickRevealIn 200ms var(--ease-out-soft) forwards;
}
.trick-reveal.tr-exit .trick-reveal-card {
  animation: trickRevealOut 220ms ease-in forwards;
}
@keyframes trickRevealIn {
  to { transform: scale(1) translateY(0); opacity: 1; }
}
@keyframes trickRevealOut {
  from { transform: scale(1); opacity: 1; }
  to   { transform: scale(0.90); opacity: 0; }
}
.trick-reveal-card .tr-cost {
  position: absolute; top: 6px; left: 6px;
  min-width: 26px; height: 26px; padding: 0 4px;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 16px;
  color: var(--text-dim, #ecd3f6);
  background: rgba(10, 2, 16, 0.85);
  border: 1px solid rgba(155, 89, 182, 0.9);
  border-radius: 4px;
  z-index: 3;
}
.trick-reveal-card .tr-name {
  position: absolute; left: 0; right: 0; bottom: 34%;
  padding: 4px 8px;
  text-align: center;
  font-family: 'Rajdhani', sans-serif; font-weight: 700;
  font-size: 16px; letter-spacing: 1.5px; text-transform: uppercase;
  /* Same story one line up: --text-body is #e8eef6, a neutral, so the lavender
     fallback here was dead too. Using it keeps the name and the description in
     one family instead of a neutral title over a tinted body. */
  color: #f2e8fa;
  background: linear-gradient(rgba(10,2,16,0), rgba(10,2,16,0.82) 30%, rgba(10,2,16,0.82) 70%, rgba(10,2,16,0));
  text-shadow: 0 0 10px rgba(155, 89, 182, 0.9);
  z-index: 2;
}
.trick-reveal-card .tr-desc {
  position: absolute; left: 0; right: 0; bottom: 0;
  max-height: 32%;
  overflow: hidden;
  padding: 6px 10px 8px;
  font-size: 11px; line-height: 1.35; text-align: center;
  /* NOT --text-mute. That token is rgb(156,170,180) — a desaturated blue-grey
     at 168 luminance — so the rule's own lavender fallback never applied and
     the trick's body text rendered grey on purple chrome. Owner: "no grey
     text." The AI's version of this same panel had already been lifted to
     --text-hi by a later rule; only the PLAYER's reveal was left behind.
     Set to the lavender the rule always intended, which is both brighter and
     tinted toward the trick's own colour rather than neutral. */
  color: #e3d3f0;
  background: rgba(10, 2, 16, 0.88);
  border-top: 1px solid rgba(155, 89, 182, 0.35);
  z-index: 2;
}
/* Diagonal light sweep across the art — one pass, then done. */
.trick-reveal-card .tr-sweep {
  position: absolute; inset: -30%;
  background: linear-gradient(115deg,
    transparent 42%, rgba(216, 180, 240, 0.35) 50%, transparent 58%);
  transform: translateX(-70%);
  animation: trickSweep 620ms ease-out 140ms forwards;
  z-index: 2;
  pointer-events: none;
}
@keyframes trickSweep { to { transform: translateX(70%); } }
.trick-reveal .tr-label {
  font-family: 'Rajdhani', sans-serif; font-weight: 700;
  font-size: 12px; letter-spacing: 3px; text-transform: uppercase;
  color: #b98fd0;
  text-shadow: 0 0 12px rgba(155, 89, 182, 0.8);
  opacity: 0;
  animation: trickLabelIn 240ms ease-out 90ms forwards;
}
.trick-reveal.tr-exit .tr-label { animation: trickRevealOut 200ms ease-in forwards; }
@keyframes trickLabelIn { to { opacity: 1; } }

/* ---- Titan entrance (cost 9-10 arrivals) -------------------
   Gold edge flare + one-pass light sweep on the landing card,
   plus a 2px screen shake (JS-gated behind reduced-motion).
   Rarity pips are already gold at this tier — the entrance
   makes the tier legible the moment the card hits the board. */
.card.titan-arrival {
  animation: titanFlare 950ms ease-out;
}
@keyframes titanFlare {
  0%   { box-shadow: 0 0 0 rgba(241, 196, 15, 0); }
  25%  { box-shadow: 0 0 26px rgba(241, 196, 15, 0.85), 0 0 60px rgba(241, 196, 15, 0.40), inset 0 0 18px rgba(241, 196, 15, 0.30); }
  100% { box-shadow: 0 0 0 rgba(241, 196, 15, 0); }
}
.card.titan-arrival::after {
  content: '';
  position: absolute; inset: 0;
  border-radius: inherit;
  overflow: hidden;
  background: linear-gradient(115deg,
    transparent 40%, rgba(255, 232, 160, 0.38) 50%, transparent 60%);
  background-size: 250% 100%;
  background-position: 120% 0;
  animation: titanSweep 700ms ease-out 120ms forwards;
  pointer-events: none;
  z-index: 5;
}
@keyframes titanSweep { to { background-position: -120% 0; } }
#game-area.titan-shake {
  animation: titanShake 300ms ease-out;
}
@keyframes titanShake {
  0%   { transform: translate(0, 0); }
  20%  { transform: translate(-2px, 1px); }
  40%  { transform: translate(2px, -1px); }
  60%  { transform: translate(-1px, -1px); }
  80%  { transform: translate(1px, 1px); }
  100% { transform: translate(0, 0); }
}

/* ---- Face-damage vignette ----------------------------------
   Screen-edge pulse toward whichever HP bar just took damage:
   red rising from the bottom for the player, falling from the
   top for the opponent. One-shot 500ms, pointer-events none. */
.face-dmg-vignette {
  position: fixed; inset: 0;
  z-index: 8400;
  pointer-events: none;
  opacity: 0;
  animation: faceDmgPulse 500ms ease-out forwards;
}
.face-dmg-vignette.face-dmg-player {
  background: linear-gradient(to top, rgba(231, 76, 60, 0.38), rgba(231, 76, 60, 0.10) 18%, transparent 34%);
}
.face-dmg-vignette.face-dmg-ai {
  background: linear-gradient(to bottom, rgba(231, 76, 60, 0.38), rgba(231, 76, 60, 0.10) 18%, transparent 34%);
}
@keyframes faceDmgPulse {
  0%   { opacity: 0; }
  22%  { opacity: 1; }
  100% { opacity: 0; }
}

/* ============================================================
   VISUAL POLISH BATCH B — status tints on the ART itself.
   The outer status glow (6533-6536) marks the card frame; these
   tint the portrait so the whole board's state reads at a
   glance, PvZ/Snap-style. Static filters + inset washes only —
   no animations, so mobile battery is untouched. The name
   overlay lives inside the portrait and inherits the filter,
   which reinforces the state without hurting legibility.
   ============================================================ */
.card.status-frozen .card-portrait {
  filter: saturate(0.45) brightness(1.05) brightness(var(--art-grade, 1));
  box-shadow:
    inset 0 0 26px rgba(140, 205, 255, 0.55),
    inset 0 0 8px rgba(205, 235, 255, 0.35);
}

/* ============================================================
   FREEZE FX — persistent ice sheet + freeze-in burst + thaw shatter
   ============================================================
   .card-frost is injected into the portrait of a frozen card (makeCardEl). It
   layers a frosted-glass sheet, crystal bloom in the corners and a slow
   diagonal shimmer, so a frozen card reads as ENCASED, not just blue-glowing.
   The one-shot beats (.fx-freeze-burst on land, .fx-thaw-shatter on thaw) are
   spawned into #signature-fx-layer by the engine — see UI._fxFreezeStrike /
   _fxThaw. The shimmer is gated off under reduced-motion / low-fx below; the
   static ice sheet always stays, because it is the informative half of the cue
   and a frozen card must still read as frozen. */
.card-frost {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  z-index: 4;                 /* over the art, under the name overlay (z-index varies) */
  overflow: hidden;
  /* Frosted sheet + crystal bloom from the corners. */
  background:
    radial-gradient(120% 90% at 12% 8%,  rgba(214,240,255,0.55) 0%, rgba(214,240,255,0) 42%),
    radial-gradient(120% 90% at 88% 92%, rgba(190,228,255,0.45) 0%, rgba(190,228,255,0) 46%),
    linear-gradient(160deg, rgba(150,205,245,0.24) 0%, rgba(120,180,230,0.30) 100%);
  mix-blend-mode: screen;
  box-shadow:
    inset 0 0 0 1px rgba(220,244,255,0.35),
    inset 0 0 18px rgba(180,225,255,0.30);
  /* Falls off at the portrait's bottom edge rather than stopping square. The
     ice used to end in a hard horizontal line where the portrait does, which
     read as a rectangle laid over the card instead of the card being frozen.
     Only the last sliver is touched — the sheet, the cracks and the corner
     bloom are all untouched above it. */
  -webkit-mask-image: linear-gradient(180deg, #000 0%, #000 84%, rgba(0,0,0,0.55) 94%, rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg, #000 0%, #000 84%, rgba(0,0,0,0.55) 94%, rgba(0,0,0,0) 100%);
}
/* Hairline cracks — thin light lines fanning across the ice. */
.card-frost::before {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  background:
    linear-gradient(58deg,  transparent 48.6%, rgba(230,246,255,0.5) 49.4%, transparent 50.2%),
    linear-gradient(-36deg, transparent 62.4%, rgba(210,238,255,0.4) 63.0%, transparent 63.6%),
    linear-gradient(14deg,  transparent 33.5%, rgba(200,232,255,0.34) 34.0%, transparent 34.5%);
  opacity: 0.9;
}
/* Slow shimmer sweep — a highlight gliding across the ice. */
.card-frost::after {
  content: "";
  position: absolute; top: -60%; left: -60%;
  width: 60%; height: 220%;
  transform: rotate(24deg);
  background: linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.45) 50%, rgba(255,255,255,0) 100%);
  animation: frostShimmer 3.4s ease-in-out infinite;
}
@keyframes frostShimmer {
  0%, 100% { transform: translateX(-40%) rotate(24deg); opacity: 0; }
  45%      { opacity: 0.7; }
  60%      { transform: translateX(340%) rotate(24deg); opacity: 0; }
}
/* The shimmer had NO prefers-reduced-motion rule at all — it was gated only by
   the coarse-pointer/<=640px block and body.low-fx further down the sheet, so a
   desktop user who had asked the OS for reduced motion still got a 3.4s loop
   sweeping every frozen card. The matching low-fx rule already exists in that
   block; this is the half that was missing. */
@media (prefers-reduced-motion: reduce) {
  .card-frost::after { animation: none !important; }
}

/* Freeze-in burst — frost detonates over the card the instant it freezes. */
.fx-freeze-burst {
  position: fixed;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 90;
  border-radius: 12px;
  background:
    radial-gradient(closest-side, rgba(255,255,255,0.9) 0%, rgba(190,230,255,0.55) 40%, rgba(150,205,245,0) 72%);
  box-shadow: 0 0 26px rgba(190,230,255,0.7);
  animation: fxFreezeBurst 720ms var(--ease-out-soft, cubic-bezier(0.16,1,0.3,1)) forwards;
}
/* Radiating spikes drawn as a conic sheen inside the burst. */
.fx-freeze-burst::before {
  content: "";
  position: absolute; inset: 8%;
  border-radius: inherit;
  background: conic-gradient(from 0deg,
    rgba(220,244,255,0.55) 0deg, transparent 18deg, rgba(220,244,255,0.55) 45deg, transparent 63deg,
    rgba(220,244,255,0.55) 90deg, transparent 108deg, rgba(220,244,255,0.55) 135deg, transparent 153deg,
    rgba(220,244,255,0.55) 180deg, transparent 198deg, rgba(220,244,255,0.55) 225deg, transparent 243deg,
    rgba(220,244,255,0.55) 270deg, transparent 288deg, rgba(220,244,255,0.55) 315deg, transparent 333deg);
  mix-blend-mode: screen;
}
@keyframes fxFreezeBurst {
  0%   { transform: translate(-50%,-50%) scale(0.35); opacity: 0; }
  25%  { opacity: 1; }
  100% { transform: translate(-50%,-50%) scale(1.15); opacity: 0; }
}
/* The card shudders as it locks up. */
.card-freeze-shudder { animation: cardFreezeShudder 480ms ease-out; }
@keyframes cardFreezeShudder {
  0%,100% { transform: translate(0,0); }
  15% { transform: translate(-2px, 1px); }
  30% { transform: translate(2px, -1px); }
  45% { transform: translate(-1.5px, -1px); }
  60% { transform: translate(1.5px, 1px); }
  75% { transform: translate(-1px, 0); }
}

/* Thaw shatter — ice shards fling off when the freeze wears off. */
.fx-thaw-shatter { position: fixed; pointer-events: none; z-index: 90; }
.fx-thaw-shatter i {
  position: absolute; left: 50%; top: 50%;
  width: 7px; height: 9px;
  margin: -4px 0 0 -3px;
  background: linear-gradient(135deg, rgba(255,255,255,0.95), rgba(180,225,255,0.65));
  clip-path: polygon(50% 0, 100% 38%, 78% 100%, 22% 100%, 0 38%);
  box-shadow: 0 0 6px rgba(200,235,255,0.8);
  animation: fxThawShard 560ms ease-out forwards;
  animation-delay: var(--sd, 0ms);
  opacity: 0;
}
@keyframes fxThawShard {
  0%   { transform: translate(0,0) rotate(0deg) scale(1); opacity: 0.95; }
  100% { transform: translate(var(--sx,0), calc(var(--sy,0) + 18px)) rotate(var(--sr,120deg)) scale(0.5); opacity: 0; }
}
/* ============================================================
   BURN FX — a card that is on fire (Boiler Room / Burning)
   ============================================================
   .card-burn is injected into the portrait of a burning card (makeCardEl):
   a smouldering edge glow, a heat shimmer, and embers (its <i> children)
   drifting up off the art. The ignite BURST (.fx-burn-ignite) and heat flinch
   are one-shots fired from the engine (UI._fxBurnIgnite). All motion gated off
   under reduced-motion / low-fx below; the static ember tint stays as a plain
   state cue. Mirrors the frost block above. */
.card-burn {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  z-index: 4;                 /* over the art, same layer as frost */
  overflow: hidden;
  /* Smouldering wash — hot at the bottom, licking up the sides. The whole
     glow FLICKERS like real firelight (opacity + inner-shadow pulse). */
  /* THE HOT ZONE SITS INSIDE THE ELEMENT, NOT PAST ITS EDGE.
     These radials used to be centred at 50% 112% and 15/85% 100% — below and
     exactly on the bottom edge. .card-burn is inset:0 on the portrait with
     overflow:hidden, so that put PEAK BRIGHTNESS on the clip line, and the
     portrait's bottom edge falls mid-card. The result was a hard horizontal
     cut from full orange straight to black, which read as a rendering seam
     rather than as fire. Pulling the centres up to 94/88% peaks the wash in
     the lower third of the art, already falling off by the boundary. */
  background:
    radial-gradient(130% 78% at 50% 80%, rgba(255,150,45,0.62) 0%, rgba(255,90,20,0) 62%),
    radial-gradient(70% 48% at 15% 76%, rgba(255,120,30,0.34) 0%, rgba(255,90,20,0) 64%),
    radial-gradient(70% 48% at 85% 76%, rgba(255,120,30,0.34) 0%, rgba(255,90,20,0) 64%),
    linear-gradient(0deg, rgba(150,35,0,0) 0%, rgba(150,35,0,0.30) 20%, rgba(255,120,30,0) 62%);
  mix-blend-mode: screen;
  /* The inset -20px bottom glow was the hardest edge of the lot: a bright band
     painted along the inside of the very edge being cut. Gone; only the thin
     ember rim survives. */
  box-shadow: inset 0 0 0 1px rgba(255,180,80,0.32);
  /* THE FADE MUST START BELOW THE FIRE, NOT THROUGH IT.
     The mask and the hot zone are one decision, not two: feather too early and
     it erases the flames it was meant to soften, which inverts the effect and
     makes the light look like it is coming from above. Peak sits at 76-80%,
     the mask holds solid to 80%, and only the tail past it dissolves — so the
     fire still reads as rising from the lower art and simply runs out of fuel
     before the portrait's edge instead of being cut off at full brightness.
     Applies to the flame tongues and embers too, since they are children;
     embers now fade IN as they rise off the bottom rather than popping on. */
  -webkit-mask-image: linear-gradient(180deg, #000 0%, #000 80%, rgba(0,0,0,0.55) 92%, transparent 100%);
  mask-image: linear-gradient(180deg, #000 0%, #000 80%, rgba(0,0,0,0.55) 92%, transparent 100%);
  animation: burnFlicker 0.42s ease-in-out infinite alternate;
}
/* Heat shimmer — a warm haze breathing over the art. */
.card-burn::before {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  background: radial-gradient(95% 65% at 50% 100%, rgba(255,205,130,0.40) 0%, rgba(255,150,50,0) 62%);
  mix-blend-mode: screen;
  animation: burnHeat 1.6s ease-in-out infinite;
}
/* Flame licks — three tongues of fire dancing along the bottom edge, drawn as
   an animated conic/gradient mask that wavers left-right. */
.card-burn::after {
  content: "";
  position: absolute; left: -8%; right: -8%; bottom: -6px; height: 46%;
  border-radius: inherit;
  background:
    radial-gradient(38% 100% at 22% 100%, rgba(255,180,60,0.85) 0%, rgba(255,110,20,0.35) 42%, rgba(255,90,20,0) 72%),
    radial-gradient(34% 92% at 52% 100%, rgba(255,225,140,0.9) 0%, rgba(255,130,30,0.4) 40%, rgba(255,90,20,0) 70%),
    radial-gradient(38% 100% at 80% 100%, rgba(255,170,55,0.85) 0%, rgba(255,110,20,0.35) 42%, rgba(255,90,20,0) 72%);
  mix-blend-mode: screen;
  filter: blur(1.5px);
  animation: burnFlames 0.9s ease-in-out infinite;
}
/* Embers — glowing motes that rise, drift sideways, and wink out. */
.card-burn i {
  position: absolute;
  bottom: -6px;
  width: 5px; height: 5px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff2d2 0%, #ffb347 45%, #ff7a1e 70%, rgba(255,90,20,0) 100%);
  box-shadow: 0 0 8px rgba(255,170,70,1), 0 0 3px rgba(255,240,200,0.9);
  opacity: 0;
  animation: burnEmber 1.7s ease-in infinite;
}
.card-burn i:nth-child(1) { left: 16%; --edx:-10px; animation-delay: 0s;    transform: scale(1.15); }
.card-burn i:nth-child(2) { left: 36%; --edx: 8px;  animation-delay: 0.42s; transform: scale(0.8); }
.card-burn i:nth-child(3) { left: 52%; --edx:-6px;  animation-delay: 0.8s;  transform: scale(1.3); }
.card-burn i:nth-child(4) { left: 68%; --edx: 12px; animation-delay: 0.25s; transform: scale(0.95); }
.card-burn i:nth-child(5) { left: 84%; --edx:-9px;  animation-delay: 1.05s; transform: scale(1.1); }
@keyframes burnFlicker {
  0%   { opacity: 0.82; box-shadow: inset 0 0 0 1px rgba(255,180,80,0.40), inset 0 -18px 24px rgba(255,110,20,0.48); }
  100% { opacity: 1;    box-shadow: inset 0 0 0 1px rgba(255,200,100,0.55), inset 0 -24px 32px rgba(255,120,25,0.68); }
}
@keyframes burnHeat {
  0%, 100% { opacity: 0.4; }
  50%      { opacity: 0.8; }
}
@keyframes burnFlames {
  0%, 100% { transform: scaleY(1)    translateX(0);    opacity: 0.85; }
  30%      { transform: scaleY(1.18) translateX(-3px); opacity: 1; }
  65%      { transform: scaleY(0.92) translateX(3px);  opacity: 0.9; }
}
@keyframes burnEmber {
  0%   { transform: translate(0,0) scale(var(--es,1)); opacity: 0; }
  12%  { opacity: 1; }
  70%  { opacity: 1; }
  100% { transform: translate(var(--edx,0), -78px) scale(0.25); opacity: 0; }
}

/* ============================================================
   TAUNT AURA — a magnetic "pull" on a card forcing attacks onto itself.
   Persistent while tauntTurns > 0 (injected into the portrait by makeCardEl,
   board cards only), same layer/pattern as frost & burn. Gold — the same
   colour the attack telegraph uses for taunt-redirected lines. The two <i>
   are rings that contract INWARD, reading as "everything is dragged here."
   ============================================================ */
.card-taunt {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  z-index: 4;
  overflow: hidden;
  /* A steady gold rim + a soft central draw-in glow. */
  box-shadow:
    inset 0 0 0 1px rgba(255,205,70,0.55),
    inset 0 0 26px rgba(255,180,40,0.30);
  background: radial-gradient(120% 90% at 50% 50%, rgba(255,190,50,0) 52%, rgba(255,190,50,0.16) 100%);
  animation: tauntRim 1.5s ease-in-out infinite;
}
/* Contracting pull rings — spawn large + faint, shrink and brighten toward the
   centre, so the eye is drawn IN (the opposite of a ripple going out). */
.card-taunt i {
  position: absolute;
  left: 50%; top: 50%;
  width: 150%; height: 150%;
  margin: -75% 0 0 -75%;
  border-radius: 50%;
  border: 1.5px solid rgba(255,200,60,0.85);
  box-shadow: 0 0 10px rgba(255,190,50,0.6);
  opacity: 0;
  animation: tauntPull 1.9s ease-in infinite;
}
.card-taunt i:nth-child(2) { animation-delay: 0.95s; }
@keyframes tauntRim {
  0%, 100% { box-shadow: inset 0 0 0 1px rgba(255,205,70,0.45), inset 0 0 22px rgba(255,180,40,0.24); }
  50%      { box-shadow: inset 0 0 0 1px rgba(255,220,100,0.75), inset 0 0 30px rgba(255,190,45,0.42); }
}
@keyframes tauntPull {
  0%   { transform: scale(1);    opacity: 0; }
  25%  { opacity: 0.8; }
  100% { transform: scale(0.18); opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .card-taunt { animation: none !important; }
  .card-taunt i { display: none; }
}
body.low-fx .card-taunt { animation: none !important; }
body.low-fx .card-taunt i { display: none; }

/* ============================================================
   FEAR FX — dread closing in on a card that now attacks ITSELF
   ============================================================
   .card-fear is injected into the portrait of a feared card (makeCardEl),
   same shell and same z-layer as frost / burn / taunt.

   What it has to say is "the threat is inside this card", so it is built as
   the exact inverse of taunt: taunt pushes gold rings OUTWARD to advertise
   itself, fear presses darkness INWARD until the art is squeezed into a
   shrinking pool of light. Crimson rather than the keyword's flat grey,
   because the portrait tint this sits on top of is already
   rgba(200,40,60) — the overlay finishes a cue that was half there.

   Weighted to the TOP and SIDES, deliberately lighter along the bottom: the
   whole family sits at z-index 4, which is ABOVE .card-name-overlay (z-index
   3), and unlike frost and burn this overlay REMOVES light. Darkening the
   bottom edge evenly would push the card's own name toward unreadable. */
.card-fear {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  z-index: 4;                 /* over the art, same layer as frost/burn/taunt */
  overflow: hidden;
  /* No mix-blend-mode: frost and burn screen because they ADD light, this
     subtracts it, so it composites normally. */
  background:
    /* Wide, slow falloff. The first pass stepped from clear to dark over a
       narrow band, which drew a visible dark RING on the art instead of
       reading as gloom — that hard shoulder is what made it look stark. */
    radial-gradient(140% 105% at 50% 30%, rgba(0,0,0,0) 12%, rgba(24,0,8,0.20) 48%,
                    rgba(18,0,6,0.44) 76%, rgba(10,0,4,0.66) 100%),
    linear-gradient(180deg, rgba(14,0,5,0.38) 0%, rgba(0,0,0,0) 46%);
  box-shadow:
    inset 0 0 0 1px rgba(150,25,45,0.26),
    inset 0 0 30px rgba(90,0,18,0.44);
  /* Thinned out across the name band. Frost and burn ADD light, so sitting at
     z-index 4 over .card-name-overlay (z-index 3) costs them nothing; this one
     subtracts it, and at full strength it dimmed the card's own name to
     unreadable. Masking the overlay — pseudo-elements included, since a mask
     applies to the element as a group — is the fix that stays inside fear
     rather than re-layering the whole family for one member. */
  /* Two jobs. It thins across the name band (see above), and it FADES THE
     OVERLAY OUT at the portrait's bottom edge, so the effect dissolves into
     the card instead of stopping dead in a hard horizontal line where the
     portrait ends. That line was the stark part — an overlay that terminates
     square reads as a graphic pasted on top; one that falls off reads as
     something happening TO the art. */
  -webkit-mask-image: linear-gradient(180deg,
    #000 0%, #000 60%, rgba(0,0,0,0.34) 74%, rgba(0,0,0,0.30) 86%,
    rgba(0,0,0,0.12) 95%, rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg,
    #000 0%, #000 60%, rgba(0,0,0,0.34) 74%, rgba(0,0,0,0.30) 86%,
    rgba(0,0,0,0.12) 95%, rgba(0,0,0,0) 100%);
}
/* Shapes reaching in from the upper corners — the thing it is afraid of. */
.card-fear::before {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  background:
    radial-gradient(62% 46% at 0% 0%,    rgba(0,0,0,0.52) 0%, rgba(0,0,0,0) 76%),
    radial-gradient(62% 46% at 100% 0%,  rgba(0,0,0,0.52) 0%, rgba(0,0,0,0) 76%),
    radial-gradient(54% 38% at 0% 100%,  rgba(0,0,0,0.26) 0%, rgba(0,0,0,0) 78%),
    radial-gradient(54% 38% at 100% 100%,rgba(0,0,0,0.26) 0%, rgba(0,0,0,0) 78%);
}
/* ONE loop, opacity and transform only so it stays on the compositor — the
   dark breathing inward, like the card flinching from itself. Deliberately
   slow: this is dread, not panic, and a fast loop on a persistent overlay is
   exactly the battery cost the low-fx toggle exists to remove. */
.card-fear::after {
  content: "";
  position: absolute; inset: -14%;
  border-radius: inherit;
  background: radial-gradient(closest-side, rgba(0,0,0,0) 46%, rgba(120,0,26,0.17) 78%, rgba(0,0,0,0.34) 100%);
  animation: fearClose 2.8s ease-in-out infinite;
}
@keyframes fearClose {
  0%, 100% { transform: scale(1.06); opacity: 0.5; }
  50%      { transform: scale(0.94); opacity: 0.9; }
}
/* Gated from the start, both halves — the mistake frost and burn each made in
   their own way. The static vignette stays under both: it is the informative
   half of the cue, only the breathing stops. */
@media (prefers-reduced-motion: reduce) {
  .card-fear::after { animation: none !important; }
}
body.low-fx .card-fear::after { animation: none !important; }

/* ============================================================
   MIND CONTROL FX — the card is being worked from outside
   ============================================================
   .card-mind-ctrl is injected into the portrait of a mind-controlled card
   (makeCardEl), same shell and z-layer as frost / burn / taunt / fear.

   Puppet STRINGS, drawn as hairlines dropping from the top edge into the art.
   Every other member of the family owns a different direction, which is what
   keeps five overlays legible on one board: frost is diagonal cracks, burn
   rises from the bottom, taunt contracts in rings, fear gathers in the
   corners. Nothing else uses verticals, so this reads as its own thing at a
   glance even at board size.

   Violet, matching the rgba(155,89,182) already on this status's portrait
   tint, rather than the keyword's badge yellow — same call as fear, where the
   overlay finishes the cue the tint had started. */
.card-mind-ctrl {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  z-index: 4;                 /* over the art, same layer as the rest */
  overflow: hidden;
  background:
    radial-gradient(120% 70% at 50% 0%, rgba(155,89,182,0.34) 0%, rgba(120,60,160,0) 62%),
    linear-gradient(180deg, rgba(140,70,180,0.22) 0%, rgba(90,40,130,0) 55%);
  mix-blend-mode: screen;
  box-shadow:
    inset 0 0 0 1px rgba(190,140,225,0.26),
    inset 0 0 26px rgba(140,70,180,0.34);
  /* Falls off at the portrait's bottom edge instead of stopping square, the
     same dissolve frost and fear use. */
  -webkit-mask-image: linear-gradient(180deg, #000 0%, #000 78%, rgba(0,0,0,0.5) 92%, rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg, #000 0%, #000 78%, rgba(0,0,0,0.5) 92%, rgba(0,0,0,0) 100%);
}
/* The strings. Uneven lengths and spacing so they read as hanging rather than
   as a ruled grid. */
.card-mind-ctrl::before {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  background:
    linear-gradient(180deg, rgba(214,170,245,0.62) 0%, rgba(214,170,245,0) 58%),
    linear-gradient(180deg, rgba(196,146,235,0.52) 0%, rgba(196,146,235,0) 74%),
    linear-gradient(180deg, rgba(214,170,245,0.58) 0%, rgba(214,170,245,0) 46%);
  background-repeat: no-repeat;
  background-size: 1px 100%, 1px 100%, 1px 100%;
  background-position: 27% 0, 51% 0, 73% 0;
}
/* ONE loop, opacity only — the hold tightening and slackening. */
.card-mind-ctrl::after {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  background: radial-gradient(90% 55% at 50% 6%, rgba(205,150,240,0.30) 0%, rgba(160,90,200,0) 66%);
  animation: mindPull 3.1s ease-in-out infinite;
}
@keyframes mindPull {
  0%, 100% { opacity: 0.35; }
  50%      { opacity: 0.85; }
}
@media (prefers-reduced-motion: reduce) {
  .card-mind-ctrl::after { animation: none !important; }
}
body.low-fx .card-mind-ctrl::after { animation: none !important; }

/* ============================================================
   INVINCIBLE FX — an aegis the card is sealed inside
   ============================================================
   .card-invincible is injected into the portrait of a card with
   invincibleTurns > 0 (makeCardEl), same shell and z-layer as the rest.

   Note this status had NO card-level styling whatsoever before now: the
   status-invincible class was being added in makeCardEl and no rule in the
   sheet ever matched it, so the only cue was the badge star. For the status
   that says "cannot die", that was the biggest hole in the set.

   Its direction is the PERIMETER. Every member owns one so several can stack
   and still be told apart — frost cuts diagonals, burn rises from the bottom,
   taunt contracts in rings, fear gathers in the corners, mind control hangs
   verticals — and nothing was using the edge. The chamfered corner plates read
   as armour rather than as another glow, which is what keeps it from reading
   like taunt: taunt's rings MOVE inward, this shell is fixed and only
   brightens.

   Cold platinum (#e8eef6, the keyword's own colour) so it never reads as
   taunt's gold, and the centre stays clear so the art is undimmed — being
   invincible should not cost you the ability to see the card. */
.card-invincible {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  z-index: 4;
  overflow: hidden;
  background:
    radial-gradient(132% 102% at 50% 50%, rgba(0,0,0,0) 54%,
                    rgba(226,240,248,0.14) 84%, rgba(255,255,255,0.26) 100%);
  mix-blend-mode: screen;
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.50),
    inset 0 0 20px rgba(210,235,255,0.24);
  -webkit-mask-image: linear-gradient(180deg, #000 0%, #000 82%, rgba(0,0,0,0.5) 93%, rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg, #000 0%, #000 82%, rgba(0,0,0,0.5) 93%, rgba(0,0,0,0) 100%);
}
/* Chamfered corner plates. Each is one tile carrying the diagonal that cuts
   its own corner — the 50% isoline of a corner-to-corner gradient axis is the
   opposite diagonal, which is exactly the cut we want.
   These were briefly promoted to every card and then reverted: at hand-card
   size the diagonals cut straight through the cost badge and both stat orbs.
   They work HERE because the aegis is board-only, where the card is larger and
   the corners are clear. */
.card-invincible::before {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  --p: rgba(255,255,255,0.55);
  background:
    linear-gradient(to bottom right, transparent calc(50% - 0.6px), var(--p) calc(50% - 0.6px),
                    var(--p) calc(50% + 0.6px), transparent calc(50% + 0.6px)) 0    0    / 24px 24px no-repeat,
    linear-gradient(to bottom left,  transparent calc(50% - 0.6px), var(--p) calc(50% - 0.6px),
                    var(--p) calc(50% + 0.6px), transparent calc(50% + 0.6px)) 100% 0    / 24px 24px no-repeat,
    linear-gradient(to top right,    transparent calc(50% - 0.6px), var(--p) calc(50% - 0.6px),
                    var(--p) calc(50% + 0.6px), transparent calc(50% + 0.6px)) 0    100% / 24px 24px no-repeat,
    linear-gradient(to top left,     transparent calc(50% - 0.6px), var(--p) calc(50% - 0.6px),
                    var(--p) calc(50% + 0.6px), transparent calc(50% + 0.6px)) 100% 100% / 24px 24px no-repeat;
}
/* ONE loop, opacity only — the shield holding, not pulsing at you. */
.card-invincible::after {
  content: "";
  position: absolute; inset: 0;
  border-radius: inherit;
  box-shadow:
    inset 0 0 0 1.5px rgba(255,255,255,0.80),
    inset 0 0 15px rgba(215,240,255,0.45);
  animation: aegisHold 3.4s ease-in-out infinite;
}
@keyframes aegisHold {
  0%, 100% { opacity: 0.42; }
  50%      { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .card-invincible::after { animation: none !important; }
}
body.low-fx .card-invincible::after { animation: none !important; }

/* ============================================================
   DAMAGE IMMUNITY FX — the hit does not land at all
   ============================================================
   Deliberately not a second aegis. Invincible ABSORBS a lethal hit, so it is
   a shell hugging the perimeter; this REFUSES damage outright, so it reads as
   a field filling the whole surface. Three gradient axes 60 degrees apart tile
   into the hex lattice a force field is always drawn with, and full-surface is
   the one direction the family had not spent (frost runs diagonal, burn rises,
   taunt contracts, fear gathers at the corners, invincible hugs the edge). */
.card-dmg-immune {
  position: absolute; inset: 0;
  pointer-events: none; border-radius: inherit;
  z-index: 4; overflow: hidden;
  background: radial-gradient(120% 96% at 50% 50%, rgba(211,84,0,0) 42%,
              rgba(211,84,0,0.16) 78%, rgba(255,140,50,0.26) 100%);
  mix-blend-mode: screen;
  box-shadow: inset 0 0 0 1px rgba(255,150,60,0.40), inset 0 0 22px rgba(211,84,0,0.28);
  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 80%,rgba(0,0,0,0.5) 92%,rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg,#000 0%,#000 80%,rgba(0,0,0,0.5) 92%,rgba(0,0,0,0) 100%);
}
.card-dmg-immune::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  --l: rgba(255,160,70,0.17);
  background:
    repeating-linear-gradient(60deg,  transparent 0 13px, var(--l) 13px 14px),
    repeating-linear-gradient(-60deg, transparent 0 13px, var(--l) 13px 14px),
    repeating-linear-gradient(0deg,   transparent 0 13px, var(--l) 13px 14px);
  mix-blend-mode: screen;
}
/* ONE loop, opacity only — the field energised, not strobing. */
.card-dmg-immune::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  box-shadow: inset 0 0 0 1.5px rgba(255,170,80,0.68), inset 0 0 16px rgba(255,120,30,0.38);
  animation: fieldHold 3.1s ease-in-out infinite;
}
@keyframes fieldHold { 0%, 100% { opacity: 0.38; } 50% { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .card-dmg-immune::after { animation: none !important; } }
body.low-fx .card-dmg-immune::after { animation: none !important; }

/* ============================================================
   EVADE FX — the card is already half somewhere else
   ============================================================
   Lateral displacement, which nothing else in the family uses. The weight sits
   on the LEFT AND RIGHT edges rather than anywhere central, so the card reads
   as mid-sidestep instead of merely glowing green. */
.card-evade {
  position: absolute; inset: 0;
  pointer-events: none; border-radius: inherit;
  z-index: 4; overflow: hidden;
  background:
    linear-gradient(90deg,  rgba(46,204,113,0.24) 0%, rgba(46,204,113,0) 22%),
    linear-gradient(270deg, rgba(46,204,113,0.24) 0%, rgba(46,204,113,0) 22%);
  mix-blend-mode: screen;
  box-shadow: inset 0 0 0 1px rgba(90,230,150,0.30);
  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 78%,rgba(0,0,0,0.45) 92%,rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg,#000 0%,#000 78%,rgba(0,0,0,0.45) 92%,rgba(0,0,0,0) 100%);
}
/* The afterimage it leaves slipping the hit. */
.card-evade::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  background: repeating-linear-gradient(90deg, transparent 0 6px, rgba(120,255,180,0.11) 6px 7px);
  mix-blend-mode: screen;
}
/* ONE loop, transform + opacity only so it stays on the compositor. */
.card-evade::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  background: linear-gradient(90deg, transparent 0%, rgba(150,255,200,0.18) 45%, transparent 90%);
  mix-blend-mode: screen;
  animation: evadeSlip 2.6s ease-in-out infinite;
}
@keyframes evadeSlip {
  0%, 100% { transform: translateX(-13%); opacity: 0.25; }
  50%      { transform: translateX(13%);  opacity: 0.72; }
}
@media (prefers-reduced-motion: reduce) { .card-evade::after { animation: none !important; } }
body.low-fx .card-evade::after { animation: none !important; }

/* ============================================================
   ARMOR FX — plating, and the quietest member on purpose
   ============================================================
   Armor is COMMON and passive: a card can carry it from turn one to the end of
   the match, and several can carry it at once. So this gets banding and a rim
   and no wash at all. If every armoured card had a dramatic overlay the truly
   dramatic states would stop reading as dramatic — the family only works if
   its weights are graded. Horizontal banding is also the last axis left. */
.card-armor {
  position: absolute; inset: 0;
  pointer-events: none; border-radius: inherit;
  z-index: 4; overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(205,170,110,0.32), inset 0 0 14px rgba(205,170,110,0.13);
  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 78%,rgba(0,0,0,0.4) 92%,rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg,#000 0%,#000 78%,rgba(0,0,0,0.4) 92%,rgba(0,0,0,0) 100%);
}
/* Plate strips — a bright top edge and a dark under-edge read as bevelled. */
.card-armor::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  background: repeating-linear-gradient(180deg,
    rgba(228,200,150,0.15) 0 1px,
    rgba(120,95,55,0.09)   1px 2px,
    transparent            2px 17px);
  mix-blend-mode: screen;
}
/* ONE loop — a sheen travelling down the plates. transform only. */
.card-armor::after {
  content: ""; position: absolute; left: 0; right: 0; top: -40%; height: 40%;
  background: linear-gradient(180deg, transparent, rgba(255,235,190,0.15), transparent);
  mix-blend-mode: screen;
  animation: armorSheen 4.2s linear infinite;
}
@keyframes armorSheen { 0% { transform: translateY(0); } 100% { transform: translateY(350%); } }
@media (prefers-reduced-motion: reduce) { .card-armor::after { animation: none !important; } }
body.low-fx .card-armor::after { animation: none !important; }

/* ============================================================
   CRITICAL FX — charged to hit for double
   ============================================================
   The only OFFENSIVE member of the family, so it is the only one that radiates
   OUTWARD from the centre. Fear gathers inward, taunt contracts inward — this
   is the opposite vector, and it should be, because the threat is leaving the
   card rather than closing on it. Lasts one round, so it is allowed to be the
   fastest loop here. */
.card-critical {
  position: absolute; inset: 0;
  pointer-events: none; border-radius: inherit;
  z-index: 4; overflow: hidden;
  background: radial-gradient(72% 58% at 50% 50%, rgba(255,105,180,0.28) 0%,
              rgba(255,60,140,0.11) 46%, rgba(255,20,120,0) 78%);
  mix-blend-mode: screen;
  box-shadow: inset 0 0 0 1px rgba(255,120,190,0.42), inset 0 0 24px rgba(255,40,130,0.24);
  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 80%,rgba(0,0,0,0.5) 92%,rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg,#000 0%,#000 80%,rgba(0,0,0,0.5) 92%,rgba(0,0,0,0) 100%);
}
/* Charge spokes firing out of the centre. */
.card-critical::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  background: repeating-conic-gradient(from 0deg at 50% 50%,
    rgba(255,140,200,0.18) 0deg 5deg, transparent 5deg 30deg);
  mix-blend-mode: screen;
}
/* ONE loop — the charge swelling. transform + opacity, compositor only. */
.card-critical::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  background: radial-gradient(closest-side, rgba(255,150,210,0.32) 0%, rgba(255,60,140,0) 72%);
  mix-blend-mode: screen;
  animation: critCharge 1.5s ease-in-out infinite;
}
@keyframes critCharge {
  0%, 100% { transform: scale(0.86); opacity: 0.35; }
  50%      { transform: scale(1.06); opacity: 0.88; }
}
@media (prefers-reduced-motion: reduce) { .card-critical::after { animation: none !important; } }
body.low-fx .card-critical::after { animation: none !important; }
/* Ignite burst — flame flares up over the card the instant it catches. */
.fx-burn-ignite {
  position: fixed;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 90;
  border-radius: 12px;
  background:
    radial-gradient(80% 90% at 50% 82%, rgba(255,238,180,0.95) 0%, rgba(255,140,40,0.6) 38%, rgba(255,80,20,0) 72%);
  box-shadow: 0 0 30px rgba(255,140,40,0.7);
  animation: fxBurnIgnite 620ms var(--ease-out-soft, cubic-bezier(0.16,1,0.3,1)) forwards;
}
/* Licking flame tongues drawn as a conic sheen inside the burst. */
.fx-burn-ignite::before {
  content: "";
  position: absolute; inset: 12%;
  border-radius: inherit;
  background: conic-gradient(from 200deg,
    rgba(255,210,120,0.6) 0deg, transparent 22deg, rgba(255,160,60,0.55) 48deg, transparent 70deg,
    rgba(255,200,110,0.6) 96deg, transparent 118deg, rgba(255,150,50,0.5) 150deg, transparent 172deg,
    rgba(255,190,90,0.55) 210deg, transparent 232deg, rgba(255,140,40,0.5) 300deg, transparent 322deg);
  mix-blend-mode: screen;
}
.fx-burn-ignite i {
  position: absolute; left: 50%; top: 62%;
  width: 4px; height: 4px;
  margin: -2px 0 0 -2px;
  border-radius: 50%;
  background: radial-gradient(circle, #ffe9a8 0%, #ff8c2a 60%, rgba(255,90,20,0) 100%);
  box-shadow: 0 0 6px rgba(255,150,60,0.9);
  animation: fxBurnSpark 620ms ease-out forwards;
  animation-delay: var(--sd, 0ms);
  opacity: 0;
}
@keyframes fxBurnIgnite {
  0%   { transform: translate(-50%,-50%) scale(0.4); opacity: 0; }
  22%  { opacity: 1; }
  100% { transform: translate(-50%,-50%) scale(1.15); opacity: 0; }
}
@keyframes fxBurnSpark {
  0%   { transform: translate(0,0) scale(1); opacity: 0.95; }
  100% { transform: translate(var(--sx,0), calc(var(--sy,0) - 14px)) scale(0.4); opacity: 0; }
}
/* Heat flinch on the card as it ignites — a small recoil + a warm flash. */
.card-burn-flinch { animation: cardBurnFlinch 480ms ease-out; }
@keyframes cardBurnFlinch {
  0%,100% { transform: translate(0,0); filter: none; }
  20% { transform: translate(0, -2px); filter: brightness(1.25) saturate(1.2); }
  45% { transform: translate(1px, 1px); }
  70% { transform: translate(-1px, 0); filter: brightness(1.08); }
}
/* Reduced-motion / low-fx: keep the static ember tint as a state cue, drop
   every animation (shimmer, embers, burst, flinch). */
/* The list below used to omit the BASE .card-burn (burnFlicker, 0.42s) and
   .card-burn::after (burnFlames, 0.9s), so the two fastest of burn's four
   infinite loops ran straight through both reduced-motion and low-fx — the
   heaviest overlay in the game was also the least gated. Both are now named. */
@media (prefers-reduced-motion: reduce) {
  .card-burn, .card-burn::before, .card-burn::after, .card-burn i,
  .fx-burn-ignite, .fx-burn-ignite i,
  .card-burn-flinch { animation: none !important; }
  .card-burn i { display: none; }
}
body.low-fx .card-burn,
body.low-fx .card-burn::before,
body.low-fx .card-burn::after,
body.low-fx .card-burn i { animation: none !important; }
body.low-fx .card-burn i { display: none; }

/* ============================================================
   EVADE FX — a dodged swing
   ============================================================
   When a swing is evaded the card sidesteps (blurs out to --evade-dx and snaps
   back) and leaves a translucent after-image behind at its original spot.
   Fired from applyCombatDamage via UI._fxEvadeDodge. Motion gated off under
   reduced-motion / low-fx (the engine still resolves the evade; it just skips
   the flourish). Mirrors the frost / burn one-shots. */
.card-evade-dodge { animation: cardEvadeDodge 380ms cubic-bezier(0.22, 1, 0.36, 1); }
@keyframes cardEvadeDodge {
  0%   { transform: translateX(0);                 filter: none; }
  30%  { transform: translateX(var(--evade-dx, 18px)); filter: blur(1.2px) brightness(1.15); }
  55%  { transform: translateX(var(--evade-dx, 18px)); filter: blur(0.6px); }
  100% { transform: translateX(0);                 filter: none; }
}
/* The after-image — a faint theme-tinted silhouette of the card left behind. */
.fx-evade-afterimage {
  position: fixed;
  pointer-events: none;
  z-index: 82;
  border-radius: 8px;
  border: 2px solid rgba(var(--theme-rgb, 79,195,247), 0.95);
  box-shadow:
    0 0 26px rgba(var(--theme-rgb, 79,195,247), 0.75),
    inset 0 0 28px rgba(var(--theme-rgb, 79,195,247), 0.35);
  /* The card art (set inline) reads as a cyan-tinted ghost sliding away. */
  background-color: rgba(var(--theme-rgb, 79,195,247), 0.14);
  background-blend-mode: luminosity;
  filter: brightness(1.3) drop-shadow(0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.85));
  animation: fxEvadeAfterimage 460ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes fxEvadeAfterimage {
  0%   { opacity: 0.9; transform: translateX(0) scale(1); }
  60%  { opacity: 0.7; }
  100% { opacity: 0;   transform: translateX(var(--evade-dx, 26px)) scale(0.9); }
}
@media (prefers-reduced-motion: reduce) {
  .card-evade-dodge { animation: none !important; }
  .fx-evade-afterimage { display: none !important; }
}
body.low-fx .card-evade-dodge { animation: none !important; }
body.low-fx .fx-evade-afterimage { display: none !important; }

/* ============================================================
   LEGENDARY ENTRANCE — genuine 10-cost titans only (Doomsday excluded
   in the engine). A full-screen accent flash + a heavier card drop than
   the standard titan arrival. Gated under reduced-motion / low-fx.
   ============================================================ */
.fx-legendary-flash {
  position: fixed; inset: 0; z-index: 8400; pointer-events: none;
  --leg: var(--theme-rgb, 79,195,247);
  animation: fxLegendaryFlash 950ms cubic-bezier(0.16,1,0.3,1) forwards;
}
.fx-legendary-enemy { --leg: 231, 76, 60; }
.fx-legendary-flash {
  /* Accent vignette that rushes in from the edges — center stays clear so the
     card is readable as it lands. */
  background:
    radial-gradient(130% 90% at 50% 50%, rgba(var(--leg),0) 46%, rgba(var(--leg),0.34) 100%);
}
/* A soft central bloom for the first beat, then it clears. */
.fx-legendary-flash::before {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(closest-side at 50% 47%,
    rgba(255,255,255,0.38) 0%, rgba(var(--leg),0.42) 14%, rgba(var(--leg),0) 58%);
  animation: fxLegendaryBloom 760ms ease-out forwards;
}
/* Two light bars sweep out from the middle — a Tron "reveal". */
.fx-legendary-flash::after {
  content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 2px;
  transform: translateY(-50%);
  background: linear-gradient(90deg, rgba(var(--leg),0) 0%, rgba(var(--leg),0.95) 50%, rgba(var(--leg),0) 100%);
  box-shadow: 0 0 18px rgba(var(--leg),0.8);
  animation: fxLegendaryBar 620ms cubic-bezier(0.16,1,0.3,1) forwards;
}
@keyframes fxLegendaryFlash {
  0% { opacity: 0; } 16% { opacity: 1; } 100% { opacity: 0; }
}
@keyframes fxLegendaryBloom {
  0% { opacity: 0; transform: scale(0.5); }
  26% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.35); }
}
@keyframes fxLegendaryBar {
  0% { opacity: 0; transform: translateY(-50%) scaleX(0.1); }
  35% { opacity: 1; }
  100% { opacity: 0; transform: translateY(-50%) scaleX(1); }
}
.legendary-arrival {
  animation: legendaryArrival 1150ms cubic-bezier(0.22,1,0.36,1);
  z-index: 45; position: relative;
}
@keyframes legendaryArrival {
  0%   { transform: translateY(-54px) scale(1.55); opacity: 0; filter: brightness(2.4) drop-shadow(0 0 22px rgba(var(--theme-rgb,79,195,247),0.9)); }
  26%  { opacity: 1; }
  52%  { transform: translateY(5px) scale(1.08); filter: brightness(1.5); }
  74%  { transform: translateY(0) scale(0.97); }
  100% { transform: none; filter: none; }
}
@media (prefers-reduced-motion: reduce) {
  .fx-legendary-flash { display: none !important; }
  .legendary-arrival { animation: none !important; }
}
body.low-fx .fx-legendary-flash { display: none !important; }

/* --- Legendary (10-cost) entrance — a beam of light erupts behind the titan. --- */
.fx-legendary-pillar {
  position: fixed;
  width: 60px;
  transform: translate(-50%, -100%) scaleY(0);
  transform-origin: 50% 100%;
  pointer-events: none;
  border-radius: 40px 40px 0 0;
  background: linear-gradient(to top, var(--lc, #ffd23a) 0%, rgba(255,255,255,0.55) 40%, transparent 100%);
  box-shadow: 0 0 30px 8px var(--lc, #ffd23a);
  filter: blur(1px);
  mix-blend-mode: screen;
  opacity: 0;
  animation: legendaryPillar 900ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: transform, opacity;
}
@keyframes legendaryPillar {
  0%   { opacity: 0; transform: translate(-50%, -100%) scaleY(0.1) scaleX(0.5); }
  22%  { opacity: 1; transform: translate(-50%, -100%) scaleY(1) scaleX(1.15); }
  60%  { opacity: 0.8; transform: translate(-50%, -100%) scaleY(1) scaleX(1); }
  100% { opacity: 0; transform: translate(-50%, -100%) scaleY(1) scaleX(0.7); }
}
@media (prefers-reduced-motion: reduce) { .fx-legendary-pillar { animation: none; } }
body.low-fx .legendary-arrival { animation: none !important; }

.card.status-stunned .card-portrait {
  filter: grayscale(0.65) brightness(0.85) brightness(var(--art-grade, 1));
  box-shadow: inset 0 0 22px rgba(241, 196, 15, 0.30);
}
.card.status-feared .card-portrait {
  filter: saturate(0.75) brightness(0.82) contrast(1.06) brightness(var(--art-grade, 1));
  box-shadow: inset 0 0 26px rgba(200, 40, 60, 0.55);
}
.card.status-mind-ctrl .card-portrait {
  filter: saturate(0.9) brightness(var(--art-grade, 1));
  box-shadow: inset 0 0 24px rgba(155, 89, 182, 0.50);
}

/* ============================================================
   VISUAL POLISH BATCH C — game-over board reaction. Rides the
   existing 2.4s victory-cinema / defeat-cinema body classes:
   the WINNING side's surviving cards surge in their faction
   color while the LOSING side's flicker dark under the rising
   result panel. One-shot; gated on reduced-motion.
   ============================================================ */
@media (prefers-reduced-motion: no-preference) {
  body.victory-cinema .board .card-slot.player-slot .card,
  body.defeat-cinema  .board .card-slot.ai-slot .card {
    animation: goWinnerSurge 1300ms ease-out;
  }
  body.victory-cinema .board .card-slot.player-slot .card {
    --go-surge-rgb: 79, 195, 247;
  }
  body.defeat-cinema .board .card-slot.ai-slot .card {
    --go-surge-rgb: 231, 76, 60;
  }
  body.victory-cinema .board .card-slot.ai-slot .card,
  body.defeat-cinema  .board .card-slot.player-slot .card {
    animation: goLoserFlicker 1400ms ease-out forwards;
  }
}
@keyframes goWinnerSurge {
  0%   { box-shadow: 0 0 0 rgba(var(--go-surge-rgb, 79, 195, 247), 0); }
  30%  { box-shadow: 0 0 24px rgba(var(--go-surge-rgb, 79, 195, 247), 0.85), 0 0 56px rgba(var(--go-surge-rgb, 79, 195, 247), 0.35); }
  100% { box-shadow: 0 0 0 rgba(var(--go-surge-rgb, 79, 195, 247), 0); }
}
@keyframes goLoserFlicker {
  0%   { opacity: 1; filter: none; }
  18%  { opacity: 0.45; }
  26%  { opacity: 0.9; }
  38%  { opacity: 0.4; }
  48%  { opacity: 0.75; }
  100% { opacity: 0.35; filter: saturate(0.35) brightness(0.6); }
}

/* ---- Block-absorb shield flash --------------------------------
   The HP bar visibly SHIELDS when block meter is spent: an expanding
   cyan ring + a brief brightness pulse on the bar container. One-shot
   ~600ms, spawned by UI.fxBlockAbsorb via the render diff watcher. */
.health-container { position: relative; }
.block-absorb-ring {
  position: absolute;
  inset: -6px -10px;
  border-radius: 12px;
  pointer-events: none;
  border: 2px solid rgba(var(--theme-rgb, 79,195,247), 0.95);
  box-shadow:
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 30px rgba(var(--theme-rgb, 79,195,247), 0.40),
    inset 0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.35);
  opacity: 0;
  animation: blockAbsorbRing 600ms ease-out forwards;
  z-index: 5;
}
@keyframes blockAbsorbRing {
  0%   { opacity: 0;   transform: scale(0.86); }
  18%  { opacity: 1;   transform: scale(1); }
  70%  { opacity: 0.8; transform: scale(1.06); }
  100% { opacity: 0;   transform: scale(1.14); }
}
.health-container.block-absorb-pulse {
  animation: blockAbsorbPulse 600ms ease-out;
}
@keyframes blockAbsorbPulse {
  0%   { filter: brightness(1); }
  20%  { filter: brightness(1.7); }
  100% { filter: brightness(1); }
}

/* ============================================================
   SNAP/PvZ IDENTITY BATCH — hero avatars, emotes, environment
   reveal, done-nudge, rarity finishes, hover parallax.
   ============================================================ */

/* ---- Hero avatar chips ---------------------------------- */
.bar-cell.bar-hp {
  display: flex;
  align-items: center;
  gap: 8px;
  position: relative;
}
.bar-cell.bar-hp .health-container { flex: 1; min-width: 0; }
.hero-avatar {
  width: 38px; height: 38px;
  flex: 0 0 38px;
  border-radius: 50%;
  background-color: #000;
  background-size: cover;
  background-position: center 18%;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 16px;
  color: var(--text-dim, #cfe8f7);
  position: relative;
}
.hero-avatar.avatar-player {
  border: 2px solid rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95);
  box-shadow:
    0 0 10px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.55),
    0 0 20px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.22);
}
.hero-avatar.avatar-ai {
  border: 2px solid rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95);
  box-shadow:
    0 0 10px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.55),
    0 0 20px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.22);
}
@container (max-width: 520px) {
  .hero-avatar { width: 26px; height: 26px; flex-basis: 26px; font-size: 12px; }
  .bar-cell.bar-hp { gap: 4px; }
}

/* ---- Emotes --------------------------------------------- */
.emote-btn {
  width: 22px; height: 22px;
  flex: 0 0 22px;
  border: none; background: none; padding: 0;
  color: rgba(207, 232, 247, 0.55);
  font-size: 16px; line-height: 1;
  cursor: pointer;
  transition: transform 150ms var(--ease-out-soft), color 150ms var(--ease-snap), text-shadow 150ms var(--ease-snap);
}
.emote-btn:hover {
  color: #fff;
  transform: scale(1.25);
  text-shadow: 0 0 10px rgba(var(--theme-rgb, 79, 195, 247), 0.9);
}
.emote-picker {
  position: absolute;
  left: 0; bottom: calc(100% + 8px);
  display: flex; gap: 6px;
  padding: 6px 8px;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79, 195, 247), 0.65);
  border-radius: 8px;
  box-shadow: 0 0 14px rgba(var(--theme-rgb, 79, 195, 247), 0.35);
  z-index: 900;
}
.emote-opt {
  border: none; background: none; padding: 2px 4px;
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 20px;
  color: var(--text-body, #e8eef6);
  cursor: pointer;
  transition: transform 150ms var(--ease-out-soft), text-shadow 150ms var(--ease-snap);
}
.emote-opt:hover {
  transform: scale(1.35);
  text-shadow: 0 0 12px rgba(var(--theme-rgb, 79, 195, 247), 0.95);
}
.emote-bubble {
  position: absolute;
  left: 50%; bottom: calc(100% + 6px);
  transform: translateX(-50%);
  padding: 4px 10px;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79, 195, 247), 0.85);
  border-radius: 8px;
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 18px;
  color: #fff;
  white-space: nowrap;
  box-shadow: 0 0 12px rgba(var(--theme-rgb, 79, 195, 247), 0.5);
  animation: emotePop 2.4s var(--ease-out-soft) forwards;
  z-index: 950;
  pointer-events: none;
}
@keyframes emotePop {
  0%   { opacity: 0; transform: translateX(-50%) scale(0.4); }
  8%   { opacity: 1; transform: translateX(-50%) scale(1.12); }
  14%  { transform: translateX(-50%) scale(1); }
  82%  { opacity: 1; }
  100% { opacity: 0; transform: translateX(-50%) scale(0.92); }
}

/* ---- MP taunts: 🔊 button + scrollable character-sound picker --------- */
.taunt-btn { font-size: 14px; }
/* The roster can be long, so the taunt picker is a scrollable NAME column
   rather than the emote's single emoji row. */
.taunt-picker {
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
  max-height: 240px;
  overflow-y: auto;
  min-width: 128px;
  max-width: 190px;
}
.taunt-opt {
  font-size: 14px;
  text-align: left;
  white-space: nowrap;
  padding: 3px 8px;
  border-radius: 4px;
}
.taunt-opt:hover {
  transform: none;                      /* a scale on a list row looks jumpy */
  background: rgba(var(--theme-rgb, 79, 195, 247), 0.18);
  text-shadow: 0 0 10px rgba(var(--theme-rgb, 79, 195, 247), 0.9);
}
.taunt-empty { padding: 8px 10px; color: #88a0b8; font-size: 12px; white-space: nowrap; }
/* Corner preview toggle steps aside while an emote/taunt bubble or picker is
   up — it is fixed at the same top-left corner as the AI avatar's bubble, in a
   HIGHER stacking context, so it painted straight over the opponent's emote.
   Toggled by UI._syncCornerToggle. */
body.clb-emote-open .viewport-toggle { display: none !important; }

/* ============================================================
   MOBILE: FIT-TO-WIDTH HAND + TRICK ROWS, EVEN VERTICAL RHYTHM
   ============================================================
   Reference the user supplied (PvZ Heroes on a phone): every zone reads as its
   own band, nothing is clipped, and the hand sits as ONE tidy row across the
   bottom. Ours broke that in two measurable ways at 414x896:

     • The hand row was fixed at 92px per card with `min-width: max-content` on
       the track, so five cards needed 476px inside a 414px viewport — the last
       card was sliced by the screen edge and the row silently became a
       horizontal scroller. A hand you cannot see is the single most "unclean"
       thing on the screen.
     • The two trick cards rendered 168px tall — over half the height of the
       whole six-lane board (286px) — so the bottom of the screen was dominated
       by the smallest-stakes row.

   Fix: both rows now SHARE the width instead of demanding it. `flex: 1 1 0`
   with a max-width keeps the old 92px look whenever the cards genuinely fit,
   and shrinks them evenly toward a legibility floor when they don't. Below the
   floor the row still scrolls, so a 7-card hand degrades gracefully instead of
   clipping. Nothing here changes the desktop layout — it is scoped to the same
   phone container query the rest of the mobile rules use. */
@container (max-width: 520px) {
  /* The track must be allowed to shrink; `min-width: max-content` (set in the
     earlier mobile blocks) is what forced the overflow in the first place. */
  .player-hand-section .hand-cards,
  .tricks-section .trick-cards { min-width: 0; }

  .player-hand-section .hand-cards .card,
  .player-hand-section .hand-cards .hand-card-wrapper {
    flex: 1 1 0;
    width: auto;
    /* Floor chosen so even a FULL hand fits without clipping: at 414px the
       track is 398px, minus 6 gaps (24px) leaves 374px / 7 cards = 53.4px. */
    min-width: 52px;
    max-width: 92px;      /* never larger than the tuned size */
  }
  /* Tricks match the hand's scale so the two bottom rows read as one system
     rather than two different card sizes stacked on top of each other. */
  .tricks-section .trick-cards > *,
  .tricks-section .trick-cards .trick-card {
    flex: 1 1 0;
    width: auto;
    min-width: 58px;
    max-width: 92px;
  }
  /* Even gutters top and bottom so the bands breathe equally. */
  .player-hand-section { padding: 6px 8px; }
  .tricks-section      { padding: 6px 8px; }
}
/* Taunt bubble carries a character NAME, not a big emoji — smaller type. */
.emote-bubble.taunt-bubble { font-size: 13px; letter-spacing: 0.3px; }

/* ---- Environment reveal (Snap location moment) ----------- */
.env-reveal {
  position: absolute; inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 12;
  border-radius: inherit;
}
.env-reveal-sweep {
  position: absolute; inset: 0;
  background: linear-gradient(180deg,
    transparent 30%, rgba(46, 204, 113, 0.28) 50%, transparent 70%);
  transform: translateY(-100%);
  animation: envSweep 900ms ease-out forwards;
}
@keyframes envSweep { to { transform: translateY(100%); } }
.env-reveal-name {
  position: absolute; left: 50%; top: 46%;
  transform: translate(-50%, -50%) scale(0.8);
  font-family: 'Rajdhani', sans-serif; font-weight: 700;
  font-size: 16px; letter-spacing: 3px; text-transform: uppercase;
  color: var(--text-body, #d9ffe5);
  text-shadow: 0 0 12px rgba(46, 204, 113, 0.95), 0 0 26px rgba(46, 204, 113, 0.5);
  white-space: nowrap;
  opacity: 0;
  animation: envName 1.45s ease-out forwards;
}
@keyframes envName {
  0%   { opacity: 0; transform: translate(-50%, -50%) scale(0.8); }
  16%  { opacity: 1; transform: translate(-50%, -50%) scale(1.05); }
  24%  { transform: translate(-50%, -50%) scale(1); }
  78%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(0.96); }
}

/* ---- Done-button "nothing left to play" nudge ------------ */
.btn.btn-nudge {
  animation: doneNudge 1.7s ease-in-out infinite;
}
@keyframes doneNudge {
  0%, 100% { box-shadow: 0 0 5px rgba(var(--theme-rgb, 79, 195, 247), 0.30); }
  50%      { box-shadow: 0 0 16px rgba(var(--theme-rgb, 79, 195, 247), 0.95),
                         0 0 30px rgba(var(--theme-rgb, 79, 195, 247), 0.40); }
}

/* ---- Rarity frame finishes — EVERYWHERE a card face renders except the
        board (ally/enemy side colors own that surface): hand, draft,
        codex, Paul Atreides / Dr. Strange / Mobius pick trays, block-trick
        modal, inspect. User: "rarity finishes in all these different
        areas? draft" — the :not() form covers present and future pick
        surfaces automatically instead of enumerating containers. -------- */
.card.cost-7:not(.ally-card):not(.enemy-card),
.card.cost-8:not(.ally-card):not(.enemy-card) {
  border-color: rgba(205, 215, 230, 0.92);
  box-shadow:
    0 0 10px rgba(205, 215, 230, 0.35),
    0 0 22px rgba(205, 215, 230, 0.14);
}
.card.cost-9:not(.ally-card):not(.enemy-card),
.card.cost-10:not(.ally-card):not(.enemy-card) {
  border-color: rgba(241, 196, 15, 0.95);
  box-shadow:
    0 0 12px rgba(241, 196, 15, 0.45),
    0 0 26px rgba(241, 196, 15, 0.18),
    inset 0 0 10px rgba(241, 196, 15, 0.10);
}
/* Gold-tier idle sheen — a slow light pass over the art, desktop-only
   (hover-capable devices; phones skip the infinite loop entirely). */
@media (hover: hover) and (pointer: fine) {
  .player-hand-section .card.cost-9 .card-portrait .pt-shine,
  .player-hand-section .card.cost-10 .card-portrait .pt-shine {
    opacity: 1;
    animation: goldSheen 7s linear infinite;
  }
}
@keyframes goldSheen {
  0%, 72% { transform: translateX(-130%) skewX(-18deg); }
  92%, 100% { transform: translateX(130%) skewX(-18deg); }
}

/* ---- Hover extras (the Snap art-float that lived here is gone) ---- */
@media (hover: hover) and (pointer: fine) {
  /* Clip at the CARD level — transform:scale grows the portrait's whole
     BOX, and overflow:hidden on the portrait only clips its background,
     not its own scaled box. The card is overflow:visible by default, so
     the enlarged art painted past the frame line (user: "the 3d effect
     is still clipping"). Hidden only WHILE hovered, so nothing else ever
     loses its overflow behavior. */
  /* REMOVED — the Snap art-float. User: "can you get rid of the marvel snap
     style card art zoom in move?"
     It was `translate(tilt * -3px) scale(1.12)` on the portrait, sliding the
     art against the tilt so it appeared to hover behind the frame. Two reasons
     it stopped earning its keep: the art is now EDGE-TO-EDGE, so a 1.12 overscan
     is cropping 12% off a painting that was just given the whole card, and the
     whole-card tilt already supplies the depth this was faking.
     The `overflow: hidden` that sat on the hovered card went with it — it
     existed ONLY to clip this overscan (see the note about art painting past
     the frame line), so keeping it would clip for no reason. Cards go back to
     the overflow behaviour they have at rest. */
  /* Magnified hover restores FULL color on an unaffordable card — you're
     reading it, not playing it; the softened grey snaps back on leave. */
  .hand-card-wrapper:hover .card.hand-card.unafford {
    filter: grayscale(0) brightness(1) !important;
  }
}

/* Custom card-back artwork. Sits above the fallback SVG pattern and fills the
   card frame; if the image 404s the <img> removes itself and the pattern shows
   through instead. Same back is rendered to BOTH players. */
.card.face-down-hidden .card-back-art {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  /* `contain`, not `cover`: the artwork has an ornate border that reads as
     part of the design, and `cover` crops it off at the edges. `contain` fits
     the whole image inside the card frame with the border intact. The card's
     own dark background fills any letterbox gap, which is invisible against
     the art's black field. User: "I think having the border looks best". */
  object-fit: contain;
  border-radius: inherit;
  z-index: 2;
  pointer-events: none;
}

/* When the custom back art actually loads, it IS the whole card face — hide the
   built-in pattern/glyph/label so they don't show through the letterbox gaps
   left by object-fit: contain. If the art is missing these stay visible as the
   fallback. */
.card.face-down-hidden.has-back-art .card-back-pattern,
.card.face-down-hidden.has-back-art .card-back-glyph,
.card.face-down-hidden.has-back-art .card-back-label {
  display: none;
}
.card.face-down-hidden.has-back-art {
  background: #000;
}

/* A face-down card has no text content, so it used to collapse to its
   min-height (140x130, nearly square) while a real card sits at 140x220. That
   squat frame is what forced the back art into a hard letterbox. Match the
   normal card's proportions so the board reads uniformly AND the artwork
   (which is a full portrait card face) fills the frame with its border intact. */
.card.face-down-hidden {
  aspect-ratio: 140 / 220;
  height: auto;
}

/* Online deck picker — sits under the Create/Join options on the multiplayer
   screen so both players choose which saved deck they bring. */
.mp-deck-pick {
  margin: 14px 0 0;
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  font-family: 'Rajdhani', sans-serif; letter-spacing: 1px;
  color: rgba(200,220,235,0.75); font-size: 13px; text-transform: uppercase;
}
.mp-deck-pick label { color: rgba(var(--theme-rgb, 79,195,247),0.85); }
.mp-deck-pick select {
  background: rgba(6,12,22,0.85);
  border: 1px solid rgba(120,160,210,0.4);
  border-radius: 4px; padding: 6px 8px;
  color: var(--text-dim, #dcebf8); font-family: inherit; font-size: 13px; letter-spacing: 1px;
}
.mp-deck-pick .mp-deck-hint {
  flex-basis: 100%; font-size: 11px; letter-spacing: 0.5px;
  color: rgba(160,180,200,0.55); text-transform: none;
}
.mp-deck-pick-empty em { color: var(--text-dim, #dcebf8); font-style: normal; }

/* "Build a deck" action inside the online deck picker — turns the empty /
   incomplete state into something the player can act on instead of a dead end. */
.mp-deck-build {
  background: none; border: 1px solid rgba(var(--theme-rgb, 79,195,247),0.5); border-radius: 4px;
  color: var(--theme-accent-bright, #4fc3f7); font-family: 'Rajdhani', sans-serif; font-size: 12px;
  letter-spacing: 1px; text-transform: uppercase; padding: 4px 10px; cursor: pointer;
}
.mp-deck-build:hover { background: rgba(var(--theme-rgb, 79,195,247),0.12); }
.mp-deck-build-inline {
  padding: 0 4px; border: none; text-transform: none; letter-spacing: 0.5px;
  font-size: 11px; text-decoration: underline;
}
.mp-deck-pick select option[disabled] { color: rgba(160,180,200,0.45); }

/* ===== DECK BUILDER PICKER GRID — Codex-style card faces =====
   The grid now renders the same card faces the Codex does, so these rules only
   add the deck-builder chrome on top: the click target, the ×N copies chip and
   the dimmed at-max / deck-full state. */
.db-pick {
  position: relative;
  cursor: pointer;
  transition: transform 0.12s var(--ease-snap), filter 0.12s var(--ease-snap);
}
.db-pick:hover { transform: translateY(-3px); }
.db-pick .card, .db-pick .trick-card { pointer-events: none; }  /* wrapper owns the click */
.db-pick-owned .card,
.db-pick-owned .trick-card {
  outline: 1px solid rgba(var(--theme-rgb, 79,195,247),0.65);
  outline-offset: -1px;
}
.db-pick-disabled { cursor: default; filter: grayscale(0.55) brightness(0.6); }
.db-pick-disabled:hover { transform: none; }
.db-pick-count {
  position: absolute; top: 4px; right: 4px; z-index: 4;
  min-width: 20px; padding: 1px 6px; border-radius: 8px;
  background: rgba(6,12,22,0.92); border: 1px solid rgba(var(--theme-rgb, 79,195,247),0.6);
  color: var(--theme-accent-bright, #4fc3f7); font-family: 'Rajdhani', sans-serif; font-weight: 700;
  font-size: 11px; letter-spacing: 0.5px; text-align: center;
  pointer-events: none;
}
.db-pick-count-max { border-color: rgba(255,138,128,0.75); color: #ff8a7a; }

/* Picker grid. Renders the SAME card faces the Codex does (real portrait,
   keyword badges, stat orbs, rules text) but at the natural in-hand card size
   rather than the Codex's full-screen scale — borrowing .encyc-grid produced
   535px-tall cards in a 129px region, so nothing but the art was ever visible. */
.db-pick-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, 140px);
  justify-content: center;
  align-content: start;
  gap: 16px 14px;
  padding: 10px 6px 12px;
  overflow-y: auto;
}
.db-collection .db-pick-grid { grid-template-columns: repeat(auto-fill, 140px); }
.db-pick-grid .db-pick-card { width: 140px; max-width: 140px; }
/* The deck strip sits above the picker and is mostly empty until cards are
   added — cap it so the picker gets enough height to show a WHOLE card. */
.db-deck-strip { flex: 0 1 auto; max-height: 15vh; }
.db-pick-grid .card.hand-card.enc-card {
  min-width: 0;
  width: 132px;
  max-width: 132px;
  min-height: 0;
  contain-intrinsic-size: auto 300px;
}
/* Keep the rules text legible at the smaller size. */
.db-pick-grid .card.hand-card.enc-card .card-desc {
  font-size: 9px;
  line-height: 1.25;
}
.db-pick-grid .card.hand-card.enc-card .card-name { font-size: 11px; }

/* The deck strip carried min-height:160px, which beat the max-height cap and
   kept the picker squeezed into ~130px — not even one card tall. The dashed
   "No cards added yet" placeholder was 112px of that on its own. Shrink both so
   the picker gets room to show WHOLE cards; the strip still grows as you add
   cards, it just no longer reserves space it isn't using. */
.db-deck-strip {
  min-height: 0 !important;
  max-height: 15vh !important;
}
.db-deck-strip .db-deck-empty {
  min-height: 0 !important;
  height: auto !important;
  padding: 8px 10px !important;
  font-size: 10px;
}
/* Sections may collapse when empty, but the LIST must size to its content or
   added cards get clipped (it collapsed to 24px and hid the rows). Cap comes
   from the strip's max-height; the list scrolls past that. */
.db-deck-strip .db-deck-section { min-height: 0 !important; }
.db-deck-strip .db-deck-list { min-height: 0 !important; flex: 1 1 auto; overflow-y: auto; }
.db-deck-strip:has(.db-deck-row) { min-height: 92px !important; }
/* Floor the picker so a full card is always visible even at 720p. */
.db-collection .db-pick-grid { min-height: 232px; }

/* ============================================================
   PERF: JUST-IN-TIME LAYER PROMOTION
   Card portraits and cards no longer carry a permanent will-change /
   translateZ layer (that promoted 30+ image-textured layers at once and
   starved integrated GPUs — see .card-portrait). Instead, promote a card to
   its own compositor layer ONLY while it is actually animating, then drop back.
   This keeps attack lunges / entrances / shakes smooth without the always-on
   VRAM cost. These classes are added transiently by the JS animation helpers
   and removed when the animation ends. */
.card.card-enter,
.card.lane-landed,
.card.combat-attacker,
.card.combat-target,
.card.titan-shake,
.card.crit-shake,
.card.card-shake-rejected,
.card.hit-flash {
  will-change: transform;
}
.card.card-enter .card-portrait,
.card.lane-landed .card-portrait,
.card.combat-attacker .card-portrait,
.card.combat-target .card-portrait {
  /* Promote the painting too, but only for the moment the parent moves, so the
     background image stays crisp during the transform instead of re-rasterising
     each frame on the CPU. */
  transform: translateZ(0);
}

/* ============================================================
   BLANK-CARD / FLICKER FIX — NESTED 3D COMPOSITING STACK
   ============================================================
   User report (2026-07-23, 2 of 4 laptops affected):
     • Hand: "the picture shows as long as the mouse isn't moving,
       but once you move it, the picture goes in and out."
     • Board: "the picture for all the cards is never there, and
       even the NAME doesn't show — but hover the card and the
       picture shows."

   The name not rendering either is the tell: this is not an image
   loading failure, it's a PAINT failure. The card element's tile is
   never rasterized until something invalidates it (hover).

   Root cause — three rules compounded so that every card at rest sat
   inside a triple-nested 3D compositing stack:

     1. #game-area  { perspective: 1500px;
                      transform: rotateY(var(--cam-tx)) rotateX(var(--cam-ty)) }
        A 3D root wrapping the ENTIRE game — and installCameraParallax()
        rewrites --cam-tx/--cam-ty on every mousemove, so the root
        transform of the whole scene changes every frame the mouse moves.
     2. .card-slot / .hand-card-wrapper { perspective: 700px }
        A second perspective, once per card.
     3. .card.ally-card / .card.enemy-card / hand cards
                     { transform-style: preserve-3d }
        A third — permanent, on every card, making each one its own
        3D rendering context that must be rasterized as a separate plane.

   Nothing at rest needed (3): the translateZ content layers that
   actually use the 3D context are all :hover-scoped. So idle cards paid
   the full cost for zero visual benefit. On a laptop whose GPU driver is
   blocklisted (Chrome falls back to software compositing) or whose
   integrated GPU runs out of texture budget, the compositor defers or
   drops those plane rasterizations — board cards never paint at all, and
   hand cards drop tiles for exactly as long as the root transform keeps
   changing (i.e. while the mouse moves). Machines with a healthy
   discrete GPU rasterize it fine. Hence 2 laptops broken, 2 fine.

   The permanent fix is above: preserve-3d + per-card perspective are now
   :hover-scoped in all four places (hand cards, board ally/enemy cards,
   the .player-hand-section hand card, trick/draft cards). Hover visuals
   are unchanged; the idle board is flat 2D and paints on the normal path.

   `body.low-fx` below is the belt-and-suspenders fallback for drivers
   that still can't cope — it flattens the scene completely. Set
   automatically when a software/blocklisted renderer or a sustained low
   frame rate is detected, and forceable from Settings → Graphics.
   ============================================================ */

/* ---- 1. Flatten every 3D context ---------------------------------- */
body.low-fx #game-area {
  /* The mouse-parallax camera pivot is the single most expensive thing
     on the page for a weak compositor: it re-transforms the 3D root
     containing the whole game on every mouse move. Gone. */
  perspective: none !important;
  transform: none !important;
  transition: none !important;
}
body.low-fx .card-slot,
body.low-fx .hand-card-wrapper,
body.low-fx .trick-cards,
body.low-fx .draft-panel,
body.low-fx .player-hand-section .hand-cards .card,
body.low-fx .player-hand-section .hand-cards .card:hover {
  perspective: none !important;
}
body.low-fx .card,
body.low-fx .card:hover,
body.low-fx .trick-card,
body.low-fx .trick-card:hover,
body.low-fx .draft-card.trick-draft,
body.low-fx .draft-card.trick-draft:hover,
body.low-fx .hand-card-wrapper:hover .card.hand-card,
body.low-fx .card.ally-card:hover,
body.low-fx .card.enemy-card:hover {
  transform-style: flat !important;
}

/* ---- 2. Hover magnify WITHOUT the 3D tilt -------------------------
   The enlarge is a readability feature (it's how you read a small card),
   so it stays — but as a plain 2D scale with no rotateX/rotateY, so no
   3D rendering context is created. */
body.low-fx .hand-card-wrapper:hover .card.hand-card {
  /* The lift+scale now lives on the WRAPPER, so low-fx must NOT re-apply it on
     the card — that would compound into 1.6 x 1.6 = 2.56x. Low-fx's actual job
     here is dropping the 3D tilt, so the card's transform is simply cleared and
     the wrapper's plain 2D enlarge (which needs no 3D context) carries it. */
  transform: none !important;
}
body.low-fx .card.ally-card:hover,
body.low-fx .card.enemy-card:hover {
  transform: scale(1.4) !important;
}
body.low-fx .trick-card:hover {
  transform: scale(1.5) translateY(-6px) !important;
}
/* Inner content-layer pop-out needs the 3D context — drop it. */
body.low-fx .hand-card-wrapper:hover .card.hand-card .card-desc,
body.low-fx .hand-card-wrapper:hover .card.hand-card .card-name-banner,
body.low-fx .hand-card-wrapper:hover .card.hand-card .status-badges,
body.low-fx .hand-card-wrapper:hover .card.hand-card .stat-circle,
body.low-fx .hand-card-wrapper:hover .card.hand-card .card-cost {
  transform: none !important;
}
/* Particles lose their Z depth (they were only interesting under the
   camera pivot, which is now off). */
body.low-fx .game-particle { transform: none !important; }

/* ---- 3. Kill the cursor-follow decoration -------------------------
   Every one of these repaints on mousemove, which is precisely when the
   flicker was reported. */
body.low-fx .custom-cursor,
body.low-fx .cursor-trail,
body.low-fx #tron-cursor-trail,
body.low-fx .mm-particle,
body.low-fx .board-mote {
  display: none !important;
}
/* ...but GIVE THE NATIVE CURSOR BACK. The global rule at the top of the
   cursor section sets `cursor: none` everywhere so the glowing custom
   follower can stand in for it. In low-fx we've just hidden that follower,
   so without this the player has NO cursor at all and can't tell where
   they're clicking (user report). Same restore the touch safety-net does:
   re-enable the native arrow, with pointer/text affordances on the right
   elements. Placed after the global rule so equal-specificity !important
   wins by source order. */
body.low-fx,
body.low-fx *,
body.low-fx *::before,
body.low-fx *::after { cursor: auto !important; }
body.low-fx a,
body.low-fx button,
body.low-fx [role="button"],
body.low-fx summary,
body.low-fx label[for],
body.low-fx select,
body.low-fx .card.playable,
body.low-fx .hand-card-wrapper,
body.low-fx .lane,
body.low-fx .choice-card,
body.low-fx .choice-real { cursor: pointer !important; }
body.low-fx input:not([type="button"]):not([type="submit"]):not([type="reset"]),
body.low-fx textarea,
body.low-fx [contenteditable="true"] { cursor: text !important; }

/* ---- 4. No live blur anywhere -------------------------------------
   backdrop-filter forces the compositor to re-rasterize everything
   behind the element every frame. The surfaces keep their dark rgba
   backgrounds, so nothing turns transparent. */
body.low-fx *,
body.low-fx *::before,
body.low-fx *::after {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ---- 5. Stop the always-on ornamental animation loops -------------
   Same list as the mobile low-power block — none of these convey game
   state. Everything FUNCTIONAL (lane-active combat pulse, target
   highlights, playable-slot cue, hp-critical, lethal skull, status
   badges, spinners, thinking dots) is deliberately left alone. */
body.low-fx::before,
body.low-fx.turn-ai::before,
body.low-fx.turn-player::after,
body.low-fx.turn-combat::before,
body.low-fx.turn-combat::after,
body.low-fx .board::before,
body.low-fx .board-section::before,
body.low-fx .card.vibe-alien:not(.card-enter):not(.card-exit),
body.low-fx .card.vibe-cosmic:not(.card-enter):not(.card-exit),
body.low-fx .card.vibe-magnetic:not(.card-enter):not(.card-exit),
body.low-fx .card.vibe-phase:not(.card-enter):not(.card-exit),
body.low-fx .card.vibe-slasher:not(.card-enter):not(.card-exit),
body.low-fx .card.vibe-speed:not(.card-enter):not(.card-exit),
body.low-fx .card.vibe-symbiote:not(.card-enter):not(.card-exit),
body.low-fx .card.vibe-titan:not(.card-enter):not(.card-exit),
body.low-fx .tron-perimeter::after,
body.low-fx .tron-shimmer,
body.low-fx .tron-fx-breathe,
body.low-fx .hud-pill-main,
body.low-fx .hud-round #round-num,
body.low-fx .hud-count b,
body.low-fx .lane-number,
body.low-fx .empty-hand::before,
body.low-fx .mm-mw3 .mm-hero-img,
body.low-fx .mm-sideart-img {
  animation: none !important;
}

/* ---- 6. Belt-and-suspenders repaint guarantee ---------------------
   If a driver STILL defers the card tile, giving the portrait its own
   plain 2D containing block and an explicit backface makes Chrome take
   the simple software-raster path for it rather than a deferred
   composited one. Cheap, and only applied in the fallback mode. */
body.low-fx .card-portrait {
  transform: none !important;
  will-change: auto !important;
  backface-visibility: visible !important;
}

/* One-shot notice shown when the frame-rate probe auto-enables low-fx, so
   a player on an affected machine knows why the visuals look plainer and
   where the switch lives. Deliberately dependency-free (no modal, no
   toast host element) — it has to work on the machine that's struggling. */
.low-fx-notice {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%) translateY(12px);
  z-index: 9999;
  max-width: min(520px, 92vw);
  padding: 10px 16px;
  border: 1px solid rgba(127, 208, 255, 0.55);
  border-radius: 4px;
  background: rgba(6, 12, 20, 0.96);
  color: #d4ecff;
  font-size: 12px;
  letter-spacing: 0.4px;
  text-align: center;
  pointer-events: none;
  opacity: 0;
  transition: opacity 300ms var(--ease-snap), transform 300ms var(--ease-snap);
}
.low-fx-notice.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ============================================================
   ONLINE ROOM BANNER IN THE DECK BUILDER
   ============================================================
   Building a deck for an online match used to be a one-way door: you left the
   multiplayer screen, the room went with you, and there was no code to send a
   friend. The builder now carries the live room code at the top so the friend
   can join WHILE the deck is being assembled.
   ============================================================ */
.db-mp-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin: 0 0 10px;
  padding: 8px 14px;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.45);
  border-radius: 4px;
  background: rgba(10, 22, 36, 0.85);
  font-family: 'Rajdhani', sans-serif;
}
.db-mp-banner-go { border-color: rgba(120, 230, 160, 0.55); }
.db-mp-label {
  color: var(--theme-accent-bright, #4fc3f7);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
}
.db-mp-banner-go .db-mp-label { color: #7ee8a5; }
/* The code itself — big, monospaced, obviously copyable. */
.db-mp-code {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 6px;
  color: var(--text-body, #e8f5ff);
  background: rgba(6, 12, 22, 0.9);
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.6);
  border-radius: 4px;
  padding: 3px 12px;
  cursor: pointer;
}
.db-mp-code:hover {
  border-color: var(--theme-accent-bright, #4fc3f7);
  background: rgba(var(--theme-rgb, 79,195,247), 0.14);
}
.db-mp-code-create {
  font-family: 'Rajdhani', sans-serif;
  font-size: 13px;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--theme-accent-bright, #4fc3f7);
}
.db-mp-hint {
  flex: 1 1 240px;
  min-width: 200px;
  font-size: 12px;
  letter-spacing: 0.3px;
  color: rgba(180, 200, 220, 0.75);
}
.db-mp-hint b { color: var(--text-body, #e8f5ff); font-weight: 700; }
.db-mp-back {
  background: none;
  border: 1px solid rgba(120, 160, 210, 0.45);
  border-radius: 4px;
  color: var(--text-dim, #cfe2ef);
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  padding: 6px 12px;
  cursor: pointer;
  margin-left: auto;
}
.db-mp-back:hover {
  border-color: var(--theme-accent-bright, #4fc3f7);
  color: var(--text-body, #e8f5ff);
}
@media (max-width: 720px) {
  .db-mp-banner { gap: 8px; padding: 8px 10px; }
  .db-mp-code { font-size: 18px; letter-spacing: 4px; }
  .db-mp-hint { flex-basis: 100%; font-size: 11px; }
  .db-mp-back { margin-left: 0; }
}

/* Deck picker repeated under the room code on the waiting screen — centered to
   match the code above it, rather than the left-aligned idle-screen layout. */
.mp-deck-pick-waiting {
  justify-content: center;
  margin-top: 16px;
}
.mp-deck-pick-waiting .mp-deck-hint { text-align: center; }
/* "Share this code" line between the code and the deck picker. */
.mp-share-hint {
  margin-top: 8px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px;
  letter-spacing: 0.4px;
  color: rgba(170, 195, 215, 0.7);
  text-align: center;
}

/* ---- Shared deck-build lobby: ready-check row ----------------------
   Both players build at once; each readies up when their deck is legal and
   the match auto-starts. These sit inside .db-mp-banner. */
.db-mp-banner-lobby { border-color: rgba(var(--theme-rgb, 79,195,247), 0.55); }
.db-mp-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.db-mp-chip {
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: rgba(190, 210, 230, 0.85);
  background: rgba(6, 12, 22, 0.8);
  border: 1px solid rgba(120, 160, 210, 0.35);
  border-radius: 999px;
  padding: 3px 10px;
  white-space: nowrap;
}
.db-mp-chip-ready {
  color: #7ee8a5;
  border-color: rgba(120, 230, 160, 0.6);
  background: rgba(20, 50, 34, 0.7);
}
.db-mp-ready {
  background: rgba(var(--theme-rgb, 79,195,247), 0.14);
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.65);
  border-radius: 4px;
  color: var(--text-body, #e8f5ff);
  font-family: 'Rajdhani', sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  padding: 6px 16px;
  cursor: pointer;
}
.db-mp-ready:hover:not(:disabled) { background: rgba(var(--theme-rgb, 79,195,247), 0.26); }
.db-mp-ready:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  border-color: rgba(120, 160, 210, 0.3);
}
.db-mp-ready-on {
  background: rgba(20, 60, 38, 0.85);
  border-color: rgba(120, 230, 160, 0.7);
  color: #7ee8a5;
}
.db-mp-ready-on:hover { background: rgba(28, 80, 50, 0.9); }

/* ============================================================
   GLOBAL CARD-MAGNIFY MOTION (2026-07-27)
   User: "hover should be GLOBAL in all areas of the game, not just a local fix
   — like on boards, roguelite, draft if necessary. All the changes I make are
   GLOBAL."
   The smooth hover growth was only ever authored on .trick-card (and then the
   hand). Every OTHER card surface had its own ad-hoc timing with the browser
   default ease, which is why they felt like a snap next to the tricks:
       .card                     transform 0.2s
       .draft-card               transform 0.2s
       .rl-pick-cardslot         transform 0.18s
       .choice-tray .choice-card transform 0.15s
       .db-grid-item             transform 0.1s
       .trick-card               transform 240ms + soft ease   <- the good one
   Five durations, one shared feel missing. This block makes the trick's motion
   the SINGLE SOURCE OF TRUTH for every card-like surface — board, hand, tricks,
   draft, roguelite picks, choice trays, deck-builder grid — so a card magnifies
   identically wherever it appears, and a new surface only has to choose its
   scale AMOUNT, never re-invent the timing.
   DELIBERATELY NOT unified: transform-origin. It is contextual and already
   documented per surface — hand + tricks grow UPWARD from their row baseline
   (center bottom), board cards grow from center because lanes have headroom
   both ways and a bottom origin would shove them into the opposite row.
   Placed last so it beats the per-surface transitions above without !important.
   ============================================================ */
:root {
  --card-magnify-dur: 240ms;
  --card-magnify-ease: cubic-bezier(0.22, 1, 0.36, 1);
}
.card,
.hand-card-wrapper,
.hand-card-wrapper .card.hand-card,
.trick-card,
.draft-card,
.rl-pick-cardslot,
.choice-tray .choice-card {
  transition: transform var(--card-magnify-dur) var(--card-magnify-ease), box-shadow 200ms var(--ease-snap), border-color 200ms var(--ease-snap), filter 200ms var(--ease-snap);
}
/* .db-grid-item is deliberately NOT in that list. The deck-builder grid does not
   MAGNIFY — its hover is a 2px lift on a dense list of dozens of rows. Pushing a
   240ms grow-curve onto a 2px nudge makes the whole grid feel sluggish, so this
   contract covers surfaces that actually scale a card. (It also declares
   `transition: all 0.15s ` var(--ease-snap), which would need an  war to
   override — not worth starting for a change that would make it feel worse.) */
/* Reduced motion / low-fx keep the snap — growth is the affordance, not the
   animation, so removing the tween must not remove the enlarge. */
@media (prefers-reduced-motion: reduce) !important{
  .card, .hand-card-wrapper, .hand-card-wrapper .card.hand-card, .trick-card,
  .draft-card, .rl-pick-cardslot, .choice-tray .choice-card {
    transition-duration: 0.01ms;
  }
}

/* ---- Focus rings restored where a reset had removed them outright --------
   Three rules killed the focus ring with `outline: none !important` and put
   nothing in its place, so keyboard users had no idea where they were:
   .mp-code-display (the multiplayer room code), .db-search (the deck-builder
   search field — an INPUT, where focus matters most), and .game-over-btn.
   The first two are now scoped to `:focus:not(:focus-visible)`, the standard
   pattern: no ring when clicked with a mouse, ring when reached by keyboard.
   .game-over-btn's reset sits on its BASE rule, so it needs an explicit
   keyboard-only override rather than a rescope. Deliberately NOT touched:
   .mm-mw3 .mm-option:focus-visible, which suppresses the outline because it
   has its own scale + glow focus treatment — that one is a design choice. */
.game-over-btn:focus-visible {
  outline: 2px solid var(--theme-accent-bright, #4fc3f7) !important;
  outline-offset: 3px;
}

/* ============================================================
   SCREEN SHELL — THE FINAL WORD (2026-07-27)
   User: "I just want uniformity from game board to codex to roguelite to menu
   to multiplayer — everything the same style, texture."

   Assigning the shell tokens at each panel's own rule was not enough: the
   sheet has accumulated EIGHT later blocks that re-apply a gradient wash
   (linear-gradient theme-wash at ~12333, 12351, 13147, 13880, 27611; radial
   at ~14191, 14509; plus the deck-builder's own at ~18079), and several that
   re-assert `border-radius: 4px` and a different border colour. Source order !important;
   the computed styles alone looked fine, which is exactly why a visual check is
   not optional for this kind of sweep. A hero screen differing from a panel
   screen is hierarchy, not inconsistency. */
.mode-panel,
.draft-panel,
.db-panel,
.stats-panel,
.rl-panel,
.mh-panel,
.rl-modal-panel,
.encyc-panel,
.mp-panel,
/* The draft screen defended itself with COMPOUND selectors at (0,2,0) —
   `.draft-panel:not(.draft-tricks)` and `.draft-panel.draft-tricks` — carrying
   !important on border-top-color / border-bottom-color plus their own radial
   wash. Two !important declarations are resolved by specificity, so a bare
   `.draft-panel` here could never win: the draft screen kept a brighter frame
   (0.95 alpha vs 0.55) and a gradient nobody else had. Matching their
   specificity is what finally brings it into line with the other nine. */
.draft-panel:not(.draft-tricks),
.draft-panel.draft-tricks {
  background: #000 !important;
  background-image: none !important;   /* kills every re-applied wash gradient */
  border: var(--panel-border) !important;
  border-top-color: rgba(var(--theme-rgb, 79,195,247), 0.55) !important;
  border-bottom-color: rgba(var(--theme-rgb, 79,195,247), 0.55) !important;
  border-radius: var(--panel-radius) !important;
}

/* ============================================================
   44px HIT TARGETS — the controls the 2026-06 a11y pass missed
   ============================================================
   That pass took .settings-cog from 42 -> 44px and shipped the in-match help
   button at 44px, but seven other real controls stayed between 30 and 36px:
   the battle-log toggle a phone player taps mid-match, and the close buttons
   that are the only way out of the card-inspect / encyclopedia / game-over
   panels on touch. Under the WCAG 2.5.5 / Apple HIG 44px minimum.

   The VISUAL size is deliberate (a chunky 44px square in the HUD next to the
   round pill would read as a box, and the house rule is no boxes), so only the
   hit area grows. A centered 44x44 pseudo does it independently of each
   control's own size — one rule instead of seven bespoke insets — and being
   out of flow it changes no layout.

   DELIBERATELY EXCLUDED, both for the same reason — a bigger target that
   overlaps a neighbour is WORSE than a small accurate one, because it starts
   stealing the neighbour's taps:

   .theme-swatch — 29px rings on a 36px pitch; 44px would overlap each
   neighbour by 8px a side. Needs the row respaced, which is a visual call.

   .log-drawer-toggle — it is anchored at left: calc(50% + 300px) while the
   in-match help button is at right: 68px. Clearing each other needs a viewport
   of at least 884px, but the media query that relocates the toggle only fires
   at <= 700px. So at 700-884px the two ALREADY overlap by up to 26px before
   any hit-area change (measured 694-724 vs 676-720 at a 788px viewport).
   That is a pre-existing placement bug, and where the toggle should live
   instead is a design decision, not something to patch invisibly here. */
.ci-close,
.peek-toggle,
.encyc-close,
.card-inspect-close,
.game-over-toggle,
.viewport-toggle {
  /* The pseudo positions against the control, so it must not be static.
     Only .encyc-close was (the rest are already fixed/absolute). */
  position: relative;
}
/* Re-assert the ones that were already fixed/absolute — `position: relative`
   above must not clobber their placement. */
.viewport-toggle { position: fixed; }
.ci-close, .peek-toggle, .card-inspect-close, .game-over-toggle { position: absolute; }

.ci-close::after,
.peek-toggle::after,
.encyc-close::after,
.card-inspect-close::after,
.game-over-toggle::after,
.viewport-toggle::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 44px;
  height: 44px;
  transform: translate(-50%, -50%);
  /* Invisible: this is reach, not chrome. */
  background: none;
  border: 0;
  /* NO pointer-events:none here. The pseudo is what makes the extra area
     tappable at all — hit-testing attributes it to its host button, so a tap
     7px outside the 30px visual still fires the button's handler. Setting
     pointer-events:none would make this whole block a silent no-op. */
}

/* ============================================================
   CONTESTED SEAM — the two sides actually MEET and blend
   ============================================================
   User: "i like color theory and tron, so when red and blue meet it creates
   purple in the middle, when the neon theme changes so does the middle —
   red and green make yellow and so on. make the color transition smooth and
   different depending on the combination."

   The MIX ITSELF is computed in UI.recomputeContestMix() (ui.js) by additive
   light mixing of the live --enemy-* and --player-* triplets, so it is correct
   for any theme including ones added later. It lands on magenta for red+blue,
   yellow for red+green, orange for red+gold, pink for red+purple. The
   hand-picked --contest-pop values stay in the cascade purely as a fallback
   for the frame before JS runs.

   This block is the other half: making the meeting VISIBLE. The centerline is
   a 1px hairline, so a gradient inside it has nowhere to go. Instead a band
   sits behind the seam carrying enemy colour down from above and player colour
   up from below, crossing through the computed mix exactly at the centerline —
   two neon fields bleeding into each other rather than a flat divider. */
.lane.occ-both .lane-sep::after {
  content: '';
  position: absolute;
  left: 0; right: 0;
  top: 50%;
  /* Tall enough to read as a bleed, centered on the hairline. */
  height: 46px;
  transform: translateY(-50%);
  pointer-events: none;
  z-index: -1;
  background:
    /* Vertical: enemy above -> MIX at the seam -> player below. */
    linear-gradient(180deg,
      transparent                                     0%,
      var(--enemy-glow-inner,  rgba(231,76,60,0.22)) 26%,
      var(--contest-pop, rgb(255, 60, 200))          50%,
      var(--player-glow-inner, rgba(79,195,247,0.22))74%,
      transparent                                   100%);
  /* Horizontal falloff so the band dies out at the lane edges instead of
     ending in a hard rectangle. */
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 22%, #000 78%, transparent 100%);
          mask-image: linear-gradient(90deg, transparent 0%, #000 22%, #000 78%, transparent 100%);
  opacity: 0.55;
}

/* SMOOTH TRANSITION on a theme change. Custom properties do not animate on
   their own, so the transition goes on the properties that consume them —
   swapping themes cross-fades the seam from (say) magenta to yellow instead of
   snapping. Duration deliberately longer than the UI's 240ms motion rung: this
   is an ambient colour shift, not a control responding to a tap.
   Held to the contested seam only, so no other surface gains a transition. */
.lane .lane-sep::before,
.lane .lane-sep::after,
.lane .lane-number {
  transition:
    background 420ms var(--ease-out-soft, var(--ease-snap)), background-color 420ms var(--ease-out-soft, var(--ease-snap)), border-color 420ms var(--ease-out-soft, var(--ease-snap)), box-shadow 420ms var(--ease-out-soft, var(--ease-snap)), color 420ms var(--ease-out-soft, var(--ease-snap));
}
@media (prefers-reduced-motion: reduce) {
  .lane .lane-sep::before,
  .lane .lane-sep::after,
  .lane .lane-number { transition: none; }
}

/* ============================================================
   CONTESTED LANE — one color for the whole seam, blended
   ============================================================
   User, looking at a contested lane: "the lanes in the middle should also
   match the contested color, so for red/blue there should be no yellow on the
   left/right, it should be magenta and a seamless blend. red/green is
   yellow/gold, red/white is pink, red/gold is orange and so on."

   Two separate things were painting gold over a contested lane:

   1. The lane's LEFT/RIGHT BORDERS. .lane.occ-both drew its border-image as
      enemy-red down to 46%, a hard LEGENDARY-GOLD band from 47-53%, then
      player colour from 54%. That gold band sits at exactly seam height, which
      is the yellow flanking the magenta centre. It came from an older spec
      ("this yellow should be the same yellow you use as in legendaries") that
      this instruction supersedes.
   2. The ACTIVE-LANE combat pulse, still hardcoded gold in three places even
      though its own comment says the gold was replaced by a neutral pulse
      precisely so it "doesn't fight the lane's faction color".

   --lane-mid-color was already the canonical per-occupancy seam variable
   (player colour when you hold it, enemy colour when they do). It just needed
   to point at the computed mix for contested, and everything else needed to
   stop hardcoding gold and read it. One variable, every lane cue derives. */
.board-section .lane.occ-both {
  --lane-mid-color: var(--contest-pop, rgb(255, 60, 200));
  /* Seamless: the old stops were 46/47/53/54, deliberately hard-edged. The two
     sides now bleed through the mix instead of butting against a band. */
  border-image: linear-gradient(180deg,
    rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95)     0%,
    rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95)    28%,
    var(--lane-mid-color)                                                      50%,
    rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95) 72%,
    rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95) 100%
  ) 1 !important;
}

/* Lane interior — the pillar left a transparent hole at 50%, exactly where the
   two colours meet. Carry a faint wash of the mix through it so the blend
   reads across the whole lane, not just on the 1px centreline. Kept low-alpha:
   this is atmosphere behind the cards, not a beam. */
.lane.occ-both::before {
  background: linear-gradient(180deg,
    transparent 0%,
    rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.10)     22%,
    rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.10)     42%,
    var(--contest-pop-dim, rgba(255, 60, 200, 0.22))                            50%,
    rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.10) 58%,
    rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.10) 78%,
    transparent 100%) !important;
}

/* Active lane (the one resolving combat) — reads the lane's OWN seam colour
   instead of gold, so a contested lane pulses magenta/yellow/orange to match
   its own mix. The "resolving now" cue is carried by the 1.2s pulse and the
   tracer sweep, which is what the earlier note intended. Empty lanes have no
   --lane-mid-color, so they fall back to neutral white rather than gold. */
.lane.lane-active {
  border-color: var(--lane-mid-color, rgba(255,255,255,0.95)) !important;
  box-shadow:
    0 0 12px var(--lane-mid-color, rgba(255,255,255,0.95)),
    0 0 24px var(--contest-pop-soft, rgba(255,255,255,0.25)) !important;
}
/* A contested lane KEEPS its blended border while active — the old rule killed
   border-image outright so the gold could win, which threw away the whole
   red -> mix -> player gradient for the duration of combat. */
.board-section .lane.occ-both.lane-active {
  border-image: linear-gradient(180deg,
    rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95)     0%,
    rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95)    28%,
    var(--lane-mid-color)                                                      50%,
    rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95) 72%,
    rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95) 100%
  ) 1 !important;
}
.lane.lane-active::after {
  background: linear-gradient(180deg,
    transparent 0%,
    var(--lane-mid-color, rgba(255,255,255,0.95)) 50%,
    transparent 100%) !important;
  box-shadow:
    0 0 12px var(--lane-mid-color, rgba(255,255,255,0.95)),
    0 0 24px var(--contest-pop-soft, rgba(255,255,255,0.30)) !important;
}
.lane .lane-sep.lane-active::before {
  box-shadow:
    0 0 10px var(--lane-mid-color, rgba(255,255,255,0.55)),
    0 0 20px var(--contest-pop-soft, rgba(255,255,255,0.20)) !important;
}

/* ============================================================
   HIT FLASH must beat the ambient "vibe" breathe
   ============================================================
   `animation` is a single property, so a card's ambient loop and its one-shot
   damage flash compete — and the ambient one was winning on specificity:

     .card.vibe-titan:not(.card-enter):not(.card-exit)   (0,4,0)
     .card.hit-flash                                     (0,2,0)

   So every card with a vibe (titan / cosmic / symbiote / slasher / phase /
   speed — i.e. exactly the splashy ones where impact matters most) breathed
   calmly through being hit and never flashed at all. Measured live: Bane
   (vibe-titan) computed animationName `vibeTitanBreathe` with .hit-flash
   applied, while King Shark (no vibe) correctly computed `hitFlash`.

   Matching the vibe rules' shape gives equal specificity, and being later in
   the file wins the tie. For the 300-520ms the flash runs it replaces the
   3.6s breathe, which is the correct read — a card taking a hit should flash,
   not breathe. The ambient loop resumes when the class self-removes.
   Both !important guards still outrank this: reduced-motion and the
   coarse-pointer / narrow-screen battery diet continue to suppress it. */
.card.hit-flash:not(.card-enter):not(.card-exit) {
  animation: hitFlash var(--flash-ms, 0.3s) ease-out;
}

/* ============================================================
   HERO HEAL FEEDBACK — the green mirror of the damage float
   ============================================================
   Healing emitted nothing at all until now: the `heal` FX type was documented
   on Game.emitDmg and the `+N` branch existed in showDamageFloats, but no
   engine path ever raised the event, so both were dead code. Lifesteal was the
   worst case — HP crept up mid-combat with no tell whatsoever.
   Reuses .hp-dmg-float's geometry and timing so a heal reads as the exact
   counterpart of a hit, only green and offset to the other side so a
   simultaneous hit and heal don't overlap. */
.hp-dmg-float.hp-heal-float {
  color: #7ee8a5;
  right: auto;
  left: 10%;
  text-shadow: 0 0 8px rgba(46,204,113,0.7), 0 2px 4px rgba(0,0,0,0.8);
}
/* Bar pulse on heal — counterpart of .hp-flash, which is the damage version. */
.hp-heal-flash {
  animation: hpHealFlash 500ms ease-out;
}
@keyframes hpHealFlash {
  0%   { filter: brightness(1); }
  30%  { filter: brightness(1.9) saturate(1.3); }
  100% { filter: brightness(1); }
}
@media (prefers-reduced-motion: reduce) {
  .hp-dmg-float.hp-heal-float { animation: none; }
  .hp-heal-flash { animation: none; }
}

/* ============================================================
   HAND CARDS READ LIKE BOARD CARDS — text on hover only
   ============================================================
   User: "can we change the cards in hand to look like the ones on board with
   no text? and then when you hover it will show the text."

   The phone build has done exactly this for a while (the rule in the <=640px
   block), and its comment records the payoff: dropping the description takes a
   hand card from ~276px to ~140px — i.e. board-card height. Desktop kept the
   tall text face, which is why the hand reads as a different object from the
   board, and why at 430px three of eight cards sit entirely off-screen.

   So this is the phone treatment promoted to the default, which also makes the
   two surfaces consistent rather than adding a third look.

   Hover reveal is gated on a real hover-capable fine pointer. On touch,
   :hover latches after a tap and would leave a card stuck open — touch keeps
   its own path (tap = inspect modal, drag = play).

   THE TEXT IS A FACE, NOT CONTENT — this is the whole trick.
   The first attempt simply un-hid .card-desc on hover, and it fell apart on
   screen: a hand card is ~125px wide, so releasing a long description inside it
   reflowed the card into a 700px ribbon of two-word lines that ran off the
   bottom of the viewport (Boiler Room, worst case, is ~60 words). Nothing about
   a fixed card height survives content that can triple it.

   So the description is taken OUT OF FLOW and laid over the card as its back
   face: position:absolute, so it can never contribute to card height, and the
   194px row below stays true no matter how wordy the card is. It swings in on
   rotateY, which is the flip the user asked for — "when you hover press it will
   flip the card to show the text".

   The rotation is on the FACE, not the card, and that is deliberate: the card's
   own transform is already owned by the JS hover spring (see the note at
   ~21567 about the spring driving translate3d), and the wrapper's transform is
   owned by the tilt parallax. Animating either here would fight code that is
   writing transform every frame. The face is a free surface, and flipping it
   over a stationary card reads the same.

   The face covers the WHOLE card, orbs included. It first stopped 30px short
   so the ATK/HP orbs stayed readable, and that was wrong on screen — the black
   panel ended in a seam just above the numbers instead of reading as the back
   of the card. User: "i want that pure black on the whole back of the card it
   stops just abover the damage/health that needs to cover the entire back."
   Going full-bleed also hands the text those 30px, which is why fewer cards
   need to step their font down now. */
.player-hand-section .hand-cards .card .card-desc {
  position: absolute;
  inset: 0;
  border-radius: inherit;   /* follow the card's corners, do not square them off */
  z-index: 7;
  margin: 0;
  /* MUST be block flow, not flex. The description is rich text — it contains
     <b> runs and <span class="kw"> keyword chips — and under `display: flex`
     every one of those becomes its own flex item in a row, each squeezed to
     its minimum content width and wrapped character-by-character. Measured on
     Yoda: 250 characters demanded 746px of height inside a 162px box. Block
     flow lets the inline runs sit in the sentence where they belong. */
  display: block;
  /* Vertical centering WITHOUT display:flex — align-content works on a block
     container in modern engines, so the text block is centred while its inline
     runs (<b>, keyword chips) keep laying out as a normal sentence. Flex would
     centre it too, and would also shatter the sentence into one flex item per
     inline element. Where align-content is unsupported the text just sits at
     the top, which is the previous behaviour and perfectly readable. */
  align-content: center;
  text-align: center;
  padding: 5px 5px;
  background: #000;    /* panel interiors are always pure #000 */
  font-size: 8px !important;   /* beats the base .card-desc size (9px) */
  line-height: 1.25;
  letter-spacing: 0.1px;
  overflow: hidden;
  /* Out of sight at rest, and out of the way of clicks/drags. */
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: rotateY(90deg);
  transform-origin: 50% 50%;
  backface-visibility: hidden;
}
/* THE FLIP IS A CLICK, NOT A HOVER.
   Hover used to reveal the face automatically, and that was wrong: the cursor
   crosses the hand constantly, so cards kept turning over on their own and you
   could never just look at the art. User: "when you hover over a card it
   shouldnt automatically show the text you have to click in order to flip the
   card ... so you can still see the art on the front when you magnify".
   Hover now does nothing but magnify. Click turns the card over, click again
   turns it back, and dragging still plays it — the drag handler suppresses the
   click that ends a drag, so pulling a card out never flips it on the way. */
/* THE DOSSIER — the card's own record, under its rules text on the flip side.
   Quiet by construction: it is reference material you go looking for, not
   something competing with the rules for the same glance. Tabular round
   numbers so the column lines up. */
.card-dossier {
  margin-top: 7px;
  padding-top: 6px;
  border-top: 1px solid rgba(var(--theme-rgb,79,195,247),0.18);
  text-align: left;
}
.dossier-title {
  font-family: 'Rajdhani', sans-serif;
  font-size: 8px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  color: rgba(var(--theme-rgb,79,195,247),0.75);
  margin-bottom: 3px;
}
.dossier-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 1px; }
.dossier-list li { display: flex; gap: 6px; align-items: baseline; }
.dossier-round {
  font-family: var(--font-mono);
  font-size: 9px; font-weight: 700;
  color: rgba(var(--theme-rgb,79,195,247),0.9);
  font-variant-numeric: tabular-nums;
  flex: 0 0 auto; min-width: 16px;
}
.dossier-text {
  font-family: 'Inter', sans-serif;
  font-size: 9px; line-height: 1.35;
  color: var(--text-mute, #b8c2cc);
  overflow-wrap: anywhere;
}

.player-hand-section .hand-cards .card.face-flipped .card-desc {
  visibility: visible;
  opacity: 1;
  transform: rotateY(0deg);
  /* Opacity lands at the halfway point of the turn, so the face appears
     edge-on rather than fading in flat. */
  transition:
    transform 240ms var(--ease-out-quart), opacity 90ms linear 70ms;
}
/* The turn reads as one object rotating: the art swings out as the text swings
   in, rather than a black panel simply appearing on top of a static portrait. */
.player-hand-section .hand-cards .card .card-portrait {
  transition: transform 240ms var(--ease-out-quart), opacity 90ms linear 70ms;
  backface-visibility: hidden;
}
.player-hand-section .hand-cards .card.face-flipped .card-portrait {
  transform: rotateY(-90deg);
  opacity: 0;
}
/* A flipped card is showing its rules, so the front chrome should not be
   half-visible around the edges of the panel. */
.player-hand-section .hand-cards .card.face-flipped .status-badges,
.player-hand-section .hand-cards .card.face-flipped .card-name-overlay,
.player-hand-section .hand-cards .card.face-flipped .card-name-banner {
  opacity: 0;
  transition: opacity 90ms linear;
}
/* THE FRONT CHROME IS NOT A HOVER TARGET WHILE THE FACE IS UP.
   The face is pointer-events:none so it never eats a drag, which means the
   badge strip UNDERNEATH kept receiving the hover and kept firing its keyword
   tooltip — describing badges the player can no longer see, on top of the card
   they are trying to read. User: "when i hover over the card the status badges
   in the front are still being described."
   Making the covered chrome non-interactive is the fix at the source rather
   than teaching the tooltip code about this one case, and it settles a second
   bug for free: the keyword click handler calls stopPropagation, so clicking
   the badge strip on a hand card used to pin a tooltip INSTEAD of playing the
   card — an invisible dead zone once the face covered it.
   Scoped to hover-capable pointers, which is exactly where the face exists.
   Touch never flips, its badges stay visible, and tap-to-pin still works. */
@media (hover: hover) and (pointer: fine) {
  /* NARROWED to the flipped state only. Blanket pointer-events:none also
     killed the tooltip on a badge you CAN see — hovering Overdrive on a hand
     card described nothing, because elementFromPoint returned the card and
     closest('[data-kw]') found nothing to describe.
     Both original bugs stay fixed. The "describing chrome hidden behind the
     face" case is exactly the flipped state, which is still switched off here.
     The "click pins instead of playing the card" case is now handled in the
     click handler itself, which returns early for any keyword inside the hand
     — a better place for it, since it is about what a CLICK means rather than
     whether the element can be pointed at. */
  .player-hand-section .hand-cards .card.face-flipped .status-badges,
  .player-hand-section .hand-cards .card.face-flipped .status-badge {
    pointer-events: none;
  }
}
/* Motion budget: reduced-motion users get the same face, no rotation. */
@media (prefers-reduced-motion: reduce) {
  .player-hand-section .hand-cards .card .card-desc {
    transform: none;
    transition: opacity 120ms linear;
  }
}

/* ============================================================
   SETTING: HAND CARD TEXT = "ALWAYS SHOW"  (body.hand-text-always)
   ============================================================
   Default is flip-to-view (art on front, click to read). This opt-in mode
   (Settings > Hand card text > Always show) keeps the rules visible at rest,
   as a panel across the LOWER half of the card with the art still showing
   above it. User: "i like it better when you can see the cards description."
   The panel sits at z-index 3 — under the cost badge and the ATK/HP orbs
   (both z-index 4), so those stay legible on top — and over the portrait. The
   click-to-flip face still works; this only changes the at-rest look. */
body.hand-text-always .player-hand-section .hand-cards .card .card-desc {
  /* OLD SPEC-SHEET LOOK: the rules flow IN the card body again (below the art
     and the keyword badges) instead of being a hidden flip face, and the card
     grows to fit — art on top, name, badges, then the description, all visible
     at once. User: "i basically want the always show method to be like the old
     way the cards and tricks looked, along with showing the badges." */
  position: static;
  inset: auto;
  transform: none;
  visibility: visible;
  opacity: 1;
  z-index: auto;
  height: auto;
  background: transparent;
  align-content: normal;
  text-align: center;
  border-radius: 0;
  overflow: visible;
  padding: 3px 6px 4px;
  pointer-events: none;
}
/* Let the card grow to fit the in-flow rules. The card carries
   `aspect-ratio: 92/182`, which pins its height to its WIDTH regardless of
   content — so with the description back in flow, long cards (Galactus,
   Anakin) overflowed their own border (user: "the card text leaves the card
   border"). Dropping the ratio here lets the height track the CONTENT again. */
body.hand-text-always .player-hand-section .hand-cards .card {
  aspect-ratio: auto !important;
  height: auto !important;
  min-height: 0 !important;
}
/* Show the keyword badges (Bullseye / Evade / …) as they used to appear, and
   let the strip show every row rather than the 2-row art-mode clamp.
   The compact flip view renders badges as ICONS to fit one fixed row; but an
   "Always show" card GROWS to its content, so there is room for the readable
   WORD badges the way they used to look. Swap the glyph back for the word and
   let the strip wrap to as many rows as it needs. User: "why do the badges
   look so weird to how they used to look." */
body.hand-text-always .player-hand-section .hand-cards .card .status-badges,
body.hand-text-always .trick-cards .trick-card .status-badges {
  max-height: none;
  overflow: visible;
}
body.hand-text-always .player-hand-section .hand-cards .card .status-badge .sb-i,
body.hand-text-always .trick-cards .trick-card .status-badge .sb-i {
  display: none;
}
body.hand-text-always .player-hand-section .hand-cards .card .status-badge .sb-w,
body.hand-text-always .trick-cards .trick-card .status-badge .sb-w {
  display: inline;
  font-size: 8px;
  letter-spacing: 0.2px;
}
body.hand-text-always .player-hand-section .hand-cards .card .status-badge,
body.hand-text-always .trick-cards .trick-card .status-badge {
  font-size: 8px;
  padding: 1px 4px;
  gap: 2px;
}
body.hand-text-always .player-hand-section .hand-cards .card .status-badge .sb-n,
body.hand-text-always .trick-cards .trick-card .status-badge .sb-n {
  font-size: 8px;
}
/* BOARD character cards match the hand in "Always show": word badges, not the
   compact-view icon glyphs. User: "i want the badges for characters on the
   board to be like the way they are in hand." The board strip keeps its 2-row
   cap, so a 5-keyword legend still clips its overflow the way the board always
   did — the card is a fixed lane slot and cannot grow like a hand card. */
body.hand-text-always .card.ally-card .status-badge .sb-i,
body.hand-text-always .card.enemy-card .status-badge .sb-i {
  display: none;
}
body.hand-text-always .card.ally-card .status-badge .sb-w,
body.hand-text-always .card.enemy-card .status-badge .sb-w {
  display: inline;
}
/* A keyword with no glyph is dropped on the compact board; with words back it
   can show its text again. */
body.hand-text-always .card.ally-card .status-badge.sb-noicon,
body.hand-text-always .card.enemy-card .status-badge.sb-noicon {
  display: inline-flex;
}
body.hand-text-always .card.ally-card .status-badge.sb-noicon .sb-w,
body.hand-text-always .card.enemy-card .status-badge.sb-noicon .sb-w {
  display: inline;
}
/* Re-enable badge hover/tap so the keyword tooltip works. Badges are
   pointer-events:none in the compact view only because the flip face covers
   them; in "Always show" there is no face over them, and the user wants a
   badge to name itself on hover or click. */
body.hand-text-always .player-hand-section .hand-cards .card .status-badges,
body.hand-text-always .player-hand-section .hand-cards .card .status-badge,
body.hand-text-always .trick-cards .trick-card .status-badges,
body.hand-text-always .trick-cards .trick-card .status-badge {
  pointer-events: auto;
}
/* The name sits over the art as before — keep it readable above everything. */
body.hand-text-always .player-hand-section .hand-cards .card .card-name-banner,
body.hand-text-always .player-hand-section .hand-cards .card .card-name-overlay {
  z-index: 4;
}
/* The click-flip face, when used in this mode, is still the full-bleed panel —
   restore its full height so a flipped card reads exactly as before. */
body.hand-text-always .player-hand-section .hand-cards .card.face-flipped .card-desc {
  inset: 0;
  height: auto;
  align-content: center;
  background: #000;
  padding: 5px 5px;
}

/* ============================================================
   HAND CARD SPACING — orb strip + an even row
   ============================================================
   Fallout from making hand cards textless. Two things broke, both visible on
   Thor (Splash 5 + Unresistible):

   1. THE STAT ORBS GOT SAT ON. .stat-circle is absolutely positioned in the
      bottom corners, and the description used to occupy the space above them.
      With the text gone the badge block runs straight down into the orbs, so a
      two-row badge set overlaps the ATK/HP numbers.
      This is the same problem the BOARD already solved — .card-slot > .card
      carries `padding-bottom: 30px` as a dedicated orb strip, with a comment
      about PEACEMAKER reading as EACEMAKE when the orbs sat on the name. The
      hand needs the identical reservation.

   2. THE ROW WENT RAGGED. Card height is now driven by badge COUNT, measured
      across a real hand: Boiler Room 117, Gizmo 141, The Thing 154,
      Spider-Man 154, Thor 169, Galactus 213 — a 96px spread, so the cards no
      longer sit on a shared baseline.
      A fixed height puts them back on one. Badges that do not fit are clipped
      at rest and revealed on hover, which is the same bargain the text already
      makes: rest is the at-a-glance read, hover is the full card. */
.player-hand-section .hand-cards .card {
  /* Reserved strip for the corner ATK/HP orbs — mirrors the board rule. */
  padding-bottom: 30px;
  /* PROPORTION, NOT A FIXED HEIGHT. User: "why do the cards change aspect
     ratio, that shouldnt happen."

     This was `height: 200px`, and that was wrong the moment it was written: the
     card's WIDTH is fluid. It has no width rule at all — it is a shrink-to-fit
     flex item, so its width comes out of the layout and measures 92px in the
     <=520px container query, 108px at a 836px viewport and 140px at 1400px.
     Pinning the height to a constant while the width floats means the card's
     SHAPE changes with the window: measured 0.54 at 836 and 0.70 at 1400.

     It also broke the layout outright, because the art's height derives from
     the width via aspect-ratio 360/472. At 140px wide the art is 181 tall, so
     the card needs 181 + 28 badges + 30 orb strip = 239px of content inside a
     200px box — every card in the hand overflowed, by 26px on a two-badge card
     and 41px on Galactus, which is the badge spill visible under the card.

     aspect-ratio makes height track width, so the card is the same object at
     every size. The ratio is set by the SMALLEST width, since the badge strip
     and orb strip are fixed px and therefore eat the largest share there:
       92 wide  -> art 120.6 + badges 28 + orbs 30 + 3 clearance = 181.6
     giving 92/182. Wider cards inherit slack rather than overflow — at 108 the
     content needs 202 of 213, at 140 it needs 245 of 277.
     Ragged before any of this: 117 / 141 / 154 / 154 / 169 / 213. */
  aspect-ratio: 92 / 182;
  box-sizing: border-box;
}
.player-hand-section .hand-cards .card .status-badges {
  /* Badges live between the portrait and the orb strip: 178 - 30 orbs - 123
     portrait leaves 25px, so the strip is capped at two rows.

     Sizing it by ROWS rather than clipping horizontally is deliberate. The
     strip is justify-content: center, so a nowrap + overflow clip would slice
     the FIRST and LAST badge in half and show two stubs. Wrapping and capping
     the height keeps every badge that is visible a whole, readable badge, and
     drops whole rows past the cap.

     The shrink is what makes the cap nearly free. Measured across all 117 card
     defs at the old size, the strip came out 0 / 13 / 28 / 42 / 72px tall
     (Anakin Skywalker worst at 5 badges). Sizing the CARD to fit 72px would
     mean a 225px-tall hand row, which is why the cap exists at all — but a
     badge two steps smaller re-flows those same badges into far fewer rows, so
     the cap catches only the heaviest handful instead of a third of the set.

     Re-measured after the shrink, the strip is 0px on 59 cards, one row on 40,
     two rows on 12, and only 6 need more (Knull at 3 rows; Anakin, Dormammu,
     Dr. Manhattan, Galactus and Trigon at 5 badges / 4 rows). Capping at two
     rows therefore shows every badge on 111 of 117 cards, and those last 6 are
     exactly the legends whose card you were going to hover anyway. */
  max-height: 28px;
  overflow: hidden;
  gap: 1px;
  font-size: 7px;
  letter-spacing: 0.1px;
}
.player-hand-section .hand-cards .card .status-badge {
  padding: 1px 3px;
  font-size: 7px;
  letter-spacing: 0.1px;
}
/* NOTE — the height stays 194px on hover too, and there is deliberately no
   `height: auto` release here. That release existed while the description was
   in flow; now that the text is an absolutely-positioned face (see above) it
   adds nothing, and it would actively hurt: with the desc out of flow the
   natural height is only ~164px, so releasing would make the card SHRINK the
   moment you hover it. Same reason the badge clamp is not released — the text
   face is drawn over the badge strip, so anything revealed underneath is
   simply not visible. */

/* ============================================================
   DRAG GHOST = THE BOARD TILE IT WILL BECOME (all screen sizes)
   ============================================================
   User, on the new desktop drag: "for the drag there should be no text as it
   looks weird" — the ghost was dragging the full tall card, description and
   all.

   These rules already existed and already fixed exactly this, but they were
   written INSIDE the <=640px block, so only phones got them. The comment there
   even recorded the same complaint from the mobile era: "the drag works but its
   the whole long card not the condensed board version." Desktop drag simply
   inherited the bug the moment mouse drag was added.

   The ghost is a hand-card clone appended to <body>, so it escapes every
   .player-hand-section-scoped rule — including the textless-hand rule — which
   is why it needs its own explicit compaction rather than inheriting one.
   Promoted here verbatim and deleted from the media query, so there is ONE
   definition instead of two that can drift apart. */
.card-drag-ghost .card-name-banner,
.card-drag-ghost .card-name,
.card-drag-ghost .card-desc,
.card-drag-ghost .trick-desc,
.card-drag-ghost .card-active-text { display: none !important; }
/* .card-name-overlay IS NOT A NAME LABEL — IT IS THE ART-TO-BLACK SCRIM.
   It used to sit in the hide list above, and that brought back the exact seam
   the user reported months ago on the magnified card ("you can clearly see the
   separation point of the art and the card"), this time on the drag ghost:
   "when you drag a card you see the crisp separation of the art and black, it
   should be merged like the card in hand."
   The element carries BOTH jobs — the 180deg gradient that dissolves the
   painting into #000 (see .card-portrait .card-name-overlay, whose whole
   comment is about that fade needing LENGTH as well as a black endpoint), and
   the name text drawn on top of it. Hiding the element to lose the text threw
   away the fade with it, and the art then ended on a hard edge against the
   card body.
   So hide the TEXT and keep the SCRIM. Transparent colour rather than
   font-size:0 on purpose: the box is anchored bottom:0 with no height, so its
   height is padding-top PLUS one line — collapsing the line would shorten the
   gradient by ~13px and quietly weaken the very blend this is protecting.
   The ghost now dissolves identically to the card it was cloned from. */
.card-drag-ghost .card-name-overlay {
  color: transparent !important;
  text-shadow: none !important;
}
.card-drag-ghost .card-abilities.status-badges { font-size: 6px; gap: 1px; flex-wrap: wrap; max-width: 100%; }
.card-drag-ghost .status-badge { padding: 1px 2px; font-size: 6px; letter-spacing: 0.1px; max-width: 100%; }
.card-drag-ghost .card-cost { --cost-size: 20px; }
.card-drag-ghost .stat-circle { width: 16px; height: 16px; font-size: 10px; }
.card-drag-ghost .stat-circle.stat-atk { bottom: 2px; left: 2px; }
.card-drag-ghost .stat-circle.stat-hp  { bottom: 2px; right: 2px; }
.card-drag-ghost .rarity-strip { top: 3px; right: 3px; transform: scale(0.6); transform-origin: top right; }

/* ============================================================
   IN-MATCH CARD TILE — EDGE-TO-EDGE ART, ORIGINAL CROP
   ============================================================
   User: "now there is so much more room on the front to make the cards look
   sleeker and for the art to not clip", then, on the first attempt:
   "the zooms are a little off ... the zooms need to be like the original crops
   ... like the draft cards."

   WHAT THE FIRST ATTEMPT GOT WRONG. It stretched the art to the CARD's shape.
   The card is 0.557 and the art is 0.763, so cover had to scale to the taller
   side: every card came out magnified 1.57x with 27% of its width cut. More art
   on screen, yes, but a different photograph — and it re-framed the 51 focal
   and 11 zoom overrides that had been dialled in by hand.

   The draft card is the reference and shows why: its window is 186x244, aspect
   0.763 — the ART'S OWN SHAPE — so cover crops nothing. The old hand window
   (94x123) was the same 0.763. Matching that aspect is what makes the crop
   "original", at any size.

   SO THE ART BOX KEEPS 0.763 AND ONLY GETS WIDER: full card width instead of
   inset 6px, height following the ratio. Same aspect means the same crop as the
   draft card and as the original for every card, every focal point and every
   zoom, while still being ~27% more art than before and edge-to-edge across the
   card. Sleeker without re-framing anything.

   The portrait stays in NORMAL FLOW. Taking it out was what forced the rest of
   this block to re-place the name and badges absolutely, and with a 139px-tall
   art box instead of 194 those hand-placed offsets dropped the name plate on
   top of the badge row (visible on Batman, Black Widow and Thor). In flow, the
   badges sit under the art on their own, exactly as they always did.

   Hand and board share this: measured side by side they are the same object.
   Codex/draft/dead-pile are untouched — they already frame the art correctly,
   which is the whole reason the draft card was the target. */
.player-hand-section .hand-cards .card,
.card.ally-card,
.card.enemy-card,
/* The drag ghost is a hand-card clone appended to <body>, so it escapes every
   .player-hand-section-scoped rule and would keep the old inset art while the
   card it left and the slot it targets both went edge-to-edge. */
.card-drag-ghost {
  /* Only the side/top inset goes; the bottom 30px stays as the orb strip. */
  padding: 0 0 30px;
}
.player-hand-section .hand-cards .card .card-portrait,
.card.ally-card .card-portrait,
.card.enemy-card .card-portrait,
.card-drag-ghost .card-portrait {
  /* Full width, and the height follows the art's own ratio — the draft card's
     window shape. Left in flow so the badges keep falling underneath it. */
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 360 / 472;
  margin: 0;
  /* Square art inside a 5px-rounded card is the classic cheap tell. Only the
     TOP corners round: the art stops partway down the card, so rounding its
     bottom corners would draw a curve across the middle of it. */
  border-radius: inherit;
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  /* NO background-position here on purpose. This rule briefly set one, and a
     bare value broke two things at once: it overrode --portrait-pos, which
     carries 51 hand-tuned focal points and 11 zooms published in
     card-art-manifest.js plus PORTRAIT_POSITION and any local gallery draft;
     and it collapsed the portrait's TWO background layers (art, then a
     200% 100% sweep) onto one value, so the sweep lost its 0% 0% anchor.
     The base .card-portrait rule already states both layers correctly and now
     carries the focal default too, so the tile inherits it and the tile, draft
     card and codex cannot drift apart. */

  /* (see also the corner-bracket rule below, which clears the thin lines that
     were left sitting in the black base under the art) */

  /* DROP THE PORTRAIT'S 1px FRAME RING — THIS is the "separation point".
     The base rule (~29754, the Tron frame) draws
       inset 0 0 0 1px rgba(var(--portrait-frame-rgb), 0.55)
     which is a theme-coloured line around all four sides of the ART BOX. That
     was right when the art was an inset 94x123 window: the ring framed the
     painting. Edge-to-edge it is wrong twice over — three sides now sit
     directly under the card's own 1px border and double it, and the fourth
     draws a bright green line straight across the middle of the card at the
     art's bottom edge.
     That line is what has been read as the seam all along. It is why fixing
     the scrim's opacity and then its length both helped and neither finished
     the job: they were dissolving the PAINTING into the black correctly while
     a 1px rule stayed drawn on top of the result.
     The inner vignette is kept — it is soft (18px blur), so it has no edge to
     see, and it is what gives the art depth. */
  box-shadow: inset 0 0 18px 4px rgba(0, 0, 0, 0.55);
}

/* ============================================================
   NO CORNER BRACKETS ON THE IN-MATCH TILE
   ============================================================
   User, after asking how the card is built: "thats why theres a base bottom
   with thin lines? i want the art to stay exactly where it is, just add black
   to the bottom to cover the entire card, thats all i want."

   The thin lines are .card::before. It paints EIGHT solid segments of
   rgba(220,226,234,0.75) — sized 10px x 1px and 1px x 10px, positioned at
   0%/0%, 100%/0%, 0%/100% and 100%/100% — i.e. an L-shaped bracket at each
   corner of the card.

   Over the art the top two are lost in the painting. The bottom two land in
   the black base, and a pair of bright right-angles down there is exactly what
   makes the base read as a separate panel bolted under the art rather than as
   the same card continuing. Answering the question directly: the art is a
   layer covering the top 140px of a 200px card, so everything below it is the
   card's own body showing through — and these brackets were the only thing
   drawing in it.

   Dropped for the in-match tile only. The card keeps its glowing edge: that is
   .card::after, the animated tron-perimeter tube, which is untouched — this
   removes the corner ticks, not the frame.
   Every other panel that uses .tron-perimeter keeps its brackets. */
.player-hand-section .hand-cards .card::before,
.card.ally-card::before,
.card.enemy-card::before,
.card-drag-ghost::before {
  background-image: none;
}

/* ============================================================
   THE BASE MUST BE ACTUALLY BLACK — KILL THE SHEEN OVER IT
   ============================================================
   User: "you have to be messing with me this is not the same", circling the
   black area under the art.

   They were right and I had been chasing edges when the problem was a FILL.
   .card::after paints, across the WHOLE card:

     linear-gradient(125deg, transparent 30%, rgba(255,255,255,0.10) 45%,
                     rgba(171,226,255,0.18) 50%, rgba(255,255,255,0.10) 55%,
                     transparent 70%)

   a diagonal gloss sweep. Over the painting it is invisible — it is competing
   with a photograph. Over the base it is an 18% pale-blue band lying across
   pure #000, which is roughly rgb(30,40,46) and obvious. So the two halves of
   the card were made of different material: photo above, tinted gloss below.
   No amount of work on the art's bottom edge could fix that, because the edge
   was never what was showing.

   Only the background is dropped. The border and box-shadow on the same
   pseudo-element are the tron-perimeter glow edge and are untouched, so the
   card keeps its lit outline.

   NOTE the sibling texture, deliberately left alone: .card-portrait::before
   carries the CRT scanlines and stops at the art (118px), so it too ends at the
   boundary. Measured, it does not matter — the lines are rgba(0,200,255,0.043)
   and by that depth they sit under ~65% of the name scrim, so the step across
   the boundary is well under 2% and invisible. The sheen was 10x that and
   unveiled. Removing texture that is not visible would only cost the art its
   CRT feel, and the CRT toggle owns that layer. */
/* BOARD CARDS ARE DELIBERATELY NOT IN THIS LIST — they were, and it was a bug.
   .card.ally-card::after / .card.enemy-card::after (style.css:29028) OVERRIDE the base
   gloss with something completely different: the CONTACT SHADOW, the soft ellipse under
   the card that makes it read as a physical token resting on the grid
   (radial-gradient + bottom:-12px + blur(4px) + rotateX(60deg)).
   So board cards never carried the sheen this rule removes — and including them here
   blanked their `background-image`, which is the gradient the shadow is MADE of. The
   geometry survived (still 28px tall, still blurred, still rotated) with nothing left to
   draw, so every card on the board went flat against the grid like a sticker.
   Two selectors, ten thousand lines apart, sharing one pseudo-element. */
/* REVERTED — this used to blank the ::after background on hand cards and the
   drag ghost, on the theory that a diagonal gloss was tinting the black base.
   It was not. That gradient sits at `opacity: 0` at rest and only rises to 1 on
   :hover (style.css ~19099), sweeping its background-position across — it is the
   card's hover SHINE, and it was invisible at rest the whole time. The base was
   actually being tinted by the inner outline ring, found later and now removed
   at the source. Blanking this only cost hand cards their shine.
   Kept as an empty rule so the history of the mistake stays attached to it. */
.player-hand-section .hand-cards .card::after,
.card-drag-ghost::after {
}

/* ============================================================
   THE HAIRLINE AT THE ART'S BOTTOM — A #111 BOX ON A #000 CARD
   ============================================================
   User: "there's still a visible line/edge."

   There was, and it is not drawn by anything — it is a COMPOSITING artifact,
   which is why removing the frame ring, the corner brackets and the gloss
   sweep each fixed a real defect and none of them touched this.

   Two facts that only matter together:
     1. .card-portrait carries `background-color: #111` — a loading placeholder
        so the art area is not a black void while the image fetches. With the
        art painted over it at `cover`, that colour is never visible... except
        exactly at the element's edge.
     2. The portrait's height comes from aspect-ratio (360/472), so it is
        138.942px — its bottom edge lands on a FRACTIONAL pixel (measured
        882.052).

   A #111 box therefore meets the card's #000 on a partial pixel row. The
   browser blends that row and leaves something marginally lighter than the
   base, one pixel tall, precisely at the art's bottom edge. On any other
   background it would be invisible; on pure black it is a hairline.

   Making the placeholder #000 removes the only colour in the stack that is
   lighter than the card, so the partial pixel blends black into black and there
   is nothing left to anti-alias. The loading shimmer gradient is untouched —
   it still sweeps while art loads, it just sweeps over black instead of #111,
   which is what the rest of the card looks like anyway. */
.player-hand-section .hand-cards .card .card-portrait,
.card.ally-card .card-portrait,
.card.enemy-card .card-portrait,
.card-drag-ghost .card-portrait {
  background-color: #000;
}

/* ============================================================
   NO INNER RING ON THE IN-MATCH TILE
   ============================================================
   User, pointing at the black base beside the SPLASH 1 / CRAZY badges: "to the
   right and left, that is not pure black, that is a green line, thats what im
   talking about."

   It is the outline at style.css:12666:

     .card { outline: 1px solid color-mix(in srgb, var(--card-edge) 22%, transparent);
             outline-offset: -5px; }

   A NEGATIVE outline-offset draws the ring INSIDE the element — a 1px rectangle
   5px in from the card's edge, all four sides, full height. Its own comment
   calls it "premium depth", and it was: over a textured base and an inset art
   window it read as a subtle inner bevel.

   Now that the base is genuinely pure #000 it has nothing to blend into, so it
   is just a coloured rectangle drawn in the black — and because --card-edge is
   the side/rarity colour it is GREEN on a player card. Its vertical runs pass
   immediately left and right of the badge row, which is exactly where it was
   reported.

   This is also why I kept missing it: it is an `outline`, not a border, not a
   background, not a box-shadow. Every audit I ran walked backgrounds, borders
   and shadows, so it was never in the results.

   The card keeps its real edge — the 1px border and the tron-perimeter glow are
   untouched. Tricks keep theirs (.trick-card declares its own purple ring and
   still uses the text layout this was designed for). */
.player-hand-section .hand-cards .card,
.card.ally-card,
.card.enemy-card,
.card-drag-ghost {
  outline: none;
}

/* ============================================================
   TRICKS GET THE CARD TREATMENT — same materials, same finish
   ============================================================
   User: "can we do to tricks the exact same we did to cards."

   The in-match trick row sits 8px below the hand, so the two rows are on screen
   together and every difference reads as two different games. Measured before
   this, trick vs hand card:
     art inset 8px vs edge-to-edge · frame ring vs none · L-brackets vs none ·
     gloss sweep vs none · inner outline ring vs none · #111 placeholder vs #000 ·
     square art corners vs rounded · rules text in flow vs a flip face
   Everything on the left is exactly what was stripped off the card today.

   Structurally a trick is already almost a card — same .card-portrait at the
   art's own 0.765, same cost pip, same rarity strip, same .card-name-overlay —
   so the whole treatment transfers. The one real difference is .trick-desc
   instead of .card-desc, which is why it needs its own selector below.

   SCOPED TO .trick-cards, the in-match row. The DRAFT trick
   (.trick-card.draft-card.trick-draft, 220px wide in .draft-choices) is a
   deliberately different object: it is a big pick-me card that must show its
   full rules text in flow while you choose. It keeps its own look, exactly as
   the draft CARD does. */
.trick-cards .trick-card {
  /* NO bottom strip. User: "the tricks are too long you can shorten them."
     A card reserves 30px there for the ATK/HP orbs and room above it for the
     badge row. A trick has NEITHER — no orbs, no badges — so on a trick that
     space was reserved for nothing and the tile was 261px of which ~88 was
     empty black. */
  padding: 0;
  /* THE TRICK IS EXACTLY ITS ARTWORK. Matching the card's 92/182 made the two
     rows identical, which was the point at the time, but it also inherited the
     card's allowance for chrome a trick does not have. Taking the ART's own
     ratio instead means the tile ends where the painting ends: 261px -> ~173,
     a third shorter, with nothing lost because nothing was down there.
     Still a ratio and not a height, for the reason the cards demonstrated —
     trick width is fluid, so a px height would drift with the window. */
  aspect-ratio: 360 / 472;
  height: auto;
  box-sizing: border-box;
  outline: none;              /* the 1px inner ring at offset -5px */
}
.trick-cards .trick-card::before { background-image: none; }   /* corner brackets */
.trick-cards .trick-card::after  { background-image: none; }   /* diagonal gloss sweep */
.trick-cards .trick-card .card-portrait {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 360 / 472;
  margin: 0;
  border-radius: inherit;
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  /* #111 meeting #000 on the portrait's fractional edge is what draws a
     hairline on pure black — the same artifact chased down on the cards. */
  background-color: #000;
  /* Keep the soft inner vignette, drop the 1px themed frame ring. */
  box-shadow: inset 0 0 18px 4px rgba(0, 0, 0, 0.55);
}

/* The rules text becomes a flip face, exactly as it did on cards: absolutely
   positioned so it can never drive the tile's height, swinging in on rotateY.
   Click turns it over, click again turns it back; drag still plays it, because
   the flip listener is bubble-phase and never stops propagation. */
.trick-cards .trick-card .trick-desc {
  position: absolute;
  inset: 0;
  z-index: 7;
  margin: 0;
  display: block;
  align-content: center;
  text-align: center;
  padding: 5px 5px;
  background: #000;
  font-size: 8px !important;
  line-height: 1.25;
  letter-spacing: 0.1px;
  overflow: hidden;
  border-radius: inherit;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: rotateY(90deg);
  transform-origin: 50% 50%;
  backface-visibility: hidden;
}
.trick-cards .trick-card.face-flipped .trick-desc {
  visibility: visible;
  opacity: 1;
  transform: rotateY(0deg);
  transition: transform 240ms var(--ease-out-quart), opacity 90ms linear 70ms;
}
.trick-cards .trick-card .card-portrait {
  transition: transform 240ms var(--ease-out-quart), opacity 90ms linear 70ms;
  backface-visibility: hidden;
}
.trick-cards .trick-card.face-flipped .card-portrait {
  transform: rotateY(-90deg);
  opacity: 0;
}
.trick-cards .trick-card.face-flipped .card-name-overlay { opacity: 0; transition: opacity 90ms linear; }
@media (prefers-reduced-motion: reduce) {
  .trick-cards .trick-card .trick-desc { transform: none; transition: opacity 120ms linear; }
}

/* ============================================================
   NOTIFICATION BANNER — TRON PASS
   ============================================================
   User: "update the banner to be more triple AAA professional tron style."

   It was a purple rounded box on a navy fill (rgba(6,10,18,0.96)) with a purple
   border, wearing the trick identity no matter what it was announcing — which
   is how an error ended up looking like a trick. The kind now drives the
   colour, and the shell follows the game's own language: pure #000 interior,
   one hairline edge, one outer glow, a square-ish corner and a lit rule under
   the eyebrow instead of a coloured slab.

   --toast-accent is set per kind below; everything else reads from it, so a new
   kind is one rule and not a restyle. */
.ai-trick-toast {
  --toast-accent: 155, 89, 182;          /* trick purple, overridden per kind */
  background: #000;                       /* panel interiors are ALWAYS pure #000 */
  border: 1px solid rgba(var(--toast-accent), 0.85);
  border-radius: 2px;                     /* squarer reads as machined, not soft */
  padding: 13px 22px 14px;
  box-shadow:
    0 0 0 1px rgba(0,0,0,0.9),
    0 10px 34px rgba(0,0,0,0.75),
    0 0 22px rgba(var(--toast-accent), 0.30),
    inset 0 0 18px rgba(var(--toast-accent), 0.06);
  /* The lit top edge — the same "tube of light along the perimeter" idea the
     cards and panels use, applied to one edge so the banner reads as a HUD
     element rather than a floating card. */
  background-image: linear-gradient(90deg,
    rgba(var(--toast-accent), 0) 0%,
    rgba(var(--toast-accent), 0.9) 22%,
    rgba(var(--toast-accent), 0.9) 78%,
    rgba(var(--toast-accent), 0) 100%);
  background-size: 100% 1px;
  background-position: 0 0;
  background-repeat: no-repeat;
}
.ai-trick-toast .ai-trick-label {
  color: rgba(var(--toast-accent), 0.95);
  font-size: 9px;
  letter-spacing: 3.2px;                  /* wide-tracked eyebrow = HUD voice */
  opacity: 0.9;
  margin-bottom: 6px;
}
.ai-trick-toast .ai-trick-name {
  color: var(--text-hi, #f5fbff);         /* the MESSAGE is white; the accent is chrome */
  font-size: 15px;
  letter-spacing: 2px;
  text-shadow: 0 0 14px rgba(var(--toast-accent), 0.45);
}
.ai-trick-toast .ai-trick-desc {
  margin-top: 5px;
  font-size: 11px;
  /* Matches the neon rule above — this duplicate comes later in the sheet, so
     leaving it grey would silently undo it. */
  color: color-mix(in srgb, rgb(var(--toast-accent, 79, 195, 247)) 55%, #ffffff);
}

/* Kind = colour. Only the accent changes; the shell above is identical, which
   is what makes them feel like one component instead of five banners. */
.ai-trick-toast.toast-kind-trick   { --toast-accent: 155, 89, 182; }   /* trick purple */
.ai-trick-toast.toast-kind-discard { --toast-accent: 220, 226, 234; }  /* spent-a-card white */
.ai-trick-toast.toast-kind-error   { --toast-accent: 231,  76,  60; }  /* refusal red */
.ai-trick-toast.toast-kind-info    { --toast-accent:  79, 195, 247; }  /* neutral cyan */
.ai-trick-toast.toast-kind-system  { --toast-accent:  46, 204, 113; }  /* confirmation green */
/* The discard variant used to recolour the label to white explicitly; it now
   inherits from --toast-accent like every other kind. */
.ai-trick-toast.toast-kind-discard .ai-trick-label,
.ai-trick-toast.toast-kind-discard .ai-trick-name { color: inherit; }
.ai-trick-toast.toast-kind-discard .ai-trick-name { color: var(--text-hi, #f5fbff); }
/* SETTING: "Always show" (body.hand-text-always) — same treatment the hand
   cards get, applied to the in-match trick row. The rules show at rest as a
   panel across the lower part of the trick, art visible above; cost stays on
   top. Click-to-flip still works. See the hand-card block above. */
body.hand-text-always .trick-cards .trick-card .trick-desc {
  /* Same as the hand cards: rules flow in the trick body (old look), trick
     grows to fit. */
  position: static;
  inset: auto;
  transform: none;
  visibility: visible;
  opacity: 1;
  z-index: auto;
  height: auto;
  background: transparent;
  align-content: normal;
  text-align: center;
  border-radius: 0;
  overflow: visible;
  padding: 3px 5px 4px;
  pointer-events: none;
}
body.hand-text-always .trick-cards .trick-card {
  /* Drop the artwork aspect-ratio so the trick grows to fit its in-flow rules
     instead of overflowing its border (same fix as the hand cards above). */
  aspect-ratio: auto !important;
  height: auto !important;
  min-height: 0 !important;
}
/* Keep the trick name legible above the art. */
body.hand-text-always .trick-cards .trick-card .card-name-overlay {
  z-index: 4;
}
/* A clicked (flipped) trick still reads as the full-bleed face. */
body.hand-text-always .trick-cards .trick-card.face-flipped .trick-desc {
  inset: 0;
  height: auto;
  align-content: center;
  background: #000;
  padding: 5px 5px;
}

/* ============================================================
   BOARD TILE GETS THE HAND TILE'S GEOMETRY CONTRACT
   ============================================================
   Measured across a live 6-lane row: 174 / 187 / 202 / 202 / 231 / 231 — a 57px
   spread, entirely driven by badge count (0 badges 174, 4 badges 231). The board
   read as untidy because every card was a different height.

   This is a debt I created. When the art went edge-to-edge I gave the HAND a
   fixed geometry and deliberately left the board on auto height so cards with
   four or five status badges could show all of them. That restored exactly the
   raggedness the hand block had just fixed — its own comment records the same
   problem ("THE ROW WENT RAGGED... a 96px spread").

   Same contract as the hand, and for the same reasons:
     - aspect-ratio, NOT a px height. Board card width is fluid; a fixed height
       makes the shape drift with the window and overflows the art at wide
       viewports, which is the bug the hand hit at 1400px.
     - badges capped at two rows, so the tile cannot be pushed taller by a card
       that happens to carry five keywords.
   The cap is only safe because the clip ORDER is fixed in the same change (see
   getStatusBadges in ui.js): transients like Frozen and Critical now sort ahead
   of permanent keywords, so what survives the cap is what changes your decision
   this turn. Capping without that would have hidden the urgent ones. */
.card.ally-card,
.card.enemy-card {
  aspect-ratio: 92 / 182;
  height: auto;
  box-sizing: border-box;
}
.card.ally-card .status-badges,
.card.enemy-card .status-badges {
  /* Two rows, expressed in icons so the cap tracks the badge instead of
     clipping a row off the moment the badge scales up. 8px icon x 3.5 = the
     28px this used to be, so nothing moves at the size it was tuned at. */
  max-height: calc(var(--sb-i) * 3.5);
  overflow: hidden;
  gap: calc(var(--sb-pad) * 0.9);
  font-size: var(--sb-num);
  letter-spacing: 0.1px;
}
.card.ally-card .status-badge,
.card.enemy-card .status-badge {
  padding: 1px 3px;
  font-size: 7px;
  letter-spacing: 0.1px;
}

/* ============================================================
   MOBILE BATTERY — THE LOOPS THE LOW-POWER BLOCK MISSED
   ============================================================
   The existing low-power list names all 8 .card.vibe-* loops and the ambient
   washes, and its comment says functional cues are deliberately left running.
   Measured against that: the sheet has 90 rules carrying an infinite animation
   and the coarse/low-power blocks silence 27. Most of the rest are transient UI
   that is only on screen for a moment (spinners, the selected ring, draft pips)
   and are fine.

   These are not. Every one below runs CONTINUOUSLY on a live board, and several
   run once PER CARD — a full board is 12 cards, so a single 0.6s text flash is
   twelve simultaneous forever-loops:
     .badge-critical    critical-badge-flash 0.6s   (the fastest loop in the file)
     .badge-burning     burn-flicker 1.2s
     .badge-crazy       cardCrazyGlitch 1.1s steps
     .badge-insane      cardCrazyGlitch 1.4s steps
     .card.status-crazy cardCrazyWobble 3.4s        (a per-card TRANSFORM loop)
     .game-particle     gameDrift linear            (purely ornamental drift)
     .card-damaged .stat-hp                          (pulse on an already-red number)
     status glow pulses on critical / stunned / frozen / feared / mind-ctrl / burning

   NO INFORMATION IS LOST. The badge text still says CRITICAL, BURNING, CRAZY —
   only the flashing stops. The status tints on .card-portrait are separate
   STATIC rules (style.css ~32856+), so a frozen card still reads as frozen; it
   just stops pulsing. That is the distinction the original block was drawing —
   these are the decorative half of a cue whose informative half is elsewhere.

   Desktop is untouched. */
@media (pointer: coarse), (hover: none), (max-width: 640px) {
  .badge-critical,
  .badge-burning,
  .badge-crazy,
  .badge-insane,
  .game-particle,
  .card-damaged .stat-hp,
  .card.status-crazy,
  .card.status-critical,
  .card.status-stunned,
  .card.status-frozen,
  .card.status-feared,
  .card.status-mind-ctrl,
  .card.status-burning:not(.card-enter):not(.card-exit),
  .card-frost::after {
    animation: none !important;
  }
}
/* Same list for the explicit low-power toggle, which mirrors the mobile block. */
body.low-fx .badge-critical,
body.low-fx .badge-burning,
body.low-fx .badge-crazy,
body.low-fx .badge-insane,
body.low-fx .game-particle,
body.low-fx .card-damaged .stat-hp,
body.low-fx .card.status-crazy,
body.low-fx .card.status-critical,
body.low-fx .card.status-stunned,
body.low-fx .card.status-frozen,
body.low-fx .card.status-feared,
body.low-fx .card.status-mind-ctrl,
body.low-fx .card.status-burning:not(.card-enter):not(.card-exit),
body.low-fx .card-frost::after {
  animation: none !important;
}

/* The card currently under the cursor mid-drag. The ghost IS that card now, so
   the original should read as lifted out of the hand rather than duplicated —
   without it you see the same card twice, once in the row and once in flight.
   Kept as a dim ghost-slot rather than display:none so the hand does not reflow
   and the other cards stay where the player expects them. */
.card.card-being-dragged {
  opacity: 0.22;
  filter: grayscale(1);
}

/* ============================================================
   STATUS-BADGE INTERNALS (word / number / icon)
   formatAbilityBadges now emits three separate elements inside a
   .status-badge instead of one text run ("Taunt 99"), so the phone board can
   swap the WORD for the keyword's icon while keeping the NUMBER. Splitting a
   single text node in CSS is impossible, hence the markup change.
   These are the NEUTRAL defaults: every surface except the phone board keeps
   rendering exactly what it rendered before — word, then number, no icon.
   ============================================================ */
.status-badge .sb-w,
.status-badge .sb-n,
.status-badge .sb-i {
  /* <i> is italic by default and these are structural, not emphatic. */
  font-style: normal;
}
/* The icon is opt-in per surface. Only the phone board turns it on; showing it
   everywhere would put a glyph next to the word on all 16 card surfaces. */
.status-badge .sb-i { display: none; }
.status-badge .sb-i svg { width: 100%; height: 100%; display: block; }
/* Restores the single space that used to sit between the keyword and its count
   back when they were one text node. */
.status-badge .sb-n { margin-left: 0.32em; }

/* ============================================================
   MOBILE HAND-CARD FLIP + VICTORY-SCREEN MVP CARD
   ============================================================ */

/* TAP-TO-FLIP ON PHONES.
   The phone hand card hides its rules text outright —
     .player-hand-section .hand-cards .card .card-desc { display: none !important }
   — which is right for the card's FRONT (at 92px wide the description is
   unreadable and it doubled the card's height), but it also killed the flipped
   FACE, because that face IS .card-desc repositioned. So enabling the tap
   gesture alone would have turned the card over to a blank black panel.
   These re-assert display on the flipped state only, and must carry !important
   to beat the front-face hide, which is itself !important and equally specific.
   The front stays textless exactly as before; only a card you have explicitly
   turned over shows its text. */
@container (max-width: 520px) {
  .player-hand-section .hand-cards .card.face-flipped .card-desc,
  .trick-cards .trick-card.face-flipped .trick-desc {
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    transform: rotateY(0deg) !important;
  }
  /* A 92px card is narrower than the ~140px desktop hand card the 8px face size
     was tuned against, so start a step down. UI._fitHandCardFace still measures
     each card and steps further on demand; this only moves its starting point
     so fewer cards need the extra pass. */
  .player-hand-section .hand-cards .card.face-flipped .card-desc {
    font-size: 7px !important;
    padding: 4px 4px;
    line-height: 1.22;
  }
}

/* VICTORY SCREEN — the MVP / runner-up card is a TROPHY, not a reference card.
   It is built by renderCard() in the game-over stats via makeCardEl, which
   emits the full card including its description. On a wordy card that is
   catastrophic on a phone: Gojo's ~400-character rules text stretched the tile
   to roughly 1000px, wrapping to two or three words a line, burying the Impact
   / Damage / Kills readout that is the actual point of the panel and pushing
   REMATCH and VIEW REPLAY off the bottom (user screenshot).
   Nothing is lost by cutting it — you have just finished playing this card, the
   stats block directly beneath it is what the screen is for, and the full text
   is in the codex. Same reasoning as the board token: show the art and the
   numbers, defer the prose. Applied on every screen size, not just phones —
   "for the victory screen theres no need for the text". */
.go-mvp-real .card-desc,
.go-mvp-real .card-trick-passive,
.go-mvp-real .card-active-text {
  display: none !important;
}

/* ============================================================
   FLIP SURFACES — the general, opt-in version of the hand-card turn-over
   ============================================================
   The hand and trick rows grew their own flip implementation, scoped hard to
   `.player-hand-section .hand-cards .card`. That was right for one surface and
   wrong as a pattern: every other place a card appears — card-choice prompts
   (Paul Atreides, Batman Who Laughs, Dr Strange), trick reveals (Lasso of
   Truth), floating prompts — either crammed the rules text onto the tile at 9px
   or dropped it entirely.
   `.flip-host` is the opt-in. A renderer adds the class and inherits the whole
   treatment; no new selector list, no second copy of the animation. This is the
   "fix the source" version of what the hand does.
   DRAFT IS EXCLUDED ON PURPOSE — a draft card is chosen BY its text, so hiding
   that text behind a flip would defeat the surface.
   ============================================================ */

/* THE FACE. Absolutely positioned so it can never change the card's height —
   the same reason the hand does it this way. `inset: 0` resolves to the padding
   box, so the card's neon perimeter survives underneath. */
.flip-host { position: relative; }
.flip-host .card-desc,
.flip-host .trick-desc {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  z-index: 7;
  margin: 0;
  /* MUST be block flow, not flex — descriptions carry <b> runs and .kw keyword
     chips, and under flex each becomes its own flex item squeezed to minimum
     width and wrapped character by character. align-content centres the block
     without shattering the sentence. */
  display: block;
  align-content: center;
  text-align: center;
  padding: 8px 8px;
  background: #000;    /* panel interiors are always pure #000 */
  line-height: 1.3;
  overflow: hidden;
  /* Out of sight at rest, and out of the way of clicks. */
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: rotateY(90deg);
  transform-origin: 50% 50%;
  backface-visibility: hidden;
}
.flip-host.face-flipped .card-desc,
.flip-host.face-flipped .trick-desc {
  visibility: visible;
  opacity: 1;
  transform: rotateY(0deg);
  /* Opacity lands halfway through the turn so the face arrives edge-on rather
     than fading in flat. */
  transition:
    transform 240ms var(--ease-out-quart), opacity 90ms linear 70ms;
}
/* The art swings out as the text swings in, so the turn reads as ONE object
   rotating rather than a black panel appearing over a static portrait. */
.flip-host .card-portrait {
  transition: transform 240ms var(--ease-out-quart), opacity 90ms linear 70ms;
  backface-visibility: hidden;
}
.flip-host.face-flipped .card-portrait {
  transform: rotateY(-90deg);
  opacity: 0;
}
/* A flipped card is showing its rules — the front chrome should not be left
   half-visible around the edges of the panel. */
.flip-host.face-flipped .status-badges,
.flip-host.face-flipped .card-abilities,
.flip-host.face-flipped .card-name-overlay,
.flip-host.face-flipped .card-name-banner,
.flip-host.face-flipped .card-name,
.flip-host.face-flipped .rarity-strip,
.flip-host.face-flipped .card-type-sigil {
  opacity: 0;
  transition: opacity 90ms linear;
  pointer-events: none;
}
/* Reading is a click, so say so. */
.flip-host { cursor: pointer; }
@media (prefers-reduced-motion: reduce) {
  .flip-host .card-desc,
  .flip-host .trick-desc,
  .flip-host .card-portrait { transition: none !important; transform: none !important; }
  .flip-host.face-flipped .card-portrait { opacity: 0; }
}

/* ---- CHOICE TRAY: art-first cards + an explicit PICK button ----
   The card face used to BE the pick target, so one click committed an
   irreversible choice on a tile whose rules were crammed in at 9px. The card is
   now purely for reading (tap it as often as you like — it only flips) and
   committing is a separate, labelled act. */
.choice-tray .choice-opt {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
}
.choice-tray .choice-pick-btn {
  /* Boxless glow-text, per the house button language — NEVER the blue box. */
  background: none;
  border: 0;
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247),0.35);
  color: rgba(var(--theme-rgb, 79,195,247),0.95);
  font-family: 'Rajdhani', sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  padding: 10px 6px 8px;
  /* 44px min so it is a real touch target on the layout where it matters. */
  min-height: 44px;
  cursor: pointer;
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247),0.55);
  transition: color 0.15s var(--ease-snap), text-shadow 0.15s var(--ease-snap), transform 0.15s var(--ease-snap), border-color 0.15s var(--ease-snap);
}
.choice-tray .choice-pick-btn:hover,
.choice-tray .choice-pick-btn:focus-visible {
  color: #ffffff;
  border-top-color: rgba(var(--theme-rgb, 79,195,247),0.9);
  text-shadow: 0 0 12px rgba(var(--theme-rgb, 79,195,247),0.95);
  transform: translateY(-1px);
}
.choice-tray .choice-pick-btn:active { transform: translateY(1px); }
/* The tray tile no longer needs room reserved under the art for a text block —
   the text lives on the back now. */
.choice-tray .choice-card { padding: 0 0 10px; }

/* ============================================================
   HAND + TRICK BADGES: ICONS, ONE ROW, LEGIBLE
   ============================================================
   The 7px badge text was not a style choice, it was a consequence. The strip
   gets ~28px between the portrait and the orb row, so the font was shrunk two
   steps specifically to reflow badges into two rows — see the measurement log
   on `.player-hand-section .hand-cards .card .status-badges` above, which
   records 0/13/28/42/72px strip heights across all 117 defs and notes that
   fitting the worst case would demand a 225px-tall hand row. Legibility was
   knowingly traded away to hold that cap, and 6 cards got sliced anyway.
   Icons BREAK the trade instead of re-striking it — they are bigger marks that
   take fewer rows. Measured on real cards at hand size:
     Predator (3 kw)  words 104px / 1 row   ->  icons  61px / 1 row
     Knull    (3 kw)  words 155px / 2 rows  ->  icons  61px / 1 row
     Anakin   (5 kw)  words 202px / 2+ rows ->  icons 110px / 1 row
   Every card in the set now fits one row, which is what buys the size back.
   The glyphs are the same KEYWORD_DATA `svg` the tooltip header draws and the
   board already uses, so this also ends the split where the board spoke in
   icons and the hand spoke in 7px words.
   Nothing is lost: the count stays (Armor 2 vs Armor 1 is live combat math),
   hovering or tapping a badge still names the keyword through its data-kw
   tooltip, and the card's full rules are one flip away.
   ============================================================ */
.player-hand-section .hand-cards .card .status-badges,
.trick-cards .trick-card .status-badges {
  /* One row of icons + padding, expressed in icons: 11px x 2 = the 22px this
     used to be. Was 28px for two rows of 7px text before the icons landed. */
  max-height: calc(var(--sb-i) * 2);
  overflow: hidden;
  /* 2px, not 3px. The five-keyword legends — Anakin, Dormammu, Dr. Manhattan,
     Galactus, Trigon — are the whole reason the old cap clipped, and at 3px
     gaps they still spilled to a second row (measured 141px of badges + gaps
     against ~136px of usable strip). A pixel off each gap and each side of the
     padding below brings the worst card in the set to ~127px, so EVERY card
     now fits the single row this is capped at, which is what makes the cap
     safe rather than lossy. */
  gap: 2px;
  flex-wrap: wrap;
}
.player-hand-section .hand-cards .card .status-badge,
.trick-cards .trick-card .status-badge {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px 3px;         /* 3px, not 4 — see the gap note above */
  font-size: 10px;          /* was 7px — this is the readability win */
  letter-spacing: 0;
  line-height: 1;
}
.player-hand-section .hand-cards .card .status-badge .sb-w,
.trick-cards .trick-card .status-badge .sb-w { display: none; }
.player-hand-section .hand-cards .card .status-badge .sb-i,
.trick-cards .trick-card .status-badge .sb-i {
  display: inline-flex;
  width: var(--sb-i); height: var(--sb-i);
}
.player-hand-section .hand-cards .card .status-badge .sb-n,
.trick-cards .trick-card .status-badge .sb-n {
  font-size: var(--sb-num); font-weight: 700; margin-left: 0;
}
/* A keyword with no KEYWORD_DATA entry has no glyph to show, so it KEEPS ITS
   WORD rather than rendering as an empty chip. Deliberately different from the
   board, which drops them: at 55px a stray word is noise, but in the hand it is
   the only way that keyword can be read at all, and there is room for it. */
.player-hand-section .hand-cards .card .status-badge.sb-noicon .sb-w,
.trick-cards .trick-card .status-badge.sb-noicon .sb-w {
  display: inline;
  font-size: 8px;
  letter-spacing: 0.1px;
}

/* ============================================================
   BOARD BADGES: ONE ROW ACROSS, NEVER A VERTICAL STACK
   ============================================================
   User: "the symbols help but they need to all be on the card, not one vertical
   line like Spawn, but spread across."
   Measured on a 58.6px board tile with three keywords: the badges came to 24 +
   16 + 16 = 56px, plus two 1px gaps = 58px, against a 57px strip. One pixel
   over — so the third badge wrapped and the set read as a vertical column down
   the middle of the art instead of a row across it.
   Two things caused the squeeze. The badges were still carrying `padding: 1px
   3px` and `font-size: 7px` from the `.card.ally-card/.enemy-card` block near
   the end of this file, which lands AFTER the phone `@container` block and
   quietly won the cascade over the icon sizing set there. And nothing capped
   the strip to a single row, so overflow turned into stacking rather than into
   a decision.
   Both fixed here, in a rule that is last and therefore actually authoritative:
   trim the horizontal padding to the minimum that still reads as a chip, and
   cap the strip at ONE row so a card with more keywords than fit drops the
   extras (readable in tap-inspect) rather than growing a column over its own
   art. Wrap is left ON rather than using nowrap on purpose: the strip is
   justify-content:center, and nowrap + overflow would slice the FIRST and LAST
   badge in half and show two stubs — the exact failure the hand block's own
   comment warns about. Wrapping past a one-row cap drops whole badges instead.
   ============================================================ */
/* ============================================================
   THE STATUS BOX — a fixed 3 x 2 grid of BOXLESS glyphs.

   Two problems, one shape. Wrapping was ragged: the strip flowed as a flex
   row and clipped at a height cap, so Trigon's five badges spilled a SECOND
   ROW THAT GOT SLICED IN HALF — the card showed three whole badges and two
   stumps. A fixed 3-column, 2-row grid cannot do that. Six slots is the shape
   on every card, occupied or not, and six covers the widest cards in the game
   (the five-keyword legends: Anakin, Dormammu, Dr. Manhattan, Galactus,
   Trigon) with one to spare.

   And the chip itself is gone. At the old 8px the pill's border and fill read
   as a hairline; scaled up to 20px the same chrome became six chunky boxes
   fighting the art. So the glyph now sits straight on the black and glows in
   its own keyword colour — the same move as the menu's text buttons, and it
   keeps card interiors pure #000 with nothing drawn on top of them.

   Scoped to the four surfaces that render ICONS. The codex, deck builder and
   draft render the keyword WORD instead, where a pill still earns its keep.
   ============================================================ */
.card.ally-card .status-badges,
.card.enemy-card .status-badges,
.player-hand-section .hand-cards .card .status-badges,
.trick-cards .trick-card .status-badges {
  /* Flex, not grid — and the difference is exactly what a PARTIAL row does.
     A 3-column grid pins every badge to a column, so a card with one badge put
     it in column 1 and it sat hard LEFT. Flex thirds keep the three-per-row
     rhythm (each badge is locked to a third, so a full row still lines up
     across cards) while justify-content centres whatever is actually there:
     one badge lands dead centre, two straddle the middle, three fill the row
     left / centre / right. */
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  --sb-gap: calc(var(--sb-pad) * 1.1);
  gap: var(--sb-gap);
  /* Two rows, then clip. Rows are content-created so a card with no badges
     reserves nothing, and every badge is the same fixed height, so a 7th is
     dropped as a WHOLE row rather than sliced the way the old wrap did. */
  max-height: calc(var(--sb-i) * 2.84 + var(--sb-gap));
  overflow: hidden;
}
.card.ally-card .status-badge,
.card.enemy-card .status-badge,
.player-hand-section .hand-cards .card .status-badge,
.trick-cards .trick-card .status-badge {
  /* Boxless: no fill, no border, no pill halo. The glow IS the chrome. */
  background: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
  /* No gap: the count is out of flow now (see .sb-n below), so the glyph is
     the badge's only in-flow child and centres in its third by itself. */
  gap: 0;
  font-size: var(--sb-num);
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  /* Locked to a third of the row (minus the two gaps), so exactly three fit
     per row on every card and a full row always lines up.
     min-width: 0 is what MAKES that true rather than merely intended. A flex
     item defaults to min-width: auto, which refuses to go below its content
     width — so on a card whose row is a few px narrower (padding, a magnified
     tile, a two-digit count) the third stops binding, the item keeps its
     content width, and only TWO fit per row. That is the Dormammu 2x2. With
     min-width: 0 the third always wins and the row is always three across. */
  flex: 0 0 calc((100% - var(--sb-gap) * 2) / 3);
  min-width: 0;
  height: calc(var(--sb-i) * 1.42);
  max-width: 100%;
  text-shadow: 0 0 calc(var(--sb-i) * 0.5) currentColor;
}
/* THE COUNT RIDES ITS GLYPH'S CORNER, rather than sitting beside it.
   Inline, the count was 86% of the icon, so a two-digit value like 12 was
   physically WIDER than the glyph it described — and with three badges in a
   row there was nothing to say whether a number bound to the glyph on its left
   or the one on its right. Tucked into the bottom-right corner and overlapping
   slightly, glyph and count read as ONE object and the binding is unambiguous
   no matter how many badges sit side by side.
   Positioned from the badge's CENTRE, not its right edge: the badge box is a
   full third of the row and much wider than the glyph, so anchoring right
   would strand the number out in the gap. The double black shadow keeps it
   legible where it overlaps the glyph's own glow. */
.card.ally-card .status-badge .sb-n,
.card.enemy-card .status-badge .sb-n,
.player-hand-section .hand-cards .card .status-badge .sb-n,
.trick-cards .trick-card .status-badge .sb-n {
  position: absolute;
  left: calc(50% + var(--sb-i) * 0.26);
  /* Sits INSIDE the badge box, not below it. A negative offset hung the digit
     past the box and the row's overflow:hidden clipped its descender. */
  bottom: calc(var(--sb-i) * 0.03);
  font-size: calc(var(--sb-i) * 0.60);
  line-height: 1;
  margin-left: 0;
  text-shadow: 0 0 2px #000, 0 0 2px #000, 0 0 calc(var(--sb-i) * 0.42) currentColor;
}
/* ============================================================
   BUSY CARDS GET A FOURTH COLUMN
   ============================================================
   The row is 3 columns x 2 rows = SIX slots, then overflow:hidden. Measured on
   a real board tile, Dr. Manhattan with Chained + Critical + Burning + Frozen +
   Feared emits ELEVEN badges: six render and five are destroyed without a
   trace — draw, immune, INVINCIBLE, taunt, untrickable. Losing "this card
   cannot be damaged" is not a cosmetic problem; it is the one fact that decides
   whether attacking it does anything.
   Vertical space cannot grow — a third row runs into the ATK/HP corners
   (measured: only 3px of clearance below two rows at the desktop board size).
   So capacity grows sideways, and ONLY on the cards that need it: at seven or
   more badges the row switches to four columns, taking 6 slots to 8 in exactly
   the same height. 77% of cards never show more than one badge and are not
   touched by this at all — the common card does not pay for the rare one.
   :has() is what makes it count-aware without JS measuring anything. */
.card.ally-card .status-badges:has(.status-badge:nth-child(7)),
.card.enemy-card .status-badges:has(.status-badge:nth-child(7)),
.player-hand-section .hand-cards .card .status-badges:has(.status-badge:nth-child(7)),
.trick-cards .trick-card .status-badges:has(.status-badge:nth-child(7)) {
  --sb-cols: 4;
}
.card.ally-card .status-badges:has(.status-badge:nth-child(7)) .status-badge,
.card.enemy-card .status-badges:has(.status-badge:nth-child(7)) .status-badge,
.player-hand-section .hand-cards .card .status-badges:has(.status-badge:nth-child(7)) .status-badge,
.trick-cards .trick-card .status-badges:has(.status-badge:nth-child(7)) .status-badge {
  flex-basis: calc((100% - var(--sb-gap) * 3) / 4);
}
/* THE HAND TILE GETS ONE ROW, NOT TWO.
   A hand card is 86-200px wide and only ~170px tall, and its stat circles sit
   much closer to the badge row than a board tile's do. Measured at 1220px with
   badges correctly sized: one row clears the ATK circle by 12px, two rows run
   8px INTO it. There is no arrangement of two rows that fits, so the hand row
   is capped to one and widened to five columns once it holds four or more.
   getStatusBadges caps the hand at five and emits the +N chip past that, so a
   busy card still reports what it is not showing rather than clipping it. */
.player-hand-section .hand-cards .card .status-badges {
  max-height: calc(var(--sb-i) * 1.42);
  flex-wrap: nowrap;
}
/* FOUR ON TOP, THE REST CENTRED BENEATH. (User: "lets do 4 on top 1 in the
   middle.") Two rows do not fit at the normal pill height — measured, a hand
   card has 29.1px between the badge row and the ATK circle, and two rows at the
   standard 1.42x box come to 37.2px. The GLYPH is what carries legibility and
   it is --sb-i, so the box is what gives: 1.06x instead of 1.42x brings two
   rows to 28.4px and keeps the icon full size. These pills have no background
   or border, so tightening the box costs nothing visually — it is pure layout
   height.
   The row already centres its content, so a trailing fifth badge (or the +N
   chip, since getStatusBadges caps the hand at five) lands under the middle of
   the four above it. */
.player-hand-section .hand-cards .card .status-badges:has(.status-badge:nth-child(4)) {
  /* 1.0, not 1.06: at 1.06 the two rows cleared the ATK circle by a single
     pixel, which is not a margin, it is a coincidence waiting for a different
     font metric or zoom level. At 1.0 the box is exactly the glyph and the
     pair clears by ~2px. These pills have no background or border, so a box
     with no padding looks identical — it only costs layout height. */
  --sb-h: var(--sb-i);
  flex-wrap: wrap;
  max-height: calc(var(--sb-h) * 2 + var(--sb-gap));
}
.player-hand-section .hand-cards .card .status-badges:has(.status-badge:nth-child(4)) .status-badge {
  flex-basis: calc((100% - var(--sb-gap) * 3) / 4);
  height: var(--sb-h);
}

/* THE OVERFLOW CHIP. Past eight there is no honest amount of shrinking left,
   so the row stops pretending: it shows what fits and says how many it is not
   showing, with the rest named in the tooltip. A count the player can see and
   question beats a status that quietly ceased to exist. */
.status-badge.badge-more {
  color: var(--text-hi, #f5fbff);
  opacity: 0.85;
}
.status-badge.badge-more .sb-n { display: none; }

.card.ally-card .status-badge .sb-i,
.card.enemy-card .status-badge .sb-i,
.player-hand-section .hand-cards .card .status-badge .sb-i,
.trick-cards .trick-card .status-badge .sb-i {
  /* text-shadow does nothing for an SVG; the glyph needs its own glow. */
  filter: drop-shadow(0 0 calc(var(--sb-i) * 0.34) currentColor);
}
/* ============================================================
   BADGE SCALE — one share of the card, every screen.
   Badge sizes used to be fixed px while card widths were not, so the badge's
   share of the card drifted badly across devices. Measured before this rule:

     board card   phone 56.2px / 8px icon  = 14.2%
                  desktop 140px / 8px icon =  5.7%     <- 2.5x drift
     hand card    phone 92.1px / 11px      = 11.9%
                  desktop 140px / 11px     =  7.9%

   i.e. the same ARMOR 1 pill read large in hand and nearly invisible on the
   board. Now every surface multiplies its OWN card width by one shared
   constant, so the pill occupies the same fraction of the card on a phone, a
   tablet and a desktop — the card can be any size and the badge follows it.

   Why the width is declared per surface instead of read from the element: CSS
   can only read an element's own width through a container query, and giving
   .card a container-type would re-point all ten UNNAMED
   `@container (max-width: 520px)` blocks at the card instead of body. A card
   is never wider than 520px, so every one of those phone-only rules would then
   match at any viewport. Explicit widths are the only safe option here.
   ============================================================ */
:root {
  /* The phone board tile is both the tuned reference and the legibility floor:
     an 8px icon on a 56.2px card. 8 / 56.2 = 0.1423. Everything else scales up
     to meet it rather than the tile scaling down to meet everything else. */
  --sb-share: 0.1423;
}
/* These live on the CARD, not on .status-badge. The badge ROW (.status-badges)
   needs --sb-i too, for its own height cap, and custom properties only inherit
   downward — declared on the pill, the row saw nothing, its calc() was invalid,
   and max-height silently computed to `none`. That let a five-badge card stack
   five rows and spill 17.6px past the bottom of the card. */
.card, .trick-card {
  --sb-card: 140px;
  /* max() keeps the floor: at phone-board width this resolves to exactly 8px,
     so the tile that was already tuned does not move by a fraction of a pixel. */
  --sb-i: max(8px, calc(var(--sb-card, 140px) * var(--sb-share)));
  /* The pill's own padding and its count scale with the glyph, or the chip's
     proportions drift even though the icon inside it does not. */
  --sb-pad: calc(var(--sb-i) * 0.18);
  --sb-num: calc(var(--sb-i) * 0.86);
}
.trick-card { --sb-card: 132px; }
@container (max-width: 520px) {
  .board .card { --sb-card: calc((100cqw - 14px) / 6 - 4px); }
}

/* THE HAND AND TRICK TILES SIZE THEMSELVES FROM THEIR OWN WIDTH.
   These used to be flat numbers inside the phone-only container query — 92px
   and 110px — which left every wider viewport falling back to the 140px board
   default. Measured on a 1220px desktop: a hand card is 86px wide while its
   badges were being sized for a 140px card, 63% too big, and Dr. Manhattan's
   second badge row ran 31px INTO the ATK circle. The --sb-share system exists
   precisely so a badge is a constant fraction of the tile it sits on; a
   hard-coded pixel value opts that tile out of it.
   --hand-card-w / --trick-card-w are written by UI._fitHandCards on the hand
   area and range 86-200px with the window and the hand size, so reading them
   is the only way this can be right at every width. Declared OUTSIDE the
   container query so it holds everywhere, and the flat overrides are gone
   rather than left to win on phones. */
.player-hand-section .hand-cards .card { --sb-card: var(--hand-card-w, 86px); }
.trick-cards .trick-card { --sb-card: var(--trick-card-w, 110px); }

.card.ally-card .status-badge .sb-i,
.card.enemy-card .status-badge .sb-i {
  display: inline-flex;
  width: var(--sb-i); height: var(--sb-i);
}
.card.ally-card .status-badge .sb-w,
.card.enemy-card .status-badge .sb-w { display: none; }
/* Board keeps its own weight, but the SIZE now comes from the corner-count
   block above. This rule used to re-assert font-size: var(--sb-num) at the same
   specificity and, being later in the file, silently beat it — leaving the
   board on the old 0.86x inline size while the hand had already moved. */
.card.ally-card .status-badge .sb-n,
.card.enemy-card .status-badge .sb-n { font-weight: 700; }
/* No glyph means an empty chip at this size — drop it; the word is one
   tap-inspect away. (The hand does the opposite and keeps the word, because
   there is room for it there.) */
.card.ally-card .status-badge.sb-noicon,
.card.enemy-card .status-badge.sb-noicon { display: none; }


/* ============================================================
   EVERY SUBMENU SECTION CENTRES — GLOBAL RULE
   ============================================================
   The panel itself was already dead centre; what differed was INSIDE it.
   Measured, same 760px panel centred at 585.5 in a 1171 window:

     Solo   .mm-grid-section  margin 248.7px auto   options centred on 585.5
     MP     .mm-section       margin 0, width 320   options pinned at 205.5

   So Multiplayer was a fixed 320px column hard against the panel's left edge
   while Solo was a full-width section with an auto-centred grid inside it. One
   of the two had been centred and the other had not.
   Stated as a rule over both wrappers rather than a patch on .mp-section, so a
   future submenu inherits it instead of being the next one to miss out. Solo is
   unaffected: its section already spans the full panel, and auto margins on a
   full-width box resolve to zero. */
.mm-mw3 .mm-panel .mm-section,
.mm-mw3 .mm-panel .mm-grid-section {
  margin-inline: auto;
}

/* ============================================================
   SIM / DIRECT LABELS, AND THE CARD BACK
   ============================================================
   THE LABELS GO. The damage preview printed a "SIM" chip and a "Direct" side
   label above the number. Neither is information: SIM tags every preview, so a
   flag on all of them distinguishes nothing, and "Direct" names the mechanism
   rather than the outcome — the player wants the number. The phone breakpoint
   had ALREADY hidden both for exactly this reason (see the dp-sim-tag rule in
   the phone block); this just stops desktop disagreeing with it. */
.dmg-preview .dp-sim-tag { display: none !important; }
.dmg-preview .dp-row > .dp-side { display: none !important; }

/* THE CARD BACK CENTRES ITS TEXT. Rules text started at the top of the face and
   left a large dead gap underneath on anything but the longest card, so a short
   ability read as a fragment stuck to the ceiling. Centring on both axes means
   two lines and eight lines are both composed rather than only the long ones
   looking right. */
/* ============================================================
   TRICK DROP ZONE — showing what already worked
   ============================================================
   Dropping a trick anywhere clear of the tray has ALWAYS played it; the code
   for that is one `!onTray` test. What never existed was any sign of it, so the
   only discoverable way to play a trick was the one you already knew about.
   Nothing here changes behaviour — it makes the existing target visible for the
   length of the drag and then gets out of the way.

   Costs nothing at rest: every rule below is behind body.dragging-trick, which
   exists only while a trick is actually in hand mid-drag. */
body.dragging-trick .info-bar.player-bar {
  outline: 1px dashed rgba(155, 89, 182, 0.75);
  outline-offset: -3px;
  /* !important because THREE .info-bar.player-bar background rules already
     carry it — measured, not assumed. Without it the outline and label landed
     but the wash silently did not, which is the half-applied state that looks
     deliberate and is not. */
  background:
    linear-gradient(0deg, rgba(155,89,182,0.16), rgba(155,89,182,0) 70%),
    #000 !important;
}
/* The whole board above the tray is a valid drop, not just the banner, so it
   gets the same quiet wash — otherwise the banner reads as the ONLY target and
   the rule is narrower on screen than it is in code. */
body.dragging-trick .board-section {
  /* Same story: .board-section declares box-shadow:none with !important. */
  box-shadow: inset 0 0 0 1px rgba(155,89,182,0.28) !important;
}
/* Says the rule in words the first time, where the hand can see it. */
body.dragging-trick .info-bar.player-bar::after {
  content: "RELEASE ANYWHERE ABOVE TO PLAY";
  position: absolute; left: 0; right: 0; top: 50%;
  transform: translateY(-50%);
  text-align: center;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 10px; letter-spacing: 0.18em; font-weight: 700;
  color: rgba(214, 160, 255, 0.95);
  text-shadow: 0 0 10px rgba(155, 89, 182, 0.8);
  pointer-events: none;
  z-index: 2;
}
/* The bar's own contents step back so the label is the thing you read. */
body.dragging-trick .info-bar.player-bar > * { opacity: 0.25; }

/* ============================================================
   HOLLOW PURPLE — two energies colliding
   ============================================================
   The direction nothing else in the family uses: everything so far either
   radiates OUT (critical), gathers IN at the corners (fear), contracts toward
   the middle (taunt), rises (burn), runs diagonal (frost), hugs the perimeter
   (invincible/immunity) or displaces sideways (evade). This CONVERGES — two
   arcs driving in from opposite corners onto a core at the centre, which is
   what Hollow Purple is: red and blue cursed energy collided into one point.

   Two stages, driven by Gojo's own combat counter rather than a timer, so the
   card tells you how close the board-clear is:
     hp-stage-0  gathering  — faint core, arcs barely lit
     hp-stage-1  critical   — core hot, arcs bright, one combat from firing */
.card-hollow-purple {
  position: absolute; inset: 0;
  pointer-events: none; border-radius: inherit;
  z-index: 4; overflow: hidden;
  mix-blend-mode: screen;
  background: radial-gradient(38% 30% at 50% 50%,
    rgba(168,85,247,0.55) 0%, rgba(120,40,200,0.20) 45%, rgba(80,20,160,0) 72%);
  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 80%,rgba(0,0,0,0.5) 92%,rgba(0,0,0,0) 100%);
          mask-image: linear-gradient(180deg,#000 0%,#000 80%,rgba(0,0,0,0.5) 92%,rgba(0,0,0,0) 100%);
}
/* The two energies. Red drives in from the top-left, blue from the bottom-right
   — the collision that makes the purple, kept as separate hues so the core
   reads as a MIX rather than as a flat violet wash. */
.card-hollow-purple::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  background:
    radial-gradient(46% 34% at 4% 4%,   rgba(255,60,90,0.42) 0%, rgba(255,60,90,0) 70%),
    radial-gradient(46% 34% at 96% 96%, rgba(70,140,255,0.42) 0%, rgba(70,140,255,0) 70%);
  mix-blend-mode: screen;
}
/* ONE loop — the core breathing as it gathers. transform + opacity only. */
.card-hollow-purple::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  background: radial-gradient(closest-side, rgba(214,160,255,0.55) 0%, rgba(168,85,247,0) 62%);
  animation: hollowGather 2.4s ease-in-out infinite;
}
@keyframes hollowGather {
  0%, 100% { transform: scale(0.72); opacity: 0.34; }
  50%      { transform: scale(1.0);  opacity: 0.9; }
}
/* Stage 0 — gathering. Deliberately quiet: this is most of Gojo's life on the
   board and it must not shout over the cards around him. */
.card-hollow-purple.hp-stage-0 { opacity: 0.45; }
/* Stage 1 — critical. One combat from firing, and it should read across the
   board without being hunted for. */
.card-hollow-purple.hp-stage-1 {
  opacity: 1;
  box-shadow: inset 0 0 0 1px rgba(200,130,255,0.55), inset 0 0 26px rgba(150,60,240,0.40);
}
.card-hollow-purple.hp-stage-1::after { animation-duration: 1.35s; }
@media (prefers-reduced-motion: reduce) {
  .card-hollow-purple::after { animation: none !important; }
}
body.low-fx .card-hollow-purple::after { animation: none !important; }

/* ============================================================
   CARD RULES TEXT — LABELLED ROWS, CENTRED
   ============================================================
   formatDesc now emits one .cd-row per trigger: a label, then its effect. The
   anatomy is identical whether a card has one trigger or four, which is the
   uniformity that text-length alone could never give.
   Global on .card-desc, not just the flip face, so the inspect modal, codex and
   draft all read the same. */
.card-desc .cd-row {
  display: block;
  text-align: center;
}
.card-desc .cd-row + .cd-row { margin-top: 0.55em; }
.card-desc .cd-trig {
  display: block;
  font-size: 0.86em;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: rgba(var(--theme-rgb, 79,195,247), 0.95);
  margin-bottom: 0.12em;
}
.card-desc .cd-eff { display: block; }

/* Vertically centred, and SAFE to do now: the container's children are block
   rows, not raw inline text. Centring the prose directly is what shattered
   "(+1/+1)" into five lines — grid and flex place BOXES, so the fix was to give
   them boxes to place rather than to stop centring. */
.player-hand-section .hand-cards .card.face-flipped .card-desc {
  display: grid;
  align-content: center;
  justify-items: center;
  text-align: center;
}

/* ============================================================
   CENTRED MENU, PART 2 — SECTION RULES + THE MUSIC BLOCK
   ============================================================ */

/* PLAY / LIBRARY: FLANKING HAIRLINES, NOT A LEFT BAR.
   The bar is `border-left: 2px` + `padding-left: 10px` from the base
   .mm-section-label — chrome designed for a LEFT-ALIGNED list, where a bar on
   the left edge lines up with the column. Centre the label and that same bar
   becomes an off-centre tick hanging on one side, which is what looks wrong.
   The user suggested an underline. I went with flanking rules instead, for
   three reasons:
     - this menu ALREADY has the pattern. .mm-mw3 .mm-tagline is a centred caps
       label flanked by fading 1px neon rules, directly under THE GAME. Using it
       here makes PLAY / LIBRARY speak the same language instead of inventing a
       third treatment.
     - it is symmetric, so it survives centring by construction — the failure
       mode we just fixed cannot come back.
     - an underline under a short centred label reads as a text FIELD, and it
       would sit a few pixels above the first option row, competing with it.
       A rule that runs OUT from the label reads as a section divider, which is
       what this element actually is.
   The gradients fade outward from the text, so the rules dissolve into the art
   rather than stopping on a hard edge — the same trick the hero mask uses. */
.mm-mw3 .mm-section-label {
  border-left: none;
  padding-left: 0;
  margin: 10px auto 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}
.mm-mw3 .mm-section-label::before,
.mm-mw3 .mm-section-label::after {
  content: '';
  height: 1px;
  width: clamp(26px, 5vw, 64px);
  background: linear-gradient(90deg, transparent, rgba(var(--theme-rgb, 79,195,247), 0.7));
}
.mm-mw3 .mm-section-label::after {
  background: linear-gradient(90deg, rgba(var(--theme-rgb, 79,195,247), 0.7), transparent);
}

/* THE MUSIC BLOCK — same root cause as the panel itself.
   .mm-botbar is `max-width: 220px` sitting in flow at the end of a panel that
   is now centred, so it stayed pinned to the panel's LEFT edge — a narrow
   column hanging off-axis under a centred menu, over the dark left side of the
   art. User: "the music scroll doesnt go with the art."
   Auto side margins put it on the same centre line as everything else, and its
   own contents centre within it so the now-playing line, the star and the hero
   list all share that axis. Its top hairline is kept — that rule is what
   separates the chrome from the menu, and centred it now reads as a deliberate
   footer divider rather than a left-edge tick. */
.mm-mw3 .mm-botbar {
  margin-inline: auto;
}
.mm-mw3 .mm-npline {
  justify-content: center;
}
.mm-mw3 .mm-heropick-row {
  text-align: center;
}

/* THE HERO STOPS DRIFTING — ONE FRAMING, HELD.
   User: "i want the one with the happy face all the time, not for it to switch."
   The two screenshots were not two layouts or two window sizes — they are the
   two ENDS of a loop. `.mm-mw3 .mm-hero-img` carried
     animation: mmHeroDrift 34s ease-in-out infinite alternate
   whose keyframes are
     0%   { transform: scale(1.05) translate(0, -1.5%) }
     100% { transform: scale(1.11) translate(-1.8%, 1.5%) }
   so over every 34 seconds the art zoomed 6% and slid, then reversed, forever.
   The wider/brighter frame is the 100% end (more zoom pulls the lit wall on the
   right into view); the calmer one with more black around the figure is 0%.
   Pinned at 0% — the framing that was asked for. Chosen over "slow the drift
   down" because a slower loop still arrives at both ends, and what was asked
   for is that it stop arriving at the second one.
   This also removes a 34-second infinite animation from the menu, which the
   mobile battery diet wants gone anyway. The prefers-reduced-motion rule above
   already pinned exactly this state; it is now simply the default for everyone
   rather than an accessibility fallback.
   The one-shot rez-in on .mm-hero is untouched — it plays once on load and
   settles, so it never switches anything. */
/* THE ART BREATHES AGAIN — but it does not travel.
   User: "bring back the art slowly moving on its own."
   The drift was pinned off for a real reason, and that reason still stands:
   mmHeroDrift ran scale 1.05 -> 1.11 with a 1.8%/3% slide, so over 34s the
   framing arrived somewhere visibly DIFFERENT and the owner read it as the art
   switching on them ("i want the one with the happy face all the time, not for
   it to switch"). Restoring that keyframe would restore that complaint.
   So this is a BREATH, not a Ken Burns. It starts and returns to the exact
   pinned framing that was asked for, and at any moment in the cycle the crop
   stays close enough to it that there is no second look to arrive at — you feel
   the movement without the picture changing.
   AMPLITUDE LADDER, so the next adjustment has the whole range in view:
     old mmHeroDrift (rejected)             zoom 6.0%   slide 1.8% / 3.0%
     first breath                           zoom 2.5%   slide 0.5% / 0.6%
     now ("the art can move a little more") zoom 4.0%   slide 1.1% / 1.2%
   Two thirds of the rejected zoom and under half its vertical slide, so there
   is still headroom before the framing starts to travel again.
   The 42s period is deliberately NOT shortened: more travel over the same long
   cycle reads as more movement while staying slow, which is what was asked for.
   Faster would read as restless.
   mmHeroDrift itself is left untouched; nothing else references it now, but
   redefining a shared keyframe to suit one caller is how the next surface
   inherits a surprise. */
/* A PAN, NOT A BREATH. User: "i just want the art to move around the screen,
   thats all, nothing fancy" — said after rejecting both a bigger zoom and a
   layered ember/light-pass treatment. So: the picture itself travels, and
   nothing is added on top of it.
   FOUR POINTS, NOT TWO. A two-keyframe alternate can only slide up one line and
   back down it, which reads as a pendulum. Four points let it wander — left,
   down, right, home — so at no moment is the next position the one it just
   came from. It ends where it starts, so `infinite` loops seamlessly with no
   `alternate` and no visible turn-around.
   THE SCALE IS THE TRAVEL BUDGET. scale(1.08) leaves 4% of overscan on each
   side, and the path never asks for more than 2.6% — so the art can move this
   much without the edge of the image ever entering the frame. Raising the
   travel means raising the scale first; that is the constraint to respect, not
   the numbers themselves. */
@keyframes mmHeroPan {
  0%   { transform: scale(1.08) translate(0,     -1.5%); }
  25%  { transform: scale(1.08) translate(-2.6%, -2.6%); }
  50%  { transform: scale(1.08) translate(-1.2%,  0.6%); }
  75%  { transform: scale(1.08) translate(2.2%,  -0.6%); }
  100% { transform: scale(1.08) translate(0,     -1.5%); }
}
.mm-mw3 .mm-hero-img {
  animation: mmHeroPan 60s ease-in-out infinite;
  transform: scale(1.08) translate(0, -1.5%);
}
/* Reduced motion and the low-FX/battery path keep it pinned — the existing
   rules at 2292 and 36543 already target this element; this is the explicit
   partner for the new keyframe so neither can drift apart from the other. */
@media (prefers-reduced-motion: reduce) {
  .mm-mw3 .mm-hero-img { animation: none; transform: scale(1.08) translate(0, -1.5%); }
}
body.low-fx .mm-mw3 .mm-hero-img { animation: none; }

/* ============================================================
   MENU TYPE SCALE — the caps were sized for a 560px column
   ============================================================
   User: "nice but now the text is too small."
   Every menu size is a clamp, and on a big display it is the MAX that governs,
   not the vw term — so the menu stopped growing long before the window did.
   Measured on a 1900px-wide viewport: title pinned at its 62px cap while 4.4vw
   wanted 84px, options pinned at 30px while 1.7vw wanted 32px, and the whole
   menu block occupied 14.7% of the screen. Those ceilings date from the
   left-column layout, where the panel was a 560px strip beside the art and text
   larger than that would have collided with the hero. Centred over a full-bleed
   hero there is nothing to collide with, so the ceilings are just leftovers.
   Raised roughly 1.5x across the board, keeping every vw coefficient and every
   floor untouched — so small windows and phones render EXACTLY as before, and
   only the large-display case (which was the complaint) changes. The panel cap
   goes up with them, otherwise bigger type would just wrap inside the old strip.
   ============================================================ */
.mm-mw3 .mm-panel { width: min(760px, 82vw); }
.mm-mw3 .mm-title { font-size: clamp(30px, 4.4vw, 92px); }
/* Coefficient raised too, not just the ceiling — this is the one size where the
   vw term was still the binding constraint after the cap came up. At 2000px the
   old 1.7vw gave 34px against an 88px title, a 2.6:1 gap that read as a big
   title above a small list rather than one type scale. 2.2vw lands 44px, a 2:1
   title-to-item ratio. The 18px floor is untouched, so phones are unchanged. */
.mm-mw3 .mm-option-label { font-size: clamp(18px, 2.2vw, 48px); }
.mm-mw3 .mm-section-label { font-size: clamp(11px, 1vw, 22px); }
.mm-mw3 .mm-option-icon { width: clamp(30px, 2.6vw, 64px); height: clamp(30px, 2.6vw, 64px); }
.mm-mw3 .mm-svg { width: clamp(22px, 2vw, 48px); height: clamp(22px, 2vw, 48px); }
.mm-mw3 .mm-option { padding-top: clamp(12px, 1.1vw, 26px); padding-bottom: clamp(12px, 1.1vw, 26px); }
/* The footer chrome was a flat 11px — fine beside a 30px label, undersized
   beside a 44px one. Scaled the same way, with the same 11px floor. */
.mm-mw3 .mm-nowplaying { font-size: clamp(11px, 0.75vw, 16px); }
.mm-mw3 .mm-heropick-row { font-size: clamp(11px, 0.72vw, 15px); }
.mm-mw3 .mm-botbar { max-width: min(340px, 40vw); }
.mm-mw3 .mm-heropick { max-width: min(340px, 40vw); }

/* The PORTRAIT branch (@media max-aspect-ratio: 1/1) caps the title at 40px.
   That cap was written for phones, but the query matches ANY window at least as
   tall as it is wide — including a 1900x1900 desktop one, which then rendered a
   40px title on a huge screen. Same treatment: keep the 26px floor and the 6vw
   coefficient, lift only the ceiling. */
@media (max-aspect-ratio: 1/1) {
  .mm-mw3 .mm-title { font-size: clamp(26px, 6vw, 84px); }
}

/* ============================================================
   THE ARENA — light-cells, horizon, verdict rails
   ============================================================
   An empty .card-slot used to paint NOTHING: no background, no border, no
   box-shadow, and neither pseudo-element. Twelve of them tile almost the whole
   play area, which is the entire reason the board read as a void — not lane
   height. The lane is 610px and its two slots take 574 of it; the space was
   allocated, just blank.

   WHERE THESE LAYERS LIVE, and why. Both .card-slot pseudos are already spoken
   for (.target-highlight uses both, .playable uses ::after) and .lane::before
   is claimed three times over. The free channel is .empty-lane-glyph — a real
   element that ONLY exists while a slot is empty and currently renders nothing.
   Using it plus its two pseudos gives three layers with zero contention, and
   scopes the whole treatment to empty slots without :has() or a JS flag.

   Everything here is static paint. Nothing loops, so there is nothing new for
   reduced-motion or low-fx to gate.
   ============================================================ */

/* ---- 1. THE LIGHT-CELL ---------------------------------------------------
   Revives the glyph element, which is switched off globally at style.css:15007
   (that rule kills the old "+" and carries !important, so this needs both a
   deeper selector and !important to answer it). The lock variant stays hidden —
   it is a different mark with a different job. */
.card-slot .empty-lane-glyph:not(.lane-glyph-locked) {
  display: grid !important;
  place-items: center;
  position: absolute;
  inset: 0;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: clamp(22px, 34cqw, 52px);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: rgba(255, 255, 255, 0.05);
  pointer-events: none;
}
/* Floor grid. Sits inside a 7px margin so it never touches the lane rails. */
.card-slot .empty-lane-glyph:not(.lane-glyph-locked)::before {
  content: "";
  position: absolute; inset: 7px;
  background:
    repeating-linear-gradient(0deg,  transparent 0 21px, rgba(255,255,255,0.028) 21px 22px),
    repeating-linear-gradient(90deg, transparent 0 21px, rgba(255,255,255,0.028) 21px 22px);
}
/* Corner brackets — FOUR CORNERS, NOT A BORDER. A full outline would box the
   slot in, which is the language this project has spent months removing; the
   corners imply the rectangle without drawing it, same reticle as DONE. Eight
   1px background slices, so it costs no extra element. */
.card-slot .empty-lane-glyph:not(.lane-glyph-locked)::after {
  content: "";
  position: absolute; inset: 7px;
  --b: rgba(var(--theme-rgb, 79,195,247), 0.30);
  --len: 15px;
  background:
    linear-gradient(var(--b), var(--b)) left  top    / var(--len) 1px no-repeat,
    linear-gradient(var(--b), var(--b)) left  top    / 1px var(--len) no-repeat,
    linear-gradient(var(--b), var(--b)) right top    / var(--len) 1px no-repeat,
    linear-gradient(var(--b), var(--b)) right top    / 1px var(--len) no-repeat,
    linear-gradient(var(--b), var(--b)) left  bottom / var(--len) 1px no-repeat,
    linear-gradient(var(--b), var(--b)) left  bottom / 1px var(--len) no-repeat,
    linear-gradient(var(--b), var(--b)) right bottom / var(--len) 1px no-repeat,
    linear-gradient(var(--b), var(--b)) right bottom / 1px var(--len) no-repeat;
  transition: background 0.2s var(--ease-snap), opacity 0.2s var(--ease-snap);
}
.card-slot.ai-slot .empty-lane-glyph:not(.lane-glyph-locked)::after {
  --b: rgba(255, 90, 74, 0.28);
}

/* ---- 2. THE HORIZON ------------------------------------------------------
   A shallow gradient per half, brightest at the centre seam and gone by the
   halfway mark, so the two territories read as facing lit planes rather than
   one flat sheet. GRADIENTS, NOT PERSPECTIVE: a real 3D perspective on the
   board would re-parent every transform inside it — the hand magnify, the drag
   ghost, the FLIP moves — and break five things to fix one.
   Two classes deep so it outranks .card-slot.playable's background: transparent. */
.card-slot.ai-slot {
  background: linear-gradient(180deg,
    transparent 52%, rgba(255,90,74,0.020) 76%, rgba(255,90,74,0.075) 100%);
}
.card-slot.player-slot {
  background: linear-gradient(0deg,
    transparent 52%, rgba(var(--theme-rgb, 79,195,247),0.020) 76%, rgba(var(--theme-rgb, 79,195,247),0.075) 100%);
}

/* ---- 3. VERDICT RAILS ----------------------------------------------------
   renderBoard ALREADY stamps data-forecast-cls on the lane from
   laneForecastVerdict — the same helper the footer strip reads. So the lane can
   show who is winning it with no new JS and no second source of truth: the
   strip and the rails cannot disagree.
   Painted as background slices on .lane, whose background is unset — both
   .lane pseudo-elements are already taken. */
.lane[data-forecast-cls] {
  --rail: rgba(255,255,255,0.16);
  background:
    linear-gradient(var(--rail), var(--rail)) left  center / 1px 100% no-repeat,
    linear-gradient(var(--rail), var(--rail)) right center / 1px 100% no-repeat;
}
/* WIN is YOUR outcome, so the rail is your neon, not a fixed cyan. This and the
   trade rail below were the "boxes in the lanes not all blue" — the only two
   board rules in the sheet still holding a literal instead of the token. Every
   other .lane / .ally-card rule already spells it var(--theme-rgb, 79,195,247),
   where the hex is only a fallback. LOSE stays red because that is the enemy's
   colour and enemy red is fixed by design. */
.lane[data-forecast-cls="lf-win"]   { --rail: rgba(var(--theme-rgb, 79,195,247),0.75); }
.lane[data-forecast-cls="lf-lose"]  { --rail: rgba(255,90,74,0.75); }
/* A trade is genuinely both, so it gets both — the rail reads as a live wire
   rather than picking a winner that does not exist. */
.lane[data-forecast-cls="lf-trade"] {
  background:
    linear-gradient(180deg, rgba(255,90,74,0.75) 0 50%,
                            rgba(var(--theme-rgb, 79,195,247),0.75) 50% 100%)
      left center / 1px 100% no-repeat,
    linear-gradient(180deg, rgba(255,90,74,0.75) 0 50%,
                            rgba(var(--theme-rgb, 79,195,247),0.75) 50% 100%)
      right center / 1px 100% no-repeat;
}
.lane[data-forecast-cls="lf-stall"] { --rail: rgba(255,255,255,0.30); }

/* ---- 4. ARMED ------------------------------------------------------------
   The existing affordance is a 1px dashed outline at 18% white. With a
   light-cell already sitting there this is a STATE CHANGE ON AN EXISTING
   OBJECT rather than a new one: brackets snap to full, the floor grid lights,
   and a glow gathers at the base where the card will land. That is why it costs
   a transition and not a layer — and why it reads instantly, since the eye
   already knows the pad's resting state. */
.card-slot.playable .empty-lane-glyph:not(.lane-glyph-locked)::after {
  --b: rgba(var(--theme-rgb, 79,195,247),0.95);
  --len: 22px;
}
.card-slot.playable .empty-lane-glyph:not(.lane-glyph-locked)::before {
  background:
    repeating-linear-gradient(0deg,  transparent 0 21px, rgba(var(--theme-rgb, 79,195,247),0.10) 21px 22px),
    repeating-linear-gradient(90deg, transparent 0 21px, rgba(var(--theme-rgb, 79,195,247),0.10) 21px 22px),
    radial-gradient(120% 80% at 50% 100%, rgba(var(--theme-rgb, 79,195,247),0.13), transparent 70%);
}
.card-slot.playable .empty-lane-glyph:not(.lane-glyph-locked) {
  color: rgba(var(--theme-rgb, 79,195,247),0.30);
}
.card-slot.playable:hover .empty-lane-glyph:not(.lane-glyph-locked) {
  color: rgba(var(--theme-rgb, 79,195,247),0.55);
}


/* ============================================================
   ENERGY DIAMOND — the shape is the gauge
   ============================================================
   It was a bare number with NO MAXIMUM anywhere on screen, so "4" could have
   been 4 of 8 or 4 of anything. The diamond now fills like a tank.

   BOTH PSEUDO-ELEMENTS WERE ALREADY TAKEN, and I burned an attempt on each
   before checking: ::before IS the diamond backdrop (inset 4px, rotated 45deg,
   gold border, black interior) — overriding it deleted the diamond and left a
   grey rectangle. ::after belongs to .tron-perimeter, which .energy-text also
   carries, so a rule there lost the cascade and painted nothing at all.

   So the fill is layered ONTO the existing diamond instead of claiming an
   element. Setting background-IMAGE only leaves the shorthand's
   background-color: #000 intact underneath, so the plate, the border and the
   rotation are all untouched and the gradient simply paints over the black.

   -45deg because the element is rotated +45deg: the two cancel and the fill
   line reads horizontal on screen rather than running diagonally across the
   diamond, which was the other half of why the first attempt looked wrong. */
.energy-display { --nrg-fill: 0%; }
/* --nrg-tint is set PER SIDE below. It is not defaulted to the theme here on
   purpose: an unscoped theme colour is exactly the mistake that put the
   player's neon on the OPPONENT's diamond. Every other rule on this element is
   already split .player-bar / .ai-bar; the fill now matches that shape instead
   of quietly assuming one side. */
.energy-text::before {
  background-image: linear-gradient(-45deg,
    rgba(var(--nrg-tint, 255,215,0), 0.50) 0 var(--nrg-fill),
    rgba(0,0,0,0) var(--nrg-fill) 100%);
  transition: background-image 240ms var(--ease-out-soft, cubic-bezier(0.16, 1, 0.3, 1));
}
@media (prefers-reduced-motion: reduce) {
  .energy-text::before { transition: none; }
}

/* ============================================================
   REDRAW — beside the music toggle, in the hand strip
   ============================================================
   Moved out of the action bar to sit under the note at the head of the hand
   row. That is where it belongs: redraw acts on your HAND, so the control lives
   with the hand rather than with Done and Undo, which act on the turn.
   Mirrors .hand-audio-toggle exactly — same absolute corner, same 44px touch
   target with no 44px box drawn, same resting opacity and grow-on-hover. */
.hand-redraw-toggle {
  position: static;              /* was absolute over the hand — see .hand-tools */
  background: none;
  border: 0;
  padding: 0;
  min-width: 44px; min-height: 44px;
  display: flex; align-items: center; justify-content: center; gap: 3px;
  /* Full-strength accent — see the note on .hand-audio-toggle. Both controls
     were the only two places in the stylesheet using the ambient glow token as
     ink, and both were the ones that read as dark grey. */
  color: var(--theme-accent, #4fc3f7);
  opacity: 0.85;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: opacity 150ms var(--ease-snap), transform 150ms var(--ease-snap), color 150ms var(--ease-snap);
}
.hand-redraw-toggle .redraw-glyph {
  width: 23px; height: 23px; display: block;
  filter: drop-shadow(0 0 7px currentColor);
}
.hand-redraw-toggle .redraw-cost {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px; font-weight: 700; line-height: 1;
  text-shadow: 0 0 8px currentColor;
}
.hand-redraw-toggle:hover:not(:disabled),
.hand-redraw-toggle:focus-visible:not(:disabled) {
  opacity: 1; transform: scale(1.15); outline: none;
}
/* Unaffordable: dimmed but still legible, because the number it is showing you
   is the thing you are planning around. Dimmed IN THEME — the old #94a8c0 slate
   plus the global button:disabled saturate(0.4) desaturated it twice over, so an
   unaffordable redraw stopped looking like the same control and started looking
   like dead chrome. Same hue at lower alpha reads as "can't afford it yet". */
.hand-redraw-toggle:disabled {
  color: rgba(var(--theme-rgb, 79,195,247), 0.6);
  opacity: 0.6;
  filter: none;
  cursor: default;
}

/* ============================================================
   UNDO — the menu's grow + glow, on an arrow
   ============================================================
   Same treatment the main-menu options use, which the stylesheet there calls
   "the letters grow + brighten + glow (the ONLY highlight chrome)". No box, no
   wash, no ring: the mark itself scales up, brightens toward white and throws a
   glow. The one difference is that an SVG arrow cannot take text-shadow, so the
   glow is drop-shadow instead — same look, correct property. */
#btn-undo {
  background: none !important;
  border: 0 !important;
  box-shadow: none !important;
  outline: none !important;
  padding: 6px 8px;
}
#btn-undo .undo-arrow {
  transition:
    transform 180ms var(--ease-out-soft, cubic-bezier(0.22, 1, 0.36, 1)), filter 180ms var(--ease-snap), color 180ms var(--ease-snap);
}
#btn-undo:hover .undo-arrow,
#btn-undo:focus-visible .undo-arrow {
  transform: scale(1.18);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 92%, white);
  filter:
    drop-shadow(0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.85))
    drop-shadow(0 0 16px rgba(var(--theme-rgb, 79,195,247), 0.40));
}
#btn-undo:active .undo-arrow { transform: scale(1.06); }

/* ============================================================
   NO BOXES, ANYWHERE   (the menu's language, made global)
   ============================================================
   I had been removing the box one button at a time — DONE got the treatment
   three separate times — which is why it kept coming back somewhere else. A
   measured sweep found TWELVE elements still carrying it: undo, new game,
   danger, round-summary continue, the settings cog, five secondaries, quit,
   primary and the viewport toggle.

   The box is two things, both from the shared .tron-fx machinery rather than
   from any one button: a .tron-sweep CHILD that slides a filled gradient across
   the element, and a 1px breathing OUTLINE from .tron-fx-breathe. Killing them
   at the source is the fix; killing them per-button was the mistake.

   What survives is the menu's language: the word, its text-shadow, and any
   corner reticle. */
.tron-sweep { display: none !important; }
/* Cards keep their animation (they have their own shimmer work); they only
   lose the outline. Everything else loses both, so no no-op loop is left
   running for an outline that no longer paints. */
.tron-fx-breathe:not(.card):not(.trick-card) {
  outline: none !important;
  animation: none !important;
}
.tron-fx-breathe.card,
.tron-fx-breathe.trick-card { outline: none !important; }

/* ============================================================
   BLOCK RING + ENERGY DIAMOND
   ============================================================
   The bright arc on the left of the block circle was not the gauge — it was
   .tron-perimeter, a conic "flow" sweep layered on top of it. At 0/8 the gauge
   itself draws nothing, so the only thing left was that shine, which read as a
   stray highlight on an empty ring. Off on both the ring and the diamond: what
   is wanted is the ring, not a lens flare on it. */
.block-circle.tron-perimeter::after,
.energy-text.tron-perimeter::after { content: none !important; }

/* The diamond's fill was one flat pass of silver, which is what made it read
   as unfinished — a solid shape with a hard diagonal edge and nothing
   happening inside it. It gets a texture: a fine diagonal weave over the fill
   so it reads as charged material rather than paint, plus a brighter edge
   where the fill ends. Static gradients, so nothing runs at rest. */
.energy-text::before {
  background-image:
    repeating-linear-gradient(45deg,
      rgba(255,255,255,0.10) 0 1px,
      rgba(0,0,0,0.16) 1px 3px),
    repeating-linear-gradient(-45deg,
      rgba(255,255,255,0.05) 0 1px,
      transparent 1px 4px);
  background-blend-mode: overlay, normal;
}

/* ============================================================
   FORCED LANE LOCKOUT   (board design 05)
   ============================================================
   When an ability forces your next card into one lane, the other five are
   closed — and until now the board said nothing at all. There has been a
   padlock glyph for exactly this since the feature shipped, and it NEVER DREW:
   `.empty-lane-glyph { display: none !important }` hides the whole family, and
   every light-cell rule excludes the locked variant with :not(.lane-glyph-locked),
   so it fell straight through to the global hide with nothing to catch it.
   Un-hiding it needs !important of its own — that is what it is competing with,
   not sloppiness.

   The treatment is a whole-board statement rather than one slot: five closed
   doors read faster than one open one. Hatch goes on .card-slot::before, which
   was genuinely free — .lane's two pseudos are both long spoken for. */
.card-slot .empty-lane-glyph.lane-glyph-locked {
  display: flex !important;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  color: rgba(255, 190, 110, 0.5);
  filter: grayscale(1) brightness(1.6);
  z-index: 3;
}
/* The five that are closed: hatched floor, dimmed, number nearly gone. */
.lane.lane-locked .card-slot.player-slot::before {
  content: "";
  position: absolute; inset: 0;
  pointer-events: none;
  z-index: 1;
  background:
    repeating-linear-gradient(45deg,
      rgba(255,255,255,0.05) 0 5px, transparent 5px 11px),
    rgba(0,0,0,0.55);
}
.lane.lane-locked .card-slot.player-slot .empty-lane-glyph:not(.lane-glyph-locked) {
  opacity: 0.25;
}
/* The one that is open. Amber, because this is a CONSTRAINT rather than a
   friendly prompt — it deliberately does not borrow the player's neon, which
   everywhere else means "yours to choose". */
.lane.lane-forced {
  border-color: rgba(255, 180, 84, 0.75) !important;
}
.lane.lane-forced .card-slot.player-slot .empty-lane-glyph {
  color: rgba(255, 180, 84, 0.55);
}
/* Phone: the hatch stays, the padlock shrinks. At a 56px tile a 15px glyph is
   most of the slot. */
@container (max-width: 520px) {
  .card-slot .empty-lane-glyph.lane-glyph-locked { font-size: 10px; }
}

/* ============================================================
   CENTRE BAR CELL
   ============================================================
   This held the conduit spine: a rail across the cell whose lit length was
   your energy. Removed at the owner's call, and the reason it goes cleanly is
   that it was never the only place that number lived — the 0/8 orb sits
   directly beside it saying the same thing in digits. The rail was a second
   rendering of one value, and a horizontal line through the middle of the bar
   is an expensive way to say something already written two inches to the left.

   The layout rules stay: the cell still centres its contents, and its children
   still sit in their own stacking context. */
.info-bar .bar-cell.bar-center {
  position: relative;
  justify-content: center;
}
.info-bar .bar-cell.bar-center > * {
  position: relative;
  z-index: 1;
}
/* Gone now. It began as a mask so the conduit rail would not run through the
   lettering; the rail was removed, and I kept this on the grounds that changing
   how DONE looked was not what had been asked for. It since was — the plate
   reads as a black rectangle punched into the banner instead of a button
   sitting ON it, because the banner has a vertical gradient and the plate does
   not. Transparent lets that gradient run straight through, so the reticle and
   the word are all that mark the button.

   Explicit rather than just deleted: .btn carries its own background further up
   the sheet, so this has to override it, not merely stop adding to it. */
.info-bar .bar-cell.bar-center > .btn { background: transparent; }

/* THREAT ON THE LANE — REMOVED.
   This painted a red rise plus a damage number on .lane::after for any lane
   reaching a face. It was a duplicate: updateThreatSignaling has computed lane
   threat since the initial commit and paints .lane.threat-lane::after with an
   inset danger glow scaled 1-3 by severity. Both used the SAME pseudo-element,
   so they over-constrained each other — the original sets inset:0, this set
   height:30%+bottom:0, and with top and height both resolved the bottom was
   ignored. The gradient pinned to the TOP of the lane and stopped dead a third
   of the way down: the "red overlay that gets cut off".
   The original also handles stun, freeze, Bullseye, armor and invincible,
   which this did not. Removed rather than reconciled. */

/* ============================================================
   ENVIRONMENTS READ AS TERRAIN   (board design 03)
   ============================================================
   An environment is not a combatant: it cannot attack and cannot be attacked.
   On the board it was still wearing the full card chrome — cost pip, rarity
   strip, framed portrait, captioned name, badge row — so it read as a fighter
   that happened to be broken. Terrain instead: hatched ground, dimmed art,
   the name set into the floor rather than captioned under a picture.

   CORRECTION to my first pass on this: I claimed environments showed 0 attack
   and 1 health in stat orbs. They do not — measured statCircleCount is 0,
   because makeCardEl already omits the orbs for environments. The .stat-circle
   rule below is kept only as a guard if that ever changes; it is a no-op today
   and should not be read as the reason this treatment exists.

   Static: no animation, nothing to schedule.
   !important throughout because .card.ally-card sets the card background with
   !important, which outranks a plain higher-specificity selector. */
.board .card.env-card .stat-circle,
.card-slot .card.env-card .stat-circle {
  display: none !important;   /* guard only — the renderer already omits these */
}
.board .card.env-card,
.card-slot .card.env-card {
  background:
    repeating-linear-gradient(135deg,
      rgba(140, 190, 110, 0.10) 0 6px, transparent 6px 12px),
    linear-gradient(160deg, #1b2616, #0b0f09) !important;
  border-color: rgba(140, 190, 110, 0.55) !important;
  box-shadow: inset 0 0 18px rgba(90, 140, 70, 0.22) !important;
}
/* The chrome that says "unit": a cost you could pay to trade with it, a rarity
   tier, a badge row for statuses it can never carry. */
.board .card.env-card .card-cost,
.card-slot .card.env-card .card-cost,
.board .card.env-card .rarity-strip,
.card-slot .card.env-card .rarity-strip { display: none !important; }
/* The portrait keeps the art but loses the framing that says "unit". */
.board .card.env-card .card-portrait,
.card-slot .card.env-card .card-portrait {
  opacity: 0.34;
  border-radius: 0;
}
/* Name reads as a place, not a combatant: wide tracking, set into the ground
   rather than captioned under a portrait. */
.board .card.env-card .card-name-overlay,
.card-slot .card.env-card .card-name-overlay {
  color: rgba(186, 224, 158, 0.92);
  text-shadow: 0 0 10px rgba(120, 180, 90, 0.55);
  letter-spacing: 0.18em;
  background: none;
}
/* Nothing on terrain is a target, so drop the combat affordances. */
.board .card.env-card .status-badges,
.card-slot .card.env-card .status-badges { display: none; }


/* ============================================================
   PHASE BANNER COLOURS  (neon text, option 03) — END OF FILE
   ============================================================
   Appended at the very end deliberately. Three separate later rules declare
   .phase-banner-text's colour !important, and one of them was already killing
   the .phase-combat rule that has existed since long before this change — so
   combat had no colour of its own and nobody noticed. Living at the end with
   !important means nothing outranks these, which is the only way to win
   against three important declarations spread across the file.

   The colours are EXPLICIT, not derived from --theme-rgb. That was the second
   failure: on the silver theme the "player colour" is #d8dee4, so a cards
   banner mixed from it came out near-white and identical to combat. The point
   of the pass is telling the phases apart, so each gets a fixed hue that holds
   on every theme. */
.phase-banner-text.phase-cards {
  color: #7fd0ff !important;
  border-color: rgba(79, 195, 247, 0.85) !important;
  text-shadow: 0 0 10px rgba(79, 195, 247, 0.65) !important;
  box-shadow:
    0 0 12px rgba(79, 195, 247, 0.42),
    0 0 26px rgba(79, 195, 247, 0.18) !important;
}
.phase-banner-text.phase-tricks {
  color: #d7b3e6 !important;
  border-color: rgba(155, 89, 182, 0.85) !important;
  text-shadow: 0 0 10px rgba(155, 89, 182, 0.65) !important;
  box-shadow:
    0 0 12px rgba(155, 89, 182, 0.42),
    0 0 26px rgba(155, 89, 182, 0.18) !important;
}
.phase-banner-text.phase-combat {
  color: #ff9a8c !important;
  border-color: rgba(231, 76, 60, 0.85) !important;
  text-shadow: 0 0 10px rgba(231, 76, 60, 0.65) !important;
  box-shadow:
    0 0 12px rgba(231, 76, 60, 0.45),
    0 0 26px rgba(231, 76, 60, 0.20) !important;
}

/* ============================================================
   NO TEXT SELECTION ON THE PLAYFIELD
   ============================================================
   Dragging a card across the board rubber-band-SELECTED everything it swept
   over — the big lane watermarks lit up in grey selection boxes behind the
   numbers, which is what a text editor should do and a card game should not.
   User: "is there a way to not have numbers highlited when holding down the
   cursor and draging".

   There was already a guard for exactly this, but only
   `body.mobile-card-dragging`, i.e. touch only and only mid-drag. Desktop had
   none, and a state-scoped rule is the wrong shape anyway: it has to be armed
   before the gesture that needs it. Nothing on the playfield is prose, so it is
   simply never selectable.

   Scoped to the match shell rather than <body> so the surfaces where reading
   and copying genuinely matter are untouched — and the game log, which IS
   prose, gets it back explicitly below. */
.board,
.info-bar,
.player-hand-section,
.trick-cards,
.lane,
.card,
.trick-card {
  -webkit-user-select: none;
  user-select: none;
}
/* The log is the one thing on this screen you might want to read closely or
   copy out of, so it keeps normal text behaviour. */
.game-log,
.log-entry {
  -webkit-user-select: text;
  user-select: text;
}

/* ============================================================
   LANE NUMBER — back to the disc
   ============================================================
   The seam treatment lived here: number engraved into the centreline, no
   circle. It removed the chrome but left the number sitting in a HOLE in the
   rule with nothing closing it, so the line read as broken rather than
   deliberately interrupted. Owner: "these numbers needs a redesign it looks
   incomplete", then "we had a circle for the lane number we can go back to
   that."
   Deleting the block is the whole revert — it only ever OVERRODE the original
   disc rules (shape, halo, animation), never edited them, so the pip comes
   back exactly as it was. Five other treatments were mocked and none beat the
   circle, which is a fair result: it was the finished-looking one all along.
   ============================================================ */


/* ============================================================
   DEAD PILE — CARDS GROW TO FIT THEIR OWN RULES TEXT
   ============================================================
   User: "my opponent was looking at the dead pile and Mahoraga's text was
   covering the close button, making it impossible for him to close out."

   Reproduced exactly. `.card` carries `aspect-ratio: 92/182`, which locks the
   height to the width. On the BOARD that is harmless because the rules text is
   hidden behind the flip face — but the dead pile shows the text inline, and
   with `overflow: visible` a long desc simply paints outside the box and over
   whatever is beneath it. Measured overflow past the card's own bottom edge:

     Mahoraga 63px   Batman 66px   Superman 66px   Juggernaut 14px

   Every card in the pile was doing it; it only became a TRAP on the bottom row,
   where the spill lands on the Close button and eats the click. Which is why it
   reads as a Mahoraga bug and is not one — he is just wordy enough to notice.

   Clipping the text would hide rules on a screen whose entire job is reading
   them, so the card grows instead. The PORTRAIT keeps the aspect ratio, so the
   art still reads as a card; only the body extends. Same shape as the fix for
   the floating-prompt trick face. align-self keeps a tall card from stretching
   its whole flex row. */
/* TWO class names in the selector, not one. The rule holding the height is
   `.card.ally-card, .card.enemy-card` — specificity (0,2,0) — and every
   dead-pile face carries one of those. A bare `.dead-pile-card` is (0,1,0) and
   loses no matter how late it is authored; measured, the cards stayed at
   exactly 277px and the 66px spill was untouched. */
.card.dead-pile-card {
  aspect-ratio: auto;
  height: auto;
  align-self: flex-start;
}
.card.dead-pile-card .card-portrait {
  aspect-ratio: 3 / 4;
  height: auto;
}
/* The Close button must never be something you have to fight for. It sits last
   in the panel's normal flow, so anything spilling out of the grid above landed
   on top of it — a stacking context of its own puts it back in front, whatever
   a future card face does. */
.dead-pile-panel > button {
  position: relative;
  z-index: 2;
}

/* ============================================================
   BADGE TEXT MUST NEVER CLIP ITS OWN WORD
   ============================================================
   The compact board/hand view lays badges out as a 3-across ICON grid, so each
   pill is pinned to a fixed 1/3-card width: `flex: 0 0 calc((100% - gap*2)/3)`
   with the strip clamped to 2 rows and `overflow: hidden`. That is correct while
   only the GLYPH shows. But wherever the readable WORD is shown instead — the
   "Always show" hand/board setting, and the hover-magnify clone — that same
   1/3-width cell is far narrower than "Unresistible" / "Untrickable" /
   "Invincible", so the centered word overflowed the cell and the strip's
   overflow:hidden sliced it on BOTH sides (user: "the words are too long now").
   Fix: any badge that is showing its word sizes to its CONTENT and the strip
   drops its clamp, so long keywords wrap to new rows fully legible. The icon
   grid (no word) is untouched. Appended last so it wins on source order over the
   compact-view rules at equal specificity. */
body.hand-text-always .card.ally-card .status-badge,
body.hand-text-always .card.enemy-card .status-badge,
body.hand-text-always .player-hand-section .hand-cards .card .status-badge,
body.hand-text-always .trick-cards .trick-card .status-badge,
.hover-magnify .card .status-badge,
.hover-magnify .trick-card .status-badge {
  flex: 0 0 auto;
  width: auto;
  max-width: 100%;
  overflow: visible;
}
body.hand-text-always .card.ally-card .status-badges,
body.hand-text-always .card.enemy-card .status-badges,
body.hand-text-always .player-hand-section .hand-cards .card .status-badges,
body.hand-text-always .trick-cards .trick-card .status-badges,
.hover-magnify .card .status-badges,
.hover-magnify .trick-card .status-badges {
  max-height: none;
  overflow: visible;
}
/* The magnify clone is the full readable card — always show the word, drop the
   compact glyph, so a titan's five keywords read in full at 1.6x. */
.hover-magnify .card .status-badge .sb-w,
.hover-magnify .trick-card .status-badge .sb-w { display: inline; }
.hover-magnify .card .status-badge .sb-i,
.hover-magnify .trick-card .status-badge .sb-i { display: none; }

/* ============================================================
   IN-HAND EFFECT HAZE — a colored veil that rolls over a hand.
   Apocalypse empowers your hand (blue), Mace Windu curses the enemy's
   (purple). A tinted fog fades in over the whole hand; per-card puffs sweep
   down the row so every touched card is visible. Driven by _fxHandHaze. */
/* Hand-effect overlay. MUST out-rank the hand itself (.player-hand-section is
   z-index 220, and 300 in the mobile block) — the shared cast layer
   #signature-fx-layer is only z-index 200, so every hand effect drawn there
   was painted UNDERNEATH the cards it was meant to mark and read as "the
   animation doesn't work". Kept below the emote/taunt popups (900+). */
#hand-fx-layer {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 520;
  overflow: visible;
}
.sig-hand-haze {
  position: fixed;
  pointer-events: none;
  z-index: 1100;
  border-radius: 12px;
  opacity: 0;
  background: radial-gradient(ellipse at center,
    color-mix(in srgb, var(--sig-c, #a24bff) 42%, transparent) 0%,
    color-mix(in srgb, var(--sig-c, #a24bff) 14%, transparent) 55%,
    transparent 74%);
  box-shadow: inset 0 0 46px color-mix(in srgb, var(--sig-c, #a24bff) 42%, transparent);
  filter: blur(3px);
  animation: sigHandHaze 900ms ease-out forwards;
}
@keyframes sigHandHaze {
  0%   { opacity: 0; }
  30%  { opacity: 1; }
  100% { opacity: 0; }
}
.sig-card-haze {
  position: fixed;
  pointer-events: none;
  z-index: 1101;
  border-radius: 8px;
  opacity: 0;
  mix-blend-mode: screen;
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--sig-c, #a24bff) 55%, transparent) 0%,
    color-mix(in srgb, var(--sig-c, #a24bff) 22%, transparent) 100%);
  box-shadow:
    0 0 16px 3px color-mix(in srgb, var(--sig-c, #a24bff) 60%, transparent),
    inset 0 0 18px color-mix(in srgb, var(--sig-c, #a24bff) 42%, transparent);
  animation: sigCardHaze 700ms ease-out forwards;
}
@keyframes sigCardHaze {
  0%   { opacity: 0; transform: translateY(6px) scale(0.98); }
  35%  { opacity: 1; transform: translateY(0) scale(1); }
  100% { opacity: 0; transform: translateY(-4px) scale(1.02); }
}
@media (prefers-reduced-motion: reduce) {
  .sig-hand-haze, .sig-card-haze { animation: none !important; opacity: 0 !important; }
}

/* ============================================================
   ROGUELITE STYLE CONTINUITY PASS (2026-08-10)
   Owner: "retouch the roguelite mode and update it to match the
   current aesthetic of the game."

   The roguelite screens were built before the glow-text language
   landed and never got the sweep, so they were the last place in
   the game still wearing the look that language replaced: gradient
   -filled pills, 1px white-ish borders, and — on the pickers —
   .mm-option-rl painting a literal blue box on top of the main
   menu's boxless .mm-option. Every rule below is a KILL, not a new
   invention: the surfaces end up matching .mm-option, .md-back and
   the codex, which are the reference.

   Scoped by CONTAINER wherever a container exists, per the lesson
   in the glow-text block above — a rule that needs a class name
   pasted into four lists is a rule that gets broken again.
   ============================================================ */

/* ---- 1. Pickers: .mm-option-rl stops repainting the box --------
   .mm-option is already the canonical boxless row. The -rl variant
   existed only to add a gradient, a border and two shadows on top,
   which is the exact "blue box" the language forbids. Killing the
   chrome leaves the icon + label + sub, which is what the main menu
   shows, and the theme glow now lives entirely in the TEXT. */
.mm-option-rl,
.mm-option-rl:hover {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.mm-option-rl::before { display: none !important; }   /* left accent bar */
.mm-option-rl > .tron-sweep { display: none !important; }
.mm-option-rl.tron-fx-breathe { animation: none !important; }
.mm-option-rl {
  transition: transform 150ms var(--ease-spring, var(--ease-snap)), color 200ms var(--ease-snap), text-shadow 200ms var(--ease-snap);
  transform-origin: left center;
}
.mm-option-rl:hover { transform: scale(1.04); }
.mm-option-rl:active { transform: scale(1.01); }
.mm-option-rl:hover .mm-option-label {
  color: #fff;
  text-shadow:
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
.mm-option-rl:hover .rl-mm-glyph {
  filter:
    drop-shadow(0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.85))
    drop-shadow(0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.40));
}

/* ---- 2. RELIC / CARD / BOON step strip -------------------------
   Three rounded grey pills for a read-only progress indicator is
   three boxes the player never clicks. Reduced to spaced caps:
   dim = not there yet, glowing = you are here, faint = done. */
.rl-pick-step,
.rl-pick-step-active,
.rl-pick-step-done {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 6px 10px;
  letter-spacing: 3px;
}
.rl-pick-step-active {
  color: #fff;
  text-shadow:
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 20px rgba(var(--theme-rgb, 79,195,247), 0.40);
}

/* ---- 3. Ascension rows / event choices -------------------------
   .rl-event-choice carried the worst offender in the mode: a solid
   #000000 fill behind a 1px white border, i.e. a grey box on black.
   The Ascension screen is a LIST — it should read like the main
   menu's list, and the current tier should glow rather than sit in
   a highlighted rectangle. */
.rl-event-choices { padding-left: 8px; padding-right: 8px; }
.rl-event-choice,
.rl-event-choice:hover:not([disabled]) {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.rl-event-choice {
  padding: 11px 12px;
  transform-origin: left center;
  transition: transform 150ms var(--ease-spring, var(--ease-snap)), color 200ms var(--ease-snap), text-shadow 200ms var(--ease-snap), opacity 200ms var(--ease-snap);
  color: rgba(220,225,235,0.72);
}
.rl-event-choice:hover:not([disabled]) {
  transform: scale(1.03);
  color: #fff;
  text-shadow:
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
.rl-event-choice:active:not([disabled]) { transform: scale(1.005); }
/* The tier you are currently on: brighter at rest, no rectangle. */
.rl-event-choice.rl-asc-cur { color: #fff; }
.rl-event-choice.rl-asc-cur .rl-levelup-name {
  text-shadow:
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.75),
    0 0 20px rgba(var(--theme-rgb, 79,195,247), 0.35);
}
/* Daily run keeps its gold identity — as text colour, not a border. */
.rl-event-choice.rl-asc-daily,
.rl-event-choice.rl-asc-daily:hover { border-color: transparent !important; }
.rl-event-choice.rl-asc-daily .rl-levelup-name { color: #ffd77a; }
.rl-event-choice.rl-asc-daily:hover .rl-levelup-name {
  color: #fff;
  text-shadow: 0 0 12px rgba(255,215,122,0.85), 0 0 22px rgba(255,215,122,0.40);
}

/* ---- 4. Run HUD ------------------------------------------------
   Six gradient-filled bordered pills across the top of every map
   screen. Five of them are READOUTS (HP / gold / deck / tricks /
   relics) — a number and a label need no container. The two that
   are buttons get the scale+glow instead of a box. Container-scoped
   on .rl-hud so a seventh pill added later is boxless for free. */
.rl-hud .rl-hud-pill,
.rl-hud .rl-hud-pill:hover {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.rl-hud .rl-hud-pill > .tron-sweep { display: none !important; }
.rl-hud .rl-hud-pill.tron-fx-breathe { animation: none !important; }
.rl-hud .rl-hud-pill { padding: 8px 10px; }
.rl-hud .rl-hud-pill.rl-hud-btn {
  transition: transform 150ms var(--ease-spring, var(--ease-snap)), color 200ms var(--ease-snap), text-shadow 200ms var(--ease-snap);
}
.rl-hud .rl-hud-pill.rl-hud-btn:hover {
  transform: scale(1.12);
  color: #fff;
  text-shadow:
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
.rl-hud .rl-hud-pill.rl-hud-btn:active { transform: scale(1.02); }
/* The HP meter is the one bar worth keeping — it encodes a value a
   number alone doesn't (how close to dead), so it stays. */

/* ---- 5. Map legend --------------------------------------------- */
.rl-map-legend .rl-legend-pill {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 4px 8px;
}

/* ---- 6. Panels: one rim, not a bloom ---------------------------
   .rl-panel and .rl-modal-panel stacked two and three outer glows,
   so the roguelite shell floated in a cyan halo while the codex and
   draft screens sit behind a single hairline rim. Same border, one
   shadow. Interior was already #000 and stays that way. */
.rl-panel {
  box-shadow: 0 0 18px rgba(var(--theme-rgb, 79,195,247), 0.16);
}
.rl-modal-panel {
  box-shadow: 0 0 18px rgba(var(--theme-rgb, 79,195,247), 0.16);
}

/* ---- 7. Map viewport ------------------------------------------
   NOT a centring fix: the map is a 1700px scrolling column and the
   space under the entry row is the rest of the run, so it is doing
   its job. What it did wear was a grey box — rgba(0,0,0,0.45) over
   a 6%-white hairline — sitting inside a panel that is already pure
   black. Interior goes back to #000 with no rule around it. */
.rl-map-panel .rl-map-svg-wrap {
  background: #000 !important;
  border-color: transparent !important;
}

/* ---- 8. Mastery chip gets out of the stat row -------------------
   The roguelite XP chip (`0/30`) was absolutely positioned bottom-
   centre, which is the same band the ATK and HP orbs occupy — and on
   a narrow card the three of them collide. It was ALSO sitting on top
   of the last line of rules text, because .card-desc ran to 11px off
   the bottom and had no idea the chip was coming.

   Both are the same mistake: the chip was parked in the busiest strip
   of the card. Moved to the top edge instead, centred in the gap the
   cost badge (top-left) and rarity pip (top-right) leave open, where
   nothing else is ever drawn. It reads as a header on the art rather
   than a third stat, and the whole bottom of the card goes back to
   the description and the orbs.

   Keyed on :has() rather than a roguelite wrapper class because the
   chip renders in the run pickers, the deck grid AND the in-run hand
   — a wrapper-scoped rule would have to be pasted into all three, and
   the glow-text lesson above is that a rule needing four edit sites
   is a rule that gets broken. */
.card > .card-xp-chip {
  top: 6px;
  bottom: auto;
}
/* Reserve the strip so the art/name never rides under it, and keep the
   chip clear of the cost badge and rarity pip on either side. */
.card:has(> .card-xp-chip) .card-portrait { margin-top: 0; }

/* ============================================================
   ONE PICK SCREEN FOR EVERY CHOICE (2026-08-10)
   Owner: "for paul i want the same pick section screen that's
   shared between all choices in the game — foresee, invis, paul,
   grinch, BWL etc."

   The tray renderer was ALREADY shared — every branch of it appends
   the same pickBtn(). What was not shared was the LAYOUT. Options
   are a column of [tile, PICK], stacked at their natural height, so
   a prompt whose options differ in height (Paul's Knull is tall with
   rules text, his Spawn is short) put the two PICK buttons at two
   different baselines — and on a tall option the button was pushed
   past the bottom of the panel and out of sight entirely, which is
   why Paul's prompt looked like it had no way to choose.

   Two rules fix it for every prompt at once, rather than per-card.
   ============================================================ */

/* 1. PICK SITS ON A SHARED BASELINE. .choice-tray-cards already
      stretches every .choice-opt to the tallest one; margin-top:auto
      then drops each button to the bottom of its own equal-height
      cell, so the row of PICKs is a straight line no matter how the
      tiles above them differ. The tiles keep their natural size —
      stretching a real card face would distort the art. */
.choice-tray .choice-opt > .choice-pick-btn { margin-top: auto; }

/* 2. THE PANEL CAN NEVER PUSH THE COMMIT OUT OF VIEW. A prompt whose
      options are full-height card faces could grow taller than the
      viewport, and the panel had no ceiling — so the thing you have
      to click to continue was the first thing to go off-screen.
      Bounded and scrollable, with the header pinned so you can still
      read what you are choosing while you scroll. */
.choice-tray-panel {
  max-height: 88vh;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.choice-tray-header {
  position: sticky; top: 0; z-index: 2;
  background: rgba(6,10,18,0.97);
}

/* 3. ACTION-TILE TEXT: NO GREY, AND ACTUALLY CENTRED.
      The body text on an action tile (Invisible Woman's face-up /
      face-down, Grinch's keep-or-discard, Voldemort's curses) was
      var(--text-mute) — #9caab4, a flat grey with no theme in it at
      all, on a screen where every other word glows. And the block
      only LOOKED centred: .card-desc centres its child but carried
      4px top / 14px bottom padding, so the 10px difference pushed
      the text 5px above the middle of the tile.
      Owner: "the text is grey and not centered." */
.choice-tray .choice-action .card-desc {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 22%, #e8f5ff);
  padding: 8px 12px;
  text-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.28);
}
/* The tile's own heading picks up the same glow the panel title has, so
   the two tiles read as buttons rather than as inert labels. */
.choice-tray .choice-action .cn-text {
  color: #fff;
  text-shadow:
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.75),
    0 0 20px rgba(var(--theme-rgb, 79,195,247), 0.35);
}

/* ============================================================
   ROGUELITE HUD — ONE HUE PER CHANNEL (2026-08-10)
   Owner: "there should be no gray. Letters like menu, HP, gold,
   deck, tricks, relics, they all should have the neon highlights.
   I mean, not all blues, so it doesn't get washed out."

   Two problems, one cause. The labels were rgba(220,235,250,0.65) —
   a desaturated near-white that reads as grey against pure black —
   and every value in the row was the same --theme-accent-bright, so
   six different readouts said the same colour and the eye had to
   read the words to tell them apart. Six channels, six hues: you
   can now find gold or HP by colour alone.

   Deck / Tricks / Relics had NO distinguishing class of their own
   (all three were bare `.rl-hud-pill.rl-hud-btn`), so this pass
   added rl-hud-deck / -tricks / -relics in roguelite.js rather than
   colouring by :nth-child, which would silently repaint the wrong
   pill the day a seventh readout is inserted.
   ============================================================ */
.rl-hud {
  /* Per-pill hue, read by the shared label/value/glyph rules below. */
  --rlc: rgb(var(--theme-rgb, 79,195,247));
}
.rl-hud .rl-hud-menu   { --rlc: #8fd6ff; }  /* the way out — cool, quiet */
.rl-hud .rl-hud-hp     { --rlc: #ff6b7a; }  /* vitals — the one that means danger */
.rl-hud .rl-hud-gold   { --rlc: #ffc247; }  /* currency — amber, same as shop prices */
.rl-hud .rl-hud-deck   { --rlc: #4fc3f7; }  /* cards — the game's card blue */
.rl-hud .rl-hud-tricks { --rlc: #c77dff; }  /* tricks are purple everywhere else */
.rl-hud .rl-hud-relics { --rlc: #3fe0c0; }  /* relics — teal, nothing else uses it */

/* NO GREY ANYWHERE IN THE ROW. Label, value and glyph all take the
   channel hue; the label sits a touch dimmer than the value so the
   number still leads, but it is the same colour rather than a
   washed-out neutral. */
.rl-hud .rl-hud-pill .rl-hud-label {
  color: color-mix(in srgb, var(--rlc) 72%, white);
  text-shadow: 0 0 8px color-mix(in srgb, var(--rlc) 55%, transparent);
}
.rl-hud .rl-hud-pill .rl-hud-value {
  color: #fff;
  text-shadow:
    0 0 6px var(--rlc),
    0 0 14px color-mix(in srgb, var(--rlc) 55%, transparent);
}
.rl-hud .rl-hud-pill .rl-hud-sep { color: var(--rlc); opacity: 0.6; }
.rl-hud .rl-hud-pill .rl-hud-glyph {
  color: var(--rlc);
  filter:
    drop-shadow(0 0 4px color-mix(in srgb, var(--rlc) 75%, transparent))
    drop-shadow(0 0 9px color-mix(in srgb, var(--rlc) 35%, transparent));
}
/* The HP meter tracks its own channel instead of the global theme, so a
   run at 3 HP reads red at a glance rather than the same blue as DECK. */
.rl-hud .rl-hud-hp .rl-hud-bar { border-color: color-mix(in srgb, var(--rlc) 45%, transparent); }
.rl-hud .rl-hud-hp .rl-hud-bar-fill {
  background: linear-gradient(90deg, var(--rlc), color-mix(in srgb, var(--rlc) 60%, white));
  box-shadow: 0 0 8px var(--rlc);
}
/* Hover glows in the pill's OWN colour — the boxless scale from the
   restyle pass stays, it just stops being blue for all six. */
.rl-hud .rl-hud-pill.rl-hud-btn:hover {
  color: #fff;
  text-shadow: 0 0 12px var(--rlc), 0 0 22px color-mix(in srgb, var(--rlc) 45%, transparent);
}
.rl-hud .rl-hud-pill.rl-hud-btn:hover .rl-hud-label { color: #fff; }

/* The map legend is the same problem one row down — seven node types
   that all have a meaning already encoded in their own colour. Let the
   word take the glyph's colour instead of printing grey next to it. */
.rl-map-legend .rl-legend-pill { color: currentColor; }
.rl-map-legend .rl-legend-pill span { color: inherit; }

/* ============================================================
   IN-MATCH HUD CLUSTER — LOG + HINT + SETTINGS (2026-08-10)
   Owner: "can we put the settings and hint bar stay locked by the
   battle log, make it look symmetrical."

   The three top-bar controls had drifted into three unrelated
   coordinate systems: the battle log was anchored to the CENTRE
   (left: calc(50% + 300px), tracking the round pill), while the hint
   and the cog were pinned to the right EDGE (right: 68px / 14px).
   So the gap between log and hint was whatever the window happened
   to be that second — the wider the screen, the further apart they
   drifted — and they were three different sizes and two different
   shapes on top of it (30px square, two 44px circles).

   One anchor, one size, one shape, one gap. Every button is placed
   as anchor + n*(size + gap), so the row is even by construction
   rather than by three hand-tuned offsets that can disagree.

   IN-MATCH ONLY. The cog is the one control that also exists on the
   menu, codex and deck-builder, where it belongs in the corner on
   its own — body.in-match is the same gate .cheat-help-toggle
   already uses to show itself at all.
   ============================================================ */
body.in-match {
  --hudc-size: 36px;   /* visual size; the global 44px hit-target block
                          still gives all three a real touch area */
  --hudc-gap:  10px;
  /* The HUD strip's vertical padding, and the round pill's height. Both are
     tokens rather than literals because --hudc-top below is DERIVED from them
     — see there. --hud-pad-y also drives .turn-hud's own padding further down
     this file, so the two can never disagree. */
  --hud-pad-y:   5px;
  --hud-pill-h:  36px;
  /* WAS A HAND-TUNED 12px, which is exactly what the comment above this block
     says the cluster is meant to avoid. It put the three buttons 7px below the
     round pill (button centres at y=30 against the pill's y=23) and ran their
     bottom edge to 48px against the HUD strip's own 47px, so they bled down
     into the info bar underneath. Owner: "these are not even with the round
     pill and bleed down."
     Derived instead: start at the strip's content top, then correct by half
     the difference in height between the pill and a button. The two centre
     lines coincide by construction, and stay coincident if either size is
     ever retuned. With both at 36px the correction is zero and this is simply
     the strip's padding. */
  --hudc-top: calc(var(--hud-pad-y) + (var(--hud-pill-h) - var(--hudc-size)) / 2);
  --hudc-left: calc(50% + 300px);   /* just right of the round pill */
  --hudc-step: calc(var(--hudc-size) + var(--hudc-gap));
}
body.in-match .log-drawer-toggle,
body.in-match .cheat-help-toggle,
body.in-match .settings-cog {
  position: fixed !important;
  top: var(--hudc-top) !important;
  right: auto !important;
  width: var(--hudc-size) !important;
  height: var(--hudc-size) !important;
  border-radius: 50% !important;   /* the log was a rounded square — the
                                      other two are circles, and circles win:
                                      the cog and hint are the pair the player
                                      already knows by shape */
  transform: none !important;
  display: flex; align-items: center; justify-content: center;
}
/* The toggle used to be hidden outside a match simply by living inside
   #game-area (display:none between matches). Now that it is at body level
   it needs the same explicit gate the hint button uses, or it would float
   over the menu, codex and deck builder. */
.log-drawer-toggle { display: none; }
body.in-match .log-drawer-toggle  { display: flex; left: var(--hudc-left) !important; }
body.in-match .cheat-help-toggle  { left: calc(var(--hudc-left) + var(--hudc-step)) !important; }
body.in-match .settings-cog       { left: calc(var(--hudc-left) + 2 * var(--hudc-step)) !important; }

/* Matching chrome so the trio reads as ONE control, not one control and
   two visitors. The log had a flatter, dimmer treatment than the other
   two; levelled onto the hint/cog look. */
body.in-match .log-drawer-toggle {
  background: #000 !important;
  border: 1px solid var(--theme-accent-bright) !important;
  color: color-mix(in srgb, var(--theme-accent) 55%, white) !important;
  box-shadow:
    0 0 7px var(--theme-glow-outer),
    0 0 14px var(--theme-glow-inner),
    inset 0 0 0 1px var(--theme-accent-dim) !important;
}
/* Glyphs sit on one optical size across the three. */
body.in-match .log-drawer-toggle svg { width: 17px; height: 17px; }
body.in-match .cheat-help-toggle,
body.in-match .settings-cog { font-size: 17px !important; }

/* Narrow windows: the centre anchor would run the cluster off the right
   edge, so fall back to the corner and let the row flow leftward from it.
   Same size/shape/gap — only the anchor changes. */
@media (max-width: 900px) {
  body.in-match {
    --hudc-left: calc(100vw - (3 * var(--hudc-size) + 2 * var(--hudc-gap)) - 12px);
  }
}

/* ============================================================
   THE STATUS STRIP STAYS PUT (2026-08-10)
   Owner: "it moves with the board — i don't want this, it should
   stay."

   The three top-bar controls were already fixed to the viewport
   after the last pass, but .turn-hud — the strip that carries the
   round pill, DECK and TRICKS, i.e. the thing those buttons belong
   to — is a static block inside #game-area. So the moment the board
   scrolled, the bar slid away underneath and left the buttons
   hovering alone over the lanes with nothing around them. Half the
   row was pinned and half of it was not.

   Sticky rather than fixed ON PURPOSE: #game-area carries
   perspective: 1500px, which hijacks position:fixed for anything
   inside it (the same trap that had the log button pinned to the
   BOARD instead of the screen). position:sticky resolves against
   the scroll container instead, so it survives inside the camera
   transform where fixed would not. The strip keeps its place in the
   flow — nothing below it jumps up by the bar's height the way it
   would if this were fixed.
   ============================================================ */
/* THE SCROLLPORT HAS TO BE THE THING THAT ACTUALLY SCROLLS.
   <body> IS the .in-match element, and it already declares
   overflow-y:auto — so it is the scroll container `position:sticky`
   binds to. But its height was left to grow with its content
   (measured 1031px against a 600px viewport), so body itself never
   scrolled: the DOCUMENT did, sliding the whole body — sticky bar
   and all — up past the top. Sticky can't hold against a scroll
   happening outside its own scrollport, which is why the bar still
   went to y = -116 with position:sticky correctly applied.
   Capping body to the viewport makes it the real scroller, so the
   board scrolls INSIDE it and the sticky strip has something to
   stick to. */
body.in-match {
  height: 100dvh;
  max-height: 100dvh;
}
body.in-match .turn-hud {
  /* !important because `#game-area > *` sets position:relative on every direct
     child, and an ID selector (1-0-1) outranks this rule's two classes (0-2-1)
     no matter how it is written. Measured: without this the computed position
     stayed `relative` and the bar scrolled away exactly as before. */
  position: sticky !important;
  top: 0;
  /* !important here for the SAME reason as position: `#game-area > *` also
     sets z-index:1, and at z-index 1 the .board (a later sibling in the same
     stacking context) painted straight over the stuck bar — it measured as
     present at y=0 and was invisible on screen. */
  z-index: 120 !important;
  /* The strip is see-through by design (a texture over rgba black), and a
     see-through bar with the board sliding under it reads as a smear. Opaque
     only while it is doing the sticky job. */
  background-color: #000 !important;
}

/* ============================================================
   TRIM THE MATCH CHROME (2026-08-10)
   Owner picked this over rebuilding the board's sizing: cut the
   rows around the board rather than make the board itself elastic.

   Measured at 1440x820 with a full hand and 3 tricks, the in-match
   column was 1349px:
     turn-hud 53 | enemy bar 64 | BOARD 610 | forecast 32
     player bar 64 | hand 302 | tricks 224
   The hand and tricks rows were 526px of that — 39% of the screen
   spent on two rows of cards, because a HAND card was rendering at
   the same 140x277 as a BOARD card. It doesn't need to be: the
   board tile is the one you read at a glance across six lanes,
   while a hand card is right in front of you and already magnifies
   on hover and flips to its rules face on click.

   Shrinking the hand card's WIDTH is the safe lever — height comes
   from `aspect-ratio: 92/182`, so the tile stays exactly in shape
   and only gets smaller. No new geometry, no squashing.

   Result: 1349 -> 1177, a 172px saving with the board untouched.
   ============================================================ */

/* Hand and trick card size is now MEASURED, not fixed — UI._fitHandToViewport
   solves it from the height left over after every other row, between the 86px
   that guarantees a fit on a short window and the 140px the card was
   originally drawn at. The fallbacks are the safe (smallest) end, so if the
   script has not run yet the layout still fits. */
body.in-match .player-hand-section .hand-cards .card { width: var(--hand-card-w, 86px); }
body.in-match .trick-card { width: var(--trick-card-w, 88px); }

/* The two rows carried 12px top and bottom each; 5px is still a visible
   gutter between the player bar, the hand and the tricks. */
body.in-match .player-hand-section,
body.in-match .tricks-section {
  padding-top: 5px;
  padding-bottom: 5px;
}
body.in-match .info-bar { padding-top: 4px; padding-bottom: 4px; }
/* Tokenised, not a literal: --hudc-top is derived from this value so the
   top-right button cluster lines up with the round pill. Change the strip's
   padding here and the buttons follow. */
body.in-match .turn-hud { padding-top: var(--hud-pad-y); padding-bottom: var(--hud-pad-y); }
/* Pins the pill's height so the cluster has something real to centre against
   — it was purely content-derived, which made the two rows' agreement a
   coincidence rather than a relationship. 36px is its measured height, so this
   changes nothing on its own. */
body.in-match .hud-pill-main { min-height: var(--hud-pill-h); }
body.in-match .lane-forecast-strip { padding-top: 2px; padding-bottom: 2px; }

/* WHERE THIS LANDS. 1349 -> 1155 with a full hand and 3 tricks, i.e. the
   match now fits any window at least ~1155px tall instead of needing 1349.
   It is NOT a fit at every size: the board is still a fixed 610px (the whole
   point of taking this route rather than rebuilding its sizing), so a short
   laptop window will still scroll. The remaining lever is the board itself —
   see the reverted experiment and its notes for why that needs its own pass. */

/* ============================================================
   HAND AND TRICKS SHARE ONE ROW (2026-08-10)
   Owner: "make the hand and tricks one row."

   They were two stacked full-width rows, 181px + 161px, and the
   tricks row was mostly empty air — three narrow cards spread
   across 1408px. Folding them side by side reclaims the SHORTER
   row outright: the in-match column drops 1155 -> 994px, so the
   match now fits any window from ~994px tall rather than ~1155.
   That is the single biggest saving available without touching
   the board's 610px.

   DONE AS A GRID, NOT A DOM CHANGE. The two sections stay exactly
   where they are in the markup, so every renderer, drag handler
   and selector that targets .hand-cards or .trick-cards keeps
   working untouched — this is purely where the boxes land.
   #game-area becomes a 2-column grid whose every other child
   spans both columns, so only these two sit beside each other.
   ============================================================ */
body.in-match #game-area {
  display: grid;
  grid-template-columns: 1fr auto;
  /* Rows size to content — without this the grid stretches them to fill
     the body's 100dvh and the saving disappears into padding. */
  align-content: start;
}
/* Everything except the two hand rows keeps the full width it had as a
   block child. Authored as a blanket span so a row added later is
   full-width by default and cannot accidentally land in column 2. */
body.in-match #game-area > * { grid-column: 1 / -1; }
body.in-match #game-area > .player-hand-section {
  grid-column: 1;
  min-width: 0;   /* lets the hand shrink instead of pushing tricks off */
}
body.in-match #game-area > .tricks-section {
  grid-column: 2;
  /* Tricks take only what they need; the hand gets the rest. */
  display: flex;
  align-items: center;
  gap: 10px;
  padding-right: 14px;
  /* A hairline on the left so the two groups read as separate zones —
     a trick is not a card you drop in a lane, and side by side they
     need to say so. */
  border-left: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.22);
}
/* (The music / redraw tools used to be ordered left of the tricks here. They
   now live in the player bar's energy cell — see the .hand-tools block — so
   the rule that positioned them inside .tricks-section matched nothing and is
   gone rather than left to look load-bearing.) */

/* The draft card keeps its authored 220px — the panel is ZOOMED as a whole by
   UI._fitDraftToViewport instead, so the rules text scales with it. Growing the
   card's width alone left the 9px type unchanged and just added whitespace. */

/* The draft card row holds ONE height for every round.
   A draft card's height is content-driven — its rules text — so a wordy pair
   (Trigon / Thanos, 521px) made the panel 733px tall while a terse one
   (Silver Surfer / Gorr) made it 621. Two consequences, both bad: the panel
   grew and shrank between picks so the cards jumped under the cursor, and the
   zoom in UI._fitDraftToViewport is solved from the panel's height, so on a
   window where height is the binding constraint the whole screen would zoom
   by a different amount every round.
   530px is the tallest row measured across 40 draft rolls (521) plus a small
   margin. Cards still centre inside it, so a short card is not stretched — it
   just sits in a stable box. */
.draft-choices { min-height: 530px; }
/* THE TWO CARDS MATCH EACH OTHER. Owner: "even though the texts will be longer
   on some cards in the draft, i'd like them to be the same height, they just
   match each other." Measured before: Lex Luthor 463.4px against Iron Giant
   583.1px, centred, so neither the tops nor the bottoms lined up — the pair
   read as two loose objects rather than one choice.

   BOTH declarations are required and they do different jobs:
   • align-items: stretch  — the cards fill the flex LINE instead of centring
     inside it, which is what equalises them.
   • align-content: center — makes the line HUG its content. Without it the
     single line grows to fill the container (the min-height above leaves ~60px
     of slack), and stretch then inflated both cards to 642.9px — equal, but
     each carrying dead space. With it they land on 583.1px: exactly the taller
     card, nothing added.

   The min-height stays. It is not about the cards — it keeps the PANEL a
   stable size between picks so the row does not jump under the cursor and
   UI._fitDraftToViewport does not solve a different zoom every round. */
.draft-choices { align-items: stretch; align-content: center; }

/* Build badge: main menu only. It is a dev readout (and the cache-clearing
   reload tap target), so it belongs where you go to check what you are
   running — not sitting over the hand for a whole match. Inline styles on the
   element set everything else, so display is all this needs to own. */
#clb-build-badge { display: none; }
body.on-main-menu #clb-build-badge { display: block; }

/* BOARD SIZE FROM ONE VARIABLE.
   --board-card-w is measured by UI._fitBoardToViewport from the height left
   over after every other row. The card, its slot and the lane all derive from
   it, because three independently authored widths (140 / 154 / 160) is what
   let the card drift out of its lane the first time I tried this. The offsets
   below ARE that authored triple: slot = card + 14, lane = card + 20.
   Fallback is the authored 140px, so nothing moves if the script has not run. */
body.in-match .card-slot > .card { width: var(--board-card-w, 140px) !important; }
body.in-match .card-slot {
  width: calc(var(--board-card-w, 140px) + 14px);
  /* Height follows the card's 92/182 aspect plus the slot's own 6+4 padding —
     the same derivation the authored rule used, just no longer pinned to 140. */
  min-height: calc(var(--board-card-h, 277px) + 10px);
}
/* THE 20px IS NOW A VARIABLE, because on a phone it is the difference between
   eight lanes fitting and eight lanes not existing. Per-lane padding is fixed
   cost paid eight times over: at 20px it eats 160px of a 375px screen before a
   single card is drawn. The solver in UI._fitBoardToViewport reads this same
   property, so the two cannot disagree. */
/* On :root, not body.in-match — the solver reads it before the match class is
   necessarily settled, and an unresolved variable there silently falls back to
   20px, which is the whole bug this replaces. */
:root { --lane-chrome: 20px; }
body.in-match .lane {
  width: calc(var(--board-card-w, 140px) + var(--lane-chrome, 20px));
  min-width: calc(var(--board-card-w, 140px) + var(--lane-chrome, 20px));
}
/* Narrow screens: shave the per-lane padding and the inter-lane gap so the
   pixels go to the CARDS instead of the space between them. (User: "for mobile
   and an Ipad make sure when playing 1v1 and 2v2 the lanes fit the size of the
   screen.") */
@media (max-width: 700px) {
  :root { --lane-chrome: 8px; }
  body.in-match .board { gap: 1px; }
}

/* ============================================================
   VOLDEMORT — UNFORGIVABLE CURSE PICKER: per-curse LIGHTNING
   ============================================================
   Each curse option carries its own colour of lightning so the three read
   apart at a glance and match the bolt that fires on resolve — Avada Kedavra
   green, Crucio red, Imperio yellow. --curse-c is set inline per tile. */
.choice-card.curse-opt {
  border: 1.5px solid var(--curse-c, #39ff5e) !important;
  box-shadow:
    0 0 14px color-mix(in srgb, var(--curse-c, #39ff5e) 50%, transparent),
    inset 0 0 22px color-mix(in srgb, var(--curse-c, #39ff5e) 20%, transparent) !important;
  animation: curseTileGlow 1.5s ease-in-out infinite;
  position: relative;
}
@keyframes curseTileGlow {
  0%, 100% { box-shadow: 0 0 12px color-mix(in srgb, var(--curse-c,#39ff5e) 45%, transparent), inset 0 0 20px color-mix(in srgb, var(--curse-c,#39ff5e) 18%, transparent); }
  50%      { box-shadow: 0 0 22px color-mix(in srgb, var(--curse-c,#39ff5e) 75%, transparent), inset 0 0 26px color-mix(in srgb, var(--curse-c,#39ff5e) 30%, transparent); }
}
/* The bolt glyph flickers like a live arc in the tile's top-right. */
.choice-card.curse-opt .curse-bolt {
  position: absolute;
  top: 8px; right: 8px;
  width: 16px; height: 27px;
  fill: var(--curse-c, #39ff5e);
  filter:
    drop-shadow(0 0 3px var(--curse-c, #39ff5e))
    drop-shadow(0 0 7px var(--curse-c, #39ff5e));
  animation: curseBoltFlicker 1.15s steps(1, end) infinite;
  pointer-events: none;
  z-index: 4;
}
@keyframes curseBoltFlicker {
  0%, 44%, 100% { opacity: 1; }
  48%           { opacity: 0.3; }
  52%           { opacity: 1; }
  68%           { opacity: 0.55; }
  74%           { opacity: 1; }
}
/* Tint the curse name in its own colour so the label matches the arc. */
.choice-card.curse-opt .card-name-overlay .cn-text {
  color: var(--curse-c, #39ff5e);
  text-shadow: 0 0 6px color-mix(in srgb, var(--curse-c, #39ff5e) 70%, transparent);
}
@media (prefers-reduced-motion: reduce) {
  .choice-card.curse-opt { animation: none; }
  .choice-card.curse-opt .curse-bolt { animation: none; }
}

/* HAND TOOLS relocated into the bottom bar (♪ + redraw), next to the energy.
   .hand-tools was absolutely positioned for its old home over the tricks; in a
   bar cell it must flow inline instead. */
/* ENERGY CELL holds the ♪ + redraw tools ALONGSIDE the energy number, so the
   player's energy sits on the same bar as the music symbol (owner), matching
   the AI. .hand-tools was absolutely positioned for its old home over the
   tricks; in the bar it must flow inline. Only the PLAYER bar has tools, so the
   player energy column is widened to fit both — the AI bar keeps the shared
   64px energy column. */
.bar-cell.bar-energy { display: flex; align-items: center; justify-content: center; gap: 8px; }
.bar-cell.bar-energy .hand-tools {
  position: static;
  left: auto; top: auto; transform: none;
  z-index: auto;
}
.info-bar.player-bar { grid-template-columns: 220px 64px 1fr 150px 96px; }

/* HAND + TRICKS AS ONE CENTERED GROUP (desktop). The bottom grid row used to be
   `1fr auto`, so the hand cards sat in a wide 1fr column and the tricks were
   stranded in an auto column pinned to the far right — a big gap between them
   (owner: "have the tricks next to the cards, just at the end"). Four columns —
   [1fr spacer][hand][tricks][1fr spacer] — centre the hand+tricks group with
   the tricks right after the last card, while the board/bars keep spanning
   1 / -1 so they stay full width. Scoped above the phone breakpoint; the mobile
   fit-to-width layout is untouched. */
@media (min-width: 521px) {
  body.in-match #game-area { grid-template-columns: 1fr auto auto 1fr; }
  body.in-match #game-area > .player-hand-section { grid-column: 2; }
  body.in-match #game-area > .tricks-section { grid-column: 3; }
}

/* HUD CONTROLS STAY ABOVE THE BOARD ON SCROLL. The battle-log, help (?) and
   settings buttons are position:fixed at body level (outside #game-area's
   camera transform). Help/settings already sit at z-index 500; the log toggle
   sat lower (125) and could be crossed by board chrome when a short viewport
   scrolls. Pin all three at the same high layer so they always clip over the
   board (owner). */
.log-drawer-toggle, .cheat-help-toggle, .settings-cog {
  position: fixed;
  z-index: 600 !important;
}

/* Asleep — Freddy Krueger's hand-lock. Indigo, distinct from Freeze's cyan and
   Stun's amber, because it is a different kind of "cannot act": the card is not
   on the board at all, it is dreaming in your hand. */
:root { --kw-asleep: #8f9bff; }
.kw-asleep { color: var(--kw-asleep); }
.badge-asleep { color: var(--kw-asleep); }
/* A slow drift on the Z's — sleep breathing, much calmer than the Crazy
   glitch. Honours the reduced-motion / low-fx opt-outs like every other
   status animation. */
@keyframes sleepDrift { 0%,100% { opacity: 0.75; } 50% { opacity: 1; } }
.badge-asleep { animation: sleepDrift 2.4s ease-in-out infinite; }
body.low-fx .badge-asleep { animation: none; }
@media (prefers-reduced-motion: reduce) { .badge-asleep { animation: none; } }
/* The hand card itself reads as dimmed while it cannot be played. */
.hand-card-wrapper .card.card-asleep,
.card.card-asleep { opacity: 0.62; filter: saturate(0.55); }

/* ============================================================
   COMBAT ZOOM — REMOVED (2026-08-14)
   Owner: "can you remove the zoom in for the combat phase."

   It folded .player-hand-section / .tricks-section away during combat
   (max-height 0 + opacity 0) so the board could claim the height, and
   unfolded them when the fight ended. Deleted rather than disabled, and
   that includes the transition + `max-height: 900px` ceiling those rows
   carried: both existed ONLY to animate this fold, so leaving them would
   have left a latent height cap on the hand row for no reason. The body
   class and the zero-height branch in UI._fitBoardToViewport went with
   them. The hand is now a fixed part of the layout for the whole round.
   ============================================================ */

/* ============================================================
   EDGE HAND CARDS GROW INWARD (2026-08-10)
   Owner: "the left and right cards are getting cut off."

   The hover enlarge is `.hand-card-wrapper:hover { scale(1.6) }` about
   a centred origin, so a magnified card reaches ~30% of its width past
   each side. For the first and last card in the row that lands outside
   the viewport, and <body> carries `overflow-x: hidden` — so it is not
   scrolled to, it is simply sliced off.

   Pinning the origin to the outer edge makes those two grow inward
   instead. Chosen over padding the row: the width solver in
   UI._fitHandToViewport reads .player-hand-section's padding to decide
   how many cards fit, so reserving ~60px a side there would have made
   every card smaller on every hand just to protect the two ends.
   Vertical origin stays `bottom` on both so the lift still rises from
   the hand baseline exactly as it does for every other card.
   ============================================================ */
.hand-card-wrapper:first-child { transform-origin: left bottom; }
.hand-card-wrapper:last-child  { transform-origin: right bottom; }
/* Tricks magnify the same way and sit hard against the right edge, so the
   last one needs the same treatment. */
.tricks-section .trick-card:last-child { transform-origin: right bottom; }

/* ============================================================
   DISMISS CONTROLS GO RED — and the × is centred by geometry
   ============================================================
   Owner: "the x needs to be red tron themed and centered. the skip needs to
   be red tron themed."

   THE CENTRING. Two problems with one cause: the × was a typed '×' character,
   so it carried the font's own ink offset inside its em box and sat high in
   the 32px circle. The standing fix was `margin-top: -2px` on the glyph — a
   hand nudge that is only correct for one font at one size, and which drifts
   the moment either changes. Drawn as two hairlines the cross is centred BY
   CONSTRUCTION: a square box centred by the parent's existing flex, with each
   bar pinned to that box's own centre line. It also stops being a typographic
   character and starts being neon strokes, which is the point.

   THE COLOUR. rgb(231,76,60) with #ff8a7a ink is not a new red — it is exactly
   what .btn-danger already uses, so "dismiss / decline" reads the same
   everywhere rather than gaining a second, slightly different red.
   ============================================================ */
.peek-toggle {
  border-color: rgba(231,76,60,0.95);
  color: #ff8a7a;
  box-shadow:
    0 0 8px  rgba(231,76,60,0.35),
    0 0 18px rgba(231,76,60,0.14);
}
.peek-toggle:hover {
  border-color: rgba(231,76,60,1);
  box-shadow:
    0 0 14px rgba(231,76,60,0.70),
    0 0 30px rgba(231,76,60,0.30);
}
.peek-toggle-glyph {
  position: relative;
  display: block;
  width: 13px;
  height: 13px;
  margin: 0;        /* kills the -2px nudge this replaces */
  font-size: 0;     /* the typed × is replaced by the strokes below */
  line-height: 0;
  pointer-events: none;
}
.peek-toggle-glyph::before,
.peek-toggle-glyph::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  /* Half the bar's own height, so the stroke's centre IS the box's centre.
     No transform in the vertical, so the rotate below cannot interact with
     the centring. */
  top: calc(50% - 0.5px);
  height: 1px;
  background: currentColor;
  box-shadow: 0 0 6px currentColor;
}
.peek-toggle-glyph::before { transform: rotate(45deg); }
.peek-toggle-glyph::after  { transform: rotate(-45deg); }

/* SKIP / KEEP — the decline half of a floating prompt. .fp-btn-primary
   already claims player-green for the confirming choice; this gives the
   other option the matching danger red, so the pair reads at a glance
   without either one needing a box. */
.fp-btn-secondary .fp-btn-title {
  color: #ff8a7a;
  text-shadow: 0 0 6px rgba(231,76,60,0.55);
}
.fp-btn-secondary:hover .fp-btn-title,
.fp-btn-secondary:focus-visible .fp-btn-title {
  color: color-mix(in srgb, #ff8a7a 80%, white);
  text-shadow:
    0 0 12px rgba(231,76,60,0.90),
    0 0 24px rgba(231,76,60,0.45);
}

/* ============================================================
   OVERCHARGED ATK ORB (2026-08-14)
   ============================================================
   A round-scoped ATK multiplier — Droideka's shields-down triple, Han Solo's
   Critical, Yoda's combined-force mark — now prints its EFFECTIVE value on the
   orb instead of the raw stat (see makeCardEl). It needs to look different
   from .stat-buffed: a buff is a permanent stat change, this will drop back
   next round, and reading a temporary spike as permanent is how you misplan a
   trade. Amber rather than green says "hot right now", not "grew". */
.stat-circle.stat-atk.stat-overcharged {
  color: #ffcf66 !important;
  /* border-color / box-shadow dropped with the box — amber reads off the
     numeral and its halo, same as every other state now. */
  text-shadow:
    0 1px 2px rgba(0,0,0,0.95),
    0 0 3px  rgba(0,0,0,0.90),
    0 0 8px  rgba(255,176,60,0.95),
    0 0 16px rgba(255,176,60,0.55);
}

/* ============================================================
   PICK TRAY — ICON BADGES + CENTRED TILE TEXT (2026-08-14)
   ============================================================
   Owner: "the text isn't centered and the cards should have the icons not the
   descriptions of bullseye, evade etc."

   THE BADGES were never a renderer problem. getStatusBadges and
   formatAbilityBadges both already emit icon + word + count through _badgeHTML;
   the BOARD and HAND then hide the word at tile size, and the tray simply never
   inherited that rule. So the identical card printed glyphs in the lane and
   "EVADE 1 / BULLSEYE" as words three inches away in the picker. Hiding the
   word here is the same treatment, applied to the surface that was missed —
   not a second badge style.

   The .sb-noicon exception is load-bearing: a badge with no icon has nothing
   BUT its word, so blanket-hiding would leave an empty chip. Those keep their
   text, exactly as the hand does. */
.choice-tray .status-badge:not(.sb-noicon) .sb-w { display: none; }
/* AND THE ICON HAS TO BE TURNED ON, which is the half that would have been
   missed. `.status-badge .sb-i { display: none }` is the GLOBAL default and
   every surface opts in individually — board, hand, tricks, ally/enemy. The
   tray never did, so hiding the word alone would have left a chip showing its
   NUMBER and nothing else: strictly worse than the words it replaced. Caught
   by checking the icon's computed display rather than only the thing I set.
   Sizing copied from the hand's opt-in so the glyphs match the cards below. */
.choice-tray .status-badge .sb-i {
  display: inline-flex;
  width: var(--sb-i); height: var(--sb-i);
}
.choice-tray .status-badge .sb-n { font-size: var(--sb-num); font-weight: 700; margin-left: 0; }
/* Same reasoning as the hand: a keyword with no glyph keeps its word rather
   than rendering as an empty chip. */
.choice-tray .status-badge.sb-noicon .sb-w { display: inline; font-size: 8px; }

/* THE TEXT. The desc box was already a centred flex container, which centres
   the BLOCK but says nothing about the lines inside it — so a two-line
   sentence stayed ragged-left within a perfectly centred box. text-align is
   the property that was actually missing, on the tile's name as well as its
   body. */
.choice-tray .choice-action .card-desc,
.choice-tray .choice-action .card-name-overlay,
.choice-tray .choice-action .cn-text {
  text-align: center;
}
.choice-tray .choice-action .card-desc { justify-content: center; }

/* ============================================================
   PICK TRAY — ACTION TILE TEXT, ACTUALLY CENTRED (2026-08-14)
   ============================================================
   Owner, twice: "the text isn't centered" / "for the picker in general it's
   still off center."

   WHY THE EARLIER FIXES DID NOT TAKE. Two reasons, and both matter:

   1. THE RULE I EDITED WAS LOSING. There are four rules matching this tile's
      .card-desc (≈11971, 11996, 12021, 39836). The one carrying the padding is
      the LAST one, so edits to the earlier block were overridden and looked
      like they had done nothing. Measured proof: computed padding read
      `8px 12px` — line 39836's value — not the `4px 12px 14px` written at
      12021. This block is appended at the END for that reason, deliberately,
      rather than being slotted next to its siblings where it would lose again.

   2. text-align CANNOT CENTRE A FLEX ITEM. .card-desc is display:flex and was
      itself perfectly centred — measured offset from the tile's centre: 0. But
      formatDesc wraps the sentence in a .cd-row, which is therefore a flex
      ITEM, shrink-to-fit at 73px inside a 122px content box, and it sat 24px
      right of centre. Every text-align in the chain was already `center` and
      none of them could move it, because the box being mis-positioned is laid
      out by flex, not by text flow.

   The fix addresses that mechanism: make the row fill the line so its centred
   text is genuinely centred, and pin the flex axes so it cannot drift again. */
.choice-tray .choice-action .card-desc {
  display: flex;
  align-items: center;      /* vertical */
  justify-content: center;  /* horizontal, for the item itself */
  text-align: center;
}
.choice-tray .choice-action .card-desc > *,
.choice-tray .choice-action .card-desc .cd-row {
  flex: 1 1 100%;
  width: 100%;
  display: block;
  text-align: center;
}
.choice-tray .choice-action .card-desc .cd-eff {
  display: block;
  width: 100%;
  text-align: center;
}

/* THE ACTUAL CAUSE OF THE OFF-CENTRE PICK-TRAY TEXT.
   `.card .card-desc::before` is a decorative hairline (height:1px; margin:0 20%)
   meant to draw a rule ABOVE the body copy — which it does correctly wherever
   .card-desc is a block. On the tray tile .card-desc is display:flex, so that
   pseudo becomes a FLEX ITEM sitting on the same line as the text. Its 20% side
   margins are 24.4px each against the 122px content box, so it consumed 48.8px
   of the line and squeezed the sentence into the remaining 73.2px, flush right.
   48.8 + 73.2 = 122 exactly — that is the whole 24.4px offset, and no amount of
   text-align or justify-content could ever have moved it, because the text was
   not mis-aligned: it was being crowded by an invisible sibling.
   The divider is not merely misplaced here, it is meaningless — a 1px-tall,
   0px-wide sliver in a row. Remove it from this one surface. */
.choice-tray .choice-action .card-desc::before { display: none; }

/* ============================================================
   MAIN MENU — THREE TIERS, NOT TEN EQUAL ROWS (2026-08-18)
   ============================================================
   Ten options rendered at one identical weight, so SOLO MATCH — the thing
   the screen exists to get you to press — read exactly as loudly as SANDBOX.
   Nothing led, so the eye had to read all ten labels to find the one it
   wanted, every single launch.

   The intent to separate was ALREADY IN THE DATA: Audio Audit, Gallery Audit
   and Sandbox each carried a "· dev" suffix in their subtitle. It just never
   reached the visual ranking, where it would have done some work. They now sit
   under their own TOOLS header, which says it once for the group — so the
   per-item suffix is gone from the copy rather than repeated three times.

   Hierarchy is TYPE SCALE + OPACITY ONLY. No boxes, no fills, no borders:
   the house rule is boxless grow+glow text, and a panel that started
   drawing containers to show rank would be solving it the one way this
   game has explicitly ruled out. Tier 1 is what ships you into a match;
   tier 2 is reference you open on purpose.

   The three dev tools were briefly a dimmed third tier here. They are now a
   single TOOLS row in Library that opens its own in-shell submenu (the same
   swap Solo Match and Multiplayer use, so the hero art and music carry
   across). Owner's call, and the better one: a dimmed row is still a row —
   it still takes vertical space and still has to be read past. Folding three
   into one takes the home screen from ten options to eight and leaves the
   dev shelf exactly one click away. Its former tier-3 block is deleted
   rather than left behind, since nothing carries that class any more. */

/* TIER 1 — PLAY. The reason the screen exists. */
.mm-section.mm-tier-1 .mm-option-label { font-size: 19px; letter-spacing: 3.4px; }
.mm-section.mm-tier-1 .mm-option-sub   { font-size: 11px; }

/* TIER 2 — LIBRARY. Player-facing reference; a step down, still full-voice. */
.mm-section.mm-tier-2 .mm-option-label { font-size: 15px; letter-spacing: 2.8px; opacity: 0.88; }
.mm-section.mm-tier-2 .mm-option-sub   { font-size: 10px; opacity: 0.85; }


/* SOLO MATCH LEADS ITS OWN TIER. One clear first move, so the eye lands
   before it starts reading. A hair above its siblings — enough to rank,
   not enough to look like a different component. */
#mm-play .mm-option-label { font-size: 21px; letter-spacing: 4px; }

/* ============================================================
   MENU PARALLAX — PLANES AT DIFFERENT DEPTHS (2026-08-18)
   ============================================================
   The scene already moved: mmHeroDrift runs a 34s Ken Burns on the hero. But
   every layer moved TOGETHER, so it read as an animated poster rather than a
   set. Depth is not more motion — it is planes travelling at different rates
   relative to one another. Each plane takes the same pointer signal
   (--mm-par-x / --mm-par-y) at its own depth.

   `translate`, NEVER `transform`. The hero already owns its transform:
   mmHeroDrift animates it forever and mmHeroRezIn plays on entry. Setting
   transform here would clobber both — the drift would freeze the instant the
   pointer moved. `translate` is a separate longhand that COMPOSES with
   transform rather than replacing it, so the drift keeps running underneath.

   The intensity multiply happens in JS, and that is a simplification, not a
   fix. While building this the planes appeared not to move at all, and the
   first suspicion was that holding clamp() in an untyped custom property broke
   the surrounding calc. That was WRONG and it was checked rather than assumed:
   an isolated element with `--k: clamp(0.35, calc(0.18*3.2), 1.3)` used as a
   multiplier computes to exactly the same -5.76px as a plain 0.576. The real
   reason nothing appeared to move was the measurement — computed style was
   read two frames into the 420ms ease below, while the value was still near
   its start. Scaling in JS is kept because one finished number is simpler to
   reason about than a nested calc, not because the nested calc was broken.

   @property registers the two inputs as real <number>s so the transition
   below INTERPOLATES them. Untyped custom properties animate discretely —
   they would snap to rest on pointerleave rather than easing back.

   Travel is deliberately tiny (10px at the deepest). Parallax announces itself
   the moment it is legible as an effect; at this size it reads as the scene
   having depth, not as the menu reacting to you. Type moves AGAINST the art:
   opposed travel separates two planes far more strongly than equal travel in
   the same direction, which is what buys legible depth from a few pixels.

   Planes are the ones the scene ACTUALLY builds — mm-tron-grid, mm-hero,
   mm-scrim, mm-panel, mm-title. THIS was the genuine defect in the first pass:
   it also drove .mm-shard and .mm-hero-reflect, and the current
   _menuSceneHTML never emits either. Those selectors still carry styling
   further up this file (a fractured-mirror treatment that is no longer built),
   which is exactly why they looked like live layers. Two of five planes were
   animating nothing. */
@property --mm-par-x { syntax: '<number>'; inherits: true; initial-value: 0; }
@property --mm-par-y { syntax: '<number>'; inherits: true; initial-value: 0; }

.mm-mw3 .mm-tron-grid,
.mm-mw3 .mm-hero,
.mm-mw3 .mm-scrim,
.mm-mw3 .mm-panel,
.mm-mw3 .mm-title {
  /* Ease back to rest on pointerleave; short enough not to read as lag. */
  transition: translate 420ms cubic-bezier(.2, .7, .2, 1);
  will-change: translate;
}
/* Deepest plane — the hero itself. */
.mm-mw3 .mm-hero {
  translate: calc(var(--mm-par-x) * 10px) calc(var(--mm-par-y) * 6px);
}
/* The grid sits behind everything and barely moves — a far wall. */
.mm-mw3 .mm-tron-grid {
  translate: calc(var(--mm-par-x) * 4px) calc(var(--mm-par-y) * 2.5px);
}
/* The scrim rides just in front of the art so the falloff slides across it. */
.mm-mw3 .mm-scrim {
  translate: calc(var(--mm-par-x) * 7px) calc(var(--mm-par-y) * 4px);
}
/* Type is the front plane and travels the OTHER way. */
.mm-mw3 .mm-panel {
  translate: calc(var(--mm-par-x) * -4px) calc(var(--mm-par-y) * -2.5px);
}
.mm-mw3 .mm-title {
  translate: calc(var(--mm-par-x) * -3px) calc(var(--mm-par-y) * -2px);
}
@media (prefers-reduced-motion: reduce) {
  .mm-mw3 .mm-tron-grid, .mm-mw3 .mm-hero, .mm-mw3 .mm-scrim,
  .mm-mw3 .mm-panel, .mm-mw3 .mm-title { translate: none; transition: none; }
}

/* ============================================================
   GALLERY AUDIT — PRECISION FRAMING TOOLS (2026-08-18)
   ============================================================
   The crop controls were two 0-100 range sliders and ±10% zoom buttons. One
   slider step moved a 898px plate by roughly 9px, the current value was never
   shown, and you were pushing abstract numbers while looking at a picture.
   The stage is now the control: drag the art, scroll to zoom, arrow-nudge for
   the last half percent. */
.gal-crop { position: relative; cursor: grab; outline: none; }
.gal-crop.is-dragging { cursor: grabbing; }
.gal-crop:focus-visible {
  box-shadow: 0 0 0 2px rgba(var(--theme-rgb, 79,195,247), 0.9);
}
/* AUTO — no focal saved, so this variant is riding the global fallback rather
   than being framed. The point is to make an invisible backlog countable. */
.gal-auto {
  position: absolute; top: 4px; right: 4px; z-index: 4;
  font: 700 8px/1 ui-monospace, Menlo, monospace; letter-spacing: 0.5px;
  padding: 2px 4px; border-radius: 2px; pointer-events: none;
  color: #ffcf66; background: rgba(0,0,0,0.72); border: 1px solid rgba(255,207,107,0.5);
}
/* Rule-of-thirds + centre cross. Off by default — a permanent grid competes
   with the very composition it is meant to help you judge. */
.gal-guides { position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: 0; }
.gal-show-guides .gal-guides { opacity: 1; }
.gal-guides::before, .gal-guides::after {
  content: ''; position: absolute; inset: 0;
  background-repeat: no-repeat;
}
.gal-guides::before {
  background-image:
    linear-gradient(to right, rgba(255,255,255,0.34) 0 1px, transparent 1px),
    linear-gradient(to right, rgba(255,255,255,0.34) 0 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255,255,255,0.34) 0 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255,255,255,0.34) 0 1px, transparent 1px);
  background-size: 100% 100%;
  background-position: 33.333% 0, 66.666% 0, 0 33.333%, 0 66.666%;
}
/* Centre cross, brighter — the reference you actually align a face to. */
.gal-guides::after {
  background-image:
    linear-gradient(to right, rgba(var(--theme-rgb,79,195,247),0.75) 0 1px, transparent 1px),
    linear-gradient(to bottom, rgba(var(--theme-rgb,79,195,247),0.75) 0 1px, transparent 1px);
  background-size: 100% 100%;
  background-position: 50% 0, 0 50%;
}
/* THE TYPE ZONE — menu crops only. The menu hero is right-anchored and its
   left edge dissolves beneath the menu list, so a face parked in the left
   third of a menu crop ends up behind the buttons. This is the one guide a
   general image editor could not give you, because it encodes where THIS
   game's chrome sits. On by default for that reason. */
.gal-safe {
  position: absolute; left: 0; top: 0; bottom: 0; width: 34%; z-index: 3;
  pointer-events: none; opacity: 0;
  background: repeating-linear-gradient(135deg,
    rgba(255,90,90,0.16) 0 6px, rgba(255,90,90,0.05) 6px 12px);
  border-right: 1px dashed rgba(255,120,120,0.55);
}
.gal-show-safe .gal-safe { opacity: 1; }
.gal-safe span {
  position: absolute; left: 3px; bottom: 3px;
  font: 700 7px/1 ui-monospace, Menlo, monospace; letter-spacing: 0.6px;
  color: rgba(255,150,150,0.9);
}
/* Numeric fields — the exact value, and somewhere to type one. */
.gal-num-row { display: flex; gap: 6px; margin-top: 5px; }
.gal-num {
  display: flex; align-items: center; gap: 3px; flex: 1;
  font: 600 9px/1 'Rajdhani', sans-serif; letter-spacing: 1px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 60%, white);
}
.gal-num input, .gal-zoom-num {
  width: 100%; min-width: 0; background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.35);
  border-radius: 2px; padding: 2px 3px;
  font: 600 10px/1.2 ui-monospace, Menlo, monospace;
  color: #e8f5ff; font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.gal-zoom-num { width: 42px; text-align: right; }
.gal-num input:focus, .gal-zoom-num:focus {
  outline: none; border-color: rgba(var(--theme-rgb, 79,195,247), 0.9);
}
.gal-zoom-pct { font: 600 9px/1 ui-monospace, monospace; opacity: 0.7; }
.gal-crop-btns { display: flex; gap: 5px; margin-top: 5px; }
.gal-crop-btns .gal-reset { flex: 1; }
.gal-chk {
  display: inline-flex; align-items: center; gap: 5px;
  font: 600 10px/1 'Rajdhani', sans-serif; letter-spacing: 1.5px;
  text-transform: uppercase; white-space: nowrap;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 62%, white);
}
.gal-hint {
  font: 500 9px/1 ui-monospace, Menlo, monospace; letter-spacing: 0.3px;
  opacity: 0.55; white-space: nowrap;
}
/* An axis with no overflow has no range — the number is inert until you zoom
   in. Dimmed rather than removed: the field still shows the stored value, and
   the tooltip says what to do about it. */
.gal-num.is-dead { opacity: 0.38; }
.gal-num.is-dead input { border-style: dashed; }

/* ============================================================
   DRAFT — WHO OPENS ROUND 1 (2026-08-18)
   ============================================================
   The coin flip is resolved at match start, so who leads round 1 is already
   decided while you are still drafting — it was simply never surfaced. It is
   not trivia: going second means you play into a board that already has a card
   in it (a cheap early body gains value), and going first means your On Play
   resolves before theirs. Drafting without it is drafting blind to half the
   opening.

   Boxless, per the house rule — a rule above and glow text, no container.
   Colour carries the answer so it reads before the sentence does: theme accent
   when it is you, warm amber when it is not. */
.draft-first {
  display: flex; align-items: baseline; justify-content: center; gap: 8px;
  margin: 6px 0 2px; padding-top: 6px;
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.16);
}
.draft-first-label {
  font: 700 9px/1 'Rajdhani', sans-serif; letter-spacing: 3px;
  text-transform: uppercase; opacity: 0.6;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 60%, white);
}
.draft-first-who {
  font: 700 13px/1 'Rajdhani', sans-serif; letter-spacing: 2.4px;
  text-transform: uppercase;
}
.draft-first.is-mine .draft-first-who {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 30%, #e8f5ff);
  text-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.55);
}
.draft-first.is-theirs .draft-first-who {
  color: #ffcf8a;
  text-shadow: 0 0 10px rgba(255, 176, 92, 0.45);
}

/* ============================================================
   KILLER MOTH — THE LANE LIST IS THE WHOLE BADGE (2026-08-18)
   ============================================================
   Owner, pointing at the board chip: "this should just say 1,5 — that's all I
   want, a list of the lanes he's been in."

   It rendered "1," because every board badge is pinned to a third of the row:
   `flex: 0 0 calc((100% - gap*2)/3)` with `min-width: 0`, so exactly three fit
   per row on every card. That is deliberate and right for a GLYPH — the note
   above it explains that min-width:0 is what makes the third bind instead of
   merely intending to. Measured here: the badge held 33.7px against a 44px
   content width, so the last character was sliced by the strip's
   overflow:hidden.

   This file already documents the same class of exception — "any badge that is
   showing its WORD sizes to its CONTENT" — for keywords like Unresistible that
   cannot fit a third. A lane list is that case in a harder form: its width is
   not merely long, it GROWS, from "1" to "1,2,3,4,5,6". So it opts out of the
   grid and sizes to content, and min-width goes back to auto, which is the half
   that actually stops the slicing.

   The glyph is dropped here too. An icon earns its place on a badge whose word
   it replaces — Armor, Evade and Burning all read as "icon + amount". This
   badge's content is a LIST rather than an amount, so the glyph is 16px spent
   restating what the tooltip already says on hover, taken straight out of the
   list it was meant to label.

   Board only. In hand and in the codex there is room for the label, and a bare
   "1,5" with nothing beside it would be a riddle. */
/* KEEP THE GRID. Two attempts to resize this cell both failed in ways worth
   recording: `flex: 0 0 auto` collapsed the badge to zero WIDTH (it vanished
   from the board), and `flex: 0 0 100%` fixed the width but collapsed its
   HEIGHT to zero. The 3-across layout is load-bearing in ways that are not
   visible from the one rule that declares it, so the badge stays in its cell
   and the fix is to stop spending that cell on things the list does not need.
   Dropping the glyph alone returns ~16px of a 33.7px cell — enough for "1,5"
   with room to spare, which is the case the owner was looking at. */
/* One correction to the note above: `flex: 0 0 100%` was NOT the thing that
   collapsed the height — the `height: auto` shipped alongside it was. The base
   rule sets an explicit height (var(--sb-i) * 1.42) and overriding it to auto
   in a centred flex row zeroed the box. Keeping the declared height and taking
   only the full-row basis gives the list a whole row at its normal height,
   which is the one shape that can hold six lanes on a 114px card. */
.board .card .status-badge.badge-lanes-flown {
  flex: 0 0 100%;
  max-width: 100%;
}
.board .card .status-badge.badge-lanes-flown .sb-i,
.board .card .status-badge.badge-lanes-flown .sb-w { display: none; }
.board .card .status-badge.badge-lanes-flown .sb-n {
  font-size: var(--sb-num);
  font-weight: 700;
  letter-spacing: 0.2px;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
/* The list is the one badge whose width GROWS — from "1" to "1,2,3,4,5,6" —
   so past a point the type has to give. Two tiers, both measured against the
   109px row rather than guessed: three lanes overflow by only 3px, six lanes
   by 66px. The count is classified in JS (ui.js) because CSS cannot measure
   its own content. */
.board .card .status-badge.badge-lanes-flown.lf-mid .sb-n {
  font-size: calc(var(--sb-num) * 0.82);
  letter-spacing: 0;
}
.board .card .status-badge.badge-lanes-flown.lf-long .sb-n {
  font-size: calc(var(--sb-num) * 0.40);
  letter-spacing: 0;
}

/* ============================================================
   BRAINIAC FORESIGHT STRIP
   Lives in the AI banner (.ai-bar), positioned just under it so it
   never disturbs the bar's flex row. Shown only while the human's
   _brainiacScanRounds > 0; UI._renderBrainiacScan fills / clears it.
   ============================================================ */
.brainiac-scan {
  display: none;
}
.brainiac-scan.is-active {
  display: flex;
  align-items: center;
  gap: 6px;
  position: absolute;
  top: calc(100% + 4px);
  right: 8px;
  z-index: 6;
  padding: 3px 8px 3px 6px;
  border-radius: 8px;
  background: rgba(18, 10, 28, 0.92);
  border: 1px solid rgba(215, 179, 230, 0.55);   /* --palette-purple, dimmed */
  box-shadow: 0 0 10px rgba(140, 90, 200, 0.35), inset 0 0 6px rgba(126, 232, 165, 0.10);
  font-size: 11px;
  line-height: 1;
  pointer-events: auto;
  cursor: pointer;
  animation: brainiac-scan-in 220ms ease-out;
}
@keyframes brainiac-scan-in {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}
.brainiac-scan-eye {
  font-size: 12px;
  filter: drop-shadow(0 0 4px rgba(126, 232, 165, 0.7));
}
.brainiac-scan-empty {
  color: var(--palette-purple);
  opacity: 0.8;
  font-style: italic;
}
.brainiac-scan-card {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 6px 2px 3px;
  border-radius: 4px;
  background: rgba(126, 232, 165, 0.08);
  border: 1px solid rgba(126, 232, 165, 0.22);
}
/* Whose hand this is, and how long the window stays open. The strip used to
   show two numbered draw slots; it now shows a whole hand, so it needs to say
   WHOSE and for how much longer. */
.brainiac-scan-who {
  font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase;
  font-size: 9px; color: #e9d6f5;
  text-shadow: 0 0 8px rgba(190, 130, 240, 0.75);
  padding-right: 2px; border-right: 1px solid rgba(215, 179, 230, 0.35);
  margin-right: 2px;
}
.brainiac-scan-rounds {
  font-size: 9px; font-weight: 700; letter-spacing: 0.04em;
  color: rgba(233, 214, 245, 0.85);
  border: 1px solid rgba(215, 179, 230, 0.45);
  border-radius: 4px; padding: 1px 4px; margin-left: 2px;
}
/* A card that arrived while the scan was open — it came in at -1 ATK, and the
   watcher should be able to see which ones those are without remembering. */
.brainiac-scan-card.is-drained {
  border-color: rgba(126, 232, 165, 0.7);
  box-shadow: 0 0 7px rgba(126, 232, 165, 0.35);
}
.brainiac-scan-card.is-drained .brainiac-scan-name { color: #cdf5dc; }
.brainiac-scan-order {
  font-size: 9px;
  font-weight: 700;
  color: #120a1c;
  background: var(--palette-purple);
  border-radius: 50%;
  width: 13px;
  height: 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.brainiac-scan-art {
  width: 18px;
  height: 24px;
  border-radius: 2px;
  background-size: cover;
  background-position: 50% 25%;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.5);
}
.brainiac-scan-name {
  color: #eafff2;
  font-weight: 600;
  max-width: 130px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.brainiac-scan-cost {
  font-size: 10px;
  font-weight: 700;
  color: #ffd77a;                                /* energy gold */
  background: rgba(0, 0, 0, 0.35);
  border-radius: 4px;
  padding: 1px 4px;
}
.brainiac-scan-pulse {
  animation: brainiac-scan-pulse 640ms ease-out;
}
@keyframes brainiac-scan-pulse {
  0%   { box-shadow: 0 0 0 0 rgba(126, 232, 165, 0.55), 0 0 10px rgba(140, 90, 200, 0.35); }
  70%  { box-shadow: 0 0 0 8px rgba(126, 232, 165, 0), 0 0 18px rgba(140, 90, 200, 0.6); }
  100% { box-shadow: 0 0 0 0 rgba(126, 232, 165, 0), 0 0 10px rgba(140, 90, 200, 0.35); }
}
@media (prefers-reduced-motion: reduce) {
  .brainiac-scan.is-active { animation: none; }
  .brainiac-scan-pulse { animation: none; }
}

/* Brainiac center-screen reveal — the prominent "here's what's coming" moment
   thrown the instant the human discards Brainiac. */
.brainiac-reveal-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at center, rgba(40, 16, 60, 0.55), rgba(4, 2, 8, 0.82));
  animation: brainiac-reveal-fade 0.28s ease-out;
  cursor: pointer;
}
.brainiac-reveal-overlay.is-leaving { animation: brainiac-reveal-fade 0.3s ease-in reverse; }
@keyframes brainiac-reveal-fade { from { opacity: 0; } to { opacity: 1; } }
.brainiac-reveal-inner { text-align: center; }
.brainiac-reveal-title {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #d9ffe5;
  text-shadow: 0 0 14px rgba(126, 232, 165, 0.6), 0 0 26px rgba(140, 90, 200, 0.5);
}
.brainiac-reveal-eye { filter: drop-shadow(0 0 8px rgba(126, 232, 165, 0.9)); }
.brainiac-reveal-sub {
  margin-top: 4px;
  font-size: 13px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(215, 179, 230, 0.85);
}
.brainiac-reveal-cards {
  margin-top: 20px;
  display: flex;
  gap: 22px;
  justify-content: center;
}
.brainiac-reveal-card {
  position: relative;
  width: 150px;
  border-radius: 12px;
  overflow: hidden;
  background: rgba(18, 10, 28, 0.95);
  border: 1px solid rgba(215, 179, 230, 0.6);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.6), 0 0 18px rgba(140, 90, 200, 0.4);
  animation: brainiac-reveal-card-in 0.42s cubic-bezier(.2,.9,.3,1) both;
  animation-delay: calc(var(--i, 0) * 0.11s + 0.06s);
}
@keyframes brainiac-reveal-card-in {
  from { opacity: 0; transform: translateY(16px) scale(0.9) rotateX(18deg); }
  to   { opacity: 1; transform: translateY(0) scale(1) rotateX(0); }
}
.brainiac-reveal-art {
  width: 100%;
  height: 200px;
  background-size: cover;
  background-position: 50% 22%;
  background-color: #000000;
}
.brainiac-reveal-name {
  padding: 8px 6px 4px;
  font-size: 13px;
  font-weight: 700;
  color: #eafff2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* Reduced stats the card arrived with under the scan (−1/−1). */
.brainiac-reveal-stats {
  display: flex; justify-content: center; gap: 10px;
  padding: 0 6px 9px; font-weight: 800; font-size: 13px;
}
.brainiac-reveal-stats .brs-atk { color: #7ee8a5; }
.brainiac-reveal-stats .brs-hp  { color: #ff8f8f; }
.brainiac-reveal-stats .brs-atk::before { content: '⚔ '; opacity: 0.7; font-weight: 600; }
.brainiac-reveal-stats .brs-hp::before  { content: '♥ '; opacity: 0.7; font-weight: 600; }
.brainiac-reveal-order {
  position: absolute;
  top: 6px;
  left: 6px;
  z-index: 2;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: rgba(140, 90, 200, 0.92);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  line-height: 20px;
  text-align: center;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.4);
}
.brainiac-reveal-cost {
  position: absolute;
  top: 6px;
  right: 6px;
  z-index: 2;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.6);
  color: #ffd77a;
  font-size: 12px;
  font-weight: 700;
  line-height: 20px;
  text-align: center;
}
@media (prefers-reduced-motion: reduce) {
  .brainiac-reveal-overlay, .brainiac-reveal-card { animation: none; }
}

/* ============================================================
   ART THE CLOWN — WEAPON FX
   Themed glyphs (spawned by UI._fxArtWeapon into the FX layer) plus a
   hit-shake on the struck card. Paired with the shared spark/impact
   primitives; these only style the emoji glyph + the shake.
   ============================================================ */
.fx-art-weapon {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 52px;
  height: 52px;
  line-height: 0;
  pointer-events: none;
  z-index: 40;
  will-change: transform, opacity;
}
.fx-art-weapon svg { width: 100%; height: 100%; }
.fx-art-bleed { width: 38px; height: 38px; }

/* NEON weapon glyphs (Art the Clown) — a glowing cyan tube like a neon sign,
   shared by the weapon-choice tiles and the swing FX. Geometry lives in the
   SVGs; stroke, color and glow are all here. */
.wneon { display: block; width: 100%; height: 100%; overflow: visible; color: #38e6ff;
  filter: drop-shadow(0 0 2px currentColor) drop-shadow(0 0 5px rgba(56,230,255,0.9)) drop-shadow(0 0 11px rgba(56,230,255,0.5));
  animation: wneon-flicker 3.2s ease-in-out infinite; }
.wneon * { fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
.wneon-blood { color: #ff2d55;
  filter: drop-shadow(0 0 2px currentColor) drop-shadow(0 0 5px rgba(255,45,85,0.9)) drop-shadow(0 0 11px rgba(255,45,85,0.5)); }
.wneon-blood * { fill: rgba(255,45,85,0.12); }
@keyframes wneon-flicker {
  0%, 100% { opacity: 1; }
  92% { opacity: 1; }
  94% { opacity: 0.72; }
  96% { opacity: 1; }
  97% { opacity: 0.85; }
  98% { opacity: 1; }
}
/* ============================================================
   "WHICH PLAYER?" TILES — The Grinch, Deadpool, Eye of Agamotto, Dormammu,
   Brainiac's scan, The Flash's first-player pick. On these the seat NAME is the
   entire decision; there is no portrait to read and no rules text that matters.
   It was rendering as small unstyled text in the tile's top-left corner because
   the markup for it shipped without any styling at all — so the one thing you
   are choosing between was the least legible thing on the tile. (User: "can you
   make the names for these type of prompts for all characters like in the
   center and glow.") Centred, large, and lit, with the team line kept small
   underneath it as the supporting detail it is.
   ============================================================ */
.choice-card.choice-player {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center;
}
.choice-player-name {
  flex: 1 1 auto;
  display: flex; align-items: center; justify-content: center;
  width: 100%; padding: 14px 8px 8px;
  font-size: 19px; font-weight: 800; letter-spacing: 0.05em; text-transform: uppercase;
  line-height: 1.1; word-break: break-word;
  color: #eaf8ff;
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.95),
               0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.55),
               0 0 40px rgba(var(--theme-rgb, 79,195,247), 0.28);
  animation: choice-player-breathe 2.6s ease-in-out infinite;
}
.choice-card.choice-player .card-desc {
  padding: 0 8px 8px; text-align: center;
  font-size: 10px; letter-spacing: 0.04em; opacity: 0.75;
}
.choice-card.choice-player:hover .choice-player-name {
  color: #fff;
  text-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 1),
               0 0 28px rgba(var(--theme-rgb, 79,195,247), 0.7),
               0 0 52px rgba(var(--theme-rgb, 79,195,247), 0.4);
}
@keyframes choice-player-breathe {
  0%, 100% { filter: brightness(1); }
  50%      { filter: brightness(1.18); }
}
@media (prefers-reduced-motion: reduce) {
  .choice-player-name { animation: none; }
}
@media (max-width: 820px) {
  .choice-player-name { font-size: 15px; padding: 10px 6px 6px; }
}
/* Weapon-choice tile: the neon glyph replaces the portrait, name + rules below. */
.art-weapon-neon { display: flex; align-items: center; justify-content: center; width: 100%; padding: 12px 4px 2px; }
.art-weapon-neon .wneon { width: 58px; height: 58px; }
.choice-card.art-weapon-opt { text-align: center; align-items: center; }
.art-weapon-name { font-size: 13px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
  color: #bfefff; text-shadow: 0 0 6px rgba(56,230,255,0.5); margin: 2px 0 4px; }
@media (prefers-reduced-motion: reduce) { .wneon { animation: none; } }
/* Scissors — a quick snip: rotate in, close, fade. */
.fx-art-scissors { animation: fx-art-scissors 0.72s cubic-bezier(.3,.8,.3,1) forwards; }
@keyframes fx-art-scissors {
  0%   { opacity: 0; transform: translate(-50%,-50%) rotate(-35deg) scale(0.6); }
  35%  { opacity: 1; transform: translate(-50%,-50%) rotate(8deg) scale(1.15); }
  60%  { transform: translate(-50%,-50%) rotate(-6deg) scale(1.0); }
  100% { opacity: 0; transform: translate(-50%,-50%) rotate(0) scale(1.1); }
}
/* Sledgehammer — slams down from above, big and heavy. */
.fx-art-sledge { animation: fx-art-sledge 0.62s cubic-bezier(.4,1.6,.5,1) forwards; }
@keyframes fx-art-sledge {
  0%   { opacity: 0; transform: translate(-50%,-190%) rotate(-42deg) scale(1.3); }
  55%  { opacity: 1; transform: translate(-50%,-50%) rotate(6deg) scale(1.5); }
  70%  { transform: translate(-50%,-46%) rotate(2deg) scale(1.35); }
  100% { opacity: 0; transform: translate(-50%,-50%) rotate(0) scale(1.4); }
}
/* Scythe — sweeps a diagonal arc across the card. */
.fx-art-scythe { animation: fx-art-scythe 0.7s cubic-bezier(.3,.7,.2,1) forwards; }
@keyframes fx-art-scythe {
  0%   { opacity: 0; transform: translate(-120%,-120%) rotate(-70deg) scale(1.1); }
  45%  { opacity: 1; transform: translate(-50%,-50%) rotate(0deg) scale(1.35); }
  100% { opacity: 0; transform: translate(30%,30%) rotate(65deg) scale(1.15); }
}
/* Hacksaw — juddering back-and-forth saw motion. */
.fx-art-hacksaw { animation: fx-art-hacksaw 0.76s ease-in-out forwards; }
@keyframes fx-art-hacksaw {
  0%   { opacity: 0; transform: translate(-70%,-50%) rotate(-14deg) scale(1.0); }
  20%  { opacity: 1; transform: translate(-30%,-50%) rotate(10deg) scale(1.2); }
  40%  { transform: translate(-70%,-50%) rotate(-10deg) scale(1.2); }
  60%  { transform: translate(-30%,-50%) rotate(10deg) scale(1.2); }
  80%  { transform: translate(-55%,-50%) rotate(-4deg) scale(1.15); }
  100% { opacity: 0; transform: translate(-50%,-50%) rotate(0) scale(1.1); }
}
/* Bleed tick — a drop wells up and falls. */
.fx-art-bleed { font-size: 30px; animation: fx-art-bleed 0.82s ease-in forwards; }
@keyframes fx-art-bleed {
  0%   { opacity: 0; transform: translate(-50%,-90%) scale(0.6); }
  30%  { opacity: 1; transform: translate(-50%,-60%) scale(1.05); }
  100% { opacity: 0; transform: translate(-50%,40%) scale(0.9); }
}
/* Struck-card shake. */
.fx-art-hit { animation: fx-art-hit 0.42s ease-in-out; }
@keyframes fx-art-hit {
  0%,100% { transform: translate(0,0); }
  20% { transform: translate(-3px,1px) rotate(-1deg); }
  50% { transform: translate(3px,-1px) rotate(1deg); }
  80% { transform: translate(-2px,1px); }
}
.fx-art-hit-heavy { animation: fx-art-hit-heavy 0.6s cubic-bezier(.36,.07,.19,.97); }
@keyframes fx-art-hit-heavy {
  0%,100% { transform: translate(0,0); }
  15% { transform: translate(-6px,3px) rotate(-2.5deg); }
  35% { transform: translate(6px,-2px) rotate(2deg); }
  55% { transform: translate(-5px,2px) rotate(-1.5deg); }
  75% { transform: translate(4px,-1px) rotate(1deg); }
}
@media (prefers-reduced-motion: reduce) {
  .fx-art-weapon, .fx-art-hit, .fx-art-hit-heavy { animation: none; }
}

/* Carnage frenzy — red-symbiote glow pulse as he feeds and heals. */
.fx-carnage-frenzy { animation: fx-carnage-frenzy 0.7s ease-out; }
@keyframes fx-carnage-frenzy {
  0%   { filter: none; }
  30%  { filter: drop-shadow(0 0 10px rgba(224,30,30,0.9)) saturate(1.45); }
  100% { filter: none; }
}
/* Michael Myers stalk — the card darkens into cold shadow as he steps in. */
.fx-myers-stalk { animation: fx-myers-stalk 0.72s ease-out; }
@keyframes fx-myers-stalk {
  0%   { filter: none; }
  40%  { filter: brightness(0.68) contrast(1.2) drop-shadow(0 0 8px rgba(150,170,190,0.7)); }
  100% { filter: none; }
}

/* Green Lantern — emerald willpower flare as the ring channels energy. */
.fx-lantern-glow { animation: fx-lantern-glow 0.7s ease-out; }
@keyframes fx-lantern-glow {
  0%   { filter: none; }
  35%  { filter: drop-shadow(0 0 12px rgba(47,227,107,0.9)) brightness(1.15); }
  100% { filter: none; }
}
/* Han Solo — blaster recoil kick. */
.fx-han-recoil { animation: fx-han-recoil 0.38s ease-out; }
@keyframes fx-han-recoil {
  0%   { transform: translate(0,0); }
  30%  { transform: translate(-5px,1px) rotate(-2deg); }
  100% { transform: translate(0,0); }
}

/* Droideka — deflector shield (blue) vs. blaster overcharge (red-hot). */
.fx-droideka-shield { animation: fx-droideka-shield 0.7s ease-out; }
@keyframes fx-droideka-shield {
  0%   { filter: none; }
  40%  { filter: drop-shadow(0 0 11px rgba(74,163,255,0.9)) brightness(1.1); }
  100% { filter: none; }
}
.fx-droideka-overcharge { animation: fx-droideka-overcharge 0.7s ease-out; }
@keyframes fx-droideka-overcharge {
  0%   { filter: none; }
  40%  { filter: drop-shadow(0 0 11px rgba(255,90,46,0.9)) saturate(1.3) brightness(1.1); }
  100% { filter: none; }
}

/* Professor X — violet mind-seizure flash as the enemy turns. */
.fx-profx-convert { animation: fx-profx-convert 0.8s ease-out; }
@keyframes fx-profx-convert {
  0%   { filter: none; }
  45%  { filter: drop-shadow(0 0 12px rgba(162,75,255,0.9)) hue-rotate(-10deg); }
  100% { filter: none; }
}
/* Jack Sparrow — gold spectral hold on the parlayed enemy. */
.fx-parlay-hold { animation: fx-parlay-hold 0.7s ease-out; }
@keyframes fx-parlay-hold {
  0%   { filter: none; }
  40%  { filter: drop-shadow(0 0 9px rgba(232,192,90,0.85)) sepia(0.3); }
  100% { filter: none; }
}
/* Freddy Fazbear — animatronic red glitch. */
.fx-fazbear-glitch { animation: fx-fazbear-glitch 0.3s steps(2) 2; }
@keyframes fx-fazbear-glitch {
  0%   { transform: translate(0,0); filter: none; }
  25%  { transform: translate(-2px,1px); filter: hue-rotate(-20deg) brightness(1.1); }
  50%  { transform: translate(2px,-1px); }
  75%  { transform: translate(-1px,0); filter: contrast(1.3); }
  100% { transform: translate(0,0); filter: none; }
}

/* Doomsday — brutal slam entrance: he lands hard, then the ground shakes. */
.fx-doomsday-slam { animation: fx-doomsday-slam 0.72s cubic-bezier(.36,.07,.19,.97); }
@keyframes fx-doomsday-slam {
  0%   { transform: scale(1.15) translateY(-6px); filter: brightness(1.3); }
  20%  { transform: scale(1) translateY(0); filter: none; }
  35%  { transform: translate(-4px,2px) rotate(-1.5deg); }
  55%  { transform: translate(4px,-1px) rotate(1deg); }
  75%  { transform: translate(-2px,1px); }
  100% { transform: translate(0,0); }
}

/* Open Water — Jaws surfaces in a wall of water. */
.fx-water-surge { animation: fx-water-surge 0.76s ease-out; }
@keyframes fx-water-surge {
  0%   { filter: none; transform: translateY(6px); }
  30%  { filter: drop-shadow(0 0 10px rgba(79,200,255,0.85)) brightness(1.1); transform: translateY(0); }
  100% { filter: none; transform: translateY(0); }
}
/* Gargantua — accretion motes spiralling into the gravity well. */
.fx-gargantua-mote {
  position: fixed; width: 5px; height: 5px; border-radius: 50%;
  background: radial-gradient(circle, #fff2c8, #e08a2a);
  box-shadow: 0 0 6px #f0b45a; transform: translate(-50%,-50%);
  pointer-events: none; z-index: 39;
  animation: fx-gargantua-mote 0.8s cubic-bezier(.4,0,.7,1) forwards;
}
@keyframes fx-gargantua-mote {
  0%   { opacity: 0; transform: translate(calc(-50% + var(--gx)), calc(-50% + var(--gy))) rotate(0) scale(1.2); }
  25%  { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%,-50%) rotate(var(--gr)) scale(0.2); }
}
/* The Bathroom — rusty iron-chain clamp jolt. */
.fx-bathroom-chain { animation: fx-bathroom-chain 0.72s ease-out; }
@keyframes fx-bathroom-chain {
  0%   { filter: none; transform: translate(0,0); }
  20%  { transform: translate(-3px,0); }
  40%  { transform: translate(3px,0); filter: sepia(0.4) drop-shadow(0 0 8px rgba(150,160,170,0.8)); }
  60%  { transform: translate(-2px,0); }
  100% { filter: none; transform: translate(0,0); }
}

/* Shared trick FX — themeable buff/debuff card pulses (color via --tfx). */
.fx-trick-buff { animation: fx-trick-buff 0.64s ease-out; }
@keyframes fx-trick-buff {
  0%   { filter: none; }
  35%  { filter: drop-shadow(0 0 11px var(--tfx, #3ad17e)) brightness(1.12); }
  100% { filter: none; }
}
.fx-trick-debuff { animation: fx-trick-debuff 0.64s ease-out; }
@keyframes fx-trick-debuff {
  0%   { filter: none; }
  35%  { filter: drop-shadow(0 0 9px var(--tfx, #c0392b)) brightness(0.85) saturate(0.82); }
  100% { filter: none; }
}

/* ============================================================
   2v2 TURN-ORDER TRACKER — who's up, who's next, what they play.
   A collapsible strip pinned top-center over the 2v2 board.
   ============================================================ */
/* NEON, NOT NAVY. This panel was rgba(10,14,22,.9) — a blue-grey wash — with
   white-alpha chip fills and solid-fill badges, which is why it read as the one
   flat, lifeless surface on the board. Interior is now pure #000 with the light
   coming from the EDGES (hairline + outer bloom + faint inner bloom), which is
   the same language the rest of the game uses. (User: "for the turn order
   popout there is no neon at all, that should all be neon.") */
/* ANCHORED BOTTOM-RIGHT, BESIDE THE TRICKS. It used to sit centred on the
   right edge (top: 50% + a translate), which put it across the middle of lanes
   7 and 8 — the part of the board you are actually reading. Down here it lines
   up with the hand band and fills space that was empty: measured at 1116x891
   the trick row ends at x=831 and the rail starts at x=934, so they sit side by
   side without touching. Owner: "place the turn order dropdown next to the
   tricks."
   Still draggable — this is only where it starts. */
.twov2-tracker {
  position: fixed; right: 6px; bottom: 6px; top: auto; transform: none;
  z-index: 60; width: 176px; max-height: 86vh; overflow-y: auto;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  border-radius: 12px;
  box-shadow: 0 0 18px rgba(var(--theme-rgb, 79,195,247), 0.22),
              0 6px 22px rgba(0,0,0,0.6),
              inset 0 0 24px rgba(var(--theme-rgb, 79,195,247), 0.06);
  padding: 8px 8px 9px;
  font-family: inherit; pointer-events: auto; user-select: none;
}
.twov2-tk-head {
  display: flex; align-items: center; gap: 6px; cursor: grab; padding-bottom: 8px;
  /* The head and the grip are drag surfaces — the browser must not claim the
     gesture for scrolling/panning first, or a touch drag never reaches us. */
  touch-action: none;
}
.twov2-tracker.is-dragging .twov2-tk-head { cursor: grabbing; }
/* Placed by the player: absolute geometry replaces the right-edge anchor, and
   the chip list scrolls inside whatever height they gave it. */
.twov2-tracker.is-placed { overflow-y: auto; }
.twov2-tracker.is-dragging, .twov2-tracker.is-sizing {
  box-shadow: 0 0 26px rgba(var(--theme-rgb, 79,195,247), 0.5),
              0 10px 30px rgba(0,0,0,0.7),
              inset 0 0 24px rgba(var(--theme-rgb, 79,195,247), 0.10);
}
/* RESIZE GRIP — two neon rules in the bottom-right corner. Sticks to the
   panel's corner while the chip list scrolls under it. */
.twov2-tk-grip {
  position: sticky; float: right; clear: both;
  bottom: 0; margin: 2px -4px -5px 0;
  width: 14px; height: 14px; cursor: nwse-resize; touch-action: none;
  background:
    linear-gradient(135deg, transparent 0 46%, rgba(var(--theme-rgb, 79,195,247), 0.85) 46% 58%, transparent 58%),
    linear-gradient(135deg, transparent 0 70%, rgba(var(--theme-rgb, 79,195,247), 0.55) 70% 82%, transparent 82%);
  filter: drop-shadow(0 0 4px rgba(var(--theme-rgb, 79,195,247), 0.7));
}
.twov2-tracker.is-collapsed .twov2-tk-grip { display: none; }
.twov2-tk-title {
  font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase;
  font-weight: 700; flex: 1;
  color: var(--theme-accent-bright, #d4ecff);
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.75),
               0 0 18px rgba(var(--theme-rgb, 79,195,247), 0.35);
}
/* Boxless — a solid blue chip with black text is exactly the "blue box" the
   rest of the UI had removed. Outline + glow says the same thing and belongs. */
.twov2-tk-round {
  font-size: 10px; font-weight: 700; letter-spacing: 0.04em;
  color: rgb(var(--theme-rgb, 79,195,247));
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  background: transparent; padding: 1px 6px; border-radius: 4px;
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.8);
  box-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.22);
}
.twov2-tk-toggle {
  font-size: 12px;
  color: rgb(var(--theme-rgb, 79,195,247));
  text-shadow: 0 0 7px rgba(var(--theme-rgb, 79,195,247), 0.6);
}
.twov2-tk-row { display: flex; flex-direction: column; gap: 5px; }
.twov2-tracker.is-collapsed { width: auto; }
.twov2-tracker.is-collapsed .twov2-tk-head { padding-bottom: 0; }
.twov2-tracker.is-collapsed .twov2-tk-round { display: none; }
.twov2-tracker.is-collapsed .twov2-tk-row { display: none; }

/* ---- COMPACT RAIL -------------------------------------------------------
   It was 176px wide with 6px chips, and in the bottom-right corner that is a
   quarter of the lower board. Owner: "the turn order block just needs to be
   smaller to fit in the bottom right corner." Everything shrinks together —
   width, chip padding, the ordinal, the two type sizes — so the proportions
   hold and it just reads as the same rail, further away. */
.twov2-tracker { width: 158px; padding: 6px 6px 7px; border-radius: 10px; }
.twov2-tk-head { padding-bottom: 6px; gap: 5px; }
.twov2-tk-title { font-size: 9px; letter-spacing: 0.06em; }
.twov2-tk-round { font-size: 9px; padding: 0 4px; }
.twov2-tk-row { gap: 3px; }
/* SIZED TO THE LONGEST REAL STRINGS, not to a round number. Measured: the name
   line needs 77px for "I luv Sy (you)" and the play line 68px for "Cards +
   Tricks", and at the first pass (146px, 12px names) the body had 66px and cut
   both. The chip pays for the new mic out of its own padding and ordinal rather
   than out of the words. */
.twov2-tk-chip { gap: 5px; padding: 5px 6px 5px 6px; }
.twov2-tk-name { font-size: 11px; }
.twov2-tk-ord { width: 15px; height: 15px; font-size: 9px; }


/* ---- VOICE, INSIDE THE RAIL --------------------------------------------
   One line at the foot: the state and the one control. The old free-floating
   panel duplicated every name that is already listed above it. */
.twov2-tk-voice {
  display: flex; align-items: center; gap: 6px;
  margin-top: 6px; padding-top: 6px;
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.18);
  font: 700 9px/1 'Rajdhani', system-ui, sans-serif;
  letter-spacing: 0.10em; text-transform: uppercase;
  color: rgba(var(--theme-rgb, 79,195,247), 0.75);
}
.twov2-tk-voice .tkv-label { flex: 1; }
.twov2-tk-voice.is-live .tkv-label { color: #37d67a; text-shadow: 0 0 7px rgba(55,214,122,0.5); }
.twov2-tk-voice .tkv-dot {
  width: 6px; height: 6px; border-radius: 50%; background: #37d67a;
  box-shadow: 0 0 7px rgba(55,214,122,0.9); flex: 0 0 auto;
}
.twov2-tk-voice .tkv-count {
  font-family: var(--font-mono); font-variant-numeric: tabular-nums;
  color: rgba(var(--theme-rgb, 79,195,247), 0.95);
}
/* Boxless, like every other text control. */
.twov2-tk-voice .tkv-btn {
  background: none; border: 0; padding: 0 1px; cursor: pointer;
  font: 700 9px/1 'Rajdhani', system-ui, sans-serif;
  letter-spacing: 0.10em; text-transform: uppercase;
  transition: color 140ms var(--ease-out-soft), text-shadow 140ms var(--ease-out-soft);
}
.twov2-tk-voice .tkv-join  { color: rgba(55,214,122,0.92); }
.twov2-tk-voice .tkv-join:hover:not(:disabled) { color: #8affc0; text-shadow: 0 0 9px rgba(55,214,122,0.8); }
.twov2-tk-voice .tkv-join:disabled { opacity: 0.5; cursor: default; }
.twov2-tk-voice .tkv-leave { color: rgba(231,76,60,0.9); }
.twov2-tk-voice .tkv-leave:hover { color: #ff9c9c; text-shadow: 0 0 9px rgba(231,76,60,0.8); }
.twov2-tracker.is-collapsed .twov2-tk-voice { display: none; }

/* ---- THE MIC ON A SEAT --------------------------------------------------
   Present only for someone actually in the call: no glyph means "not on
   voice", which is a different fact from "on voice, silent". */
.twov2-tk-mic { flex: 0 0 auto; line-height: 0; color: rgba(var(--theme-rgb, 79,195,247), 0.45); }
.twov2-tk-mic .tkm { width: 12px; height: 12px; display: block; overflow: visible; }
.twov2-tk-mic .tkm-body { fill: currentColor; }
.twov2-tk-mic .tkm-arc, .twov2-tk-mic .tkm-stem {
  fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round;
}
.twov2-tk-mic .tkm-slash {
  fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; opacity: 0;
}
/* TALKING is the one state that has to read from across the table. */
.twov2-tk-mic.is-talking {
  color: #6bff9f;
  filter: drop-shadow(0 0 6px rgba(55,214,122,0.9));
}
.twov2-tk-mic.is-muted { color: rgba(231,76,60,0.9); }
.twov2-tk-mic.is-muted .tkm-arc, .twov2-tk-mic.is-muted .tkm-stem { opacity: 0.35; }
.twov2-tk-mic.is-muted .tkm-slash { opacity: 1; }
.twov2-tk-chip.is-talking { border-color: rgba(55,214,122,0.55); }

.twov2-tk-chip {
  position: relative; display: flex; align-items: center; gap: 8px;
  padding: 6px 9px 6px 7px; border-radius: 8px;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.14);
  border-left: 3px solid var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  /* No white-alpha fill — that grey wash was the flatness. The rail carries
     the seat's hue and throws it back into the chip. */
  background: #000;
  box-shadow: -6px 0 12px -6px var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  transition: transform 160ms var(--ease-snap), box-shadow 160ms var(--ease-snap), opacity 160ms var(--ease-snap);
}
/* DONE, NOT GREYED OUT. opacity:0.42 on near-white text over a black panel
   computes to a flat grey, which is the one thing the owner asked not to see
   here. A finished turn now keeps its player's hue and simply stops glowing —
   the difference between "spent" and "active" is carried by the glow and the
   fill, not by draining the colour out of it. */
.twov2-tk-chip.is-done {
  opacity: 1;
  background: transparent;
  border-left-color: color-mix(in srgb, var(--tkc, rgb(var(--theme-rgb, 79,195,247))) 50%, transparent);
}
.twov2-tk-chip.is-done .twov2-tk-name,
.twov2-tk-chip.is-done .twov2-tk-play {
  color: color-mix(in srgb, var(--tkc, rgb(var(--theme-rgb, 79,195,247))) 62%, #e8f5ff);
  text-shadow: none;
}
/* A SPENT TURN IS STILL A RING. This filled the pip with a 60%-alpha wash of
   the seat colour — a muddy blob with pale text, which is the "stale red" the
   owner circled. Spent now reads as the same ring at lower output: still lit,
   just not burning. Only the seat actually playing gets a solid fill. */
.twov2-tk-chip.is-done .twov2-tk-ord {
  background: #000;
  color: var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  border-color: color-mix(in srgb, var(--tkc, #4fc3f7) 75%, transparent);
  text-shadow: 0 0 5px color-mix(in srgb, var(--tkc, #4fc3f7) 80%, transparent);
  box-shadow: 0 0 6px color-mix(in srgb, var(--tkc, #4fc3f7) 28%, transparent);
}
.twov2-tk-chip.is-next { opacity: 0.9; }
.twov2-tk-chip.is-now {
  background: #000;
  border-color: var(--tkc, #4fc3f7);
  box-shadow: 0 0 16px color-mix(in srgb, var(--tkc, #4fc3f7) 60%, transparent),
              inset 0 0 18px color-mix(in srgb, var(--tkc, #4fc3f7) 22%, transparent);
  transform: scale(1.03);
}
.twov2-tk-chip.is-now .twov2-tk-name {
  color: #fff;
  text-shadow: 0 0 10px var(--tkc, #4fc3f7), 0 0 22px color-mix(in srgb, var(--tkc, #4fc3f7) 60%, transparent);
}
.twov2-tk-chip.is-you {
  outline: 1px dashed rgba(var(--theme-rgb, 79,195,247), 0.65);
  outline-offset: 1px;
}
/* A RING, not a filled disc. The solid pip with black text was the "stale red"
   the owner circled — a flat blob of colour with a hole punched in it. An
   outlined ring with glowing numerals reads as lit rather than printed. */
.twov2-tk-ord {
  flex: 0 0 auto; width: 18px; height: 18px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 700;
  color: var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  background: #000;
  border: 1px solid var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  text-shadow: 0 0 6px var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  box-shadow: 0 0 8px color-mix(in srgb, var(--tkc, #4fc3f7) 45%, transparent),
              inset 0 0 6px color-mix(in srgb, var(--tkc, #4fc3f7) 25%, transparent);
}
.twov2-tk-chip.is-now .twov2-tk-ord {
  background: var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  color: #000;
  box-shadow: 0 0 14px var(--tkc, rgb(var(--theme-rgb, 79,195,247)));
  text-shadow: none;
}
.twov2-tk-body { display: flex; flex-direction: column; line-height: 1.2; min-width: 0; flex: 1; }
.twov2-tk-name {
  font-size: 12px; font-weight: 600; color: #e8f5ff;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  text-shadow: 0 0 7px rgba(var(--theme-rgb, 79,195,247), 0.4);
  display: flex; align-items: center; gap: 4px;
}
.twov2-tk-name b { color: #ffe08a; font-weight: 700; }
.twov2-tk-play {
  /* 0.02em, not 0.06: measured, "CARDS + TRICKS" needed 82px against 78 of
     body, and 14 characters of tracking is exactly where those 4px were. The
     label is a fixed vocabulary of three phrases, so it never needs the air a
     variable string would — and an ellipsis on a three-word set is worse than
     tight tracking on it. */
  font-size: 9px; letter-spacing: 0.02em; text-transform: uppercase;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font-weight: 600;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 78%, #e8f5ff);
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
.twov2-tk-now {
  position: absolute; top: -6px; right: -4px; font-size: 8px; font-weight: 700; letter-spacing: 0.08em;
  color: var(--tkc, #4fc3f7); background: #000;
  border: 1px solid var(--tkc, #4fc3f7);
  padding: 1px 5px; border-radius: 4px;
  text-shadow: 0 0 7px var(--tkc, #4fc3f7);
  box-shadow: 0 0 10px color-mix(in srgb, var(--tkc, #4fc3f7) 50%, transparent);
}
/* On narrow screens the right rail would cover lane 8 — dock it to a slim
   collapsed tab the player can still open. */
@media (max-width: 900px) {
  .twov2-tracker { width: 150px; }
  .twov2-tk-name { font-size: 11px; }
}

/* ============================================================
   2v2 ROSTER COUNTS — per-player card + trick totals. Two enemies on the
   top (ai) bar, your ally on the bottom (player) bar, each with a name.
   ============================================================ */
.info-bar .bar-center { position: relative; }
.twov2-roster-strip { display: flex; gap: 12px; z-index: 7; pointer-events: none; white-space: nowrap; align-items: center; }
/* Enemies fill the top bar's centre cell (the 1v1 mini-hand space). */
.twov2-roster-strip.rc-enemy { width: 100%; height: 100%; justify-content: center; }
/* Ally sits on the left of the player bar's centre cell, clear of the Done button. */
/* CENTRED IN THE BAR, like the two enemy chips are in theirs. This was
   `position: absolute; left: 6px` — pinned to the left of a cell that also
   holds Undo and the End button, so the pill sat wherever those two happened to
   end and drifted every time the End label changed length. It is a flex ITEM in
   that cell (the absolute positioning never took, since the cell is not a
   containing block), so the honest fix is to let flex centre it: take the
   leftover width and centre the chip inside it.
   (Owner: "the teammates hand pill needs to be centered.") */
.twov2-roster-strip.rc-ally {
  position: static;
  flex: 1 1 auto;
  min-width: 0;
  justify-content: center;
}
/* Pure black interior, hue in the EDGES. The old white-alpha border on a
   near-black wash gave these chips no colour of their own, so a row of them
   read as grey furniture. Each side now carries its own light: enemy red, ally
   blue, and the seat actually playing burns amber. (User: "same with the hands
   it just looks flat, lets have some neon and contrast.") */
.rc-chip {
  display: flex; align-items: center; gap: 7px;
  padding: 3px 9px; border-radius: 999px;
  font-size: 11px; line-height: 1;
  background: #000;
  border: 1px solid rgba(255,255,255,0.14);
  --rc-hue: 255,255,255;
}
.rc-enemy .rc-chip { --rc-hue: 224,64,64; }
.rc-ally  .rc-chip { --rc-hue: 74,163,255; }
.rc-enemy .rc-chip, .rc-ally .rc-chip {
  border-color: rgba(var(--rc-hue), 0.75);
  box-shadow: 0 0 12px rgba(var(--rc-hue), 0.30),
              inset 0 0 14px rgba(var(--rc-hue), 0.10);
}
.rc-chip.rc-active {
  --rc-hue: 255,210,74;
  border-color: rgb(var(--rc-hue));
  box-shadow: 0 0 16px rgba(var(--rc-hue), 0.55),
              inset 0 0 16px rgba(var(--rc-hue), 0.16);
}
.rc-name {
  font-weight: 700; letter-spacing: 0.02em;
  color: color-mix(in srgb, rgb(var(--rc-hue)) 30%, #ffffff);
  text-shadow: 0 0 8px rgba(var(--rc-hue), 0.55);
  max-width: 130px; overflow: hidden; text-overflow: ellipsis;
  display: inline-flex; align-items: center; gap: 4px;
}
.rc-name em { font-style: normal; opacity: 0.6; font-weight: 500; }
/* Each stat is an outlined mini-pill — cards RED for enemies / BLUE for your
   ally, tricks PURPLE for both, matching the 1v1 colour language. */
.rc-stat {
  display: inline-flex; align-items: center; gap: 3px;
  padding: 1px 6px; border-radius: 4px; font-weight: 700;
  border: 1px solid transparent;
}
.rc-enemy .rc-cards { color: #ff7a7a; border-color: rgba(224,64,64,0.7);  background: rgba(224,64,64,0.10); }
.rc-ally  .rc-cards { color: #7cbcff; border-color: rgba(74,163,255,0.7); background: rgba(74,163,255,0.10); }
.rc-tricks          { color: #d7b3e6; border-color: rgba(215,179,230,0.6); background: rgba(215,179,230,0.10); }
.rc-ic { font-style: normal; opacity: 0.9; }
/* PER-PLAYER MINI-HAND — each other player's cards + tricks shown as the same
   face-down card-backs the 1v1 opponent hand uses, with the name on the left
   and leftover Energy (diamond) on the right. (Owner: "i want the 1v1 card and
   trick look instead of whats in 2v2 right now but the players name next to the
   cards and then how much energy they have at the end using the same energy
   symbol.") */
/* 2v2: the main ENEMY (top bar) energy diamond is redundant — each enemy's
   energy sits on their roster chip now. Hide only the enemy one; the local
   player keeps their own diamond on the bottom bar. (Owner: "the enemy energy
   diamond is still and the personal energy diamonds are now gone — fix this.") */
body.twov2-online-game .info-bar.ai-bar .bar-energy { display: none; }
/* 2v2 online runs an 8-lane board, ~75px taller than 1v1's 6 lanes, which
   pushed the hand cards' bottom STAT row below the viewport — you had to scroll
   to read attack/health. Reclaim that height from the board (its lanes still
   render fine at 200px) and tighten the hand/tricks padding so the full card,
   stats included, sits on-screen without scrolling — matching 1v1. Scoped to
   2v2 online, so 1v1 is untouched. (Owner: "the stats for the cards are cut off
   and i would need to scroll down … please fix that for 2v2.") */
body.twov2-online-game .board { min-height: 200px; }
body.twov2-online-game .board .lane { min-height: 0; }
body.twov2-online-game .player-hand-section { padding-top: 6px; padding-bottom: 6px; }
body.twov2-online-game .tricks-section { padding-top: 4px; padding-bottom: 4px; }
.rc-chip-hand { gap: 10px; padding: 4px 11px; }
.rc-hand { display: inline-flex; align-items: center; gap: 3px; }
/* Bigger card-backs — fill the top bar so hand sizes read at a glance. */
/* The backs were the flattest thing here: a muted stroke at 0.95 opacity with
   no light at all. Full opacity, and each one glows in its own colour so a
   fanned hand reads as a row of lit tiles. */
/* A FILLED BODY, NOT JUST AN OUTLINE. These were a 1px border and a faint
   inner glow around a nearly-transparent diamond lattice, so at 20x29 the only
   coloured pixels were the outline — every strip read as the same dark red
   smudge and you could not tell a card from a trick, or your side from theirs.
   (User: "make the blue and red cards more blue and red and the purple tricks
   more purple so you can tell which is which.") The tint is mixed from
   currentColor, so each back still takes its own hue and one rule covers all
   three. */
.rc-back { display: inline-block; width: 20px; height: 29px; border-radius: 2px;
  border: 1px solid currentColor; overflow: hidden; opacity: 1; flex: 0 0 auto;
  background: color-mix(in srgb, currentColor 30%, #05070d);
  box-shadow: 0 0 7px color-mix(in srgb, currentColor 60%, transparent),
              inset 0 0 6px color-mix(in srgb, currentColor 30%, transparent); }
.rc-back svg { width: 100%; height: 100%; display: block; }
/* Cards tint to the side's colour (enemy red / ally blue); tricks purple — the
   same colour language as the 1v1 hand and the count-pills above. */
/* Saturated, not tinted. #ff6b6b and #6fb4ff are both pale enough that at pip
   size they drifted toward the same washed-out pink; these are unmistakably
   red and blue against each other. */
.rc-enemy .rc-back-card { color: #ff3a3a; }
.rc-ally  .rc-back-card { color: #3f9bff; }
/* THE SAME PURPLE THE TRICK CARDS USE. These backs were a lighter lavender
   (#cf9ae8) that read as a different colour sitting next to a real trick card,
   whose border/glow is rgba(155,89,182,.95). One purple for tricks everywhere.
   (User: "make the purple of the hands match that of the tricks.") */
.rc-back-trick { color: #9b59b6; }
/* The trick HUE is deliberately left exactly as it is — it is the same purple
   the real trick cards use, which was itself an earlier request ("make the
   purple of the hands match that of the tricks"). What makes it read as purple
   now is the filled body above, not a different colour. */
.rc-empty { opacity: 0.4; font-weight: 700; padding: 0 4px; }
/* NEON BOT MARK — replaces the 🤖 emoji that used to be baked into AI seat
   names. Stroke-only and currentColor, so it takes the hue of whatever names
   it sits in (red on the enemy strip, blue on the ally strip, the seat's own
   colour in the turn-order rail) and glows with it. See UI.seatNameHTML. */
.bot-ic {
  width: 1.05em; height: 1.05em; flex: 0 0 auto;
  fill: none; stroke: currentColor; stroke-width: 1.4;
  stroke-linecap: round; stroke-linejoin: round;
  filter: drop-shadow(0 0 4px currentColor);
  vertical-align: -0.15em;
}
.twov2-tk-name .bot-ic { color: var(--tkc, rgb(var(--theme-rgb, 79,195,247))); }
@media (max-width: 900px) { .rc-name { max-width: 84px; } .rc-chip { font-size: 10px; padding: 2px 7px; gap: 5px; }
  .rc-back { width: 15px; height: 22px; } }

/* ============================================================
   EMOTE + TAUNT BUTTONS — NEON, NOT DIMMED (2026-08-20)
   ============================================================
   Owner: "make these neon highlighted symbols."

   .emote-btn sat at rgba(207,232,247,0.55) — a pale blue held at 55% opacity,
   which over the black HUD computes to grey. .taunt-btn only overrode
   font-size, so it inherited exactly the same wash. Both read as disabled
   chrome next to a HUD that glows everywhere else.

   Colour comes from --theme-rgb rather than a fixed hex, so they track the
   active accent like the rest of the chrome. Full opacity with the glow doing
   the work, instead of a bright colour dimmed down — that is what separates a
   lit sign from a faded one.

   Appended at the end deliberately: the original rules live ~35778 and would
   otherwise win on source order at equal specificity. */
.emote-btn,
.taunt-btn {
  color: rgb(var(--theme-rgb, 79, 195, 247));
  opacity: 1;
  text-shadow:
    0 0 6px rgba(var(--theme-rgb, 79, 195, 247), 0.85),
    0 0 14px rgba(var(--theme-rgb, 79, 195, 247), 0.45);
}
/* Hover stays a clear step ABOVE the resting state — now that resting is lit,
   going to plain white would read as a step down. */
.emote-btn:hover,
.taunt-btn:hover,
.emote-btn:focus-visible,
.taunt-btn:focus-visible {
  color: var(--theme-accent-bright, #e8f5ff);
  transform: scale(1.25);
  text-shadow:
    0 0 10px rgba(var(--theme-rgb, 79, 195, 247), 1),
    0 0 22px rgba(var(--theme-rgb, 79, 195, 247), 0.6);
}

/* The taunt glyph is DRAWN, not an emoji. 🔊 is rendered by the OS as
   full-colour photoreal art — a literal speaker cabinet on macOS — which sat
   beside a stroked ☺ and read as a product photo dropped into a neon HUD.
   Owner: "should not be a real amp, just neon lines like the smiley face."
   An inline stroked SVG inherits currentColor, so it takes the same accent and
   the same hover as its text sibling. text-shadow does not apply to SVG
   geometry, so the glow is drop-shadow — same look, the filter that works on
   strokes. */
.emote-btn .emote-svg {
  width: 1em; height: 1em;
  display: block;
  filter:
    drop-shadow(0 0 4px rgba(var(--theme-rgb, 79, 195, 247), 0.85))
    drop-shadow(0 0 9px rgba(var(--theme-rgb, 79, 195, 247), 0.45));
}
.emote-btn:hover .emote-svg,
.emote-btn:focus-visible .emote-svg {
  filter:
    drop-shadow(0 0 6px rgba(var(--theme-rgb, 79, 195, 247), 1))
    drop-shadow(0 0 14px rgba(var(--theme-rgb, 79, 195, 247), 0.6));
}
/* The button centres a glyph; an SVG child needs the box to say so. */
.emote-btn { display: inline-flex; align-items: center; justify-content: center; }
.taunt-btn { font-size: 17px; }

/* Per-seat energy on the 2v2 roster chips. Everyone banks and spends their own
   energy in 2v2, so "how much has that player got left" is live tactical
   information the chips were not carrying. left/total says both at once. */
.rc-stat.rc-energy {
  color: rgb(var(--theme-rgb, 79, 195, 247));
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79, 195, 247), 0.55);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.rc-stat.rc-energy .rc-ic { opacity: 0.9; }


/* ============================================================
   STILLNESS — ambient motion is OPT-IN
   ============================================================
   Measured on a live board with nothing happening: THIRTY elements
   were animating on an infinite loop. When everything breathes all
   the time, motion stops meaning anything — so the moment something
   actually happens it has no headroom left to announce itself. This
   is the same rationing that was applied to light, moved into the
   time domain.

   THE LINE IS INFORMATION, NOT TASTE. Everything switched off below
   is ambient: it tells you nothing about the game state. Everything
   that MEANS something is deliberately left alone —
     .card-slot.playable  targetRipple      "you can play here"
     .card.selected       selectedCardPulse "you picked this up"
     .status-badge        cardCrazyGlitch   a live status
     .lane-sep.lane-active                  "this lane is resolving"
   Those are the reason the board can afford to be still elsewhere.

   NOT the same thing as body.low-fx, which already exists: that is a
   PERFORMANCE switch driven by the Graphics setting, and conflating
   "my machine is slow" with "I want a calm board" would mean neither
   control could be trusted.

   TO PUT IT ALL BACK: add `ambient-motion` to <body>. One class.
   ============================================================ */

/* Particles exist ONLY to drift — gameDrift fades them 0 -> 0.35 -> 0,
   so freezing the animation would leave 12 inert dots sitting on the
   board rather than a calmer board. They go entirely. */
body:not(.ambient-motion) .game-particle { display: none !important; }

/* Pulsing NUMBERS are the worst of these: a number that throbs is a
   number you re-read. Card digits were just given a fixed-width face
   so they would stop shifting; leaving the HUD counts pulsing spends
   that back. */
body:not(.ambient-motion) .hud-count b,
body:not(.ambient-motion) .hud-round #round-num,
body:not(.ambient-motion) .hud-pill-main { animation: none !important; }

/* The scanline sweep. The lines themselves stay — only the drift stops. */
body:not(.ambient-motion) .board-section .crt-scanlines { animation: none !important; }


/* ============================================================
   ART GRADE — one lighting model across a borrowed art set
   ============================================================
   Measured across all 229 art files, mean luminance ran 4.8 to 176.4
   — a 36x spread, with no design decision behind it. On a pure-black
   board that is why some cards read as lightboxes and others nearly
   disappear. Per-file corrections live in CARD_ART_GRADE and are
   emitted as --art-grade by UI._artFocalCard.

   WHY A FILTER PLUS ITS INVERSE, AND NOT JUST A FILTER. The art is
   .card-portrait's BACKGROUND, but the element also CONTAINS the card
   name and every status overlay (frost, burn, taunt, armor, ...), and
   a filter grades an element's whole subtree. Since brightness is
   multiplicative, brightness(k) on the portrait and brightness(1/k) on
   its direct children cancels exactly for the children and leaves only
   the background — the art — corrected. Neither pseudo-element was
   free to carry the layer, and re-cutting the background stack would
   have put every card's focal crop at risk for a tonal fix.

   TO TURN IT OFF: add `no-art-grade` to <body>. One class.
   ============================================================ */
.card-portrait > * {
  filter: brightness(calc(1 / var(--art-grade, 1)));
}
/* THE SWITCH. Resetting the variable disables the grade everywhere in one
   declaration — the alternative, a rule that re-sets `filter`, is exactly the
   mistake above: it would replace the tints and status treatments rather than
   sit alongside them. */
body.no-art-grade .card-portrait { --art-grade: 1 !important; }


/* ============================================================
   CONTESTED LANE — the separator carries the environment's name
   ============================================================
   In a contested lane the environment's edge labels are printed over
   the two cards fighting in front of them, so the name moves to the
   centreline instead, replacing the lane number. The centreline is the
   one strip guaranteed to be clear in a contested lane — it is the gap
   the cards are drawn either side of.

   Same element as the number, so it keeps the per-occupancy pulse
   (tronCirclePulse drives --lane-pulse-* from the lane's occupancy
   class); only the box opens from a 22px circle into a pill. The
   ellipsis is the backstop for a long name at a narrow lane width —
   the full text is on the title attribute.
   ============================================================ */
.lane-number.lane-number-env {
  width: auto;
  min-width: 22px;
  max-width: calc(100% - 10px);
  height: 18px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 8px;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  /* inline-flex, NOT flex: as a block-level flex container the pill filled
     the whole centreline and every name measured the same clamped width,
     so a short name looked identical to a long one. */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* It opens the environment's card, so it has to read as a control. The
     house language is grow + glow, never a box — the pill outline is already
     the number's, so hover only lifts and brightens. Fast-out / slow-in like
     every other interactive surface: the base rule is the RETURN to rest.
     No `cursor: pointer` — the game draws its own cursor and kills the native
     one globally (`*, *::before, *::after { cursor: none !important }`), so a
     pointer here would be a dead declaration. The lift IS the affordance. */
  transition: transform var(--dur-out) var(--ease-exit),
              filter var(--dur-out) var(--ease-exit);
}
.lane-number.lane-number-env:hover {
  transform: scale(1.06);
  filter: brightness(1.25);
  transition: transform var(--dur-in) var(--ease-snap),
              filter var(--dur-in) var(--ease-snap);
}

/* ============================================================
   MAIN MENU: TEXT LEFT, ART RIGHT — THE LOBBY'S SPLIT (LANDSCAPE ONLY)
   ============================================================
   User: "i want the main menu to look like this as well — left is where all
   the text is and right is the art, it looks clean." ("this" = the online-2v2
   lobby, which has run that split since it was built.)

   THIS REVERSES AN EARLIER REQUEST, DELIBERATELY — and not by restoring the
   old rule, because the old one was broken. Back then the hero was anchored
   `right: 0` at `width: min(calc(100% - 14%), 86vh)`: on a tall window the
   bleed term won and the art spread behind the list, on a wide window the 86vh
   cap won and the art collapsed into a right column. Same rule, two identities,
   changing shape as you resized — THAT was the complaint, and centring cured it
   by deleting the split rather than fixing it.

   This rebuilds it the way the LOBBY does, which never had the bug: the art is
   a fixed SHARE of the width (no min() that can switch terms), masked so it
   dissolves toward the text instead of ending on a seam. One identity at every
   landscape width — the art just gets wider or narrower, and the crop never
   changes because the box keeps its proportion.

   GATED ON LANDSCAPE. A split needs horizontal room; on a phone there is none,
   and the base rules above (centred list over full-bleed art) are still the
   right answer. Everything here is scoped so portrait renders byte-for-byte as
   it did before — checked at 375x812, where an ungated version squeezed the
   column to 40vw and wrapped "SOLO MATCH" onto two lines.
   ============================================================ */
@media (min-aspect-ratio: 1/1) {
  /* Right-hand column, matching .twov2-mm-hero: anchored right and sized as a
     SHARE of the window, so it cannot swap identities the way the old min() did. */
  .mm-mw3 .mm-hero {
    left: auto; right: 0;
    margin-inline: 0;
    width: 62%;
    /* Dissolve toward the TEXT, hard against the window on the right — the same
       one-sided fade the lobby uses, so the art has no seam where the column
       begins. Vertical letterbox crop kept. */
    -webkit-mask-image:
      linear-gradient(to right, transparent 0%, rgba(0,0,0,0.4) 26%, #000 60%),
      linear-gradient(to bottom, transparent 0%, #000 11%, #000 86%, transparent 100%);
    -webkit-mask-composite: source-in;
            mask-image:
      linear-gradient(to right, transparent 0%, rgba(0,0,0,0.4) 26%, #000 60%),
      linear-gradient(to bottom, transparent 0%, #000 11%, #000 86%, transparent 100%);
            mask-composite: intersect;
  }
  /* Subject sits right of centre again, since it occupies the right column. */
  .mm-mw3 .mm-hero-img { background-position: 62% 26%; }

  /* ---- The text column takes its own left axis ---- */
  .mm-mw3 .mm-header { align-items: flex-start; }
  .mm-mw3 .mm-title { text-align: left; }
  .mm-mw3 .mm-panel .mm-section,
  .mm-mw3 .mm-panel .mm-grid-section { margin-inline: 0; }
  .mm-mw3 .mm-grid.mm-grid-section { width: fit-content; margin-inline: 0; }
  /* PLAY / LIBRARY: the label leads and a single rule runs OUT to the column's
     edge. Flanking it both sides was right on a centre line; against a left
     column the leading rule pushes the word off the axis its own options sit on. */
  .mm-mw3 .mm-section-label {
    margin: 10px 0 6px;
    justify-content: flex-start;
    width: 100%;
    /* THE JOINT, part 1. `gap` spaces EVERY flex item equally, so a node
       dropped in inherits 12px from the word AND 12px from the rule — a
       floating bead, not a connector. Spacing moves onto the node itself
       below, so the rule can butt against it and read as leaving it.
       Folded into this rule rather than added as a new block: this selector is
       already written six times in this file (2412, 2476, 2482, 38836, 38926,
       and here) and a seventh copy is the bug class, not a fix. */
    gap: 0;
  }
  /* THE PLAY MARK. The label and the rule were two marks with dead air between
     them, and the dead air read as a missing piece rather than as spacing.
     (User: "i feel a symbol is missing here to tie it together" — then, shown a
     diamond and a triangle side by side: "i want the play button not diamond.")
     A triangle does something the diamond could not: it POINTS. The rule reads
     as running out of it rather than merely touching it, which is the whole job
     of a connector.
     SOLID, where the option rows below use the OUTLINED &#9655;. That is
     deliberate: the same glyph in the same weight on a heading and on the
     clickable rows underneath would say the heading is a button too. Filled vs
     hollow keeps them related without making the label look pressable.
     SIZED BY AREA, NOT BY BOX. 0.44em/0.27em is ~0.119em2 of ink against the
     diamond's 0.1156 — the two carry the same optical weight, which a 0.36em
     triangle does not (0.079, visibly lighter). A triangle needs to be wider
     than a diamond to weigh the same, not narrower.
     drop-shadow, not box-shadow: the mark is drawn with borders on a zero-size
     box, so box-shadow would trace the invisible rectangle instead of the
     shape.
     `order` places it after the text: ::after IS the rule, so ::before is the
     only free pseudo-element, and flex order re-sequences it with no new
     element in the markup.
     Landscape only. Portrait keeps its symmetric flanking rules, where
     ::before IS the left-hand hairline (38845) and the label is already tied on
     both sides. */
  .mm-mw3 .mm-section-label::before {
    display: block;
    content: '';
    order: 1;
    flex: 0 0 auto;
    width: 0; height: 0;
    background: none;
    transform: none;
    border-left: 0.44em solid rgb(var(--theme-rgb, 79,195,247));
    border-top: 0.27em solid transparent;
    border-bottom: 0.27em solid transparent;
    /* The word-to-mark breath, in em so it tracks the type the way a flat 12px
       did not. Rajdhani's 4px letter-spacing already leaves trailing air. */
    margin-left: 0.7em;
    box-shadow: none;
    filter: drop-shadow(0 0 5px rgba(var(--theme-rgb, 79,195,247), 0.9));
  }
  /* THE TRACE. 2px clears the node's 1px ring and no more, so the hairline runs
     INTO the point rather than near it. align-items:center on the row puts the
     rotated square's vertices exactly on this 1px line's axis. The 0.85 -> 0.55
     ramp is energy leaving a source and dissipating; the tail fade is unchanged.
     NOTE: this supersedes the base gradient at 38852 — one colour authority for
     this rule now lives here. */
  /* THE LADDER. Each divider is shorter than the one above it, so their right
     ends fall along a line that sweeps down and in — the top rule reaches
     furthest into the art and each one after it stops sooner.
     (User: "i want the lanes to get shorter as they go down, so the top line is
     the longest and fades to black, then shorter and shorter.")
     THE LENGTH IS SET ON THE LABEL, NOT THE RULE. The rule is flex:1, so
     capping the RULE would make its end depend on the word in front of it —
     which is exactly the accident this replaces: PLAY's rule was 431px and
     LIBRARY's 402px purely because "Play" is the shorter word, so the ends
     staggered the wrong way for no reason. Sizing the label fixes where each
     row ENDS regardless of what it says.
     nth-of-type(2) is the first .mm-section in BOTH layouts: the main menu runs
     header / section / section / botbar, and a submenu runs header / button /
     section x3 / botbar — the button is a different element type, so the divs
     number identically. One ladder covers the menu and every submenu. */
  .mm-mw3 .mm-panel .mm-section:nth-of-type(2) .mm-section-label { width: var(--mm-rule-field); }
  .mm-mw3 .mm-panel .mm-section:nth-of-type(3) .mm-section-label { width: calc(var(--mm-rule-field) * 0.84); }
  .mm-mw3 .mm-panel .mm-section:nth-of-type(4) .mm-section-label { width: calc(var(--mm-rule-field) * 0.70); }
  .mm-mw3 .mm-panel .mm-section:nth-of-type(5) .mm-section-label { width: calc(var(--mm-rule-field) * 0.58); }
  /* The music block closes the ladder. Its flat border-top was a hard 1px line
     that stopped dead at the box edge while every rule above it dissolved —
     the one divider on the screen not speaking the same language. Redrawn as
     the same fading gradient, and shortest of all. */
  .mm-mw3 .mm-botbar {
    border-top: none;
    position: relative;
  }
  .mm-mw3 .mm-botbar::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    height: 1px;
    /* Same field as the section rules above, so the whole ladder is measured
       from one origin rather than this one being a percentage of its own box. */
    width: calc(var(--mm-rule-field) * 0.58);
    background: linear-gradient(90deg,
      rgba(var(--theme-rgb, 79,195,247), 0.55) 0,
      rgba(var(--theme-rgb, 79,195,247), 0.35) 20%,
      transparent 100%);
  }
  .mm-mw3 .mm-section-label::after {
    order: 2;
    flex: 1;
    width: auto;
    margin-left: 2px;
    background: linear-gradient(90deg,
      rgba(var(--theme-rgb, 79,195,247), 0.85) 0,
      rgba(var(--theme-rgb, 79,195,247), 0.55) 20%,
      transparent 100%);
  }
  /* Back to hugging the column's left edge, where a back control belongs. */
  .mm-mw3 .mm-subback {
    display: flex;
    width: fit-content;
    margin: 2px 0 16px;
    transform-origin: left center;
  }
  /* The music block and its inner lines follow the column — a left-aligned box
     whose contents were still centred read as a third axis under a left menu. */
  .mm-mw3 .mm-botbar { margin-inline: 0; }
  .mm-mw3 .mm-npline { justify-content: flex-start; }
  .mm-mw3 .mm-heropick-row { text-align: left; }

  /* THE COLUMN, and its cap. min(760px,82vw) was sized for the centred layout
     where nothing sat beside it; as a left column it has to clear the art. */
  .mm-mw3 .mm-panel {
    /* Held in a var because the rule-field below has to subtract it. Written
       twice, these two drift apart the moment either is tuned. */
    --mm-col-inset: clamp(34px, 6vw, 120px);
    margin-left: var(--mm-col-inset);
    margin-right: auto;
    width: min(620px, 40vw);
    /* THE RULES MUST STOP BEFORE THE ART. The panel is 40vw wide starting at
       ~6vw, so its right edge lands around 46vw — while the hero begins at
       38vw. The TEXT never noticed because it is short, but the dividers are
       the longest things in the column and were running out over the picture:
       measured, PLAY's rule crossed 97px past the hero's left edge and
       LIBRARY's 19px. (User: "make sure the lines dont bleed into the art.")
       Capping the field at 36vw leaves ~2vw of clearance before the art starts,
       and min() means a narrow window still just uses the column width. */
    --mm-rule-field: min(100%, calc(36vw - var(--mm-col-inset)));
  }
}


/* ---- 2v2 End button: room for a label that names the sub-phase -----------
   "End Cards + Tricks" is four times the width of the "Done" it replaced, and
   the actions cell holds three things: Undo, this button, and the roster
   counts. The roster is `flex: 0 1 auto` with the default `min-width: auto`,
   so it REFUSES to shrink — every pixel of the squeeze landed on the button,
   which has `min-width: 0` and `overflow: hidden` and was therefore sliced
   down to bare padding (measured 60px wide holding 155px of content).

   The button is the control you have to be able to press; the roster is a
   readout. So the button stops shrinking and the roster starts.

   Selector is ID+class deliberately: #btn-action sets the padding, and the
   comment there records that "this ID rule is what every class-level attempt
   was losing to". Nothing here is worth an !important. */
#btn-action.twov2-end-btn {
  padding-left: 14px;
  padding-right: 14px;
  flex: 0 0 auto;             /* never the one that gets crushed */
}
.actions-section .twov2-roster-bottom {
  min-width: 0;               /* ...this is */
  overflow: hidden;
}

/* ============================================================
   PARTY VOICE CHAT PANEL (voice.js)
   Sits bottom-left, out of the lanes and clear of the turn-order rail on the
   right. Collapsed it is a single chip; open it lists everyone in the room.

   TRON PASS (owner: "make the voice chat tron themed no grey text and the
   sound icon should be a neon highlight not a real amp"). Three rules, the
   same three the rest of the game already follows:
     • the interior is PURE #000 — no navy, no wash, no backdrop blur. The
       colour in this panel is the border, the glow and the type;
     • NO GREY TEXT. Every secondary string is the theme hue at lower alpha,
       so it reads as dimmer LIGHT rather than as dead pigment. The idle
       speaker dot went the same way — it was slate #33455c;
     • buttons are boxless grow+glow text, never a filled rectangle. LEAVE
       was a red box; it is red LIGHT now.
   ============================================================ */
.voice-panel {
  position: fixed; left: 12px; bottom: 12px; z-index: 6000;
  width: 208px; padding: 0; border-radius: 10px;
  /* Pure black, deliberately. Anything translucent here picks up the board
     behind it and the panel stops reading as its own surface. */
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  box-shadow:
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.22),
    inset 0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.05);
  font-family: 'Rajdhani', system-ui, sans-serif;
  color: rgba(var(--theme-rgb, 79,195,247), 0.92);
  overflow: hidden;
}
.voice-panel.collapsed { width: auto; }
.voice-panel.collapsed .vp-body { display: none; }
.vp-head {
  display: flex; align-items: center; gap: 8px; width: 100%;
  background: none; border: 0; cursor: pointer; padding: 7px 12px;
  color: inherit; font: 700 12px/1 'Rajdhani', system-ui, sans-serif;
  letter-spacing: 0.14em; text-transform: uppercase;
  transition: color 140ms var(--ease-out-soft), text-shadow 140ms var(--ease-out-soft);
}
/* No hover PLATE — the label lights instead. Same language as every other
   text control in the game. */
.vp-head:hover { color: rgba(var(--theme-rgb, 79,195,247), 1); }
.vp-head:hover .vp-off {
  color: rgba(var(--theme-rgb, 79,195,247), 1);
  text-shadow: 0 0 9px rgba(var(--theme-rgb, 79,195,247), 0.65);
}
.vp-off  { color: rgba(var(--theme-rgb, 79,195,247), 0.80); }
.vp-live { color: #37d67a; text-shadow: 0 0 8px rgba(55, 214, 122, 0.55); }
.vp-live-hot { color: #6bff9f; text-shadow: 0 0 12px rgba(107, 255, 159, 0.9); }
.vp-count {
  margin-left: auto; font-size: 11px;
  font-family: var(--font-mono); font-variant-numeric: tabular-nums;
  color: rgba(var(--theme-rgb, 79,195,247), 0.95);
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.45); border-radius: 8px;
  padding: 0 6px;
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
.vp-body { padding: 4px 8px 9px; }
.vp-blurb {
  font-size: 11.5px; line-height: 1.35; padding: 2px 4px 8px;
  color: rgba(var(--theme-rgb, 79,195,247), 0.62);
}
.vp-err {
  font-size: 11px; color: #ff9c9c; background: transparent;
  border: 1px solid rgba(231, 76, 60, 0.45); border-radius: 6px;
  padding: 5px 7px; margin: 2px 0 7px; line-height: 1.3;
  text-shadow: 0 0 7px rgba(231, 76, 60, 0.35);
}
/* BOXLESS. Grow + glow, no plate, no border — see the block comment above. */
.vp-btn {
  display: block; width: 100%; margin-top: 6px; padding: 6px 4px;
  background: none; border: 0; border-radius: 0; cursor: pointer;
  font: 700 12px/1 'Rajdhani', system-ui, sans-serif; letter-spacing: 0.16em;
  text-transform: uppercase;
  transition: color 150ms var(--ease-out-soft),
              text-shadow 150ms var(--ease-out-soft),
              transform 150ms var(--ease-out-soft),
              letter-spacing 150ms var(--ease-out-soft);
}
.vp-join  { color: rgba(55, 214, 122, 0.92); }
.vp-join:hover:not(:disabled) {
  color: #8affc0; transform: scale(1.05); letter-spacing: 0.20em;
  text-shadow: 0 0 10px rgba(55, 214, 122, 0.85), 0 0 22px rgba(55, 214, 122, 0.35);
}
.vp-join:disabled { opacity: 0.5; cursor: default; }
.vp-leave { color: rgba(231, 76, 60, 0.90); }
.vp-leave:hover {
  color: #ff9c9c; transform: scale(1.05); letter-spacing: 0.20em;
  text-shadow: 0 0 10px rgba(231, 76, 60, 0.85), 0 0 22px rgba(231, 76, 60, 0.35);
}
.vp-row {
  display: flex; align-items: center; gap: 7px;
  padding: 4px 4px; border-radius: 6px;
  font-size: 12.5px; line-height: 1.2;
}
/* The dot is the whole "who is talking" answer — it lights only while that
   person's mic is actually carrying sound (RMS over a threshold), so nobody
   has to announce themselves. Idle is the theme hue turned down, NOT slate:
   a grey dot beside a lit one reads as broken rather than quiet. */
.vp-dot {
  width: 8px; height: 8px; border-radius: 50%; flex: 0 0 auto;
  background: rgba(var(--theme-rgb, 79,195,247), 0.45);
  transition: background 90ms linear, box-shadow 90ms linear;
}
.vp-speaking .vp-dot { background: #37d67a; box-shadow: 0 0 8px rgba(55, 214, 122, 0.95); }
.vp-speaking { background: rgba(55, 214, 122, 0.08); }
.vp-name {
  flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  color: var(--text-hi, #f2f8ff);
}
/* "(you)" — the theme hue, not opacity applied to white. Fading white gives
   grey; fading a hue gives a quieter version of the same light. */
.vp-name em {
  font-style: normal; font-size: 11px;
  color: rgba(var(--theme-rgb, 79,195,247), 0.72);
}
.vp-mute {
  background: none; border: 0; cursor: pointer; padding: 0 2px;
  line-height: 0; display: inline-flex; align-items: center;
  color: rgba(var(--theme-rgb, 79,195,247), 0.70);
  transition: color 140ms var(--ease-out-soft), filter 140ms var(--ease-out-soft);
}
.vp-mute:hover {
  color: rgba(var(--theme-rgb, 79,195,247), 1);
  filter: drop-shadow(0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.75));
}
/* The glyph: stroked outline in currentColor, so it inherits the panel's neon
   and every hover/muted colour change for free. */
.vp-spk { width: 17px; height: 17px; display: block; overflow: visible; }
.vp-spk .vp-cone {
  fill: currentColor; stroke: currentColor; stroke-width: 1.1;
  stroke-linejoin: round;
}
.vp-spk .vp-wave {
  fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round;
}
.vp-spk .vp-wave-far { opacity: 0.6; }
.vp-spk .vp-slash {
  fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round;
  opacity: 0;                       /* only drawn in the muted state */
}
/* MUTED: the arcs go out, the slash comes on, the whole glyph turns red. One
   shape carrying both states rather than two different pictures. */
.vp-mute.is-muted { color: rgba(231, 76, 60, 0.95); }
.vp-mute.is-muted:hover {
  color: #ff9c9c;
  filter: drop-shadow(0 0 6px rgba(231, 76, 60, 0.75));
}
.vp-mute.is-muted .vp-wave { opacity: 0; }
.vp-mute.is-muted .vp-slash { opacity: 1; }
/* Speaking: the mic glyph rides the same green the dot does. */
.vp-speaking .vp-mute:not(.is-muted) {
  color: #6bff9f;
  filter: drop-shadow(0 0 7px rgba(55, 214, 122, 0.7));
}
@media (max-width: 700px) {
  .voice-panel { left: 8px; bottom: 8px; width: 176px; }
  .vp-head { padding: 6px 9px; font-size: 11px; }
}

/* ============================================================
   ALWAYS-ON MENU LEADERBOARD RAIL — the shared board, pinned to the
   main menu (not a tab, not behind a click). Populated by
   UI._renderMenuLeaderboard; clicking it opens the full modal.
   ============================================================ */
.mm-lb-rail {
  position: absolute;
  /* Top-right of the menu, aligned with the "THE GAME" title and clear above
     the MULTIPLAYER box. `left` clears the title column; `top` lines it up with
     the title rather than sitting on the featured tile. */
  left: clamp(560px, 42%, 900px);
  top: 34px;
  bottom: auto;
  right: auto;
  transform: none;
  z-index: 7;
  width: min(400px, 30vw);
  max-height: 82vh;
  overflow: hidden;
  padding: 12px 12px 10px;
  border-radius: 12px;
  background: rgba(8, 13, 24, 0.82);
  border: 1px solid rgba(120, 160, 210, 0.30);
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.45), inset 0 0 24px rgba(60, 110, 180, 0.08);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  cursor: pointer;
  color: #dfe8f6;
  font-family: inherit;
}
.mm-lb-rail:hover { border-color: rgba(150, 190, 235, 0.55); }
.mm-lb-title {
  display: flex; align-items: center; gap: 8px;
  font: 700 15px/1 var(--font-display, inherit);
  letter-spacing: 0.4px; color: #eef4ff; margin-bottom: 9px;
}
.mm-lb-edit {
  margin-left: auto; font: 600 11px/1 inherit; color: #7ee8a5;
  background: rgba(126, 232, 165, 0.10); border: 1px solid rgba(126, 232, 165, 0.30);
  padding: 3px 8px; border-radius: 999px; white-space: nowrap;
}
.mm-lb-tablewrap { overflow: visible; }
.mm-lb-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.mm-lb-table th {
  text-align: left; padding: 4px 7px; color: #9fb6d6; font-weight: 700;
  border-bottom: 1px solid rgba(120, 160, 210, 0.30); white-space: nowrap;
}
.mm-lb-table td {
  padding: 5px 7px; border-top: 1px solid rgba(120, 160, 210, 0.12);
  white-space: nowrap; color: #dfe8f6;
}
.mm-lb-rank { color: #9fb6d6; width: 1.4em; }
.mm-lb-name { font-weight: 700; color: #eef4ff; max-width: 8.5em; overflow: hidden; text-overflow: ellipsis; }
.mm-lb-dim { color: #7f95ad; }
.mm-lb-mvp { color: #ffcf6a; max-width: 8em; overflow: hidden; text-overflow: ellipsis; }
.mm-lb-me td { background: rgba(126, 232, 165, 0.10); }
.mm-lb-me .mm-lb-name::after { content: ' (you)'; color: #7ee8a5; font-weight: 600; font-size: 10px; }
.mm-lb-empty { padding: 16px 8px; text-align: center; color: #9fb6d6; white-space: normal; }

/* Narrow screens: the rail would cover the hero/menu, so drop it to a
   full-width strip pinned to the bottom of the menu. */
@media (max-width: 900px) {
  .mm-lb-rail {
    top: auto; bottom: 10px; right: 10px; left: 10px;
    transform: none; width: auto; max-height: 40vh; overflow-y: auto;
  }
}

/* ============================================================
   CARD FRAME WEIGHT — option E, 2px.
   The frame is the only line on a tile that runs the whole way round, so it is
   what gives the card an edge to sit inside rather than a picture that fades
   out. At 1px, against art that now runs to the border on every surface, it
   read as a hairline the art kept swallowing.
   ONE rule rather than twenty: the tier colours are set with the `border`
   SHORTHAND and `!important` (the cost ramp at ~5388, the trick purple at 5579,
   the game-over MVP tiers at ~23867), and a shorthand carries a width. Editing
   each would mean keeping twenty copies of one number in step forever. This
   sets the width alone, last in the file, without touching a single colour.

   THE DOUBLED CLASS IS LOAD-BEARING — `.card.card`, not `.card`. Owner: "why
   does blue look thicker than green?" Because it WAS: cost-1 measured 1px and
   cost-6 measured 2px off the same override. The cost ramp writes the whole
   shorthand at `.draft-card.cost-1` — TWO classes — while the 4/5/6 and 7/8
   and 9/10 tiers only override `border-color`, ONE property. So a one-class
   `!important` here lost the low tiers on specificity and won the high ones by
   default, and the frame silently changed weight with the cost. Repeating the
   class costs nothing and matches (0,2,0), which ties the tier rules and takes
   it on source order. Deliberately NOT three classes: the 3- and 4-class border
   rules in this file are CHILD elements (.trick-cost, .status-badge) that must
   keep their own weights.
   box-sizing is border-box globally (line 448), so the extra pixel comes out of
   the padding box: no tile changes size and nothing downstream reflows.
   ============================================================ */
.card.card,
.draft-card.draft-card,
.trick-card.trick-card { border-width: 2px !important; }

/* ============================================================
   LEADERBOARD, INLINE IN TOOLS.
   The rail was built to float over the hero art — absolute, vertically
   centred, right-pinned, with a translucent navy plate and a blur. Dropped
   into the Tools panel unchanged it sat ON TOP of Gallery Audit and Sandbox
   and hid them. Inside a panel it is a block in the flow, not an overlay, so
   the positioning comes off entirely.
   The plate goes too: panel interiors are pure #000 in this game, and a navy
   wash with a backdrop blur reads as a different surface pasted into the menu.
   ============================================================ */
.mm-lb-rail.mm-lb-inline {
  position: static;
  transform: none;
  width: 100%;
  max-width: 420px;
  max-height: none;
  margin: 18px 0 0;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.42);
  border-radius: 10px;
  box-shadow: 0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.16),
              inset 0 0 20px rgba(var(--theme-rgb, 79,195,247), 0.05);
  backdrop-filter: none;
}

/* ============================================================
   MAIN MENU — THE HUD LAYOUT (2026-08-25)
   ============================================================
   Owner supplied a canvas for the home screen and asked for it "with the art
   how it is currently on the right", so .mm-sideart is deliberately untouched
   below — this block restyles the LEFT column only.

   Appended at the end of the file on purpose. The menu's existing rules span
   ~2018-2200 and a dozen later override blocks; matching specificity against
   all of them would mean guessing which one currently wins. Source order is
   the one lever that always works, and it keeps the old rules readable as
   history instead of shredding them.

   The one boxed thing on this screen is the featured mode. Everything else
   stays boxless glow-text, which is the standing rule — a panel around ONE
   item is what makes it read as featured; a panel around all of them is the
   blue box we keep removing. */

/* ---- Title: name, then an angled rule that cuts away to the right ---- */
.mm-panel .mm-title {
  text-align: left;
  letter-spacing: 6px;
  text-indent: 0;
  margin: 0 0 14px;
}
.mm-panel .mm-header {
  align-items: flex-start;
  position: relative;
}
/* The rule is a clipped block, not a border — a border cannot taper. The
   polygon takes the last 42px down to a point so it reads as a circuit trace
   leaving the title rather than a line that simply stops. */
.mm-panel .mm-header::after {
  content: "";
  display: block;
  width: 62%; height: 3px;
  margin: 0 0 26px;
  background: linear-gradient(90deg,
    rgba(var(--theme-rgb, 79,195,247), 0.95) 0%,
    rgba(var(--theme-rgb, 79,195,247), 0.75) 62%,
    rgba(var(--theme-rgb, 79,195,247), 0.45) 100%);
  clip-path: polygon(0 0, calc(100% - 42px) 0, 100% 100%, 0 100%);
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.55);
}

/* ---- Featured mode — chamfered on the two opposite corners ---- */
.mm-panel .mm-feature {
  position: relative;
  display: flex; align-items: center; gap: 20px;
  width: 100%;
  margin: 0 0 24px;
  padding: 18px 24px;
  cursor: pointer;
  text-align: left;
  background: linear-gradient(120deg,
    rgba(var(--theme-rgb, 79,195,247), 0.10) 0%,
    rgba(var(--theme-rgb, 79,195,247), 0.02) 46%,
    rgba(0,0,0,0) 100%), #000;
  border: 0;
  /* top-left and bottom-right cut — the same 45-degree language as the
     card frame's chamfer, so the menu and the cards read as one system. */
  clip-path: polygon(26px 0, 100% 0, 100% calc(100% - 26px),
                     calc(100% - 26px) 100%, 0 100%, 0 26px);
  color: var(--text-hi, #f5fbff);
  font-family: 'Rajdhani', sans-serif;
  transition: transform 0.18s var(--ease-snap), filter 0.18s var(--ease-snap);
}
/* The outline is a second clipped layer sitting 1px inside the first. A
   border cannot follow a clip-path, and box-shadow gets clipped away by it —
   two stacked polygons is the only way to get a stroked chamfered box. */
.mm-panel .mm-feature::before {
  content: "";
  position: absolute; inset: 0;
  background: rgba(var(--theme-rgb, 79,195,247), 0.85);
  clip-path: polygon(26px 0, 100% 0, 100% calc(100% - 26px),
                     calc(100% - 26px) 100%, 0 100%, 0 26px);
  z-index: 0;
}
.mm-panel .mm-feature::after {
  content: "";
  position: absolute; inset: 1.5px;
  background: #000;
  clip-path: polygon(25px 0, 100% 0, 100% calc(100% - 25px),
                     calc(100% - 25px) 100%, 0 100%, 0 25px);
  z-index: 1;
}
.mm-panel .mm-feature > * { position: relative; z-index: 2; }
.mm-panel .mm-feature:hover { transform: translateX(3px); filter: brightness(1.15); }
.mm-panel .mm-feature-icon {
  color: rgb(var(--theme-rgb, 79,195,247));
  display: flex; align-items: center;
}
.mm-panel .mm-feature-icon .mm-svg { width: 30px; height: 30px; }
.mm-panel .mm-feature-text { display: flex; flex-direction: column; gap: 7px; }
.mm-panel .mm-feature-label {
  font-size: 27px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase;
  line-height: 1;
  text-shadow: 0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.55);
}
.mm-panel .mm-feature-sub {
  font-family: var(--font-mono);
  font-size: 11px; font-weight: 500; letter-spacing: 2.6px; text-transform: uppercase;
  color: rgba(var(--theme-rgb, 79,195,247), 0.80);
}

/* ---- Section labels — "PLAY ╱" then a rule to the right ---- */
.mm-panel .mm-section-label {
  border-left: 0;
  padding-left: 0;
  margin: 0 0 18px;
  display: flex; align-items: center; gap: 12px;
  font-size: 11px; letter-spacing: 4.5px;
  color: rgba(var(--theme-rgb, 79,195,247), 0.95);
}
.mm-panel .mm-section-label::before {
  content: "╱";
  font-size: 12px;
  color: rgba(var(--theme-rgb, 79,195,247), 0.55);
}
.mm-panel .mm-section-label::after {
  content: "";
  flex: 1 1 auto; height: 1px;
  background: linear-gradient(90deg,
    rgba(var(--theme-rgb, 79,195,247), 0.32) 0%,
    rgba(var(--theme-rgb, 79,195,247), 0) 100%);
}

/* ---- Rows — bigger, quieter, boxless ---- */
/* The canvas is 1855px tall; a 900-1000px browser is the real target, so the
   rhythm is compressed to keep the profile chip and Now Playing above the fold
   rather than reproducing the mockup's spacing and pushing them off it. */
.mm-panel .mm-grid-section { gap: 2px; }
.mm-panel .mm-section { margin-bottom: 22px; }
.mm-panel .mm-option {
  padding: 10px 8px 10px 4px;
  gap: 18px;
  align-items: center;
}
.mm-panel .mm-option-label {
  font-size: 23px; font-weight: 700; letter-spacing: 4.5px;
}
.mm-panel .mm-option-icon .mm-svg { width: 22px; height: 22px; }
/* The one-line description is dead weight on a screen this size — the label
   already says what the row does. Kept in the DOM for the submenus, which
   genuinely need it, and hidden only on the main list. */
.mm-panel .mm-tier-1 .mm-option-sub,
.mm-panel .mm-tier-2 .mm-option-sub { display: none; }
.mm-panel .mm-option-text { flex: 1 1 auto; min-width: 0; }
.mm-panel .mm-option-meta {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 11px; font-weight: 600; letter-spacing: 2.2px; text-transform: uppercase;
  color: rgba(var(--theme-rgb, 79,195,247), 0.50);
  white-space: nowrap;
}

/* ---- Who is signed in ---- */
.mm-panel .mm-profile-chip {
  display: flex; align-items: center; gap: 18px;
  margin: 4px 0 0; padding: 0;
  background: none; border: 0; cursor: pointer;
  text-align: left;
}
.mm-panel .mm-profile-av {
  width: 58px; height: 58px;
  display: grid; place-items: center;
  font-family: 'Rajdhani', sans-serif;
  font-size: 21px; font-weight: 700; letter-spacing: 2px;
  color: rgb(var(--theme-rgb, 79,195,247));
  background: rgba(var(--theme-rgb, 79,195,247), 0.09);
  /* border-radius AND border both have to go: the base rule at ~1959 makes this
     a 50% circle with a 1px border, and a clip-path cannot un-round a box that
     has already been rounded — it just cuts the corners off a circle. The
     outline moves to an inset shadow, which does follow the clip. */
  border-radius: 0;
  border: 0;
  clip-path: polygon(0 0, calc(100% - 15px) 0, 100% 15px, 100% 100%, 15px 100%, 0 calc(100% - 15px));
  box-shadow: inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
.mm-panel .mm-profile-name {
  font-family: 'Rajdhani', sans-serif;
  font-size: 17px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase;
  color: var(--text-hi, #f5fbff);
}
.mm-panel .mm-profile-record {
  font-family: var(--font-mono);
  font-size: 10px; letter-spacing: 2.6px; text-transform: uppercase;
  color: rgba(var(--theme-rgb, 79,195,247), 0.55);
}

/* ---- Now playing ---- */
.mm-panel .mm-botbar {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.16);
}
.mm-panel .mm-np-label {
